-- بيانات مقرر كيمياء 3 (المقرر 4، قيد الإعداد) — الجزء 3 من 5. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem3-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L1-O19'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الصيغة الكيميائية لملح إبسوم؟', null, '["MgSO₄·7H₂O","MgSO₃·7H₂O","Mg(OH)₂·7H₂O","CaSO₄·7H₂O"]'::jsonb, 'تذكر', 'استرجاع صيغة', 'سهل', 'الكتاب ص 65 — ملح إبسوم'),
('mcq', 2, 'ما الاسم الكيميائي للمادة التي تتكوّن منها بلورات ملح إبسوم؟', null, '["كربونات الماغنسيوم","كبريتات الماغنسيوم المائية","أكسيد الماغنسيوم","كبريتات الكالسيوم المائية"]'::jsonb, 'تذكر', 'استرجاع اسم', 'متوسط', 'الكتاب ص 65 — ملح إبسوم'),
('mcq', 3, 'أيّ مما يأتي من استعمالات ملح إبسوم التي ذكرها الكتاب؟', null, '["تعقيم مياه الشرب","تسليك المصارف المسدودة","تخفيف آلام العضلات","تنظيف السيراميك"]'::jsonb, 'تذكر', 'استرجاع استعمال', 'سهل', 'الكتاب ص 65 — ملح إبسوم'),
('mcq', 4, 'أيّ العبارات الآتية تصف ملح إبسوم وصفًا صحيحًا؟', null, '["بلورات من كبريتات الماغنسيوم تُستعمل في صنع الأواني غير اللاصقة","غاز ينتج من احتراق الفحم ويسبب المطر الحمضي","بلورات من أكسيد الماغنسيوم تُستعمل لتخفيف الحموضة","بلورات من كبريتات الماغنسيوم تُستعمل مغذيًا للنباتات"]'::jsonb, 'فهم', 'حكم على عبارات', 'متوسط', 'الكتاب ص 65 — ملح إبسوم'),
('mcq', 5, 'ما عدد جزيئات الماء المرتبطة بكل وحدة صيغة من كبريتات الماغنسيوم في ملح إبسوم؟', null, '["4","1","7","14"]'::jsonb, 'تذكر', 'قراءة صيغة', 'متوسط', 'الكتاب ص 65 — ملح إبسوم'),
('mcq', 6, 'من تفاعل أي مادتين ينتج ملح كبريتات الماغنسيوم الذي يُعرف ملح إبسوم بلوراته المائية؟', null, '["ثالث أكسيد الكبريت SO₃ وأكسيد الماغنسيوم MgO","ثاني أكسيد الكربون CO₂ وأكسيد الماغنسيوم MgO","ثالث أكسيد الكبريت SO₃ وأكسيد الكالسيوم CaO","حمض الكبريتيك H₂SO₄ وفلز الكالسيوم Ca"]'::jsonb, 'تذكر', 'استرجاع متفاعلات', 'متوسط', 'الكتاب ص 64–65 — تفاعل SO₃ مع MgO وملح إبسوم'),
('mcq', 7, 'ما عدد ذرات الأكسجين في وحدة صيغة واحدة من ملح إبسوم MgSO₄·7H₂O؟', null, '["4","11","7","28"]'::jsonb, 'تطبيق', 'حساب من صيغة', 'صعب', 'الكتاب ص 65 — ملح إبسوم'),
('essay', 1, 'ما ملح إبسوم؟ اذكر اسمه الكيميائي وصيغته، واذكر استعمالين له.', null, null, 'تذكر', 'تعريف بالصيغة والاستعمالات', 'سهل', 'الكتاب ص 65 — ملح إبسوم'),
('essay', 2, 'اكتب معادلة التفاعل الذي ينتج كبريتات الماغنسيوم كما وردت في الكتاب، ثم وضّح الفرق بين الناتج MgSO₄ وصيغة ملح إبسوم MgSO₄·7H₂O، وماذا يعني الرمز 7H₂O.', null, null, 'فهم', 'كتابة معادلة وتوضيح', 'متوسط', 'الكتاب ص 64–65 — تفاعل SO₃ مع MgO وملح إبسوم'),
('essay', 3, 'يُعد تفاعل SO₃ مع MgO مهمًا من ناحيتين: صناعية (إنتاج ملح إبسوم) وبيئية. وضّح الناحيتين، مبينًا ما يحدث لغاز SO₃ إذا لم يُنتزع من غازات المداخن.', null, null, 'فهم', 'توضيح تطبيقات', 'صعب', 'الكتاب ص 65 — ملح إبسوم')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O19') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'ملح إبسوم بلورات من ملح كبريتات الماغنسيوم صيغتها كما في الكتاب MgSO₄·7H₂O.', '["","هذه صيغة كبريتيت الماغنسيوم المائية (SO₃²⁻)، وملح إبسوم كبريتات (SO₄²⁻).","هذه صيغة هيدروكسيد لا كبريتات، وملح إبسوم كبريتات الماغنسيوم.","ملح إبسوم ملح للماغنسيوم لا للكالسيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.595Z"}'::jsonb),
('mcq', 2, 1, 'يذكر الكتاب أن تفاعل SO₃ مع MgO ينتج بلورات من ملح كبريتات الماغنسيوم تُعرف بملح إبسوم MgSO₄·7H₂O، أي كبريتات ماغنسيوم مرتبطة بسبعة جزيئات ماء.', '["ملح إبسوم يحتوي على أيون الكبريتات SO₄²⁻ لا الكربونات.","","أكسيد الماغنسيوم MgO أحد المتفاعلين المكوّنين لملح إبسوم وليس الملح نفسه.","ملح إبسوم ملح للماغنسيوم لا للكالسيوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.595Z"}'::jsonb),
('mcq', 3, 2, 'يذكر الكتاب أن لملح إبسوم استعمالات كثيرة، منها تخفيف آلام العضلات، وأنه مغذٍّ للنباتات.', '["لم يذكر الكتاب هذا الاستعمال لملح إبسوم.","تسليك المصارف استعمال لهيدروكسيد الصوديوم NaOH كما في الكتاب، لا لملح إبسوم.","","تنظيف السيراميك استعمال لحمض الهيدروكلوريك HCl كما في الكتاب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.595Z"}'::jsonb),
('mcq', 4, 3, 'ملح إبسوم بلورات من كبريتات الماغنسيوم MgSO₄·7H₂O، ومن استعمالاته أنه مغذٍّ للنباتات ويخفف آلام العضلات.', '["صنع الأواني غير اللاصقة يرتبط بمركبات الفلور المصنوعة من فلوريد الهيدروجين، لا بملح إبسوم.","الغاز المسبب للمطر الحمضي هو SO₃، أما ملح إبسوم فمادة صلبة تنتج من انتزاعه.","ملح إبسوم كبريتات الماغنسيوم لا أكسيد الماغنسيوم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.595Z"}'::jsonb),
('mcq', 5, 2, 'صيغة ملح إبسوم MgSO₄·7H₂O، والرقم 7 قبل H₂O يعني سبعة جزيئات ماء لكل وحدة صيغة MgSO₄.', '["الرقم 4 هو عدد ذرات الأكسجين في أيون الكبريتات SO₄²⁻ لا عدد جزيئات الماء.","الصيغة تبين 7 جزيئات ماء لا جزيئًا واحدًا.","","الرقم 14 عدد ذرات الهيدروجين في 7H₂O لا عدد جزيئات الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.596Z"}'::jsonb),
('mcq', 6, 0, 'يذكر الكتاب التفاعل SO₃(g) + MgO(s) → MgSO₄(s)، وأنه ينتج بلورات من ملح كبريتات الماغنسيوم تُعرف باسم ملح إبسوم.', '["","CO₂ مع MgO يكوّن كربونات لا كبريتات، والكتاب يذكر SO₃.","تفاعل SO₃ مع CaO ينتج كبريتات الكالسيوم لا كبريتات الماغنسيوم.","هذا التفاعل ينتج كبريتات الكالسيوم وغاز الهيدروجين، لا ملح إبسوم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.596Z"}'::jsonb),
('mcq', 7, 1, 'ذرات الأكسجين = 4 (في SO₄) + 7 × 1 (في 7H₂O) = 11 ذرة.', '["هذا عدد ذرات الأكسجين في أيون الكبريتات فقط، مع إهمال جزيئات الماء السبعة.","","هذا عدد ذرات الأكسجين في جزيئات الماء فقط، مع إهمال أكسجين الكبريتات.","هذا ناتج ضرب 4 × 7 خطأً، والصحيح جمع أكسجين الكبريتات وأكسجين الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.596Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ملح إبسوم: بلورات من ملح كبريتات الماغنسيوم المائية، صيغته MgSO₄·7H₂O. من استعمالاته: تخفيف آلام العضلات، وهو مغذٍّ للنباتات.', '["الاسم: كبريتات الماغنسيوم (المائية)","الصيغة MgSO₄·7H₂O","تخفيف آلام العضلات","مغذٍّ للنباتات"]'::jsonb, '[]'::jsonb, '[{"element":"الاسم الكيميائي","marks":1},{"element":"الصيغة","marks":1},{"element":"استعمالان","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"اسم وصيغة واستعمالان صحيحة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة الصيغة MgSO₃·7H₂O","عدّه ملحًا للكالسيوم","ذكر استعمالات مواد أخرى كتسليك المصارف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.596Z"}'::jsonb),
('essay', 2, null::int, null, null, 'SO₃(g) + MgO(s) → MgSO₄(s). الناتج MgSO₄ كبريتات ماغنسيوم لا ماء فيها، أما ملح إبسوم فبلورات كبريتات الماغنسيوم مرتبطة بالماء، ويعني الرمز 7H₂O أن كل وحدة صيغة من MgSO₄ في البلورة يرتبط بها سبعة جزيئات ماء.', '["المعادلة الصحيحة بالحالات","MgSO₄ دون ماء","ملح إبسوم بلورات مائية","7H₂O: سبعة جزيئات ماء لكل وحدة صيغة"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"الفرق بين MgSO₄ وملح إبسوم","marks":1},{"element":"معنى 7H₂O","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"معادلة صحيحة وفرق ومعنى صحيحان"},{"level":"2 درجتان","description":"معادلة صحيحة مع أحد العنصرين الآخرين"},{"level":"1 درجة","description":"معادلة صحيحة فقط أو معنى 7H₂O فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة SO₂ بدل SO₃ في المعادلة","تفسير 7H₂O بأنها سبع ذرات هيدروجين","عدّ MgSO₄ وملح إبسوم المادة نفسها بالصيغة نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.596Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الناحية الأولى: ينتج التفاعل SO₃ + MgO → MgSO₄ بلورات ملح كبريتات الماغنسيوم المعروفة بملح إبسوم MgSO₄·7H₂O، الذي يُستعمل لتخفيف آلام العضلات ومغذيًا للنباتات. الناحية البيئية: عند حقن MgO في الغازات الخارجة من مداخن محطات توليد الطاقة الكهربائية العاملة بالفحم الحجري يتفاعل مع SO₃ وينتزعه من الغازات العادمة قبل خروجها إلى الجو. وإذا تُرك SO₃ لينتشر في الغلاف الجوي اتحد مع الماء في الهواء مكوّنًا حمض الكبريتيك الذي يسقط على الأرض مطرًا حمضيًا.', '["إنتاج ملح إبسوم واستعمالاته","حقن MgO في غازات مداخن محطات الفحم لانتزاع SO₃","SO₃ + H₂O → H₂SO₄ مطر حمضي إن لم يُنتزع"]'::jsonb, '[]'::jsonb, '[{"element":"الناحية الصناعية واستعمالات الملح","marks":1},{"element":"الناحية البيئية","marks":1},{"element":"مصير SO₃ إن لم يُنتزع","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"توضيح كامل للناحيتين ومصير SO₃"},{"level":"2 درجتان","description":"توضيح ناحيتين دون مصير SO₃ أو العكس"},{"level":"1 درجة","description":"توضيح ناحية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن SO₃ يكوّن H₂CO₃","عدّ MgO الغاز الملوث","إغفال أن الناتج ملح صلب يُنتزع به SO₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.597Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O19') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L1-O20'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في التفاعل: SO₃(g) + MgO(s) → MgSO₄(s)، ما الذي يمثل حمض لويس؟', null, '["أيون الأكسيد O²⁻","أيون الماغنسيوم Mg²⁺","كبريتات الماغنسيوم MgSO₄","جزيء ثالث أكسيد الكبريت SO₃"]'::jsonb, 'فهم', 'تحديد الدور', 'سهل', 'الكتاب ص 64 — مانحات ومستقبلات أزواج الإلكترونات: تفاعل SO₃ مع MgO'),
('mcq', 2, 'ما قاعدة لويس في تفاعل ثالث أكسيد الكبريت مع أكسيد الماغنسيوم الذي ينتج كبريتات الماغنسيوم؟', null, '["جزيء ثالث أكسيد الكبريت SO₃","ذرة الكبريت في MgSO₄","أيون الأكسيد O²⁻ من MgO","جزيء الماء في ملح إبسوم"]'::jsonb, 'فهم', 'تحديد الدور', 'سهل', 'الكتاب ص 64 — مانحات ومستقبلات أزواج الإلكترونات: تفاعل SO₃ مع MgO'),
('mcq', 3, 'لماذا يُصنَّف SO₃ حمض لويس في تفاعله مع MgO؟', null, '["لأنه يستقبل زوجًا من الإلكترونات من أيون الأكسيد","لأنه يمنح أيون هيدروجين لأيون الأكسيد","لأنه يعطي زوجًا من الإلكترونات لأيون الأكسيد","لأنه ينتج أيونات H⁺ عند ذوبانه في الماء"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 64 — مانحات ومستقبلات أزواج الإلكترونات: تفاعل SO₃ مع MgO'),
('mcq', 4, 'ما الأيون الذي يتكوّن من ارتباط حمض لويس بقاعدة لويس في تفاعل SO₃ مع MgO؟', null, '["أيون الكبريتيت SO₃²⁻","أيون الكبريتات SO₄²⁻","أيون الهيدروكسيد OH⁻","أيون الهيدرونيوم H₃O⁺"]'::jsonb, 'فهم', 'تحديد ناتج', 'متوسط', 'الكتاب ص 64 — مانحات ومستقبلات أزواج الإلكترونات: تفاعل SO₃ مع MgO'),
('mcq', 5, 'لماذا لا يمكن تفسير تفاعل SO₃ مع MgO بوصفه تفاعل حمض وقاعدة وفق نظرية برونستد – لوري؟', null, '["لأنه لا يحدث فيه انتقال لأيون الهيدروجين H⁺","لأن MgO مادة صلبة لا تذوب في الماء","لأن SO₃ يمنح أيون H⁺ لأيون الأكسيد","لأن الناتج ملح لا يحتوي على أيونات"]'::jsonb, 'تحليل', 'تعليل', 'صعب', 'الكتاب ص 64 — مانحات ومستقبلات أزواج الإلكترونات: تفاعل SO₃ مع MgO'),
('mcq', 6, 'ما الفائدة البيئية من حقن أكسيد الماغنسيوم في الغازات الخارجة من مداخن محطات الطاقة العاملة بالفحم؟', null, '["انتزاع CO₂ من الغازات لمنع تكوّن الكهوف","إنتاج حمض الكبريتيك لاستعماله في الصناعة","تقليل كمية بخار الماء الخارج من أبراج التبريد","انتزاع SO₃ من الغازات قبل أن يكوّن المطر الحمضي"]'::jsonb, 'فهم', 'تفسير تطبيق', 'متوسط', 'الكتاب ص 65 — ملح إبسوم والشكل 2-10'),
('mcq', 7, 'أيّ العبارات الآتية تصف تكوّن الرابطة الجديدة في تفاعل SO₃ مع O²⁻ وصفًا صحيحًا؟', null, '["رابطة تساهمية بين S وO يأتي زوج إلكتروناتها كله من SO₃","رابطة أيونية بين Mg²⁺ وSO₃ بانتقال أيون H⁺","رابطة تساهمية بين S وO يأتي زوج إلكتروناتها كله من O²⁻","رابطة تساهمية بين S وO يسهم فيها كل منهما بإلكترون"]'::jsonb, 'تحليل', 'تحليل آلية', 'صعب', 'الكتاب ص 64 — مانحات ومستقبلات أزواج الإلكترونات: تفاعل SO₃ مع MgO'),
('essay', 1, 'وضّح تكوين كبريتات الماغنسيوم (التي تُعرف بلوراتها بملح إبسوم) بوصفه تفاعل حمض لويس مع قاعدة لويس: اكتب المعادلة، وحدد حمض لويس وقاعدة لويس، وبيّن ما يحدث لزوج الإلكترونات.', null, null, 'فهم', 'توضيح تفاعل', 'متوسط', 'الكتاب ص 64 — مانحات ومستقبلات أزواج الإلكترونات: تفاعل SO₃ مع MgO'),
('essay', 2, 'قارن بين تفاعل SO₃ مع MgO وتفاعل BF₃ مع NH₃ من حيث: حمض لويس، وقاعدة لويس، وسبب عدّ كل منهما تفاعل حمض وقاعدة وفق لويس لا وفق برونستد – لوري.', null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 64 — مانحات ومستقبلات أزواج الإلكترونات: تفاعل SO₃ مع MgO'),
('essay', 3, 'اكتب سلسلة سبب ونتيجة تبين: (1) ما يحدث لغاز SO₃ إذا خرج من مداخن محطات الفحم إلى الجو، (2) كيف يمنع حقن MgO ذلك، مع تحديد دور كل من SO₃ وO²⁻ وفق نظرية لويس.', null, null, 'تطبيق', 'سلسلة سبب ونتيجة', 'سهل', 'الكتاب ص 65 — ملح إبسوم والشكل 2-10')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O20') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'يذكر الكتاب أن حمض لويس في هذا التفاعل هو جزيء SO₃، إذ يستقبل زوج إلكترونات من قاعدة لويس (أيون الأكسيد O²⁻).', '["أيون O²⁻ يعطي زوج الإلكترونات فهو قاعدة لويس لا حمضها.","لم يحدد الكتاب Mg²⁺ طرفًا في زوج الحمض والقاعدة؛ فالزوج هو SO₃ وO²⁻.","MgSO₄ ناتج التفاعل لا أحد المتفاعلين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T09:21:20.597Z"}'::jsonb),
('mcq', 2, 2, 'قاعدة لويس هي المادة التي تعطي زوجًا من الإلكترونات، وفي هذا التفاعل يعطي أيون الأكسيد O²⁻ من أكسيد الماغنسيوم زوج إلكترونات لجزيء SO₃.', '["SO₃ يستقبل زوج الإلكترونات فهو حمض لويس.","ذرة الكبريت جزء من الناتج ومن حمض لويس SO₃، وليست قاعدة لويس.","","التفاعل بين SO₃ وMgO لا يشارك فيه الماء بوصفه قاعدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.597Z"}'::jsonb),
('mcq', 3, 0, 'حمض لويس مادة تستقبل زوجًا من الإلكترونات، وSO₃ يستقبل زوج إلكترونات من أيون O²⁻ فيتكوّن أيون الكبريتات SO₄²⁻.', '["","لا يحتوي SO₃ على هيدروجين، فلا يمنح أيون H⁺.","إعطاء زوج الإلكترونات صفة قاعدة لويس، والذي يعطيه هنا هو O²⁻.","هذا تعريف أرهينيوس للحمض، والتفاعل هنا لا يحدث في الماء ولا ينتج H⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T09:21:20.598Z"}'::jsonb),
('mcq', 4, 1, 'يرتبط SO₃ بأيون O²⁻ الذي يعطيه زوج إلكترونات، فيتكوّن أيون الكبريتات SO₄²⁻، كما في تراكيب لويس في الكتاب.', '["SO₃²⁻ يحتوي على ثلاث ذرات أكسجين، والناتج من SO₃ مع O²⁻ فيه أربع ذرات أكسجين.","","لا يحتوي التفاعل على هيدروجين، فلا يتكوّن OH⁻.","H₃O⁺ يتكوّن في تفاعلات الأحماض مع الماء، وهذا التفاعل لا هيدروجين فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T09:21:20.598Z"}'::jsonb),
('mcq', 5, 0, 'تعتمد نظرية برونستد – لوري على منح أيون H⁺ واستقباله، والتفاعل بين SO₃ وMgO لا يحتوي على هيدروجين أصلًا، بل يقوم على إعطاء زوج إلكترونات واستقباله، فتفسره نظرية لويس.', '["","حالة المادة ليست سبب عدم انطباق النظرية؛ السبب غياب انتقال أيون H⁺.","لا يحتوي SO₃ على هيدروجين، فلا يمنح أيون H⁺.","MgSO₄ مركب أيوني، وسبب عدم انطباق النظرية غياب انتقال H⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T09:21:20.598Z"}'::jsonb),
('mcq', 6, 3, 'يتفاعل MgO (قاعدة لويس) مع SO₃ (حمض لويس) فينتزعه من الغازات العادمة، فلا ينتشر في الجو ليتحد مع الماء مكوّنًا حمض الكبريتيك والمطر الحمضي.', '["التفاعل المقصود في الكتاب مع SO₃ لا مع CO₂.","الهدف منع تكوّن حمض الكبريتيك في الجو، والناتج ملح MgSO₄.","بخار الماء من أبراج التبريد لا علاقة له بتفاعل MgO مع SO₃.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.598Z"}'::jsonb),
('mcq', 7, 2, 'قاعدة لويس O²⁻ تعطي زوجًا من إلكتروناتها غير المشتركة، فيستقبله SO₃ لتتكوّن رابطة تساهمية بين ذرة الكبريت وذرة الأكسجين الجديدة، وكلا الإلكترونين من O²⁻.', '["SO₃ هو مستقبل زوج الإلكترونات (حمض لويس)، فالزوج لا يأتي منه.","لا يوجد هيدروجين في التفاعل، والرابطة الجديدة بين S وO²⁻.","","في تفاعل حمض لويس مع قاعدة لويس يأتي الزوج كاملًا من القاعدة لا إلكترون من كل ذرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.599Z"}'::jsonb),
('essay', 1, null::int, null, null, 'SO₃(g) + MgO(s) → MgSO₄(s). حمض لويس: SO₃ (مستقبل لزوج الإلكترونات). قاعدة لويس: أيون الأكسيد O²⁻ من MgO (مانح لزوج الإلكترونات). يعطي أيون O²⁻ زوجًا من إلكتروناته غير المشتركة لذرة الكبريت في SO₃، فتتكوّن رابطة جديدة وينتج أيون الكبريتات SO₄²⁻، وتتكوّن بلورات كبريتات الماغنسيوم (ملح إبسوم MgSO₄·7H₂O).', '["المعادلة","SO₃ حمض لويس","O²⁻ قاعدة لويس","O²⁻ يعطي زوج الإلكترونات لـ SO₃ فيتكوّن SO₄²⁻"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"تحديد حمض لويس","marks":1},{"element":"تحديد قاعدة لويس","marks":1},{"element":"مسار زوج الإلكترونات والناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة وتحديد صحيح ومسار زوج الإلكترونات"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"تحديد الحمض والقاعدة فقط"},{"level":"1 درجة","description":"المعادلة فقط أو تحديد واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس دوري SO₃ وO²⁻","عدّ MgO كله أو Mg²⁺ قاعدة لويس دون ذكر O²⁻","القول إن SO₃ يمنح الإلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.599Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تفاعل SO₃ + MgO → MgSO₄: حمض لويس SO₃، وقاعدة لويس O²⁻. تفاعل BF₃ + NH₃ → BF₃NH₃: حمض لويس BF₃ (لذرة البورون ستة إلكترونات تكافؤ ومدار فارغ يستقبل الزوج)، وقاعدة لويس NH₃ (تعطي زوجها غير المشترك). في التفاعلين لا ينتقل أيون H⁺، بل يُعطى زوج إلكترونات ويُستقبل؛ لذا لا تفسرهما نظرية برونستد – لوري وتفسرهما نظرية لويس.', '["SO₃ حمض وO²⁻ قاعدة","BF₃ حمض وNH₃ قاعدة","لا انتقال لأيون H⁺ في التفاعلين","إعطاء زوج إلكترونات واستقباله"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الحمض والقاعدة في التفاعل الأول","marks":1},{"element":"تحديد الحمض والقاعدة في التفاعل الثاني","marks":1},{"element":"السبب: لا انتقال لـ H⁺ بل زوج إلكترونات","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح في التفاعلين وتعليل كامل"},{"level":"3 درجات","description":"تحديد صحيح مع تعليل ناقص"},{"level":"2 درجتان","description":"تحديد صحيح دون تعليل"},{"level":"1 درجة","description":"تحديد صحيح في تفاعل واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ NH₃ حمضًا لاحتوائه على هيدروجين","القول إن NH₃ تستقبل H⁺ في هذا التفاعل","عدّ BF₃ قاعدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T09:21:20.599Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) دون معالجة: SO₃ يخرج إلى الجو ← يتحد مع الماء في الهواء: SO₃ + H₂O → H₂SO₄ ← يسقط حمض الكبريتيك مطرًا حمضيًا. (2) مع حقن MgO: يتفاعل MgO مع SO₃: SO₃ + MgO → MgSO₄ ← يُنتزع SO₃ من الغازات العادمة ويتحول إلى ملح صلب (كبريتات الماغنسيوم) ← لا يتكوّن المطر الحمضي. الأدوار: SO₃ حمض لويس يستقبل زوج إلكترونات، وO²⁻ قاعدة لويس تعطيه.', '["SO₃ + H₂O → H₂SO₄ مطر حمضي","SO₃ + MgO → MgSO₄ ينتزع SO₃","SO₃ حمض لويس","O²⁻ قاعدة لويس"]'::jsonb, '[]'::jsonb, '[{"element":"السلسلة دون معالجة","marks":1},{"element":"السلسلة مع حقن MgO","marks":1},{"element":"دورا SO₃ وO²⁻","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"سلسلتان صحيحتان مع الأدوار"},{"level":"2 درجتان","description":"سلسلتان صحيحتان دون الأدوار، أو سلسلة مع الأدوار"},{"level":"1 درجة","description":"سلسلة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن MgO يتفاعل مع حمض الكبريتيك بعد تكوّنه في الجو","عكس دوري SO₃ وO²⁻","كتابة H₂SO₃ ناتجًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.599Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
