from (values
('mcq', 1, 'ما الذي يميز المحلول الحمضي من حيث تراكيز الأيونات؟', null, '["يحتوي على أيونات OH⁻ أكثر من أيونات H⁺","يحتوي على أيونات H⁺ أكثر من أيونات OH⁻","يحتوي على تركيزين متساويين من H⁺ وOH⁻","يحتوي على أيونات H⁺ ولا يحتوي على OH⁻ إطلاقًا"]'::jsonb, 'تذكر', 'تعريف بالمقارنة', 'سهل', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)'),
('mcq', 2, 'كيف تكون تراكيز أيونات الهيدروجين وأيونات الهيدروكسيد في المحلول المتعادل؟', null, '["[H⁺] > [OH⁻]","[H⁺] < [OH⁻]","[H⁺] = [OH⁻] = صفر","[H⁺] = [OH⁻]"]'::jsonb, 'تذكر', 'تعريف بالمقارنة', 'سهل', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)'),
('mcq', 3, 'يبين الجدول تراكيز أيونات H⁺ وOH⁻ في أربعة محاليل مائية. أيّ هذه المحاليل قاعدي؟', '{"headers":["المحلول","[H⁺] (M)","[OH⁻] (M)"],"rows":[["A","1×10⁻³","1×10⁻¹¹"],["B","1×10⁻⁷","1×10⁻⁷"],["C","1×10⁻¹⁰","1×10⁻⁴"],["D","1×10⁻⁵","1×10⁻⁹"]]}'::jsonb, '["A","B","C","D"]'::jsonb, 'تطبيق', 'تفسير بيانات جدول', 'متوسط', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)'),
('mcq', 4, 'يبين الشكل 2-3 في الكتاب تغيّر [H⁺] و[OH⁻] معًا. عند الانتقال من المحلول الحمضي نحو المحلول القاعدي، ماذا يحدث للتركيزين؟', null, '["يقل [H⁺] ويزداد [OH⁻]","يزداد [H⁺] ويقل [OH⁻]","يزداد التركيزان معًا","يبقى [H⁺] ثابتًا ويزداد [OH⁻]"]'::jsonb, 'فهم', 'تفسير علاقة', 'متوسط', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)'),
('mcq', 5, 'لماذا يُعد الماء النقي متعادلًا؟', null, '["لأنه لا يحتوي على أيونات H⁺ ولا OH⁻ إطلاقًا","لأنه ينتج أيونات H⁺ أكثر من أيونات OH⁻","لأنه ينتج أيونات OH⁻ أكثر من أيونات H⁺","لأن تأينه الذاتي ينتج أعدادًا متساوية من أيونات H⁺ وOH⁻"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)'),
('mcq', 6, 'أيّ العبارات الآتية صحيحة بشأن المحلول القاعدي؟', null, '["يحتوي على أيونات OH⁻ فقط، ولا يحتوي على H⁺","يحتوي على أيونات H⁺ وOH⁻ معًا، لكن OH⁻ أكثر","يحتوي على أيونات H⁺ وOH⁻ معًا، لكن H⁺ أكثر","يحتوي على تركيزين متساويين من H⁺ وOH⁻"]'::jsonb, 'فهم', 'حكم على عبارات', 'صعب', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)'),
('mcq', 7, 'محلول مائي تركيز أيونات الهيدروكسيد فيه 1×10⁻⁶ M، وتركيز أيونات الهيدروجين فيه 1×10⁻⁸ M. ما نوع هذا المحلول؟', null, '["قاعدي؛ لأن [OH⁻] أكبر من [H⁺]","حمضي؛ لأن [H⁺] أكبر من [OH⁻]","متعادل؛ لأن التركيزين صغيران جدًا","لا يمكن تحديد نوعه دون معرفة المذاب"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)'),
('essay', 1, 'قارن بين المحلول الحمضي والمحلول القاعدي والمحلول المتعادل من حيث العلاقة بين تركيز أيونات الهيدروجين H⁺ وتركيز أيونات الهيدروكسيد OH⁻، واذكر مثالًا على محلول متعادل.', null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)'),
('essay', 2, 'يبين الجدول تراكيز أيونات H⁺ وOH⁻ في أربعة محاليل. صنّف كل محلول إلى حمضي أو قاعدي أو متعادل، مع التعليل.', '{"headers":["المحلول","[H⁺] (M)","[OH⁻] (M)"],"rows":[["A","1×10⁻³","1×10⁻¹¹"],["B","1×10⁻⁷","1×10⁻⁷"],["C","1×10⁻¹⁰","1×10⁻⁴"],["D","1×10⁻⁵","1×10⁻⁹"]]}'::jsonb, null, 'تطبيق', 'تصنيف بيانات', 'متوسط', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)'),
('essay', 3, 'انطلاقًا من التأين الذاتي للماء، فسّر لماذا يكون الماء النقي متعادلًا، ثم تنبأ بما يحدث لكل من [H⁺] و[OH⁻] ولنوع المحلول عند إذابة كمية من غاز HCl في الماء النقي، مع التعليل.', null, null, 'تحليل', 'تفسير وتنبؤ', 'صعب', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد (الشكل 2-3)')
