from (values
('mcq', 1, 1, 'يذكر الكتاب أن المحلول الحمضي يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد، أي [H⁺] > [OH⁻].', '["هذا وصف المحلول القاعدي لا الحمضي.","","تساوي التركيزين صفة المحلول المتعادل.","المحاليل المائية جميعها تحتوي على الأيونين معًا، والمحلول الحمضي يتميز بزيادة H⁺ لا بغياب OH⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.600Z"}'::jsonb),
('mcq', 2, 3, 'يحتوي المحلول المتعادل على تركيزين متساويين من أيونات الهيدروجين وأيونات الهيدروكسيد، فلا يكون حمضيًا ولا قاعديًا.', '["زيادة [H⁺] على [OH⁻] تجعل المحلول حمضيًا.","زيادة [OH⁻] على [H⁺] تجعل المحلول قاعديًا.","المحلول المتعادل يحتوي على الأيونين بتركيزين متساويين وليسا صفرًا؛ فالماء النقي نفسه يتأين ذاتيًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.600Z"}'::jsonb),
('mcq', 3, 2, 'في المحلول C: [OH⁻] = 1×10⁻⁴ M أكبر من [H⁺] = 1×10⁻¹⁰ M، والمحلول الذي يحتوي على OH⁻ أكثر من H⁺ قاعدي.', '["في A: [H⁺] = 1×10⁻³ أكبر من [OH⁻] = 1×10⁻¹¹، فهو حمضي.","في B: التركيزان متساويان (1×10⁻⁷)، فهو متعادل.","","في D: [H⁺] = 1×10⁻⁵ أكبر من [OH⁻] = 1×10⁻⁹، فهو حمضي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T09:21:20.601Z"}'::jsonb),
('mcq', 4, 0, 'يوضح الشكل 2-3 أنه عندما يقل [H⁺] (نحو جهة القاعدية) تزداد قيمة [OH⁻]، والعكس؛ فالتركيزان يتغيران في اتجاهين متعاكسين.', '["","هذا ما يحدث عند الانتقال من القاعدية نحو الحمضية، لا العكس.","التركيزان يتغيران في اتجاهين متعاكسين لا في الاتجاه نفسه.","لا يبقى [H⁺] ثابتًا؛ فنقصانه هو ما يرافق زيادة [OH⁻]."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.601Z"}'::jsonb),
('mcq', 5, 3, 'ينتج الماء النقي في التأين الذاتي (H₂O ⇌ H⁺ + OH⁻) أعدادًا متساوية من أيونات H⁺ وOH⁻، فيتساوى التركيزان ويكون متعادلًا.', '["الماء النقي يتأين ذاتيًا فيحتوي على الأيونين بتركيزين صغيرين متساويين.","لو زادت أيونات H⁺ لكان الماء حمضيًا، والتأين الذاتي ينتج أعدادًا متساوية.","لو زادت أيونات OH⁻ لكان الماء قاعديًا، والتأين الذاتي ينتج أعدادًا متساوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.601Z"}'::jsonb),
('mcq', 6, 1, 'تحتوي المحاليل المائية جميعها على أيونات H⁺ وOH⁻، والمحلول القاعدي يتميز بأن تركيز OH⁻ فيه أكبر من تركيز H⁺.', '["المحلول القاعدي يحتوي على أيونات H⁺ أيضًا لكن بتركيز أقل من OH⁻.","","زيادة H⁺ على OH⁻ صفة المحلول الحمضي.","تساوي التركيزين صفة المحلول المتعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.601Z"}'::jsonb),
('mcq', 7, 0, 'العدد 1×10⁻⁶ أكبر من 1×10⁻⁸ بمئة مرة؛ إذن [OH⁻] > [H⁺] والمحلول قاعدي.', '["","هذا خطأ في مقارنة الأسس السالبة؛ فـ 10⁻⁸ أصغر من 10⁻⁶ لا أكبر منه.","صغر التركيزين لا يعني تعادل المحلول؛ المعيار تساويهما، وهما هنا غير متساويين.","تكفي مقارنة [H⁺] و[OH⁻] لتحديد نوع المحلول دون معرفة المذاب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T09:21:20.601Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحلول الحمضي: [H⁺] > [OH⁻]. المحلول القاعدي: [OH⁻] > [H⁺]. المحلول المتعادل: [H⁺] = [OH⁻]، ومثاله الماء النقي. وجميع المحاليل المائية تحتوي على الأيونين، والكميات النسبية لهما هي التي تحدد نوع المحلول.', '["الحمضي [H⁺] > [OH⁻]","القاعدي [OH⁻] > [H⁺]","المتعادل [H⁺] = [OH⁻]","مثال: الماء النقي"]'::jsonb, '[]'::jsonb, '[{"element":"الحمضي","marks":1},{"element":"القاعدي","marks":1},{"element":"المتعادل","marks":1},{"element":"المثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة ومثال صحيح"},{"level":"3 درجات","description":"مقارنة كاملة دون مثال"},{"level":"2 درجتان","description":"علاقتان صحيحتان"},{"level":"1 درجة","description":"علاقة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحلول الحمضي لا يحتوي على OH⁻","عكس العلاقة في القاعدي","عدّ المحلول المتعادل خاليًا من الأيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T09:21:20.602Z"}'::jsonb),
('essay', 2, null::int, null, null, 'A: [H⁺] = 1×10⁻³ > [OH⁻] = 1×10⁻¹¹ ← حمضي. B: [H⁺] = [OH⁻] = 1×10⁻⁷ ← متعادل. C: [OH⁻] = 1×10⁻⁴ > [H⁺] = 1×10⁻¹⁰ ← قاعدي. D: [H⁺] = 1×10⁻⁵ > [OH⁻] = 1×10⁻⁹ ← حمضي. التعليل: المحلول الذي فيه H⁺ أكثر حمضي، وOH⁻ أكثر قاعدي، والمتساويان متعادل.', '["A حمضي","B متعادل","C قاعدي","D حمضي","التعليل بمقارنة التركيزين"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف A","marks":1},{"element":"تصنيف B","marks":1},{"element":"تصنيف C","marks":1},{"element":"تصنيف D","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للأربعة مع التعليل"},{"level":"4 درجات","description":"تصنيف صحيح للأربعة دون تعليل"},{"level":"3 درجات","description":"تصنيف صحيح لثلاثة"},{"level":"2 درجتان","description":"تصنيف صحيح لاثنين"},{"level":"1 درجة","description":"تصنيف صحيح لواحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخطأ في مقارنة الأسس السالبة (عدّ 10⁻¹¹ أكبر من 10⁻³)","عدّ D متعادلًا لقرب قيمه","التصنيف بقيمة [H⁺] وحدها دون مقارنة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T09:21:20.602Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التأين الذاتي: H₂O(l) + H₂O(l) ⇌ H₃O⁺(aq) + OH⁻(aq) (أو H₂O ⇌ H⁺ + OH⁻)، وينتج أعدادًا متساوية من H⁺ وOH⁻، فيتساوى التركيزان ويكون الماء النقي متعادلًا. عند إذابة HCl يتأين: HCl → H⁺ + Cl⁻، فيزداد [H⁺]، ويقل [OH⁻] لأن التركيزين يتغيران في اتجاهين متعاكسين (الشكل 2-3)، فيصبح [H⁺] > [OH⁻] ويصير المحلول حمضيًا.', '["معادلة التأين الذاتي","أعداد متساوية ← متعادل","HCl يزيد [H⁺]","[OH⁻] يقل","المحلول يصبح حمضيًا"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة التأين الذاتي وتفسير التعادل","marks":2},{"element":"أثر HCl في [H⁺] و[OH⁻]","marks":2},{"element":"الحكم بأن المحلول حمضي مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للتعادل وتنبؤ صحيح بالتغيرات ونوع المحلول"},{"level":"4 درجات","description":"تفسير صحيح مع إغفال نقص [OH⁻]"},{"level":"3 درجات","description":"تفسير التعادل وحكم صحيح دون تحليل التغيرات"},{"level":"2 درجتان","description":"تفسير التعادل فقط"},{"level":"1 درجة","description":"حكم صحيح بأن المحلول يصبح حمضيًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن [OH⁻] يبقى ثابتًا بعد إضافة HCl","القول إن OH⁻ يختفي تمامًا","تفسير تعادل الماء بغياب الأيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.602Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
