('mcq', 7, 'رتب طالب أنواع الروابط الآتية في جزيئات مختلفة. أي رابطة تجعل ذرة الهيدروجين قابلة للتأين في الماء؟', null, '["C–H في البنزين","C–H في مجموعة CH₃ في حمض الإيثانويك","C–H في الإيثان C₂H₆","O–H في حمض الإيثانويك"]'::jsonb, 'تحليل', 'مقارنة روابط', 'صعب', 'الكتاب ص 62 — ذرات الهيدروجين القابلة للتأين (الشكل 2-9)'),
('essay', 1, 'فسّر لماذا تتأين ذرة الهيدروجين في كل من حمض الإيثانويك وفلوريد الهيدروجين، بينما لا تتأين ذرات الهيدروجين في البنزين.', null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 62 — ذرات الهيدروجين القابلة للتأين (الشكل 2-9)'),
('essay', 2, 'في جزيء حمض الإيثانويك CH₃COOH أربع ذرات هيدروجين. حدّد عدد ذرات الهيدروجين القابلة للتأين، وفسّر لماذا تختلف عن الذرات الأخرى، مع بيان الشحنات الجزئية على ذرتي الرابطة المعنية.', null, null, 'تحليل', 'تحليل بنية', 'متوسط', 'الكتاب ص 62 — ذرات الهيدروجين القابلة للتأين (الشكل 2-9)'),
('essay', 3, 'طبّق مبدأ «قابلية الهيدروجين للتأين تعتمد على قطبية رابطته» لتتنبأ: (أ) بعدد أيونات الهيدروجين التي يمكن أن يمنحها حمض الكربونيك H₂CO₃، علمًا بأن ذرتي الهيدروجين فيه مرتبطتان بذرتي أكسجين، (ب) بما إذا كان الميثان CH₄ (ذرات الهيدروجين الأربع فيه مرتبطة بالكربون) حمضًا، مع التعليل في الحالتين.', null, null, 'تطبيق', 'تنبؤ وتعليل', 'صعب', 'الكتاب ص 62 — ذرات الهيدروجين القابلة للتأين (الشكل 2-9)')
