from (values
('mcq', 1, 2, 'يذكر الكتاب أن ذرة الهيدروجين القابلة للتأين في حمض الإيثانويك مرتبطة بذرة الأكسجين الأعلى كهروسالبية من الهيدروجين، فتكون الرابطة O–H قطبية.', '["ذرات الهيدروجين المرتبطة بالكربون في مجموعة CH₃ هي التي لا تتأين.","لا ترتبط ذرات الهيدروجين بعضها ببعض في جزيء حمض الإيثانويك.","","لا يحتوي حمض الإيثانويك على الفلور؛ فالفلور موجود في HF."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.603Z"}'::jsonb),
('mcq', 2, 0, 'ترتبط ذرة الهيدروجين في HF بذرة الفلور العالية الكهروسالبية، فالرابطة بينهما قطبية، وتصبح ذرة الهيدروجين قابلة للتأين إلى حد ما، فيكون HF حمضًا.', '["","الفلور عالي الكهروسالبية، والرابطة غير القطبية لا تجعل الهيدروجين قابلًا للتأين.","عدد ذرات الهيدروجين لا يحدد الحمضية؛ المعيار قطبية الرابطة التي يشارك فيها الهيدروجين.","الذي يُمنح هو أيون الهيدروجين المرتبط بالفلور، لا الفلور نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.603Z"}'::jsonb),
('mcq', 3, 1, 'يذكر الكتاب أن كل ذرة هيدروجين في البنزين مرتبطة بذرة كربون كهروسالبيتها تساوي تقريبًا كهروسالبية الهيدروجين، فالروابط غير قطبية ولا تتأين ذرات الهيدروجين، فالبنزين ليس حمضًا.', '["الفرق قليل لا كبير، ولو كانت الروابط قطبية لأمكن أن يتأين الهيدروجين.","","لم يعلل الكتاب عدم حمضية البنزين بالذوبان، بل بعدم قطبية الروابط C–H.","كثرة ذرات الهيدروجين لا تمنع التأين؛ المعيار قطبية الرابطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.603Z"}'::jsonb),
('mcq', 4, 3, 'تعتمد قدرة الهيدروجين على التأين على قطبية رابطته؛ فإذا ارتبط بذرة عالية الكهروسالبية مثل O أو F كانت الرابطة قطبية وأمكن أن يتأين.', '["الهيدروجين المرتبط بالكربون لا يتأين لأن الرابطة غير قطبية، كما في البنزين.","CH₃COOH فيه أربع ذرات هيدروجين ويتأين منها واحدة، فالانفراد ليس شرطًا.","يربط الكتاب التأين بالرابطة القطبية مع ذرة عالية الكهروسالبية مثل O وF، لا بالفلزات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.604Z"}'::jsonb),
('mcq', 5, 1, 'الأكسجين أكثر كهروسالبية من الهيدروجين فيجذب إلكترونات الرابطة نحوه ويحمل δ⁻، وتحمل ذرة الهيدروجين δ⁺، كما في الشكل 2-9، وهذا ما يجعلها قابلة للتأين.', '["الذرة الأكثر كهروسالبية تجذب الإلكترونات فتحمل δ⁻ لا δ⁺.","","الأكسجين أكثر كهروسالبية من الهيدروجين لا أقل، ويحمل δ⁻.","الرابطة O–H قطبية لفرق الكهروسالبية بين الذرتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.604Z"}'::jsonb),
('mcq', 6, 2, 'يذكر الكتاب أن كلًّا من H₂SO₄ وH₂CO₃ يستطيع أن يمنح أيوني هيدروجين؛ لأن كليهما يحتوي على ذرتي هيدروجين مرتبطتين مع ذرتي أكسجين بروابط قطبية.', '["ذرتا الهيدروجين في H₂SO₄ مرتبطتان بالأكسجين، والرابطة غير القطبية لا تسمح بالتأين.","عدد ذرات الأكسجين لا يحدد عدد البروتونات؛ المهم أن كل ذرة هيدروجين مرتبطة بأكسجين برابطة قطبية.","","أيونات الهيدروجين هي التي تُمنح، لا ذرة الكبريت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.605Z"}'::jsonb),
('mcq', 7, 3, 'الرابطة O–H قطبية لأن الأكسجين أعلى كهروسالبية من الهيدروجين، فيتأين الهيدروجين المرتبط بها. أما الروابط C–H فغير قطبية لتقارب كهروسالبية الكربون والهيدروجين.', '["الرابطة C–H في البنزين غير قطبية، لذا البنزين ليس حمضًا.","ذرات الهيدروجين الثلاث المرتبطة بالكربون في CH₃ لا تتأين لعدم قطبية الرابطة.","الرابطة C–H غير قطبية في أي مركب لتقارب كهروسالبية الكربون والهيدروجين، فلا يتأين الهيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.605Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في حمض الإيثانويك ترتبط ذرة الهيدروجين القابلة للتأين بذرة الأكسجين الأكثر كهروسالبية منها، فتكون الرابطة O–H قطبية (O تحمل δ⁻ وH تحمل δ⁺)، فتستطيع ذرة الهيدروجين أن تتأين في المحلول. وفي HF ترتبط ذرة الهيدروجين بالفلور العالي الكهروسالبية، فالرابطة قطبية ويتأين الهيدروجين إلى حد ما، لذا HF حمض. أما في البنزين فكل ذرة هيدروجين مرتبطة بذرة كربون كهروسالبيتها تساوي تقريبًا كهروسالبية الهيدروجين، فالروابط C–H غير قطبية ولا تتأين، فالبنزين ليس حمضًا.', '["CH₃COOH: رابطة O–H قطبية لأن O أعلى كهروسالبية","HF: الفلور عالي الكهروسالبية ← رابطة قطبية","C₆H₆: فرق كهروسالبية قليل ← روابط غير قطبية ← لا تأين"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير حمض الإيثانويك","marks":1},{"element":"تفسير HF","marks":1},{"element":"تفسير البنزين","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للمواد الثلاث بالكهروسالبية والقطبية"},{"level":"3 درجات","description":"تفسير صحيح مع نقص في إحدى الحالات"},{"level":"2 درجتان","description":"تفسير البنزين فقط أو الحمضين فقط"},{"level":"1 درجة","description":"ذكر النتيجة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكربون أعلى كهروسالبية بكثير من الهيدروجين","تعليل الحمضية بعدد ذرات الهيدروجين","عكس الشحنات الجزئية في الرابطة O–H"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.605Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ذرة هيدروجين واحدة فقط قابلة للتأين، وهي المرتبطة بذرة الأكسجين في مجموعة COOH. الأكسجين أكثر كهروسالبية من الهيدروجين فيجذب إلكترونات الرابطة فيحمل δ⁻ ويحمل الهيدروجين δ⁺، فالرابطة O–H قطبية والهيدروجين قابل للتأين. أما ذرات الهيدروجين الثلاث الأخرى فمرتبطة بذرة كربون كهروسالبيتها تقارب كهروسالبية الهيدروجين، فالروابط C–H غير قطبية ولا تتأين.', '["عدد الذرات القابلة للتأين = 1","مرتبطة بالأكسجين الأعلى كهروسالبية","O: δ⁻ و H: δ⁺","الثلاث الأخرى مرتبطة بالكربون برابطة غير قطبية"]'::jsonb, '[]'::jsonb, '[{"element":"العدد الصحيح","marks":1},{"element":"تفسير قابلية H المرتبط بـ O","marks":1},{"element":"الشحنات الجزئية","marks":1},{"element":"تفسير عدم تأين H المرتبط بـ C","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة بالعدد والتفسيرين والشحنات"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"العدد وأحد التفسيرين"},{"level":"1 درجة","description":"العدد الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذرات الأربع قابلة للتأين","وضع δ⁺ على الأكسجين","إغفال سبب عدم تأين ذرات CH₃"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.605Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) يمنح H₂CO₃ أيوني هيدروجين؛ لأن كل ذرة هيدروجين مرتبطة بذرة أكسجين أعلى كهروسالبية منها برابطة قطبية، فهو حمض ثنائي البروتونات. (ب) الميثان ليس حمضًا؛ لأن ذرات الهيدروجين الأربع مرتبطة بذرة كربون كهروسالبيتها تقارب كهروسالبية الهيدروجين، فالروابط C–H غير قطبية ولا تتأين (كما في البنزين).', '["H₂CO₃ يمنح أيوني هيدروجين","تعليل: روابط O–H قطبية","CH₄ ليس حمضًا","تعليل: روابط C–H غير قطبية"]'::jsonb, '[]'::jsonb, '[{"element":"التنبؤ لـ H₂CO₃","marks":1},{"element":"تعليل H₂CO₃","marks":1},{"element":"التنبؤ لـ CH₄","marks":1},{"element":"تعليل CH₄","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تنبؤان صحيحان مع تعليل كامل"},{"level":"3 درجات","description":"تنبؤان صحيحان مع تعليل واحد"},{"level":"2 درجتان","description":"تنبؤان صحيحان دون تعليل، أو تنبؤ واحد معلل"},{"level":"1 درجة","description":"تنبؤ واحد صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ CH₄ حمضًا رباعي البروتونات","القول إن H₂CO₃ يمنح ثلاثة أيونات لاحتوائه على ثلاث ذرات أكسجين","التعليل بعدد الذرات لا بالقطبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.606Z"}'::jsonb)
