('essay', 1, 'لخّص تعريف الحمض وتعريف القاعدة في كل من نظرية أرهينيوس ونظرية برونستد – لوري ونظرية لويس في جدول مقارنة.', null, null, 'فهم', 'جدول مقارنة', 'سهل', 'الكتاب ص 63–64 — الجدول 2-2 ملخص النظريات الثلاث للأحماض والقواعد'),
('essay', 2, 'قارن بين النظريات الثلاث من حيث: (أ) ما الذي تركز عليه كل نظرية في تعريفها، (ب) اتساع كل منها، مستشهدًا بمثال يبين محدودية أرهينيوس وآخر يبين أن لويس أشمل من برونستد – لوري.', null, null, 'تحليل', 'مقارنة مع أمثلة', 'متوسط', 'الكتاب ص 63–64 — الجدول 2-2 ملخص النظريات الثلاث للأحماض والقواعد'),
('essay', 3, 'صنّف كلًّا من المواد المحددة بين قوسين في التفاعلات الآتية وفق كل نظرية يمكن تطبيقها (أرهينيوس، برونستد – لوري، لويس): (1) HCl(g) → H⁺ + Cl⁻ [الحمض HCl]، (2) NH₃ + H₂O ⇌ NH₄⁺ + OH⁻ [القاعدة NH₃]، (3) BF₃ + NH₃ → BF₃NH₃ [الحمض BF₃]. بيّن في كل حالة أي النظريات تنطبق ولماذا، ثم استنتج أي النظريات الثلاث تفسر الحالات الثلاث جميعًا.', null, null, 'تقويم', 'تصنيف ومقارنة واستنتاج', 'صعب', 'الكتاب ص 63–64 — الجدول 2-2 ملخص النظريات الثلاث للأحماض والقواعد')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O23') and x.type = v.type and x.number = v.number);
