from (values
('mcq', 1, 0, 'تعرّف نظرية أرهينيوس القاعدة بأنها المادة المنتجة لأيونات الهيدروكسيد OH⁻ عند إذابتها في الماء، والحمض بأنه المنتج لأيونات H⁺.', '["","هذا تعريف القاعدة وفق برونستد – لوري.","هذا تعريف القاعدة وفق لويس.","هذا تعريف الحمض وفق أرهينيوس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.607Z"}'::jsonb),
('mcq', 2, 2, 'حمض لويس مادة تستقبل زوجًا من الإلكترونات، وقاعدة لويس مادة تمنح زوجًا من الإلكترونات.', '["هذا تعريف الحمض وفق أرهينيوس.","هذا تعريف الحمض وفق برونستد – لوري.","","هذا تعريف القاعدة وفق لويس لا الحمض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.607Z"}'::jsonb),
('mcq', 3, 1, 'تعرّف نظرية أرهينيوس الحمض بأنه منتج لـ H⁺ والقاعدة بأنها منتجة لـ OH⁻ عند الذوبان في الماء، فهي مرتبطة بالمحاليل المائية، أما برونستد – لوري ولويس فتعتمدان على انتقال H⁺ أو زوج الإلكترونات.', '["تعتمد على منح H⁺ واستقباله، وليست مقيدة بإنتاج H⁺ وOH⁻ في الماء.","","تعتمد على زوج الإلكترونات، وتشمل تفاعلات لا يوجد فيها ماء مثل SO₃ مع MgO.","النظريات الثلاث لا تتساوى في ذلك؛ فنظرية أرهينيوس وحدها تشترط إنتاج H⁺ وOH⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.607Z"}'::jsonb),
('mcq', 4, 3, 'الأمونيا NH₃ لا تحتوي على مجموعة هيدروكسيد فلا تنتج OH⁻ بتفككها، فليست قاعدة أرهينيوس، لكنها تستقبل أيون H⁺ من الماء فتكوّن NH₄⁺ فهي قاعدة برونستد – لوري.', '["NaOH ينتج OH⁻ ويستقبل H⁺، فهو قاعدة وفق النظريتين.","KOH ينتج OH⁻ ويستقبل H⁺، فهو قاعدة وفق النظريتين.","Ca(OH)₂ ينتج OH⁻ ويستقبل H⁺، فهو قاعدة وفق النظريتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.607Z"}'::jsonb),
('mcq', 5, 2, 'يبين الكتاب أن معظم الأحماض والقواعد وفق أرهينيوس تتفق مع تعريف برونستد – لوري، وأن نظرية لويس أشمل لأنها تضم تفاعلات لا ينتقل فيها H⁺ مثل SO₃ مع MgO وBF₃ مع NH₃.', '["نظرية أرهينيوس أضيقها؛ فلا تفسر مثلًا قاعدية NH₃.","العكس هو الصحيح؛ نظرية لويس أشمل لأنها لا تشترط وجود H⁺.","","قد تنطبق النظريات الثلاث على المادة نفسها، كما في تفاعل H⁺ مع F⁻ الذي ينطبق عليه برونستد – لوري ولويس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.607Z"}'::jsonb),
('mcq', 6, 1, 'في هذا التفاعل ينتقل زوج إلكترونات من NH₃ (قاعدة لويس) إلى BF₃ (حمض لويس) دون إنتاج H⁺ وOH⁻ ودون انتقال H⁺؛ فتفسره نظرية لويس وحدها.', '["التفاعل ينتج H⁺ فتفسره نظرية أرهينيوس.","","ينتقل أيون H⁺ من HF إلى الماء فتفسره نظرية برونستد – لوري.","التفاعل ينتج OH⁻ فتفسره نظرية أرهينيوس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.608Z"}'::jsonb),
('mcq', 7, 0, 'ذرة البورون في BF₃ لها ستة إلكترونات تكافؤ ومدار فارغ يستقبل زوج إلكترونات، فهو حمض لويس؛ ومن أمثلة حمض لويس أيضًا H⁺ وSO₃.', '["","الأمونيا تمنح زوج إلكترونات فهي قاعدة لويس.","أيون الفلوريد يمنح زوج إلكترونات فهو قاعدة لويس.","أيون الأكسيد يمنح زوج إلكترونات فهو قاعدة لويس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.608Z"}'::jsonb),
('essay', 1, null::int, null, null, 'أرهينيوس: الحمض منتج H⁺، القاعدة منتجة OH⁻. برونستد – لوري: الحمض مانح H⁺، القاعدة مستقبل H⁺. لويس: الحمض مستقبل زوج إلكترونات، القاعدة مانح زوج إلكترونات.', '["أرهينيوس: منتج H⁺ / منتجة OH⁻","برونستد – لوري: مانح H⁺ / مستقبل H⁺","لويس: مستقبل زوج إلكترونات / مانح زوج إلكترونات"]'::jsonb, '[]'::jsonb, '[{"element":"تعريفا أرهينيوس","marks":1},{"element":"تعريفا برونستد – لوري","marks":1},{"element":"تعريفا لويس","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ستة تعريفات صحيحة"},{"level":"2 درجتان","description":"أربعة إلى خمسة تعريفات صحيحة"},{"level":"1 درجة","description":"تعريفان أو ثلاثة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس تعريفي الحمض والقاعدة في لويس","الخلط بين منتج H⁺ ومانح H⁺","تعريف حمض لويس بأنه مانح زوج إلكترونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.608Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) أرهينيوس تركز على إنتاج H⁺ وOH⁻ في الماء، وبرونستد – لوري تركز على انتقال أيون H⁺، ولويس تركز على انتقال زوج الإلكترونات. (ب) أرهينيوس أضيقها؛ فلا تفسر قاعدية NH₃ لأنها لا تحتوي على مجموعة OH، بينما تفسرها برونستد – لوري لأنها تستقبل H⁺ من الماء. ولويس أشملها؛ فتفسر تفاعل BF₃ مع NH₃ أو SO₃ مع MgO الذي لا ينتقل فيه H⁺ فلا تفسره برونستد – لوري.', '["محور كل نظرية","أرهينيوس أضيق: مثال NH₃","لويس أشمل: مثال BF₃/NH₃ أو SO₃/MgO","لويس تضم برونستد – لوري وغيرها"]'::jsonb, '[]'::jsonb, '[{"element":"محور كل نظرية","marks":1},{"element":"اتساع النظريات الثلاث","marks":1},{"element":"مثال محدودية أرهينيوس","marks":1},{"element":"مثال شمول لويس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة بالمثالين"},{"level":"3 درجات","description":"مقارنة صحيحة مع مثال واحد"},{"level":"2 درجتان","description":"مقارنة صحيحة دون أمثلة"},{"level":"1 درجة","description":"ذكر محور نظرية أو أكثر فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ NH₃ قاعدة أرهينيوس","القول إن برونستد – لوري أشمل من لويس","تفسير تفاعل BF₃ مع NH₃ بانتقال H⁺"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.608Z"}'::jsonb),
('essay', 3, null::int, null, null, '(1) HCl: حمض وفق أرهينيوس (ينتج H⁺)، ووفق برونستد – لوري (يمنح H⁺)، ووفق لويس (فنظرية لويس تشمل ما تشمله برونستد – لوري، إذ ينتج HCl أيون H⁺ الذي يستقبل زوج إلكترونات في تفاعلاته). (2) NH₃: ليست قاعدة أرهينيوس (لا تحتوي OH)، وهي قاعدة برونستد – لوري (تستقبل H⁺) وقاعدة لويس (تمنح زوج إلكترونات). (3) BF₃: لا ينطبق أرهينيوس ولا برونستد – لوري (لا H⁺)، وهو حمض لويس (يستقبل زوج إلكترونات). الاستنتاج: نظرية لويس وحدها تفسر الحالات الثلاث جميعًا، فهي الأشمل.', '["HCl: أرهينيوس + برونستد – لوري + لويس","NH₃: برونستد – لوري + لويس لا أرهينيوس","BF₃: لويس فقط","الاستنتاج: لويس الأشمل"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل الحالة 1","marks":1},{"element":"تحليل الحالة 2","marks":1},{"element":"تحليل الحالة 3","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل صحيح للحالات الثلاث مع الاستنتاج"},{"level":"3 درجات","description":"تحليل صحيح للحالات دون استنتاج"},{"level":"2 درجتان","description":"تحليل صحيح لحالتين"},{"level":"1 درجة","description":"تحليل صحيح لحالة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ NH₃ قاعدة أرهينيوس","تطبيق برونستد – لوري على BF₃","القول إن لويس لا تنطبق على HCl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.609Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
