from (values
('mcq', 1, 'ما المقصود بالحمض القوي؟', null, '["الحمض الذي يكون تركيزه في المحلول المائي مرتفعًا","الحمض الذي يتأين كليًا في المحلول المائي","الحمض الذي يتأين جزئيًا في المحلول المائي المخفف","الحمض الذي يحتوي جزيئه على أكثر من ذرة هيدروجين"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 66 — الأحماض القوية'),
