('mcq', 3, 'وُضع قطبا جهاز الموصلية في محلول HCl تركيزه 0.10 M فتوهج المصباح بقوة، ثم في محلول CH₃COOH تركيزه 0.10 M فكان الضوء خافتًا. ما تفسير ذلك؟', null, '["يتأين HCl كليًا فينتج أيونات أكثر من CH₃COOH الذي يتأين جزئيًا","تركيز HCl في المحلول أكبر من تركيز CH₃COOH","لا يحتوي CH₃COOH على هيدروجين قابل للتأين في الماء","جزيئات HCl غير المتأينة توصل الكهرباء أفضل من جزيئات CH₃COOH"]'::jsonb, 'فهم', 'تفسير ملاحظة', 'متوسط', 'الكتاب ص 66 — الأحماض القوية'),
('mcq', 4, 'أي الأحماض الآتية يُصنَّف حمضًا قويًا؟', null, '["HF","H₂CO₃","HNO₃","HClO"]'::jsonb, 'تذكر', 'تصنيف أمثلة', 'سهل', 'الكتاب ص 67 — الأحماض الضعيفة والجدول 2-3'),
('mcq', 5, 'أي مجموعة مما يأتي تتكون من أحماض ضعيفة فقط؟', null, '["HF و H₂S و CH₃COOH","HCl و HF و H₂S","HI و HClO₄ و HNO₃","H₂SO₄ و H₂CO₃ و HClO"]'::jsonb, 'فهم', 'تصنيف أمثلة', 'متوسط', 'الكتاب ص 67 — الأحماض الضعيفة والجدول 2-3'),
('mcq', 6, 'أي العبارات الآتية تصف محلولًا مائيًا مخففًا لحمض ضعيف HY عند الاتزان؟', null, '["أيونات H₃O⁺ وY⁻ فقط دون أي جزيئات HY","جزيئات HY فقط دون أي أيونات في المحلول","أيونات H₃O⁺ أكثر عددًا من جزيئات HY غير المتأينة","جزيئات HY غير متأينة كثيرة مع قليل من أيونات H₃O⁺ وY⁻"]'::jsonb, 'فهم', 'وصف مكونات محلول', 'صعب', 'الكتاب ص 67 — الأحماض الضعيفة والجدول 2-3'),
('mcq', 7, 'يتأين حمض الإيثانويك الذي تركيزه 0.10 M بنسبة 1.3% تقريبًا. ما التصنيف الصحيح لهذا الحمض مع سببه؟', null, '["قوي؛ لأن نسبة تأينه تزداد كلما خُفِّف المحلول","ضعيف؛ لأن معظم جزيئاته تبقى غير متأينة في المحلول","ضعيف؛ لأن تركيز محلوله منخفض ويساوي 0.10 M","قوي؛ لأن محلوله يوصل التيار الكهربائي"]'::jsonb, 'فهم', 'تصنيف مع تعليل', 'صعب', 'الكتاب ص 70 — تجربة: قارن بين قوى الأحماض'),
('essay', 1, 'عرّف كلًّا من الحمض القوي والحمض الضعيف، ثم اذكر مثالين على كل منهما.', null, null, 'تذكر', 'تعريف مع أمثلة', 'متوسط', 'الكتاب ص 67 — الأحماض الضعيفة والجدول 2-3'),
('essay', 2, 'في تجربة لقياس التوصيل الكهربائي، أضاء المصباح بقوة عند وضع القطبين في محلول HCl تركيزه 0.10 M، وكان خافتًا في محلول حمض الإيثانويك CH₃COOH بالتركيز نفسه. فسّر الفرق في شدة الإضاءة، واكتب معادلة تأين HCl في الماء، واذكر ما تستنتجه عن تصنيف كل من الحمضين.', null, null, 'فهم', 'تفسير تجربة', 'متوسط', 'الكتاب ص 66 — الأحماض القوية'),
('essay', 3, 'صنّف الأحماض الآتية إلى قوية وضعيفة: HI، HClO، HClO₄، HF، H₂CO₃، HNO₃. ثم بيّن نوع السهم الذي يُستعمل في معادلة تأين كل صنف، معلّلًا ذلك بدرجة التأين.', null, null, 'فهم', 'تصنيف مع تعليل', 'صعب', 'الكتاب ص 67 — الأحماض الضعيفة والجدول 2-3')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
