select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الحمض القوي هو الحمض الذي يتأين كليًا في المحلول المائي، فينتج أكبر عدد من الأيونات؛ ولذلك تكون محاليله موصلات جيدة للكهرباء.', '["قوة الحمض تتعلق بدرجة تأينه لا بتركيزه؛ فقد يُحضَّر محلول مركز من حمض ضعيف كالإيثانويك.","","هذا تعريف الحمض الضعيف لا القوي.","عدد ذرات الهيدروجين لا يحدد القوة؛ فـ H₂CO₃ وH₂S يحتويان على ذرتي هيدروجين وهما حمضان ضعيفان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.610Z"}'::jsonb),
('mcq', 2, 3, 'يُعرَّف الحمض الضعيف بأنه الحمض الذي يتأين جزئيًا فقط في المحلول المائي المخفف، فينتج أيونات أقل من الحمض القوي.', '["الحمض الضعيف يتأين جزئيًا فينتج بعض الأيونات، ولذلك يوصل محلوله الكهرباء توصيلًا ضعيفًا لا معدومًا.","التأين الكلي صفة الحمض القوي، والتعريف لا يتعلق بسرعة التأين بل بمداه.","الضعف صفة لدرجة التأين لا للتركيز؛ فمحلول HCl المخفف يبقى حمضًا قويًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.610Z"}'::jsonb),
('mcq', 3, 0, 'يعتمد توصيل التيار الكهربائي على عدد الأيونات في المحلول. جميع جزيئات HCl تتأين إلى أيونات هيدرونيوم وأيونات كلوريد، أما CH₃COOH فيتأين جزئيًا فقط فيحتوي محلوله على عدد أقل من الأيونات مع أن تركيزي الحمضين متساويان.', '["","التركيزان متساويان (0.10 M)، فالفرق ناتج عن اختلاف درجة التأين لا التركيز.","يتأين CH₃COOH فعلًا لكن جزئيًا منتجًا H₃O⁺ وCH₃COO⁻، ولهذا يضيء المصباح ولو خافتًا.","الجزيئات غير المتأينة لا توصل الكهرباء؛ التوصيل يعتمد على عدد الأيونات، وجميع جزيئات HCl متأينة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.610Z"}'::jsonb),
('mcq', 4, 2, 'حمض النيتريك HNO₃ من الأحماض القوية في الجدول 2-3؛ إذ يتأين كليًا: HNO₃ → H⁺ + NO₃⁻، أما HF وH₂CO₃ وHClO فأحماض ضعيفة.', '["حمض الهيدروفلوريك حمض ضعيف يتأين جزئيًا، وتُكتب معادلة تأينه بسهمي اتزان.","حمض الكربونيك حمض ضعيف رغم احتوائه على ذرتي هيدروجين.","","حمض الهيبوكلوروز حمض ضعيف يتأين جزئيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.610Z"}'::jsonb),
('mcq', 5, 0, 'الأحماض HF وH₂S وCH₃COOH جميعها من الأحماض الضعيفة في الجدول 2-3، وتُكتب معادلات تأينها بسهمي اتزان لأنها تتأين جزئيًا.', '["","HCl حمض قوي يتأين كليًا، فلا تتكون المجموعة من أحماض ضعيفة فقط.","هذه الأحماض الثلاثة قوية كلها وفق الجدول 2-3.","H₂SO₄ حمض قوي في تأينه الأول، وإن كان الحمضان الآخران ضعيفين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-17T09:21:20.611Z"}'::jsonb),
('mcq', 6, 3, 'الحمض الضعيف يتأين جزئيًا، فيتكون مخلوط اتزان تكون فيه جزيئات الحمض غير المتأينة هي الغالبة، وتوجد معها كمية قليلة من أيونات H₃O⁺ وأيونات قاعدته المرافقة Y⁻.', '["هذا وصف محلول حمض قوي تأين كليًا، لا حمض ضعيف.","الحمض الضعيف يتأين جزئيًا، فلا بد من وجود بعض الأيونات، ولذلك يوصل محلوله الكهرباء ولو ضعيفًا.","في الحمض الضعيف تبقى معظم الجزيئات غير متأينة، فتكون الأيونات أقل عددًا من الجزيئات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T09:21:20.611Z"}'::jsonb),
('mcq', 7, 1, 'نسبة التأين 1.3% تعني أن نحو 98.7% من جزيئات الحمض تبقى غير متأينة، أي أنه يتأين جزئيًا فقط، فهو حمض ضعيف. ولا يُبنى التصنيف على التركيز ولا على مجرد التوصيل.', '["ازدياد نسبة التأين بالتخفيف لا يجعله قويًا؛ فالحمض القوي يتأين بنسبة 100% تقريبًا، و1.3% تأين جزئي.","","التصنيف لا يعتمد على التركيز؛ فمحلول HCl تركيزه 0.10 M أيضًا وهو حمض قوي.","محاليل الأحماض الضعيفة توصل الكهرباء أيضًا لكن توصيلًا ضعيفًا لقلة أيوناتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T09:21:20.611Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحمض القوي: الحمض الذي يتأين كليًا في المحلول المائي، ومن أمثلته HCl (الهيدروكلوريك) وHNO₃ (النيتريك) ويقبل HI وHClO₄ وH₂SO₄. الحمض الضعيف: الحمض الذي يتأين جزئيًا فقط في المحلول المائي المخفف، ومن أمثلته HF (الهيدروفلوريك) وCH₃COOH (الإيثانويك) ويقبل H₂S وH₂CO₃ وHClO.', '["تعريف الحمض القوي: يتأين كليًا","تعريف الحمض الضعيف: يتأين جزئيًا في المحلول المائي المخفف","مثالان صحيحان للأحماض القوية","مثالان صحيحان للأحماض الضعيفة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الحمض القوي","marks":1},{"element":"تعريف الحمض الضعيف","marks":1},{"element":"مثالان على الحمض القوي","marks":1},{"element":"مثالان على الحمض الضعيف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان وأربعة أمثلة صحيحة"},{"level":"3 درجات","description":"تعريفان صحيحان مع خطأ في أحد زوجي الأمثلة"},{"level":"2 درجتان","description":"تعريف واحد صحيح مع أمثلة صحيحة، أو تعريفان دون أمثلة"},{"level":"1 درجة","description":"تعريف واحد صحيح فقط أو أمثلة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["ربط قوة الحمض بتركيزه بدل درجة تأينه","عدّ H₂SO₄ حمضًا ضعيفًا أو HF حمضًا قويًا","القول إن الحمض الضعيف لا يتأين مطلقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.611Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يعتمد التوصيل الكهربائي على عدد الأيونات في المحلول. تتأين جميع جزيئات HCl في الماء: HCl(aq) + H₂O(l) → H₃O⁺(aq) + Cl⁻(aq)، فيحتوي المحلول على عدد كبير من الأيونات ويضيء المصباح بقوة. أما CH₃COOH فيتأين جزئيًا فقط، فيحتوي محلوله على عدد أقل من الأيونات فيكون الضوء خافتًا. وبما أن التركيزين متساويان فالفرق سببه درجة التأين، فنستنتج أن HCl حمض قوي وCH₃COOH حمض ضعيف.', '["التوصيل يعتمد على عدد الأيونات","HCl يتأين كليًا فينتج أيونات كثيرة","CH₃COOH يتأين جزئيًا فينتج أيونات أقل","معادلة تأين HCl بسهم واحد","الاستنتاج: HCl قوي وCH₃COOH ضعيف مع ملاحظة تساوي التركيزين"]'::jsonb, '[]'::jsonb, '[{"element":"ربط التوصيل بعدد الأيونات","marks":1},{"element":"تفسير سلوك HCl (تأين كلي)","marks":1},{"element":"تفسير سلوك CH₃COOH (تأين جزئي)","marks":1},{"element":"معادلة تأين HCl صحيحة بسهم واحد","marks":1},{"element":"الاستنتاج الصحيح عن التصنيف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل ومعادلة صحيحة واستنتاج صحيح"},{"level":"4 درجات","description":"نقص عنصر واحد، كإغفال المعادلة أو كتابتها بسهمي اتزان"},{"level":"3 درجات","description":"تفسير صحيح لسلوك الحمضين دون معادلة أو استنتاج"},{"level":"2 درجتان","description":"تفسير سلوك أحد الحمضين فقط مع ربط التوصيل بالأيونات"},{"level":"1 درجة","description":"ذكر أن HCl قوي وCH₃COOH ضعيف دون تفسير"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["تفسير الفرق باختلاف التركيز مع أن التركيزين متساويان","كتابة معادلة HCl بسهمي اتزان","القول إن محلول CH₃COOH لا يحتوي على أيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.612Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأحماض القوية: HI وHClO₄ وHNO₃؛ تتأين كليًا في المحلول المائي، لذا تُكتب معادلات تأينها بسهم واحد (→)، مثل HI → H⁺ + I⁻. الأحماض الضعيفة: HClO وHF وH₂CO₃؛ تتأين جزئيًا فقط فيتكون مخلوط اتزان من الجزيئات والأيونات، لذا تُكتب معادلاتها بسهمي اتزان (⇌)، مثل HF ⇌ H⁺ + F⁻.', '["HI وHClO₄ وHNO₃ أحماض قوية","HClO وHF وH₂CO₃ أحماض ضعيفة","السهم الواحد للأحماض القوية لأنها تتأين كليًا","سهما الاتزان للأحماض الضعيفة لأنها تتأين جزئيًا وتكوّن مخلوط اتزان"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الأحماض القوية الثلاثة","marks":1},{"element":"تصنيف الأحماض الضعيفة الثلاثة","marks":1},{"element":"السهم الواحد مع التعليل","marks":1},{"element":"سهما الاتزان مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح كامل ونوع السهم مع التعليل لكلا الصنفين"},{"level":"3 درجات","description":"تصنيف صحيح كامل مع تعليل صنف واحد فقط"},{"level":"2 درجتان","description":"تصنيف صحيح كامل دون تعليل، أو خطأ في حمض أو حمضين مع تعليل صحيح"},{"level":"1 درجة","description":"تصنيف نصف الأحماض تقريبًا تصنيفًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["عدّ H₂CO₃ حمضًا قويًا لاحتوائه على ذرتي هيدروجين","الخلط بين HClO وHClO₄","تعليل نوع السهم بسرعة التفاعل لا بمدى التأين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T09:21:20.612Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L2-O01') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L2-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ماذا تدل عليه القيمة الأصغر لثابت تأين الحمض Ka عند مقارنة حمضين ضعيفين بالتركيز نفسه وعند درجة الحرارة نفسها؟', null, '["أن الحمض أقوى ونسبة تأينه في الماء أكبر","أن تركيز الحمض المذاب في المحلول أقل","أن الحمض أضعف وتراكيز أيوناته في محلوله أقل","أن الحمض يتأين كليًا في المحلول المخفف"]'::jsonb, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 68 — ثابت تأين الحمض Ka'),
('mcq', 2, 'اعتمادًا على بيانات الجدول، أيّ الأحماض الآتية هو الأقوى؟', '{"headers":["الحمض","معادلة التأين","Ka (298 K)"],"rows":[["الإيثانويك","CH₃COOH ⇌ H⁺ + CH₃COO⁻","1.8 × 10⁻⁵"],["الهيدروسيانيك","HCN ⇌ H⁺ + CN⁻","6.2 × 10⁻¹⁰"],["الهيدروفلوريك","HF ⇌ H⁺ + F⁻","6.3 × 10⁻⁴"],["الكربونيك (التأين الأول)","H₂CO₃ ⇌ H⁺ + HCO₃⁻","4.5 × 10⁻⁷"]]}'::jsonb, '["حمض الهيدروفلوريك HF","حمض الهيدروسيانيك HCN","حمض الكربونيك H₂CO₃","حمض الإيثانويك CH₃COOH"]'::jsonb, 'تحليل', 'مقارنة باستعمال بيانات', 'سهل', 'الكتاب ص 69 — الجدول 2-4 ثوابت تأين الأحماض الضعيفة'),
('mcq', 3, 'رتّب الأحماض الضعيفة الواردة في الجدول ترتيبًا تصاعديًا بحسب قوتها (من الأضعف إلى الأقوى).', '{"headers":["الحمض","معادلة التأين","Ka (298 K)"],"rows":[["كبريتيد الهيدروجين (التأين الأول)","H₂S ⇌ H⁺ + HS⁻","8.9 × 10⁻⁸"],["الإيثانويك","CH₃COOH ⇌ H⁺ + CH₃COO⁻","1.8 × 10⁻⁵"],["الهيدروسيانيك","HCN ⇌ H⁺ + CN⁻","6.2 × 10⁻¹⁰"],["الكربونيك (التأين الأول)","H₂CO₃ ⇌ H⁺ + HCO₃⁻","4.5 × 10⁻⁷"]]}'::jsonb, '["CH₃COOH ثم H₂CO₃ ثم H₂S ثم HCN","H₂S ثم HCN ثم H₂CO₃ ثم CH₃COOH","CH₃COOH ثم H₂CO₃ ثم HCN ثم H₂S","HCN ثم H₂S ثم H₂CO₃ ثم CH₃COOH"]'::jsonb, 'تحليل', 'ترتيب باستعمال بيانات', 'متوسط', 'الكتاب ص 69 — الجدول 2-4 ثوابت تأين الأحماض الضعيفة'),
('mcq', 4, 'حُضّرت محاليل متساوية التركيز من الأحماض الواردة في الجدول. في أيّ المحاليل تكون نسبة جزيئات الحمض غير المتأينة هي الأعلى؟', '{"headers":["الحمض","معادلة التأين","Ka (298 K)"],"rows":[["الهيدروفلوريك","HF ⇌ H⁺ + F⁻","6.3 × 10⁻⁴"],["الإيثانويك","CH₃COOH ⇌ H⁺ + CH₃COO⁻","1.8 × 10⁻⁵"],["الكربونيك (التأين الأول)","H₂CO₃ ⇌ H⁺ + HCO₃⁻","4.5 × 10⁻⁷"],["الهيدروسيانيك","HCN ⇌ H⁺ + CN⁻","6.2 × 10⁻¹⁰"]]}'::jsonb, '["محلول HF","محلول HCN","محلول CH₃COOH","محلول H₂CO₃"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'متوسط', 'الكتاب ص 68 — ثابت تأين الحمض Ka'),
('mcq', 5, 'استعمل بيانات الجدول لحمض الكربونيك. أيّ الاستنتاجات الآتية صحيح؟', '{"headers":["الحمض","معادلة التأين","Ka (298 K)"],"rows":[["الكربونيك (التأين الأول)","H₂CO₃ ⇌ H⁺ + HCO₃⁻","4.5 × 10⁻⁷"],["الكربونيك (التأين الثاني)","HCO₃⁻ ⇌ H⁺ + CO₃²⁻","4.7 × 10⁻¹¹"]]}'::jsonb, '["H₂CO₃ حمض قوي؛ لأنه يتأين على خطوتين متتاليتين","HCO₃⁻ أقوى من H₂CO₃؛ لأن الأس 11 أكبر من الأس 7","HCO₃⁻ حمض أضعف بكثير من H₂CO₃، فالتأين الثاني أقل بكثير من الأول","للتأينين قيمة Ka واحدة؛ لأنهما للحمض نفسه"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 69 — الجدول 2-4 ثوابت تأين الأحماض الضعيفة'),
('mcq', 6, 'قيمة Ka لحمض HF هي 6.3 × 10⁻⁴، ولحمض CH₃COOH هي 1.8 × 10⁻⁵. كم مرة تقريبًا تساوي قيمة Ka لـ HF قيمتها لـ CH₃COOH؟', null, '["35 مرة","3.5 مرات","0.029 مرة","4.5 مرات"]'::jsonb, 'تطبيق', 'حساب نسبة', 'متوسط', 'الكتاب ص 69 — الجدول 2-4 ثوابت تأين الأحماض الضعيفة'),
('mcq', 7, 'حمض ضعيف مجهول HZ قيمة Ka له 2.0 × 10⁻⁶ عند 298 K. أين يقع بين أحماض الجدول من حيث القوة؟', '{"headers":["الحمض","معادلة التأين","Ka (298 K)"],"rows":[["الهيدروفلوريك","HF ⇌ H⁺ + F⁻","6.3 × 10⁻⁴"],["الإيثانويك","CH₃COOH ⇌ H⁺ + CH₃COO⁻","1.8 × 10⁻⁵"],["الكربونيك (التأين الأول)","H₂CO₃ ⇌ H⁺ + HCO₃⁻","4.5 × 10⁻⁷"],["كبريتيد الهيدروجين (التأين الأول)","H₂S ⇌ H⁺ + HS⁻","8.9 × 10⁻⁸"],["الهيدروسيانيك","HCN ⇌ H⁺ + CN⁻","6.2 × 10⁻¹⁰"]]}'::jsonb, '["أقوى من CH₃COOH وأضعف من HF","أضعف من H₂S وأقوى من HCN","أضعف من HCN؛ لأن 2.0 أصغر من 6.2","أقوى من H₂CO₃ وأضعف من CH₃COOH"]'::jsonb, 'تحليل', 'مقارنة باستعمال بيانات', 'متوسط', 'الكتاب ص 69 — الجدول 2-4 ثوابت تأين الأحماض الضعيفة'),
('essay', 1, 'استعمل بيانات الجدول لترتيب الأحماض الخمسة تصاعديًا بحسب قوتها، ثم توقّع أيّ محاليلها المتساوية التركيز يكون الأفضل توصيلًا للكهرباء وأيّها الأضعف، مع التعليل.', '{"headers":["الحمض","معادلة التأين","Ka (298 K)"],"rows":[["الكربونيك (التأين الأول)","H₂CO₃ ⇌ H⁺ + HCO₃⁻","4.5 × 10⁻⁷"],["الهيدروفلوريك","HF ⇌ H⁺ + F⁻","6.3 × 10⁻⁴"],["الهيدروسيانيك","HCN ⇌ H⁺ + CN⁻","6.2 × 10⁻¹⁰"],["كبريتيد الهيدروجين (التأين الأول)","H₂S ⇌ H⁺ + HS⁻","8.9 × 10⁻⁸"],["الإيثانويك","CH₃COOH ⇌ H⁺ + CH₃COO⁻","1.8 × 10⁻⁵"]]}'::jsonb, null, 'تحليل', 'ترتيب وتوقع', 'سهل', 'الكتاب ص 69 — الجدول 2-4 ثوابت تأين الأحماض الضعيفة'),
('essay', 2, 'اكتب تعبير ثابت تأين الحمض Ka لحمض الهيدروسيانيك HCN، ثم وضّح بالاستناد إلى هذا التعبير لماذا تكون قيمة Ka صغيرة للأحماض الضعيفة. وقارن بين محلولين متساويي التركيز من HF (Ka = 6.3 × 10⁻⁴) وHCN (Ka = 6.2 × 10⁻¹⁰) من حيث تركيز H₃O⁺ ونسبة الجزيئات غير المتأينة.', null, null, 'تحليل', 'تفسير ومقارنة', 'صعب', 'الكتاب ص 68 — ثابت تأين الحمض Ka'),
('essay', 3, 'قال طالب: «حمض كبريتيد الهيدروجين H₂S أقوى من حمض الهيدروفلوريك HF؛ لأن جزيء H₂S يحتوي على ذرتي هيدروجين قابلتين للتأين، فيعطي أيونات هيدروجين أكثر». قوّم هذه العبارة مستعينًا بالقيم: Ka (HF) = 6.3 × 10⁻⁴، Ka (H₂S، التأين الأول) = 8.9 × 10⁻⁸، Ka (HS⁻، التأين الثاني) = 1 × 10⁻¹⁹.', null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 69 — الجدول 2-4 ثوابت تأين الأحماض الضعيفة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L2-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تكون قيم Ka للأحماض الأضعف أصغر؛ لاحتواء محاليلها على أقل تراكيز للأيونات (البسط) وأعلى تراكيز لجزيئات الحمض غير المتأينة (المقام). فكلما صغرت Ka كان الحمض أضعف.', '["العلاقة معكوسة؛ فالقيمة الأكبر لـ Ka هي التي تدل على حمض أقوى.","Ka ثابت اتزان لا يعبّر عن تركيز الحمض المذاب، بل عن مدى تأينه.","","التأين الكلي صفة الأحماض القوية، أما Ka فتُستعمل للأحماض الضعيفة التي تتأين جزئيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T09:21:20.613Z"}'::jsonb),
('mcq', 2, 0, 'كلما كبرت قيمة Ka كان الحمض أقوى. أكبر قيمة في الجدول هي 6.3 × 10⁻⁴ لحمض الهيدروفلوريك HF، فهو الأقوى بين هذه الأحماض.', '["","لـ HCN أصغر قيمة Ka (6.2 × 10⁻¹⁰) فهو الأضعف بينها؛ اختياره يعني عكس العلاقة بين Ka والقوة.","احتواء H₂CO₃ على ذرتي هيدروجين لا يجعله أقوى؛ وقيمة Ka لتأينه الأول 4.5 × 10⁻⁷ أصغر من قيمة HF.","قيمة Ka له 1.8 × 10⁻⁵ وهي أصغر من 6.3 × 10⁻⁴ لـ HF، فهو أضعف منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.613Z"}'::jsonb),
('mcq', 3, 3, 'قيم Ka تصاعديًا: HCN (6.2 × 10⁻¹⁰) < H₂S (8.9 × 10⁻⁸) < H₂CO₃ (4.5 × 10⁻⁷) < CH₃COOH (1.8 × 10⁻⁵)، وبما أن الحمض الأقوى له Ka أكبر فالترتيب التصاعدي للقوة: HCN ثم H₂S ثم H₂CO₃ ثم CH₃COOH.', '["هذا ترتيب تنازلي (من الأقوى إلى الأضعف) لا تصاعدي.","قورن المعامل 8.9 بالمعامل 6.2 دون النظر إلى الأس؛ و 8.9 × 10⁻⁸ أكبر من 6.2 × 10⁻¹⁰ فـ H₂S أقوى من HCN.","رُتّبت الأحماض بحسب المعاملات فقط (1.8، 4.5، 6.2، 8.9) مع إهمال قوى العشرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.613Z"}'::jsonb),
('mcq', 4, 1, 'الحمض الأضعف له أصغر Ka، ومحلوله يحتوي على أقل تراكيز للأيونات وأعلى تراكيز لجزيئات الحمض غير المتأينة. أصغر قيمة هي 6.2 × 10⁻¹⁰ لـ HCN.', '["HF أكبرها Ka فهو الأكثر تأينًا، أي أن نسبة جزيئاته غير المتأينة هي الأقل.","","قيمة Ka له (1.8 × 10⁻⁵) أكبر من قيمة HCN، فيتأين بنسبة أكبر.","قيمة Ka لتأينه الأول (4.5 × 10⁻⁷) أكبر من قيمة HCN، فتبقى نسبة أقل من جزيئاته دون تأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.614Z"}'::jsonb),
('mcq', 5, 2, 'قيمة Ka للتأين الأول 4.5 × 10⁻⁷ وللتأين الثاني 4.7 × 10⁻¹¹، أي أن Ka الثانية أصغر بنحو 10⁴ مرة؛ لذا فـ HCO₃⁻ حمض أضعف بكثير من H₂CO₃ ويحدث التأين الثاني بدرجة أقل بكثير.', '["الأحماض المتعددة البروتونات ليست بالضرورة قوية؛ وقيمتا Ka الصغيرتان تدلان على أنه ضعيف.","الأس السالب الأكبر عدديًا يعني قيمة أصغر؛ فـ 4.7 × 10⁻¹¹ أصغر بكثير من 4.5 × 10⁻⁷.","","لكل تأين للحمض المتعدد البروتونات قيمة Ka مختلفة كما يظهر في الجدول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.614Z"}'::jsonb),
('mcq', 6, 0, 'النسبة = (6.3 × 10⁻⁴) ÷ (1.8 × 10⁻⁵) = 3.5 × 10¹ = 35؛ أي أن HF أقوى من حمض الإيثانويك وقيمة Ka له أكبر بنحو 35 مرة.', '["","أُخطئ في التعامل مع الأسس؛ فالقسمة 10⁻⁴ ÷ 10⁻⁵ تساوي 10 لا 1.","قُسمت قيمة CH₃COOH على قيمة HF، أي عُكست النسبة.","طُرح المعاملان (6.3 − 1.8) بدل قسمة القيمتين كاملتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.614Z"}'::jsonb),
('mcq', 7, 3, 'القيمة 2.0 × 10⁻⁶ أكبر من 4.5 × 10⁻⁷ (H₂CO₃) وأصغر من 1.8 × 10⁻⁵ (CH₃COOH)؛ ولأن الحمض الأقوى له Ka أكبر فإن HZ أقوى من H₂CO₃ وأضعف من CH₃COOH.', '["القيمة 2.0 × 10⁻⁶ أصغر من 1.8 × 10⁻⁵، فهو أضعف من CH₃COOH.","القيمة 2.0 × 10⁻⁶ أكبر من 8.9 × 10⁻⁸ لـ H₂S، فهو أقوى منه.","قورنت المعاملات وأُهملت الأسس؛ فـ 2.0 × 10⁻⁶ أكبر بكثير من 6.2 × 10⁻¹⁰.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.615Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الترتيب التصاعدي للقوة (وهو ترتيب Ka تصاعديًا): HCN (6.2 × 10⁻¹⁰) < H₂S (8.9 × 10⁻⁸) < H₂CO₃ (4.5 × 10⁻⁷) < CH₃COOH (1.8 × 10⁻⁵) < HF (6.3 × 10⁻⁴). عند تساوي التراكيز يكون محلول HF الأفضل توصيلًا لأن قيمة Ka له أكبر فيتأين بدرجة أكبر وينتج أكبر تركيز من الأيونات، ويكون محلول HCN الأضعف توصيلًا لأن Ka له أصغر فتراكيز أيوناته أقل؛ والتوصيل يعتمد على عدد الأيونات في المحلول.', '["الترتيب الصحيح HCN < H₂S < H₂CO₃ < CH₃COOH < HF","قاعدة المقارنة: Ka أكبر يعني حمضًا أقوى","HF الأفضل توصيلًا","HCN الأضعف توصيلًا","التعليل: التوصيل يعتمد على تركيز الأيونات الذي يزداد بزيادة Ka"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":2},{"element":"تحديد الأفضل والأضعف توصيلًا","marks":1},{"element":"التعليل بربط Ka بتركيز الأيونات والتوصيل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح كامل وتوقع صحيح مع التعليل"},{"level":"3 درجات","description":"ترتيب صحيح وتوقع صحيح دون تعليل كافٍ، أو خطأ في موضع حمض واحد مع بقية الإجابة صحيحة"},{"level":"2 درجتان","description":"ترتيب صحيح فقط، أو ترتيب معكوس مع تعليل صحيح"},{"level":"1 درجة","description":"تحديد الحمض الأقوى أو الأضعف فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["ترتيب الأحماض بحسب المعاملات وإهمال الأسس","عكس العلاقة بين Ka والقوة","ربط التوصيل بعدد ذرات الهيدروجين في الصيغة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.615Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Ka = [H₃O⁺][CN⁻] / [HCN]. في الأحماض الضعيفة يكون تأين الحمض جزئيًا، فتكون تراكيز الأيونات في البسط صغيرة مقارنة بتركيز الجزيئات غير المتأينة في المقام، لذا تكون Ka صغيرة، وتصغر أكثر كلما كان الحمض أضعف. وبما أن Ka لـ HF أكبر بكثير من Ka لـ HCN فإن HF أقوى؛ لذلك يكون [H₃O⁺] في محلول HF أكبر، وتكون نسبة الجزيئات غير المتأينة في محلول HCN أكبر.', '["تعبير Ka الصحيح لـ HCN","الأيونات (البسط) صغيرة مقارنة بالجزيئات غير المتأينة (المقام)","HF أقوى لأن Ka له أكبر","[H₃O⁺] أكبر في محلول HF","نسبة الجزيئات غير المتأينة أكبر في محلول HCN"]'::jsonb, '[]'::jsonb, '[{"element":"تعبير Ka","marks":1},{"element":"تفسير صغر Ka بالبسط والمقام","marks":1},{"element":"المقارنة في [H₃O⁺]","marks":1},{"element":"المقارنة في نسبة الجزيئات غير المتأينة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعبير صحيح وتفسير صحيح ومقارنتان صحيحتان"},{"level":"3 درجات","description":"نقص أحد العناصر الأربعة"},{"level":"2 درجتان","description":"تعبير صحيح مع مقارنة واحدة صحيحة، أو مقارنتان صحيحتان دون تعبير"},{"level":"1 درجة","description":"تعبير Ka صحيح فقط أو تحديد الحمض الأقوى فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["إدخال [H₂O] في تعبير Ka","وضع التراكيز مقلوبة في التعبير","الاستنتاج أن محلول HCN يحتوي على H₃O⁺ أكثر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.615Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة. قوة الحمض تقاس بقيمة Ka لا بعدد ذرات الهيدروجين؛ وقيمة Ka للتأين الأول لـ H₂S (8.9 × 10⁻⁸) أصغر بكثير من قيمة HF (6.3 × 10⁻⁴)، فـ H₂S أضعف من HF. كما أن التأين الثاني (HS⁻) له Ka = 1 × 10⁻¹⁹ وهي صغيرة جدًا، أي أن HS⁻ لا يكاد يتأين، فلا يضيف عمليًا أيونات هيدروجين تُذكر. فالأحماض المتعددة البروتونات ليست بالضرورة قوية، ولكل خطوة تأين قيمة Ka مختلفة.', '["الحكم: العبارة خاطئة","القوة تقاس بـ Ka لا بعدد ذرات H","مقارنة Ka الأولى لـ H₂S بـ Ka لـ HF","Ka الثانية صغيرة جدًا فالتأين الثاني مهمل تقريبًا","الأحماض المتعددة البروتونات ليست بالضرورة قوية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"معيار المقارنة Ka","marks":1},{"element":"المقارنة العددية بين HF وH₂S","marks":1},{"element":"تفسير دلالة Ka الثانية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مدعوم بالمعيار والمقارنة العددية وتفسير التأين الثاني"},{"level":"3 درجات","description":"حكم صحيح مع مقارنة عددية دون مناقشة التأين الثاني"},{"level":"2 درجتان","description":"حكم صحيح مع ذكر المعيار دون مقارنة عددية"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["تأييد العبارة لأن H₂S ثنائي البروتون","جمع قيمتي Ka للتأينين","مقارنة المعاملات 8.9 و6.3 وإهمال الأسس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T09:21:20.616Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
