from (values
('mcq', 1, 'أيّ المعادلات الآتية تمثل تأين الأمونيا NH₃ في الماء تمثيلًا صحيحًا؟', null, '["NH₃(aq) + H₂O(l) → NH₄⁺(aq) + OH⁻(aq)","NH₃(aq) + H₂O(l) ⇌ NH₂⁻(aq) + H₃O⁺(aq)","NH₃(aq) + H₃O⁺(aq) ⇌ NH₄⁺(aq) + H₂O(l)","NH₃(aq) + H₂O(l) ⇌ NH₄⁺(aq) + OH⁻(aq)"]'::jsonb, 'تطبيق', 'اختيار معادلة', 'سهل', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('mcq', 2, 'ما التعبير الصحيح لثابت تأين القاعدة Kb للميثيل أمين CH₃NH₂ في الماء؟', null, '["Kb = [CH₃NH₂] / [CH₃NH₃⁺][OH⁻]","Kb = [CH₃NH₃⁺][OH⁻] / [CH₃NH₂]","Kb = [CH₃NH₃⁺][OH⁻] / [CH₃NH₂][H₂O]","Kb = [CH₃NH₂][OH⁻] / [CH₃NH₃⁺]"]'::jsonb, 'تطبيق', 'كتابة تعبير ثابت', 'متوسط', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('mcq', 3, 'ما النواتج التي تُكتب في معادلة تأين البروبيل أمين C₃H₇NH₂ في الماء؟', null, '["C₃H₇NH⁻ و H₃O⁺","C₃H₇NH₃⁺ و H₃O⁺","C₃H₇NH₃⁺ و OH⁻","C₃H₇⁺ و NH₂⁻ و H₂O"]'::jsonb, 'تطبيق', 'كتابة نواتج', 'متوسط', 'الكتاب ص 71 — مسائل تدريبية 14 و15'),
('mcq', 4, 'لماذا تُكتب معادلات تأين القواعد الضعيفة في الماء بسهمي اتزان (⇌)؟', null, '["لأنها تتأين جزئيًا مكوّنة مخلوط اتزان من الجزيئات والأيونات","لأن الماء يسلك فيها سلوك القاعدة لا الحمض","لأنها لا تنتج أيونات هيدروكسيد في المحلول","لأن تأينها كلي لكنه يحدث على خطوتين"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 70 — القواعد الضعيفة'),
('mcq', 5, 'أيّ المعادلات الآتية تمثل سلوك أيون الكربونات CO₃²⁻ قاعدةً ضعيفة في الماء؟', null, '["CO₃²⁻(aq) + H₂O(l) → HCO₃⁻(aq) + OH⁻(aq)","CO₃²⁻(aq) + H₂O(l) ⇌ HCO₃⁻(aq) + OH⁻(aq)","CO₃²⁻(aq) + H₂O(l) ⇌ HCO₃⁻(aq) + H₃O⁺(aq)","CO₃²⁻(aq) + H₂O(l) ⇌ HCO₃²⁻(aq) + OH⁻(aq)"]'::jsonb, 'تطبيق', 'كتابة معادلة', 'صعب', 'الكتاب ص 71 — مسائل تدريبية 14 و15'),
('mcq', 6, 'إذا كان ثابت تأين قاعدة ضعيفة يُعطى بالتعبير: Kb = [C₆H₅NH₃⁺][OH⁻] / [C₆H₅NH₂]، فأيّ المعادلات الآتية يمثلها هذا التعبير؟', null, '["C₆H₅NH₃⁺ + OH⁻ ⇌ C₆H₅NH₂ + H₂O","C₆H₅NH₂ + H₃O⁺ ⇌ C₆H₅NH₃⁺ + H₂O","C₆H₅NH₂ + H₂O ⇌ C₆H₅NH⁻ + H₃O⁺","C₆H₅NH₂ + H₂O ⇌ C₆H₅NH₃⁺ + OH⁻"]'::jsonb, 'تطبيق', 'استنتاج معادلة من تعبير', 'متوسط', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('mcq', 7, 'لماذا لا يظهر تركيز الماء [H₂O] في تعبير ثابت تأين القاعدة Kb؟', null, '["لأن تركيز الماء السائل ثابت في المحاليل المخففة فيُدمج مع ثابت الاتزان","لأن الماء لا يشارك في تفاعل تأين القاعدة الضعيفة","لأن الماء يتأين كليًا فلا يبقى منه شيء عند الاتزان","لأن تركيز الماء صغير جدًا فيُهمَل"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('essay', 1, 'اكتب معادلة تأين الإيثيل أمين C₂H₅NH₂ في الماء وتعبير ثابت تأينه Kb، ثم حدّد في المعادلة القاعدة وحمضها المرافق، والحمض وقاعدته المرافقة.', null, null, 'تطبيق', 'كتابة معادلة وتعبير', 'سهل', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('essay', 2, 'اكتب معادلة التأين وتعبير ثابت التأين Kb لكل من: (أ) الهكسيل أمين C₆H₁₃NH₂، (ب) أيون الفوسفات PO₄³⁻ قاعدةً في التفاعل الأمامي و OH⁻ قاعدةً في التفاعل العكسي.', null, null, 'تطبيق', 'كتابة معادلات وتعابير', 'صعب', 'الكتاب ص 71 — مسائل تدريبية 14 و15'),
('essay', 3, 'كتب طالب معادلة تأين الميثيل أمين وتعبير ثابت تأينه كما يأتي: CH₃NH₂ + H₂O → CH₃NH₃⁺ + OH⁻ ، و Kb = [CH₃NH₂][H₂O] / [CH₃NH₃⁺][OH⁻]. حدّد الأخطاء في ما كتبه، وصحّحها مع التعليل.', null, null, 'تقويم', 'تصحيح أخطاء', 'صعب', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
