from (values
('mcq', 1, 3, 'الأمونيا قاعدة ضعيفة تستقبل أيون H⁺ من الماء فتكوّن NH₄⁺ وOH⁻، ولأنها تتأين جزئيًا يتكون مخلوط اتزان، فتُكتب المعادلة بسهمي اتزان كما في الجدول 2-6.', '["السهم الواحد يعني تأينًا كليًا، والأمونيا قاعدة ضعيفة تتأين جزئيًا فتُكتب بسهمي اتزان.","هذه المعادلة تجعل NH₃ يمنح أيون H⁺ أي يسلك سلوك الحمض، بينما هو في الماء قاعدة تستقبل H⁺.","هذه معادلة تفاعل الأمونيا مع حمض (H₃O⁺)، لا معادلة تأينها في الماء التي تنتج OH⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.617Z"}'::jsonb),
('mcq', 2, 1, 'معادلة التأين: CH₃NH₂ + H₂O ⇌ CH₃NH₃⁺ + OH⁻، فيكون Kb = [CH₃NH₃⁺][OH⁻] / [CH₃NH₂]: النواتج في البسط والقاعدة غير المتأينة في المقام، دون [H₂O] لأن تركيزه ثابت في المحاليل المخففة.', '["التعبير مقلوب؛ فتراكيز النواتج توضع في البسط وتركيز القاعدة في المقام.","","هذا تعبير Keq؛ أما في Kb فيُدمج تركيز الماء الثابت مع الثابت فلا يظهر [H₂O].","وُضع تركيز القاعدة في البسط مكان حمضها المرافق CH₃NH₃⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.617Z"}'::jsonb),
('mcq', 3, 2, 'يستقبل البروبيل أمين أيون H⁺ من جزيء الماء كما يفعل الميثيل أمين: C₃H₇NH₂ + H₂O ⇌ C₃H₇NH₃⁺ + OH⁻، فالنواتج هي الحمض المرافق C₃H₇NH₃⁺ وأيون الهيدروكسيد OH⁻.', '["هذه نواتج سلوك البروبيل أمين كحمض يمنح H⁺، بينما هو قاعدة تستقبل H⁺ من الماء.","لا ينتج H₃O⁺ عند تأين قاعدة في الماء؛ فالماء يفقد H⁺ فيتحول إلى OH⁻.","","لا ينفصل الجزيء إلى أجزاء؛ بل يستقبل أيون H⁺ على مجموعة الأمين NH₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.618Z"}'::jsonb),
('mcq', 4, 0, 'القاعدة الضعيفة تتأين جزئيًا فقط في المحاليل المائية المخففة، فتكوّن مخلوط اتزان من جزيئاتها غير المتأينة وأيونات حمضها المرافق وأيونات OH⁻، ولذا يُستعمل سهما الاتزان.', '["","الماء في هذه التفاعلات يمنح أيون H⁺ فهو يسلك سلوك الحمض.","القواعد الضعيفة تنتج بعض أيونات OH⁻، لكن بكمية قليلة لأن تأينها جزئي.","التأين الكلي صفة القواعد القوية وتُكتب معادلاتها بسهم واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.618Z"}'::jsonb),
('mcq', 5, 1, 'يستقبل CO₃²⁻ أيون H⁺ من الماء فيتحول إلى HCO₃⁻ ويتحول الماء إلى OH⁻، والتأين جزئي فيُستعمل سهما الاتزان؛ والمعادلة موزونة في الذرات والشحنة (−2 = −1 + −1).', '["استُعمل سهم واحد مع أن CO₃²⁻ قاعدة ضعيفة تتأين جزئيًا.","","المعادلة غير موزونة في الهيدروجين والشحنة، والقاعدة في الماء تنتج OH⁻ لا H₃O⁺.","الشحنة غير محفوظة؛ فإضافة H⁺ إلى CO₃²⁻ تعطي HCO₃⁻ بشحنة −1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.618Z"}'::jsonb),
('mcq', 6, 3, 'البسط يحتوي على النواتج C₆H₅NH₃⁺ وOH⁻ والمقام يحتوي على القاعدة C₆H₅NH₂، فالمعادلة هي تأين الأنيلين في الماء: C₆H₅NH₂ + H₂O ⇌ C₆H₅NH₃⁺ + OH⁻ (والماء لا يظهر في Kb).', '["هذا التفاعل العكسي، وثابت اتزانه يساوي مقلوب التعبير المعطى.","لا يظهر OH⁻ في نواتج هذه المعادلة، مع أنه في بسط التعبير المعطى.","نواتج هذه المعادلة لا تطابق ما في بسط التعبير، وهي تجعل الأنيلين حمضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.618Z"}'::jsonb),
('mcq', 7, 0, 'كما في Ka، يُعدّ تركيز الماء السائل ثابتًا في المحاليل المائية المخففة، فيُدمج مع Keq ليعطي ثابتًا جديدًا هو Kb، ولذلك لا يظهر [H₂O] في التعبير.', '["","الماء يشارك فعلًا؛ فهو الذي يمنح أيون H⁺ للقاعدة.","الماء لا يتأين كليًا، وتركيزه في المحاليل المخففة يبقى ثابتًا تقريبًا.","تركيز الماء كبير جدًا وثابت، ولهذا يُدمج مع الثابت لا لصغره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.619Z"}'::jsonb),
('essay', 1, null::int, null, null, 'C₂H₅NH₂(aq) + H₂O(l) ⇌ C₂H₅NH₃⁺(aq) + OH⁻(aq)؛ Kb = [C₂H₅NH₃⁺][OH⁻] / [C₂H₅NH₂]. القاعدة: C₂H₅NH₂ وحمضها المرافق C₂H₅NH₃⁺. الحمض: H₂O وقاعدته المرافقة OH⁻.', '["معادلة موزونة بسهمي اتزان","تعبير Kb صحيح دون [H₂O]","الزوج C₂H₅NH₂ / C₂H₅NH₃⁺","الزوج H₂O / OH⁻"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة الصحيحة بسهمي اتزان","marks":1},{"element":"تعبير Kb","marks":1},{"element":"زوج القاعدة وحمضها المرافق","marks":1},{"element":"زوج الحمض وقاعدته المرافقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"معادلة وتعبير صحيحان وتحديد الزوجين المترافقين"},{"level":"3 درجات","description":"معادلة وتعبير صحيحان مع خطأ في أحد الزوجين، أو استعمال سهم واحد"},{"level":"2 درجتان","description":"معادلة صحيحة فقط أو تعبير صحيح مع الزوجين"},{"level":"1 درجة","description":"كتابة النواتج الصحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["كتابة السهم الواحد","إدخال [H₂O] في تعبير Kb","عدّ OH⁻ حمضًا مرافقًا للقاعدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.619Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) C₆H₁₃NH₂(aq) + H₂O(l) ⇌ C₆H₁₃NH₃⁺(aq) + OH⁻(aq)؛ Kb = [C₆H₁₃NH₃⁺][OH⁻] / [C₆H₁₃NH₂]. (ب) PO₄³⁻(aq) + H₂O(l) ⇌ HPO₄²⁻(aq) + OH⁻(aq)؛ Kb = [HPO₄²⁻][OH⁻] / [PO₄³⁻]. في (ب) يستقبل PO₄³⁻ أيون H⁺ في التفاعل الأمامي، ويستقبل OH⁻ أيون H⁺ من HPO₄²⁻ في التفاعل العكسي.', '["معادلة الهكسيل أمين بسهمي اتزان","تعبير Kb للهكسيل أمين","معادلة PO₄³⁻ موزونة الشحنة (−3 = −2 + −1)","تعبير Kb لـ PO₄³⁻"]'::jsonb, '["(أ) القاعدة تستقبل H⁺ من الماء على مجموعة NH₂ فتصبح NH₃⁺ وينتج OH⁻","Kb = النواتج في البسط ÷ القاعدة في المقام","(ب) PO₄³⁻ يستقبل H⁺ فيصبح HPO₄²⁻ وينتج OH⁻","التحقق من حفظ الشحنة: −3 = (−2) + (−1)","كتابة Kb دون [H₂O]"]'::jsonb, '[{"element":"معادلة الهكسيل أمين","marks":1},{"element":"تعبير Kb للهكسيل أمين","marks":1},{"element":"معادلة أيون الفوسفات","marks":2},{"element":"تعبير Kb لأيون الفوسفات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان وتعبيران صحيحة كلها"},{"level":"4 درجات","description":"خطأ واحد، كاستعمال سهم واحد أو خطأ في شحنة HPO₄²⁻"},{"level":"3 درجات","description":"جزء (أ) صحيح كاملًا مع معادلة (ب) دون تعبيرها، أو العكس"},{"level":"2 درجتان","description":"جزء واحد صحيح كاملًا فقط"},{"level":"1 درجة","description":"معادلة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["كتابة HPO₄⁻ أو HPO₄³⁻ بشحنة خاطئة","جعل PO₄³⁻ ينتج H₃O⁺","إدخال الماء في التعبير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.619Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ الأول: استعمال سهم واحد؛ والصحيح سهما اتزان CH₃NH₂ + H₂O ⇌ CH₃NH₃⁺ + OH⁻ لأن الميثيل أمين قاعدة ضعيفة تتأين جزئيًا. الخطأ الثاني: التعبير مقلوب؛ فالنواتج توضع في البسط والمتفاعلات في المقام. الخطأ الثالث: إدخال [H₂O]؛ وتركيز الماء ثابت في المحاليل المخففة فيُدمج مع الثابت. التعبير الصحيح: Kb = [CH₃NH₃⁺][OH⁻] / [CH₃NH₂].', '["خطأ السهم وتصحيحه مع التعليل بالتأين الجزئي","خطأ قلب التعبير وتصحيحه","خطأ إدخال [H₂O] وتصحيحه مع التعليل","التعبير الصحيح النهائي"]'::jsonb, '[]'::jsonb, '[{"element":"خطأ السهم مع التعليل","marks":1},{"element":"خطأ قلب التعبير","marks":1},{"element":"خطأ إدخال الماء مع التعليل","marks":1},{"element":"كتابة التعبير الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الأخطاء الثلاثة وتصحيحها وتعليلها وكتابة التعبير الصحيح"},{"level":"3 درجات","description":"تحديد الأخطاء الثلاثة مع نقص في التعليل"},{"level":"2 درجتان","description":"تحديد خطأين وتصحيحهما"},{"level":"1 درجة","description":"تحديد خطأ واحد فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["عدّ السهم الواحد صحيحًا","تصحيح القلب مع إبقاء [H₂O]","تعليل حذف الماء بأنه لا يشارك في التفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.620Z"}'::jsonb)
