('mcq', 3, 'في الجدول 2-3 كُتبت معادلة تأين HClO بسهمي اتزان، بينما كُتبت معادلة تأين HClO₄ بسهم واحد. ما سبب ذلك؟', null, '["HClO حمض قوي يتأين كليًا، وHClO₄ حمض ضعيف يتأين جزئيًا","تأين HClO ماص للطاقة، وتأين HClO₄ طارد للطاقة","HClO حمض ضعيف يتأين جزئيًا، وHClO₄ حمض قوي يتأين كليًا","HClO يحتوي على ذرة أكسجين واحدة فلا ينتج أيونات"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 67 — الجدول 2-3 معادلات التأين'),
('mcq', 4, 'أيّ المعادلات الآتية تمثل التأين الثاني لحمض السلينوز H₂SeO₃ في الماء؟', null, '["H₂SeO₃ + H₂O ⇌ H₃O⁺ + HSeO₃⁻","H₂SeO₃ + 2H₂O ⇌ 2H₃O⁺ + SeO₃²⁻","HSeO₃⁻ + H₂O ⇌ H₂SeO₃ + OH⁻","HSeO₃⁻ + H₂O ⇌ H₃O⁺ + SeO₃²⁻"]'::jsonb, 'تطبيق', 'كتابة معادلة', 'متوسط', 'الكتاب ص 69 — مسائل تدريبية 11–13'),
('mcq', 5, 'إذا علمت أن: Ka = [AsO₄³⁻][H₃O⁺] / [HAsO₄²⁻]، فما المعادلة الموزونة التي يعبّر عنها هذا الثابت؟', null, '["HAsO₄²⁻ + H₂O ⇌ H₃O⁺ + AsO₄³⁻","H₃AsO₄ + 3H₂O ⇌ 3H₃O⁺ + AsO₄³⁻","AsO₄³⁻ + H₃O⁺ ⇌ HAsO₄²⁻ + H₂O","HAsO₄²⁻ + H₂O ⇌ H₂AsO₄⁻ + OH⁻"]'::jsonb, 'تطبيق', 'استنتاج معادلة من تعبير', 'صعب', 'الكتاب ص 69 — مسائل تدريبية 11–13'),
('mcq', 6, 'ما الأيونان الناتجان من تأين الحمض الضعيف HIO في الماء؟', null, '["H₃O⁺ و I⁻","H₃O⁺ و IO⁻","OH⁻ و H₂IO⁺","H⁻ و IO⁺"]'::jsonb, 'تطبيق', 'كتابة نواتج', 'متوسط', 'الكتاب ص 69 — مسائل تدريبية 11–13'),
('mcq', 7, 'في محلول لحمض الإيثانويك عند الاتزان كان: [H₃O⁺] = [CH₃COO⁻] = 1.3 × 10⁻³ M، و [CH₃COOH] = 0.099 M. ما قيمة Ka المحسوبة من تعبير ثابت التأين؟', null, '["1.3 × 10⁻²","5.9 × 10⁴","2.6 × 10⁻²","1.7 × 10⁻⁵"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 69 — ثابت تأين الحمض Ka'),
('essay', 1, 'اكتب معادلة تأين حمض الكلوروز HClO₂ في الماء، وتعبير ثابت تأينه Ka، وحدّد القاعدة المرافقة له.', null, null, 'تطبيق', 'كتابة معادلة وتعبير', 'سهل', 'الكتاب ص 69 — مسائل تدريبية 11–13'),
('essay', 2, 'حمض كبريتيد الهيدروجين H₂S حمض ثنائي البروتون. اكتب معادلتي تأينه الأول والثاني في الماء، وتعبير Ka لكل منهما، ثم بيّن أيّ التأينين أكبر علمًا بأن Ka₁ = 8.9 × 10⁻⁸ و Ka₂ = 1 × 10⁻¹⁹.', null, null, 'تطبيق', 'كتابة معادلات وتعابير', 'متوسط', 'الكتاب ص 69 — ثابت تأين الحمض Ka'),
('essay', 3, 'لحمض الإيثانويك المعادلة: CH₃COOH(aq) + H₂O(l) ⇌ H₃O⁺(aq) + CH₃COO⁻(aq). (أ) حدّد الزوجين المترافقين (حمض/قاعدة) وفق نظرية برونستد – لوري. (ب) اكتب تعبير ثابت الاتزان Keq ثم بيّن كيف يُشتق منه تعبير Ka. (ج) لماذا تُستعمل في هذه المعادلة أسهم الاتزان؟', null, null, 'تحليل', 'تحليل معادلة واشتقاق', 'صعب', 'الكتاب ص 68 — قوة الحمض ونظرية برونستد – لوري')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L2-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'يمنح HF أيون H⁺ لجزيء الماء فينتج أيون الهيدرونيوم H₃O⁺ والقاعدة المرافقة F⁻، ولأنه حمض ضعيف يتأين جزئيًا تُكتب المعادلة بسهمي اتزان.', '["السهم الواحد يدل على تأين كلي، وHF حمض ضعيف يتأين جزئيًا.","هذه المعادلة تجعل HF قاعدة تستقبل H⁺ من الماء، وهو حمض يمنح H⁺.","","الأيونات الناتجة غير صحيحة؛ فالحمض يمنح H⁺ للماء فينتج H₃O⁺ وقاعدته المرافقة F⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.620Z"}'::jsonb),
('mcq', 2, 1, 'معادلة التأين: HNO₂ + H₂O ⇌ H₃O⁺ + NO₂⁻، فيكون Ka = [H₃O⁺][NO₂⁻] / [HNO₂]؛ النواتج في البسط والحمض غير المتأين في المقام دون تركيز الماء.', '["التعبير مقلوب؛ فالنواتج توضع في البسط والحمض غير المتأين في المقام.","","هذا تعبير Keq؛ وفي Ka يُدمج تركيز الماء الثابت مع الثابت فلا يظهر.","القاعدة المرافقة لـ HNO₂ هي NO₂⁻ لا NO₃⁻ (أيون النترات من حمض النيتريك)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.620Z"}'::jsonb),
('mcq', 3, 2, 'تُكتب معادلات الأحماض الضعيفة بسهمي اتزان لأنها تتأين جزئيًا ويميل اتزانها إلى اليسار (HClO ⇌ H⁺ + ClO⁻)، وتُكتب معادلات الأحماض القوية بسهم واحد لأنها تتأين كليًا (HClO₄ → H⁺ + ClO₄⁻).', '["التصنيف معكوس؛ فالحمض الذي يُكتب بسهم واحد هو الذي يتأين كليًا.","نوع السهم يعبر عن مدى التأين (كلي أو جزئي) لا عن تغير الطاقة.","","HClO ينتج أيونات H⁺ وClO⁻ لكن بدرجة قليلة لأن تأينه جزئي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.621Z"}'::jsonb),
('mcq', 4, 3, 'يتأين الحمض الثنائي البروتون على خطوتين لكل منهما Ka مختلفة؛ ففي التأين الثاني يمنح أيون HSeO₃⁻ (الناتج من التأين الأول) أيون H⁺ آخر للماء فينتج H₃O⁺ وSeO₃²⁻.', '["هذه معادلة التأين الأول لا الثاني.","هذه تجمع التأينين في معادلة واحدة، بينما يُكتب كل تأين للحمض المتعدد البروتونات منفصلًا.","هنا يسلك HSeO₃⁻ سلوك القاعدة فيستقبل H⁺، والمطلوب تأينه حمضًا يمنح H⁺.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.621Z"}'::jsonb),
('mcq', 5, 0, 'النواتج في البسط AsO₄³⁻ وH₃O⁺، والمتفاعل في المقام HAsO₄²⁻ (والماء لا يظهر)، فالمعادلة: HAsO₄²⁻ + H₂O ⇌ H₃O⁺ + AsO₄³⁻، وهي موزونة في الذرات والشحنة (−2 = +1 − 3).', '["","المقام يحتوي على HAsO₄²⁻ لا H₃AsO₄، والمعادلة المعطاة تجمع ثلاث خطوات تأين.","هذا التفاعل العكسي، وثابته مقلوب التعبير المعطى.","نواتج هذه المعادلة لا تطابق البسط؛ فهي تمثل سلوك HAsO₄²⁻ قاعدةً."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T09:21:20.621Z"}'::jsonb),
('mcq', 6, 1, 'يمنح HIO أيون H⁺ للماء: HIO + H₂O ⇌ H₃O⁺ + IO⁻، فينتج أيون الهيدرونيوم والقاعدة المرافقة IO⁻، ويُستعمل سهما الاتزان لأنه حمض ضعيف.', '["الحمض يفقد أيون H⁺ فقط، فتبقى قاعدته المرافقة IO⁻ محتفظة بذرة الأكسجين.","","هذه نواتج سلوك HIO قاعدةً تستقبل H⁺ من الماء، وهو هنا حمض.","الحمض يمنح أيون هيدروجين موجبًا H⁺ لا H⁻، فتكون قاعدته المرافقة سالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.622Z"}'::jsonb),
('mcq', 7, 3, 'Ka = [H₃O⁺][CH₃COO⁻] / [CH₃COOH] = (1.3 × 10⁻³)(1.3 × 10⁻³) / 0.099 = 1.69 × 10⁻⁶ / 0.099 = 1.7 × 10⁻⁵ (بمنزلتين معنويتين)، وهي قريبة من القيمة في الجدول 2-4.', '["لم يُضرب تركيزا الأيونين، بل استُعمل تركيز أيون واحد فقط في البسط.","التعبير مقلوب؛ قُسم تركيز الحمض على حاصل ضرب تركيزي الأيونين.","جُمع تركيزا الأيونين بدل ضربهما في البسط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.622Z"}'::jsonb),
('essay', 1, null::int, null, null, 'HClO₂(aq) + H₂O(l) ⇌ H₃O⁺(aq) + ClO₂⁻(aq)؛ Ka = [H₃O⁺][ClO₂⁻] / [HClO₂]؛ القاعدة المرافقة هي ClO₂⁻.', '["معادلة بسهمي اتزان ونواتج صحيحة","تعبير Ka صحيح دون [H₂O]","القاعدة المرافقة ClO₂⁻"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"تعبير Ka","marks":1},{"element":"القاعدة المرافقة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"معادلة وتعبير صحيحان وتحديد القاعدة المرافقة"},{"level":"2 درجتان","description":"عنصران صحيحان، أو الثلاثة مع استعمال سهم واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["كتابة السهم الواحد","إدخال [H₂O] في المقام","كتابة القاعدة المرافقة ClO₃⁻ أو Cl⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.622Z"}'::jsonb),
('essay', 2, null::int, null, null, 'التأين الأول: H₂S + H₂O ⇌ H₃O⁺ + HS⁻؛ Ka₁ = [H₃O⁺][HS⁻] / [H₂S]. التأين الثاني: HS⁻ + H₂O ⇌ H₃O⁺ + S²⁻؛ Ka₂ = [H₃O⁺][S²⁻] / [HS⁻]. التأين الأول أكبر بكثير لأن Ka₁ (8.9 × 10⁻⁸) أكبر بكثير من Ka₂ (1 × 10⁻¹⁹)، فـ HS⁻ حمض أضعف بكثير من H₂S.', '["معادلة التأين الأول","تعبير Ka₁","معادلة التأين الثاني","تعبير Ka₂","التأين الأول أكبر لأن Ka₁ أكبر"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة التأين الأول","marks":1},{"element":"تعبير Ka₁","marks":1},{"element":"معادلة التأين الثاني","marks":1},{"element":"تعبير Ka₂","marks":1},{"element":"المقارنة مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان وتعبيران صحيحة ومقارنة معللة"},{"level":"4 درجات","description":"خطأ واحد في معادلة أو تعبير أو مقارنة دون تعليل"},{"level":"3 درجات","description":"التأين الأول كاملًا مع المقارنة، أو المعادلتان والتعبيران دون مقارنة مع خطأ واحد"},{"level":"2 درجتان","description":"التأين الأول فقط كاملًا"},{"level":"1 درجة","description":"معادلة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["كتابة التأينين في معادلة واحدة","كتابة S²⁻ ناتجًا للتأين الأول","الاستنتاج أن التأين الثاني أكبر لأن الأس أكبر عدديًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.622Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الزوج الأول: CH₃COOH (حمض) وقاعدته المرافقة CH₃COO⁻؛ الزوج الثاني: H₂O (قاعدة) وحمضها المرافق H₃O⁺. (ب) Keq = [H₃O⁺][CH₃COO⁻] / [CH₃COOH][H₂O]؛ وبما أن تركيز الماء السائل ثابت في المحاليل المخففة يُدمج مع Keq: Keq[H₂O] = Ka = [H₃O⁺][CH₃COO⁻] / [CH₃COOH]. (ج) لأن حمض الإيثانويك حمض ضعيف يتأين جزئيًا، فيتكون مخلوط اتزان يميل إلى اليسار لأن القاعدة المرافقة CH₃COO⁻ أقوى من الماء في جذب H⁺.', '["الزوج CH₃COOH / CH₃COO⁻","الزوج H₂O / H₃O⁺","تعبير Keq متضمنًا [H₂O]","Ka = Keq[H₂O] مع تعليل ثبات تركيز الماء","تعليل سهمي الاتزان بالتأين الجزئي"]'::jsonb, '["تحديد المانح (CH₃COOH) والمستقبل (H₂O) لأيون H⁺","كتابة Keq للنواتج على المتفاعلات","ضرب الطرفين في [H₂O] الثابت للحصول على Ka","ربط نوع السهم بدرجة التأين"]'::jsonb, '[{"element":"الزوجان المترافقان","marks":2},{"element":"تعبير Keq","marks":1},{"element":"اشتقاق Ka مع التعليل","marks":1},{"element":"تعليل أسهم الاتزان","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة لجميع الأجزاء"},{"level":"4 درجات","description":"خطأ في عنصر واحد"},{"level":"3 درجات","description":"الزوجان صحيحان مع أحد الجزأين (ب) أو (ج)"},{"level":"2 درجتان","description":"الزوجان المترافقان فقط، أو الجزآن (ب) و(ج) دون (أ)"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["عدّ H₃O⁺ قاعدة مرافقة للحمض","نسيان [H₂O] في تعبير Keq","تعليل حذف الماء بأنه لا يتفاعل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.623Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L2-O04') and x.type = v.type and x.number = v.number
