from (values
('mcq', 1, 'وفق نظرية برونستد – لوري، ماذا يمكن القول عن القاعدة المرافقة X⁻ لحمض قوي HX؟', null, '["قاعدة قوية لأنها ناتجة عن حمض قوي","قاعدة أقوى من الماء في جذب أيون H⁺","قاعدة ضعيفة جذبها لأيون H⁺ أقل من جذب الماء له","ليست قاعدة لأنها لا تستقبل أيونات H⁺ مطلقًا"]'::jsonb, 'فهم', 'تفسير مفهوم', 'سهل', 'الكتاب ص 68 — قوة الحمض ونظرية برونستد – لوري'),
('mcq', 2, 'يتأين الحمض القوي HX في الماء بنسبة 100% تقريبًا. ما تفسير ذلك وفق نظرية برونستد – لوري؟', null, '["X⁻ قاعدة أقوى من الماء، فيقع اتزان التأين كليًا إلى اليمين","الماء قاعدة أقوى من X⁻، فيقع اتزان التأين كليًا تقريبًا إلى اليمين","الماء يسلك سلوك الحمض فيمنح أيون H⁺ إلى الحمض HX","الحمض HX لا ينتج قاعدة مرافقة عند تأينه في الماء"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 68 — قوة الحمض ونظرية برونستد – لوري'),
('mcq', 3, 'يميل اتزان تأين حمض الإيثانويك في الماء إلى يسار المعادلة. أيّ العبارات الآتية تفسر ذلك؟', null, '["القاعدة المرافقة CH₃COO⁻ أقوى من الماء في جذب أيون H⁺","الماء أقوى من القاعدة المرافقة CH₃COO⁻ في جذب أيون H⁺","حمض الإيثانويك لا يمنح أيون H⁺ للماء مطلقًا","جزيئات الماء لا تستقبل أيونات H⁺ من حمض الإيثانويك"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 68 — قوة الحمض ونظرية برونستد – لوري'),
('mcq', 4, 'اعتمادًا على قيم Ka في الجدول، أيّ القواعد المرافقة الآتية هي الأقوى في جذب أيون H⁺؟', '{"headers":["الحمض","القاعدة المرافقة","Ka (298 K)"],"rows":[["HF","F⁻","6.3 × 10⁻⁴"],["CH₃COOH","CH₃COO⁻","1.8 × 10⁻⁵"],["H₂CO₃","HCO₃⁻","4.5 × 10⁻⁷"],["HCN","CN⁻","6.2 × 10⁻¹⁰"]]}'::jsonb, '["أيون الفلوريد F⁻","أيون الإيثانوات CH₃COO⁻","أيون السيانيد CN⁻","أيون الكربونات الهيدروجينية HCO₃⁻"]'::jsonb, 'تحليل', 'مقارنة باستعمال بيانات', 'متوسط', 'الكتاب ص 69 — الجدول 2-4 ثوابت تأين الأحماض الضعيفة'),
('mcq', 5, 'أيّ القواعد المرافقة الآتية هي الأضعف في جذب أيون الهيدروجين H⁺؟', null, '["أيون الفلوريد F⁻","أيون السيانيد CN⁻","أيون الإيثانوات CH₃COO⁻","أيون الكلوريد Cl⁻"]'::jsonb, 'فهم', 'مقارنة', 'صعب', 'الكتاب ص 68 — قوة الحمض ونظرية برونستد – لوري'),
('mcq', 6, 'في معادلة تأين الحمض القوي: HX(aq) + H₂O(l) → H₃O⁺(aq) + X⁻(aq)، ماذا يمثل H₃O⁺ وفق نظرية برونستد – لوري؟', null, '["القاعدة المرافقة للحمض HX","الحمض المرافق للقاعدة H₂O","الحمض المرافق للقاعدة X⁻","القاعدة الأقوى في هذا التفاعل"]'::jsonb, 'تذكر', 'تحديد أزواج مترافقة', 'سهل', 'الكتاب ص 68 — قوة الحمض ونظرية برونستد – لوري'),
('mcq', 7, 'عند المقارنة بين تأين HCl وتأين CH₃COOH في الماء وفق نظرية برونستد – لوري، أيّ العبارات الآتية صحيحة؟', null, '["يتغلب الماء على Cl⁻ في جذب H⁺، بينما يتغلب CH₃COO⁻ على الماء","يتغلب الماء على CH₃COO⁻ في جذب H⁺، بينما يتغلب Cl⁻ على الماء","يتغلب كل من Cl⁻ و CH₃COO⁻ على الماء في جذب H⁺","يتغلب الماء على كل من Cl⁻ و CH₃COO⁻ في جذب H⁺"]'::jsonb, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 68 — قوة الحمض ونظرية برونستد – لوري'),
('essay', 1, 'ما العلاقة بين قوة الحمض الضعيف وقوة قاعدته المرافقة؟ وضّح إجابتك بمثال من الحمضين HF (Ka = 6.3 × 10⁻⁴) وHCN (Ka = 6.2 × 10⁻¹⁰).', null, null, 'فهم', 'تفسير علاقة', 'سهل', 'الكتاب ص 71 — التقويم 2-2 (السؤالان 16 و17)'),
('essay', 2, 'استعمل نظرية برونستد – لوري لتفسير تأين HCl كليًا في الماء بينما يتأين CH₃COOH جزئيًا. اكتب معادلة تأين كل منهما في الماء بالسهم المناسب، وحدّد القاعدتين المتنافستين على أيون H⁺ في كل معادلة.', null, null, 'فهم', 'تفسير بالنظرية', 'صعب', 'الكتاب ص 68 — قوة الحمض ونظرية برونستد – لوري'),
('essay', 3, 'صف محتويات محلولين مائيين مخففين متساويي التركيز: أحدهما للحمض القوي HI والآخر للحمض الضعيف HCOOH، من حيث الجسيمات الموجودة ووفرتها النسبية، ثم فسّر الفرق باستعمال قوة القاعدة المرافقة لكل منهما.', null, null, 'تحليل', 'وصف وتفسير', 'متوسط', 'الكتاب ص 71 — التقويم 2-2 (السؤالان 16 و17)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
