select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'يمثل HX حمضًا قويًا قاعدته المرافقة ضعيفة؛ فالماء قاعدة أقوى (في التفاعل الأمامي) من X⁻ (في التفاعل العكسي)، أي أن جذب H₂O لأيون H⁺ أكبر من جذب X⁻ له.', '["العلاقة عكسية؛ فالحمض القوي تكون قاعدته المرافقة ضعيفة.","لو كانت X⁻ أقوى من الماء لمال الاتزان إلى اليسار ولكان الحمض ضعيفًا.","","X⁻ قاعدة مرافقة (في التفاعل العكسي) لكنها ضعيفة جدًا في جذب H⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T09:21:20.624Z"}'::jsonb),
('mcq', 2, 1, 'في «معركة القواعد» على أيون H⁺ بين H₂O وX⁻، يكون الماء القاعدة الأقوى عندما يكون الحمض قويًا؛ فجذب H₂O لأيون H⁺ أكبر من جذب X⁻، فيقع الاتزان كليًا تقريبًا إلى اليمين وتُكتب المعادلة بسهم واحد.', '["لو كانت X⁻ أقوى من الماء لاستعادت أيون H⁺ ومال الاتزان إلى اليسار.","","الماء في تأين الحمض يسلك سلوك القاعدة فيستقبل H⁺ من HX.","كل حمض ينتج قاعدة مرافقة على جهة النواتج، وهي هنا X⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.624Z"}'::jsonb),
('mcq', 3, 0, 'يميل اتزان الحمض الضعيف إلى اليسار لأن قاعدته المرافقة (CH₃COO⁻ في التفاعل العكسي) أقوى من الماء (في التفاعل الأمامي) في جذب أيونات الهيدروجين، فتستعيد H⁺ ويبقى معظم الحمض غير متأين.', '["","لو كان الماء أقوى لمال الاتزان إلى اليمين كما في الأحماض القوية.","يمنح الحمض أيون H⁺ لبعض جزيئات الماء، فتأينه جزئي لا معدوم.","الماء يستقبل H⁺ من بعض جزيئات الحمض فعلًا، ولذلك يتكون H₃O⁺ وCH₃COO⁻ بكمية قليلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.624Z"}'::jsonb),
('mcq', 4, 2, 'كلما كان الحمض الضعيف أضعف كانت قاعدته المرافقة أقوى. أضعف الأحماض في الجدول HCN (Ka = 6.2 × 10⁻¹⁰)، لذا فقاعدته المرافقة CN⁻ هي الأقوى في جذب H⁺.', '["F⁻ قاعدة مرافقة لأقوى الأحماض في الجدول (HF)، فهي الأضعف لا الأقوى.","حمضها CH₃COOH أقوى من HCN (Ka أكبر)، فقاعدتها المرافقة أضعف من CN⁻.","","حمضها H₂CO₃ أقوى من HCN، فقاعدتها المرافقة أضعف من CN⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T09:21:20.624Z"}'::jsonb),
('mcq', 5, 3, 'Cl⁻ هي القاعدة المرافقة لحمض الهيدروكلوريك القوي الذي يتأين كليًا، والحمض القوي تكون قاعدته المرافقة ضعيفة جدًا، فهي الأضعف هنا؛ أما F⁻ وCN⁻ وCH₃COO⁻ فقواعد مرافقة لأحماض ضعيفة فهي قوية نسبيًا.', '["F⁻ قاعدة مرافقة لحمض ضعيف (HF)، فهي أقوى نسبيًا من Cl⁻ القاعدة المرافقة لحمض قوي.","CN⁻ قاعدة مرافقة لحمض ضعيف جدًا (HCN)، فهي قوية نسبيًا.","قاعدة مرافقة لحمض ضعيف، فهي أقوى من الماء في جذب H⁺ وأقوى من Cl⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T09:21:20.625Z"}'::jsonb),
('mcq', 6, 1, 'يستقبل الماء (القاعدة) أيون H⁺ من HX فيتحول إلى H₃O⁺، لذا فـ H₃O⁺ هو الحمض المرافق للقاعدة H₂O، بينما X⁻ هي القاعدة المرافقة للحمض HX.', '["القاعدة المرافقة للحمض HX هي X⁻ الناتجة عن فقده أيون H⁺.","","الحمض المرافق لـ X⁻ هو HX، فهما الزوج المترافق الآخر.","H₃O⁺ حمض لا قاعدة، وأقوى قاعدة في التفاعل هي الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.625Z"}'::jsonb),
('mcq', 7, 0, 'HCl حمض قوي قاعدته المرافقة Cl⁻ ضعيفة، فالماء يجذب H⁺ أكثر منها ويتأين الحمض كليًا. أما CH₃COOH فحمض ضعيف قاعدته المرافقة CH₃COO⁻ أقوى من الماء في جذب H⁺، فيميل الاتزان إلى اليسار.', '["","العبارة معكوسة؛ فهي تجعل HCl ضعيفًا وCH₃COOH قويًا.","لو تغلب Cl⁻ على الماء لكان HCl حمضًا ضعيفًا، وهو حمض قوي.","لو تغلب الماء على CH₃COO⁻ لتأين حمض الإيثانويك كليًا، وهو يتأين جزئيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.625Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العلاقة عكسية: كلما كان الحمض الضعيف أضعف كانت قاعدته المرافقة أقوى (أقدر على جذب H⁺). فـ HCN أضعف من HF لأن Ka له أصغر، لذا فقاعدته المرافقة CN⁻ أقوى من F⁻ القاعدة المرافقة لـ HF.', '["العلاقة عكسية","الحمض الأضعف قاعدته المرافقة أقوى","HCN أضعف من HF بدلالة Ka","CN⁻ أقوى من F⁻"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر العلاقة العكسية","marks":1},{"element":"تحديد الحمض الأضعف بدلالة Ka","marks":1},{"element":"تحديد القاعدة المرافقة الأقوى","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"علاقة صحيحة ومثال صحيح كامل"},{"level":"2 درجتان","description":"علاقة صحيحة مع خطأ في جزء من المثال، أو مثال صحيح دون صياغة العلاقة"},{"level":"1 درجة","description":"ذكر العلاقة العكسية فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["القول إن الحمض الأقوى قاعدته المرافقة أقوى","عدّ F⁻ أقوى لأن HF أقوى","الخلط بين القاعدة المرافقة والحمض المرافق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.625Z"}'::jsonb),
('essay', 2, null::int, null, null, 'HCl(aq) + H₂O(l) → H₃O⁺(aq) + Cl⁻(aq): القاعدتان المتنافستان H₂O (في التفاعل الأمامي) وCl⁻ (في التفاعل العكسي)؛ الماء أقوى من Cl⁻ في جذب H⁺، فيقع الاتزان كليًا تقريبًا إلى اليمين ويُكتب بسهم واحد، أي أن HCl حمض قوي قاعدته المرافقة ضعيفة. CH₃COOH(aq) + H₂O(l) ⇌ H₃O⁺(aq) + CH₃COO⁻(aq): القاعدتان المتنافستان H₂O وCH₃COO⁻؛ والقاعدة المرافقة CH₃COO⁻ أقوى من الماء في جذب H⁺ فيميل الاتزان إلى اليسار ويُكتب بسهمي اتزان، أي أن CH₃COOH حمض ضعيف قاعدته المرافقة قوية نسبيًا.', '["معادلة HCl بسهم واحد","معادلة CH₃COOH بسهمي اتزان","المتنافسان في HCl: H₂O وCl⁻ والماء أقوى","المتنافسان في CH₃COOH: H₂O وCH₃COO⁻ والقاعدة المرافقة أقوى","الربط: الحمض القوي قاعدته المرافقة ضعيفة والضعيف قاعدته المرافقة قوية نسبيًا"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلتان بالسهمين الصحيحين","marks":2},{"element":"تفسير تأين HCl","marks":1},{"element":"تفسير تأين CH₃COOH","marks":1},{"element":"الربط بقوة القاعدة المرافقة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان صحيحتان وتفسيران كاملان مع الربط"},{"level":"4 درجات","description":"نقص عنصر واحد كخطأ في سهم إحدى المعادلتين"},{"level":"3 درجات","description":"تفسيران صحيحان دون معادلات، أو معادلتان مع تفسير واحد"},{"level":"2 درجتان","description":"معادلتان صحيحتان فقط أو تفسير واحد صحيح"},{"level":"1 درجة","description":"معادلة واحدة صحيحة أو تصنيف الحمضين فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["عدّ Cl⁻ أقوى من الماء","كتابة معادلة الحمض الضعيف بسهم واحد","تفسير الفرق بالتركيز أو بعدد ذرات الهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.626Z"}'::jsonb),
('essay', 3, null::int, null, null, 'محلول HI: يحتوي على أيونات H₃O⁺ وI⁻ وجزيئات الماء، ولا يكاد يحتوي على جزيئات HI غير متأينة لأن HI يتأين كليًا. محلول HCOOH: يحتوي في معظمه على جزيئات HCOOH غير متأينة مع كمية قليلة من أيونات H₃O⁺ وHCOO⁻ وجزيئات الماء، لأنه يتأين جزئيًا. التفسير: I⁻ قاعدة مرافقة ضعيفة جذبها لـ H⁺ أقل من الماء فيقع الاتزان إلى اليمين، أما HCOO⁻ فقاعدة مرافقة أقوى من الماء في جذب H⁺ فيميل الاتزان إلى اليسار.', '["HI: أيونات H₃O⁺ وI⁻ دون جزيئات HI تقريبًا","HCOOH: جزيئات غير متأينة كثيرة مع أيونات قليلة","I⁻ قاعدة مرافقة ضعيفة أضعف من الماء","HCOO⁻ قاعدة مرافقة أقوى من الماء"]'::jsonb, '[]'::jsonb, '[{"element":"وصف محلول HI","marks":1},{"element":"وصف محلول HCOOH","marks":1},{"element":"تفسير HI بقوة القاعدة المرافقة","marks":1},{"element":"تفسير HCOOH بقوة القاعدة المرافقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"وصف صحيح للمحلولين وتفسير صحيح لكليهما"},{"level":"3 درجات","description":"وصف صحيح للمحلولين مع تفسير أحدهما فقط"},{"level":"2 درجتان","description":"وصف صحيح للمحلولين دون تفسير"},{"level":"1 درجة","description":"وصف صحيح لمحلول واحد فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["القول إن محلول HCOOH لا يحتوي على أيونات","الإشارة إلى وجود جزيئات HI كثيرة في المحلول","عدّ I⁻ قاعدة قوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T09:21:20.626Z"}'::jsonb)
