from (values
('mcq', 1, 'ما المقصود بالقاعدة القوية؟', null, '["القاعدة التي يكون تركيزها في المحلول المائي مرتفعًا","القاعدة التي تتأين جزئيًا مكوّنة مخلوط اتزان","القاعدة التي تكون ذائبيتها في الماء مرتفعة دائمًا","القاعدة التي تتحلل كليًا منتجة أيونات فلزية وأيونات هيدروكسيد"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 70 — القواعد القوية والقواعد الضعيفة'),
