('mcq', 4, 'أيّ العبارات الآتية تصف محلولًا مائيًا مخففًا من الميثيل أمين CH₃NH₂ عند الاتزان؟', null, '["أيونات CH₃NH₃⁺ وOH⁻ فقط دون جزيئات CH₃NH₂","جزيئات CH₃NH₂ كثيرة مع قليل من أيونات CH₃NH₃⁺ وOH⁻","جزيئات CH₃NH₂ فقط دون أي أيونات","أيونات OH⁻ أكثر عددًا من جزيئات CH₃NH₂"]'::jsonb, 'فهم', 'وصف مكونات محلول', 'متوسط', 'الكتاب ص 70 — القواعد القوية والقواعد الضعيفة'),
('mcq', 5, 'أيّ المعادلات الآتية تمثل تحلل هيدروكسيد البوتاسيوم في الماء تمثيلًا صحيحًا؟', null, '["KOH(s) ⇌ K⁺(aq) + OH⁻(aq)","KOH(s) + H₂O(l) ⇌ KOH₂⁺(aq) + OH⁻(aq)","KOH(s) → K⁺(aq) + O²⁻(aq) + H⁺(aq)","KOH(s) → K⁺(aq) + OH⁻(aq)"]'::jsonb, 'تطبيق', 'اختيار معادلة', 'متوسط', 'الكتاب ص 70 — الجدول 2-5 معادلات التأين للقواعد القوية'),
('mcq', 6, 'محلولان تركيز كل منهما 0.10 M، أحدهما من NaOH والآخر من NH₃. أيّ العبارات الآتية صحيحة؟', null, '["[OH⁻] متساوٍ في المحلولين؛ لأن تركيزيهما متساويان","[OH⁻] في محلول NH₃ أكبر؛ لأنه يتفاعل مع الماء","[OH⁻] في محلول NaOH أكبر؛ لأن NaOH يتحلل كليًا وNH₃ يتأين جزئيًا","محلول NH₃ لا يحتوي على OH⁻؛ لعدم وجود OH في صيغته"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 70 — القواعد القوية والقواعد الضعيفة'),
('mcq', 7, 'يميل اتزان تأين الميثيل أمين في الماء إلى اليسار: CH₃NH₂ + H₂O ⇌ CH₃NH₃⁺ + OH⁻. ما التفسير الذي يقدمه الكتاب لذلك؟', null, '["جزيء CH₃NH₂ يجذب H⁺ بقوة أكبر من جذب OH⁻ له","أيون OH⁻ يجذب H⁺ بقوة أكبر من جذب CH₃NH₂ له","الماء لا يستطيع منح أيون H⁺ لأي قاعدة","الميثيل أمين يتحلل كليًا ثم يعود فيتكون"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 71 — الجدول 2-6 والخلاصة'),
('essay', 1, 'قارن بين القواعد القوية والقواعد الضعيفة من حيث: درجة التأين في المحاليل المائية المخففة، ونوع السهم في معادلة التأين، مع ذكر مثالين على كل منهما.', null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 70 — القواعد القوية والقواعد الضعيفة'),
('essay', 2, 'صنّف القواعد الآتية إلى قوية وضعيفة: NaOH، C₂H₅NH₂، Ba(OH)₂، NH₃، CsOH، C₆H₅NH₂. ثم اكتب معادلة التأين في الماء لقاعدة قوية واحدة ولقاعدة ضعيفة واحدة منها.', null, null, 'فهم', 'تصنيف وكتابة معادلات', 'متوسط', 'الكتاب ص 70 — الجدول 2-5 معادلات التأين للقواعد القوية'),
('essay', 3, 'حُضّر محلولان متساويا التركيز من KOH ومن NH₃. (أ) توقّع أيّهما أفضل توصيلًا للتيار الكهربائي، وعلّل. (ب) لا تحتوي صيغة NH₃ على مجموعة OH، فكيف ينتج محلولها أيونات OH⁻؟ اكتب المعادلة.', null, null, 'تحليل', 'توقع وتفسير', 'صعب', 'الكتاب ص 70 — القواعد القوية والقواعد الضعيفة')
