('mcq', 4, 1, 'القواعد الضعيفة تتأين جزئيًا مكوّنة مخلوط اتزان من الجزيئات والأيونات؛ ويميل اتزان الميثيل أمين إلى اليسار، فتغلب الجزيئات غير المتأينة مع كمية قليلة من CH₃NH₃⁺ وOH⁻.', '["هذا وصف قاعدة تأينت كليًا، والميثيل أمين يتأين جزئيًا.","","الميثيل أمين يتأين جزئيًا، فلا بد من وجود بعض أيونات OH⁻.","في القاعدة الضعيفة تبقى الجزيئات غير المتأينة هي الغالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.627Z"}'::jsonb),
('mcq', 5, 3, 'هيدروكسيد البوتاسيوم قاعدة قوية تتحلل كليًا إلى أيونات البوتاسيوم وأيونات الهيدروكسيد، فتُكتب المعادلة بسهم واحد كما في الجدول 2-5.', '["سهما الاتزان يدلان على تأين جزئي، وKOH قاعدة قوية تتحلل كليًا.","KOH لا يستقبل H⁺ من الماء، بل يتحلل مباشرة إلى أيوناته.","أيون الهيدروكسيد لا يتفكك؛ فالقاعدة القوية تنتج أيونات فلزية وأيونات OH⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.628Z"}'::jsonb),
('mcq', 6, 2, 'NaOH قاعدة قوية تتحلل كليًا فيكون [OH⁻] = 0.10 M تقريبًا، أما NH₃ فقاعدة ضعيفة تتأين جزئيًا فينتج كمية أقل بكثير من OH⁻ عند التركيز نفسه.', '["تساوي التركيز لا يعني تساوي [OH⁻]؛ فدرجة التأين مختلفة.","تفاعل NH₃ مع الماء جزئي، فينتج OH⁻ أقل من NaOH المتحلل كليًا.","","NH₃ ينتج OH⁻ باستقباله H⁺ من الماء، وإن كان بكمية قليلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.628Z"}'::jsonb),
('mcq', 7, 1, 'يميل الاتزان إلى اليسار لأن CH₃NH₂ قاعدة ضعيفة والقاعدة المرافقة OH⁻ قوية؛ إذ إن جذب أيون الهيدروكسيد لأيون الهيدروجين أقوى من جذب جزيء الميثيل أمين له.', '["لو كان الميثيل أمين أقوى في جذب H⁺ لمال الاتزان إلى اليمين.","","الماء يمنح H⁺ للقاعدة فعلًا، وإلا لما تكون OH⁻.","التحلل الكلي صفة القواعد القوية، والميثيل أمين يتأين جزئيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.629Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القواعد القوية: تتحلل (تتأين) كليًا منتجة أيونات فلزية وأيونات هيدروكسيد، وتُكتب معادلاتها بسهم واحد (→)، ومن أمثلتها NaOH وKOH (ويقبل RbOH وCsOH وCa(OH)₂ وBa(OH)₂). القواعد الضعيفة: تتأين جزئيًا فقط مكوّنة مخلوط اتزان من الجزيئات والأيونات، وتُكتب معادلاتها بسهمي اتزان (⇌)، ومن أمثلتها NH₃ وCH₃NH₂ (ويقبل C₂H₅NH₂ وC₆H₅NH₂).', '["القوية تتأين كليًا","الضعيفة تتأين جزئيًا","سهم واحد للقوية وسهما اتزان للضعيفة","مثالان صحيحان للقوية","مثالان صحيحان للضعيفة"]'::jsonb, '[]'::jsonb, '[{"element":"درجة التأين لكل نوع","marks":2},{"element":"نوع السهم","marks":1},{"element":"أمثلة القواعد القوية","marks":1},{"element":"أمثلة القواعد الضعيفة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة كاملة بالمعيارين وأربعة أمثلة صحيحة"},{"level":"4 درجات","description":"نقص عنصر واحد أو خطأ في مثال"},{"level":"3 درجات","description":"درجة التأين صحيحة مع الأمثلة دون نوع السهم"},{"level":"2 درجتان","description":"درجة التأين صحيحة فقط"},{"level":"1 درجة","description":"أمثلة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["عدّ NH₃ قاعدة قوية","ربط قوة القاعدة بتركيزها","كتابة معادلات القواعد الضعيفة بسهم واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.629Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القوية: NaOH وBa(OH)₂ وCsOH. الضعيفة: C₂H₅NH₂ وNH₃ وC₆H₅NH₂. مثال قوية: Ba(OH)₂(s) → Ba²⁺(aq) + 2OH⁻(aq) (أو NaOH(s) → Na⁺(aq) + OH⁻(aq)). مثال ضعيفة: NH₃(aq) + H₂O(l) ⇌ NH₄⁺(aq) + OH⁻(aq) (أو معادلة الإيثيل أمين أو الأنيلين المماثلة).', '["تصنيف القواعد القوية الثلاث","تصنيف القواعد الضعيفة الثلاث","معادلة قاعدة قوية بسهم واحد","معادلة قاعدة ضعيفة بسهمي اتزان"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف القوية","marks":1},{"element":"تصنيف الضعيفة","marks":1},{"element":"معادلة القاعدة القوية","marks":1},{"element":"معادلة القاعدة الضعيفة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح كامل ومعادلتان صحيحتان"},{"level":"3 درجات","description":"تصنيف صحيح ومعادلة واحدة صحيحة، أو خطأ في السهم"},{"level":"2 درجتان","description":"تصنيف صحيح فقط، أو معادلتان صحيحتان مع خطأ في التصنيف"},{"level":"1 درجة","description":"تصنيف نصف القواعد تقريبًا تصنيفًا صحيحًا"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["نسيان المعامل 2 لـ OH⁻ في معادلة Ba(OH)₂","كتابة NH₄OH ناتجًا بدل NH₄⁺ وOH⁻","عدّ الأمينات قواعد قوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.629Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) محلول KOH أفضل توصيلًا؛ لأن توصيل القاعدة للتيار يعتمد على مقدار ما تنتجه من أيونات في المحلول، وKOH قاعدة قوية تتحلل كليًا إلى K⁺ وOH⁻، أما NH₃ فقاعدة ضعيفة تتأين جزئيًا فينتج محلولها أيونات أقل. (ب) تستقبل NH₃ أيون H⁺ من جزيء الماء فيتحول الماء إلى OH⁻: NH₃(aq) + H₂O(l) ⇌ NH₄⁺(aq) + OH⁻(aq)، فالقاعدة الضعيفة تنتج OH⁻ بتفاعلها مع الماء لا بتحللها.', '["KOH أفضل توصيلًا","التوصيل يعتمد على عدد الأيونات","KOH يتحلل كليًا وNH₃ يتأين جزئيًا","NH₃ تستقبل H⁺ من الماء","المعادلة بسهمي اتزان"]'::jsonb, '[]'::jsonb, '[{"element":"التوقع الصحيح","marks":1},{"element":"التعليل بدرجة التأين وعدد الأيونات","marks":2},{"element":"تفسير إنتاج NH₃ لأيونات OH⁻","marks":1},{"element":"المعادلة الصحيحة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"توقع صحيح مع تعليل كامل وتفسير صحيح ومعادلة صحيحة"},{"level":"4 درجات","description":"نقص عنصر واحد"},{"level":"3 درجات","description":"الجزء (أ) كاملًا فقط، أو الجزء (ب) كاملًا مع التوقع"},{"level":"2 درجتان","description":"توقع صحيح مع تعليل ناقص، أو معادلة صحيحة فقط مع التوقع"},{"level":"1 درجة","description":"التوقع الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["توقع تساوي التوصيل لتساوي التركيز","كتابة NH₃ → NH₂⁻ + H⁺","كتابة معادلة الأمونيا بسهم واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T09:21:20.630Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
