('mcq', 2, 'على ماذا تدل القيمة الصغيرة لثابت حاصل الذائبية لهيدروكسيد الكالسيوم (Ksp = 6.5 × 10⁻⁶)؟', null, '["على أن ما يذوب منه يتأين جزئيًا فقط","على أنه قاعدة ضعيفة مثل الأمونيا","على وجود كمية كبيرة من OH⁻ في محلوله المشبع","على وجود كمية قليلة من OH⁻ في محلوله المشبع"]'::jsonb, 'تذكر', 'دلالة قيمة', 'سهل', 'الكتاب ص 70 — هيدروكسيد الكالسيوم قاعدة قوية قليلة الذوبان'),
('mcq', 3, 'أُذيب 0.010 mol من Ca(OH)₂ ذوبانًا تامًا في ماء حتى أصبح حجم المحلول 1.0 L. ما تركيز أيونات OH⁻ في المحلول؟', null, '["0.010 M","0.020 M","0.0050 M","1.0 × 10⁻⁴ M"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 70 — الجدول 2-5 معادلات التأين للقواعد القوية'),
('mcq', 4, 'أيّ العبارات الآتية تقارن مقارنة صحيحة بين محلول مشبع من Ca(OH)₂ ومحلول من الأمونيا NH₃؟', null, '["يحتوي كلا المحلولين على جزيئات ذائبة غير متأينة كثيرة","يحتوي محلول Ca(OH)₂ على وحدات ذائبة غير متأينة لقلة ذوبانه","لا يحتوي محلول Ca(OH)₂ على وحدات ذائبة غير متأينة، بخلاف محلول NH₃","تتأين جزيئات NH₃ كليًا، بخلاف Ca(OH)₂ الذي يتأين جزئيًا"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 70 — هيدروكسيد الكالسيوم قاعدة قوية قليلة الذوبان'),
('mcq', 5, 'قال طالب: «Ca(OH)₂ قاعدة ضعيفة؛ لأن محلوله المشبع يحتوي على كمية قليلة من أيونات OH⁻». ما التقويم الصحيح لهذه العبارة؟', null, '["خاطئة؛ فقلة OH⁻ سببها انخفاض الذائبية لا التأين الجزئي","صحيحة؛ لأن قوة القاعدة تُقاس بتركيز OH⁻ في محلولها المشبع","صحيحة؛ لأن صغر Ksp يدل على أن ما يذوب يتأين جزئيًا","خاطئة؛ لأن محلوله المشبع يحتوي على كمية كبيرة من OH⁻"]'::jsonb, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 70 — هيدروكسيد الكالسيوم قاعدة قوية قليلة الذوبان'),
('mcq', 6, 'ما الخاصية التي يُحكم بها على أن هيدروكسيد فلز قليل الذوبان قاعدة قوية؟', null, '["مقدار ذائبيته في الماء","تركيز OH⁻ في محلوله المشبع","درجة تأين الجزء الذائب منه في الماء","عدد مجموعات OH في صيغته"]'::jsonb, 'فهم', 'تمييز بين مفهومين', 'سهل', 'الكتاب ص 70 — هيدروكسيد الكالسيوم قاعدة قوية قليلة الذوبان'),
('mcq', 7, 'يكون تركيز OH⁻ في محلول مشبع من Ca(OH)₂ نحو 0.02 M فقط. أيّ العبارات الآتية تقارن مقارنة صحيحة بين هذا المحلول ومحلول NaOH تركيزه 0.10 M من حيث التوصيل الكهربائي؟', null, '["يتساوى المحلولان في التوصيل لأن كلتا القاعدتين قوية","محلول Ca(OH)₂ أفضل توصيلًا لأن كل وحدة منه تنتج أيوني OH⁻","لا يوصل محلول Ca(OH)₂ الكهرباء لأنه لا يذوب في الماء","محلول NaOH أفضل توصيلًا لأن أيوناته أكثر، مع أن كلتا القاعدتين قوية"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 70 — هيدروكسيد الكالسيوم قاعدة قوية قليلة الذوبان'),
('essay', 1, 'ورد في الكتاب أن هيدروكسيد الكالسيوم «مصدر ضعيف لأيونات OH⁻» وأنه في الوقت نفسه «قاعدة قوية». فسّر كيف تصح العبارتان معًا، مستعينًا بقيمة Ksp = 6.5 × 10⁻⁶ ومعادلة تأين Ca(OH)₂.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 70 — هيدروكسيد الكالسيوم قاعدة قوية قليلة الذوبان'),
('essay', 2, 'قارن بين هيدروكسيد الكالسيوم Ca(OH)₂ والميثيل أمين CH₃NH₂ (الذي يذوب في الماء بكمية كبيرة) من حيث الذائبية ودرجة التأين، ثم بيّن أيهما قاعدة قوية وأيهما ضعيفة، وما الدرس المستفاد عن العلاقة بين الذائبية وقوة القاعدة.', null, null, 'تحليل', 'مقارنة واستنتاج', 'صعب', 'الكتاب ص 70 — هيدروكسيد الكالسيوم قاعدة قوية قليلة الذوبان'),
('essay', 3, 'أُذيب 0.0050 mol من Ca(OH)₂ ذوبانًا تامًا في ماء حتى أصبح حجم المحلول 0.50 L. (أ) احسب تركيز كل من Ca²⁺ وOH⁻ في المحلول. (ب) هل يحتوي المحلول على وحدات Ca(OH)₂ ذائبة غير متأينة؟ علّل.', null, null, 'تطبيق', 'حساب مع تفسير', 'متوسط', 'الكتاب ص 70 — الجدول 2-5 معادلات التأين للقواعد القوية')
