from (values
('mcq', 1, 0, 'هيدروكسيد الكالسيوم وغيره من هيدروكسيدات الفلزات القليلة الذوبان قواعد قوية؛ لأن كل ما يذوب منها يتأين كليًا، فلا تبقى في المحلول وحدات Ca(OH)₂ ذائبة غير متأينة.', '["","ذائبيته منخفضة فعلًا (Ksp = 6.5 × 10⁻⁶ صغير).","المحلول المشبع يحتوي على كمية قليلة من OH⁻ لانخفاض الذائبية.","عدد مجموعات OH لا يحدد القوة؛ فالمعيار هو التأين الكلي لما يذوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.630Z"}'::jsonb),
('mcq', 2, 3, 'يذكر الكتاب أن ثابت حاصل الذائبية لـ Ca(OH)₂ صغير، مما يدل على أن كمية قليلة من OH⁻ توجد في المحلول المشبع؛ ولذلك يُعد مصدرًا ضعيفًا لأيونات OH⁻.', '["صغر Ksp يدل على قلة الذوبان، أما ما يذوب فيتأين كليًا.","هو قاعدة قوية رغم قلة ذوبانه؛ فالقوة تُحدَّد بدرجة التأين.","العكس صحيح؛ فالقيمة الصغيرة تعني ذائبية منخفضة وكمية قليلة من الأيونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T09:21:20.631Z"}'::jsonb),
('mcq', 3, 1, 'Ca(OH)₂ قاعدة قوية يتأين ما يذوب منها كليًا: Ca(OH)₂ → Ca²⁺ + 2OH⁻. تركيز Ca(OH)₂ الذائب = 0.010 mol ÷ 1.0 L = 0.010 M، و[OH⁻] = 2 × 0.010 = 0.020 M.', '["أُهمل المعامل 2؛ فكل وحدة Ca(OH)₂ تنتج أيوني OH⁻.","","قُسم التركيز على 2 بدل ضربه فيه، أي عُكست نسبة المولات.","رُبّع التركيز (0.010)² كأنه حساب لثابت، لا لتركيز الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T09:21:20.631Z"}'::jsonb),
('mcq', 4, 2, 'Ca(OH)₂ قاعدة قوية يتأين ما يذوب منها كليًا، فلا يحتوي محلولها على وحدات ذائبة غير متأينة (وإن بقي جزء صلب لم يذب)، أما NH₃ فقاعدة ضعيفة تتأين جزئيًا فيحتوي محلولها على جزيئات NH₃ كثيرة غير متأينة.', '["ما يذوب من Ca(OH)₂ يتأين كليًا، فلا تبقى منه وحدات ذائبة غير متأينة.","قلة الذوبان تعني بقاء صلب غير ذائب، لا وحدات ذائبة غير متأينة.","","العكس صحيح؛ NH₃ قاعدة ضعيفة تتأين جزئيًا وCa(OH)₂ قاعدة قوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T09:21:20.631Z"}'::jsonb),
('mcq', 5, 0, 'العبارة خاطئة: صحيح أن محلول Ca(OH)₂ المشبع يحتوي على كمية قليلة من OH⁻، لكن سبب ذلك انخفاض ذائبيته، لا ضعف تأينه؛ فكل ما يذوب منه يتأين كليًا، لذا فهو قاعدة قوية.', '["","قوة القاعدة تحدَّد بدرجة تأين ما يذوب منها، لا بكمية OH⁻ التي تتأثر بالذائبية.","صغر Ksp يدل على قلة الذوبان، وكل ما يذوب من Ca(OH)₂ يتأين كليًا.","الحكم صحيح لكن السبب خاطئ؛ فالكتاب يذكر أن كمية OH⁻ في المحلول المشبع قليلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.631Z"}'::jsonb),
('mcq', 6, 2, 'الحكم على قوة القاعدة يكون بدرجة تأينها: القاعدة القوية تتحلل كليًا. وما يذوب من هيدروكسيدات الفلزات القليلة الذوبان يتأين كليًا، فهي قواعد قوية مهما قلّت ذائبيتها.', '["الذائبية تحدد كمية ما يذوب لا درجة تأينه؛ وCa(OH)₂ قليل الذوبان لكنه قوي.","تركيز OH⁻ في المحلول المشبع يتأثر بالذائبية، فقد يكون قليلًا لقاعدة قوية.","","NaOH فيه مجموعة واحدة وهو قوي، فالعدد لا يحدد القوة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.632Z"}'::jsonb),
('mcq', 7, 3, 'التوصيل يعتمد على تركيز الأيونات. في محلول NaOH 0.10 M يكون [OH⁻] = 0.10 M، بينما لا يتجاوز في محلول Ca(OH)₂ المشبع نحو 0.02 M بسبب انخفاض الذائبية؛ فمحلول NaOH أفضل توصيلًا وإن كانت القاعدتان قويتين.', '["كون القاعدتين قويتين لا يعني تساوي تركيز الأيونات؛ فذائبية Ca(OH)₂ منخفضة.","رغم أن كل وحدة تنتج أيوني OH⁻ فإن قلة ما يذوب تجعل تركيز الأيونات أقل من محلول NaOH.","Ca(OH)₂ يذوب بكمية قليلة ويتأين ما يذوب منه، فيوصل الكهرباء لكن بدرجة أقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T09:21:20.632Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العبارة الأولى تتعلق بالذائبية: قيمة Ksp لـ Ca(OH)₂ صغيرة، فذائبيته منخفضة ولا يذوب منه إلا القليل، لذا توجد كمية قليلة من OH⁻ في محلوله المشبع، فهو مصدر ضعيف لها. العبارة الثانية تتعلق بدرجة التأين: كل ما يذوب منه يتأين كليًا: Ca(OH)₂ → Ca²⁺ + 2OH⁻، والقاعدة القوية هي التي تتحلل كليًا، لذا يُعد قاعدة قوية. فالذائبية (كم يذوب) تختلف عن القوة (كم يتأين مما ذاب).', '["صغر Ksp يعني ذائبية منخفضة","قلة OH⁻ في المحلول المشبع تجعله مصدرًا ضعيفًا","ما يذوب يتأين كليًا","معادلة التأين الصحيحة","التمييز بين الذائبية والقوة"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير «مصدر ضعيف» بالذائبية وKsp","marks":1},{"element":"تفسير «قاعدة قوية» بالتأين الكلي","marks":1},{"element":"معادلة التأين","marks":1},{"element":"التمييز بين الذائبية والقوة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير صحيح للعبارتين مع المعادلة والتمييز بين المفهومين"},{"level":"3 درجات","description":"تفسير صحيح للعبارتين دون المعادلة أو دون التمييز الصريح"},{"level":"2 درجتان","description":"تفسير عبارة واحدة فقط تفسيرًا صحيحًا مع المعادلة"},{"level":"1 درجة","description":"كتابة المعادلة فقط أو ذكر أنه قليل الذوبان فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["تفسير قلة OH⁻ بالتأين الجزئي","نسيان المعامل 2 لـ OH⁻ في المعادلة","عدّ القاعدة القوية هي القاعدة الكثيرة الذوبان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.632Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Ca(OH)₂: ذائبيته منخفضة (Ksp صغير)، لكن كل ما يذوب منه يتأين كليًا، فهو قاعدة قوية. CH₃NH₂: يذوب بكمية كبيرة، لكنه يتأين جزئيًا فقط مكوّنًا مخلوط اتزان من الجزيئات والأيونات (CH₃NH₂ + H₂O ⇌ CH₃NH₃⁺ + OH⁻)، فهو قاعدة ضعيفة. الدرس المستفاد: قوة القاعدة تحددها درجة تأين ما يذوب منها لا مقدار ذائبيتها، فقد تكون القاعدة قليلة الذوبان قوية، وكثيرة الذوبان ضعيفة.', '["Ca(OH)₂ ذائبية منخفضة وتأين كلي","CH₃NH₂ ذائبية كبيرة وتأين جزئي","Ca(OH)₂ قوية وCH₃NH₂ ضعيفة","القوة تعتمد على درجة التأين لا الذائبية"]'::jsonb, '[]'::jsonb, '[{"element":"وصف Ca(OH)₂","marks":1},{"element":"وصف CH₃NH₂","marks":1},{"element":"التصنيف الصحيح","marks":1},{"element":"الاستنتاج العام","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة صحيحة كاملة وتصنيف صحيح واستنتاج واضح"},{"level":"4 درجات","description":"مقارنة وتصنيف صحيحان مع استنتاج ناقص"},{"level":"3 درجات","description":"مقارنة صحيحة وتصنيف صحيح دون استنتاج"},{"level":"2 درجتان","description":"وصف إحدى المادتين وتصنيفها فقط"},{"level":"1 درجة","description":"تصنيف صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["الحكم على CH₃NH₂ بأنه قوي لكثرة ذوبانه","الحكم على Ca(OH)₂ بأنه ضعيف لقلة ذوبانه","الخلط بين الذوبان والتأين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.633Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) تركيز Ca(OH)₂ الذائب = 0.0050 mol ÷ 0.50 L = 0.010 M. وبما أنه يتأين كليًا: Ca(OH)₂ → Ca²⁺ + 2OH⁻، فإن [Ca²⁺] = 0.010 M و[OH⁻] = 2 × 0.010 = 0.020 M. (ب) لا؛ لأن Ca(OH)₂ قاعدة قوية، وكل ما يذوب منها يتأين كليًا، فلا تبقى وحدات ذائبة غير متأينة.', '["التركيز المولاري 0.010 M","[Ca²⁺] = 0.010 M","[OH⁻] = 0.020 M","لا توجد وحدات ذائبة غير متأينة لأن ما يذوب يتأين كليًا"]'::jsonb, '["حساب التركيز: M = n ÷ V = 0.0050 ÷ 0.50 = 0.010 M","كتابة معادلة التأين الكلي: Ca(OH)₂ → Ca²⁺ + 2OH⁻","نسبة المولات 1 : 1 : 2، فـ [Ca²⁺] = 0.010 M","[OH⁻] = 2 × 0.010 = 0.020 M","التعليل: القاعدة القوية يتأين ما يذوب منها كليًا"]'::jsonb, '[{"element":"حساب التركيز المولاري","marks":1},{"element":"تركيز Ca²⁺","marks":1},{"element":"تركيز OH⁻","marks":1},{"element":"الإجابة عن (ب) مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة كاملة بالوحدات وإجابة معللة عن (ب)"},{"level":"3 درجات","description":"خطأ واحد، كنسيان المعامل 2 أو غياب التعليل"},{"level":"2 درجتان","description":"حساب التركيز المولاري وتركيز Ca²⁺ فقط، أو الجزء (ب) مع حساب واحد"},{"level":"1 درجة","description":"حساب التركيز المولاري فقط أو الإجابة عن (ب) فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["نسيان المعامل 2 فيُكتب [OH⁻] = 0.010 M","نسيان القسمة على الحجم 0.50 L","القول إن المحلول يحتوي على وحدات غير متأينة لأن ذائبية Ca(OH)₂ منخفضة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T09:21:20.633Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
