('mcq', 2, 'اعتمادًا على بيانات الجدول، أيّ القواعد الآتية هي الأضعف؟', '{"headers":["القاعدة","معادلة التأين","Kb (298 K)"],"rows":[["الأمونيا","NH₃ + H₂O ⇌ NH₄⁺ + OH⁻","2.5 × 10⁻⁵"],["الأنيلين","C₆H₅NH₂ + H₂O ⇌ C₆H₅NH₃⁺ + OH⁻","4.3 × 10⁻¹⁰"],["إيثيل أمين","C₂H₅NH₂ + H₂O ⇌ C₂H₅NH₃⁺ + OH⁻","5.0 × 10⁻⁴"],["ميثيل أمين","CH₃NH₂ + H₂O ⇌ CH₃NH₃⁺ + OH⁻","4.3 × 10⁻⁴"]]}'::jsonb, '["إيثيل أمين","الأنيلين","الأمونيا","ميثيل أمين"]'::jsonb, 'تحليل', 'مقارنة باستعمال بيانات', 'سهل', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('mcq', 3, 'رتّب القواعد الواردة في الجدول ترتيبًا تنازليًا بحسب قوتها (من الأقوى إلى الأضعف).', '{"headers":["القاعدة","معادلة التأين","Kb (298 K)"],"rows":[["الأنيلين","C₆H₅NH₂ + H₂O ⇌ C₆H₅NH₃⁺ + OH⁻","4.3 × 10⁻¹⁰"],["ميثيل أمين","CH₃NH₂ + H₂O ⇌ CH₃NH₃⁺ + OH⁻","4.3 × 10⁻⁴"],["الأمونيا","NH₃ + H₂O ⇌ NH₄⁺ + OH⁻","2.5 × 10⁻⁵"],["إيثيل أمين","C₂H₅NH₂ + H₂O ⇌ C₂H₅NH₃⁺ + OH⁻","5.0 × 10⁻⁴"]]}'::jsonb, '["الأنيلين ثم الأمونيا ثم ميثيل أمين ثم إيثيل أمين","إيثيل أمين ثم الأنيلين ثم ميثيل أمين ثم الأمونيا","إيثيل أمين ثم ميثيل أمين ثم الأمونيا ثم الأنيلين","ميثيل أمين ثم إيثيل أمين ثم الأمونيا ثم الأنيلين"]'::jsonb, 'تحليل', 'ترتيب باستعمال بيانات', 'متوسط', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('mcq', 4, 'ما الذي يمكن استنتاجه من أن قيمة Kb للأنيلين C₆H₅NH₂ هي 4.3 × 10⁻¹⁰؟', null, '["أنه قاعدة قوية تتحلل كليًا في المحلول المائي","أنه قاعدة ضعيفة جدًا تبقى معظم جزيئاته في الماء غير متأينة","أن تركيز الأنيلين في محلوله يساوي 4.3 × 10⁻¹⁰ M","أنه أقوى من الأمونيا لأن الأس 10 أكبر من الأس 5"]'::jsonb, 'تحليل', 'استنتاج من قيمة', 'متوسط', 'الكتاب ص 71 — التقويم 2-2 (السؤال 19)'),
('mcq', 5, 'قيمة Kb للإيثيل أمين 5.0 × 10⁻⁴، وللأمونيا 2.5 × 10⁻⁵. كم مرة تقريبًا تساوي قيمة Kb للإيثيل أمين قيمتها للأمونيا؟', null, '["20 مرة","2.0 مرة","0.050 مرة","200 مرة"]'::jsonb, 'تطبيق', 'حساب نسبة', 'متوسط', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('mcq', 6, 'حُضّر محلولان تركيز كل منهما 0.10 M، أحدهما من الميثيل أمين (Kb = 4.3 × 10⁻⁴) والآخر من الأنيلين (Kb = 4.3 × 10⁻¹⁰). أيّ العبارات الآتية صحيحة؟', null, '["[OH⁻] أكبر في محلول الأنيلين، ونسبة الجزيئات غير المتأينة أكبر في محلول الميثيل أمين","[OH⁻] متساوٍ في المحلولين؛ لأن تركيزيهما متساويان ومعاملي Kb متساويان","[OH⁻] أكبر في محلول الميثيل أمين، ونسبة الجزيئات غير المتأينة متساوية فيهما","[OH⁻] أكبر في محلول الميثيل أمين، ونسبة الجزيئات غير المتأينة أكبر في محلول الأنيلين"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('mcq', 7, 'قاعدة ضعيفة مجهولة B قيمة Kb لها 1.0 × 10⁻⁶ عند 298 K. أين تقع بين قواعد الجدول من حيث القوة؟', '{"headers":["القاعدة","معادلة التأين","Kb (298 K)"],"rows":[["إيثيل أمين","C₂H₅NH₂ + H₂O ⇌ C₂H₅NH₃⁺ + OH⁻","5.0 × 10⁻⁴"],["ميثيل أمين","CH₃NH₂ + H₂O ⇌ CH₃NH₃⁺ + OH⁻","4.3 × 10⁻⁴"],["الأمونيا","NH₃ + H₂O ⇌ NH₄⁺ + OH⁻","2.5 × 10⁻⁵"],["الأنيلين","C₆H₅NH₂ + H₂O ⇌ C₆H₅NH₃⁺ + OH⁻","4.3 × 10⁻¹⁰"]]}'::jsonb, '["أقوى من الأمونيا وأضعف من الميثيل أمين","أضعف من الأنيلين؛ لأن 1.0 أصغر من 4.3","أقوى من الأنيلين وأضعف من الأمونيا","أقوى من الإيثيل أمين؛ لأن الأس 6 أكبر من الأس 4"]'::jsonb, 'تحليل', 'مقارنة باستعمال بيانات', 'صعب', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('essay', 1, 'استعمل بيانات الجدول لترتيب القواعد الأربع تصاعديًا بحسب قوتها، ثم توقّع أيّ محاليلها المتساوية التركيز يحتوي على أعلى تركيز لأيونات OH⁻ وأيّها يحتوي على أقل تركيز، مع التعليل.', '{"headers":["القاعدة","معادلة التأين","Kb (298 K)"],"rows":[["الأمونيا","NH₃ + H₂O ⇌ NH₄⁺ + OH⁻","2.5 × 10⁻⁵"],["الأنيلين","C₆H₅NH₂ + H₂O ⇌ C₆H₅NH₃⁺ + OH⁻","4.3 × 10⁻¹⁰"],["إيثيل أمين","C₂H₅NH₂ + H₂O ⇌ C₂H₅NH₃⁺ + OH⁻","5.0 × 10⁻⁴"],["ميثيل أمين","CH₃NH₂ + H₂O ⇌ CH₃NH₃⁺ + OH⁻","4.3 × 10⁻⁴"]]}'::jsonb, null, 'تحليل', 'ترتيب وتوقع', 'سهل', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('essay', 2, 'قاعدتان ضعيفتان A وB، قيمة Kb للقاعدة A هي 3.0 × 10⁻⁶، وللقاعدة B هي 3.0 × 10⁻⁹. حُضّر منهما محلولان متساويا التركيز. (أ) أيّ القاعدتين أقوى؟ وكم مرة تساوي قيمة Kb لها قيمتها للأخرى؟ (ب) أيّ المحلولين أفضل توصيلًا للكهرباء؟ (ج) في أيّ المحلولين تكون نسبة جزيئات القاعدة غير المتأينة أعلى؟ علّل إجاباتك.', null, null, 'تحليل', 'مقارنة وحساب', 'متوسط', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6'),
('essay', 3, 'قال طالب: «الأمونيا أقوى من الميثيل أمين؛ لأن قيمة Kb للأمونيا (2.5 × 10⁻⁵) تحتوي على الأس 5، وهو أكبر من الأس 4 في قيمة Kb للميثيل أمين (4.3 × 10⁻⁴)». قوّم هذه العبارة، وصحّح الخطأ، واحسب كم مرة تقريبًا يكون Kb للميثيل أمين أكبر من Kb للأمونيا.', null, null, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 71 — ثابت تأين القاعدة Kb والجدول 2-6')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
