insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'Kb قيمة ثابت الاتزان لتأين القاعدة الضعيفة، وكلما صغرت كانت القاعدة أضعف؛ لذا فالقيمة الأكبر تدل على قاعدة أقوى تتأين بدرجة أكبر فتنتج تركيزًا أكبر من OH⁻ عند التركيز نفسه.', '["","العلاقة معكوسة؛ فالكتاب ينص على أنه كلما صغرت Kb كانت القاعدة أضعف.","Kb تُستعمل للقواعد الضعيفة التي تتأين جزئيًا، أما التحلل الكلي فصفة القواعد القوية.","Kb ثابت اتزان يعبر عن مدى التأين، لا عن تركيز القاعدة المذابة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T09:21:20.634Z"}'::jsonb),
('mcq', 2, 1, 'كلما صغرت قيمة Kb كانت القاعدة أضعف. أصغر قيمة في الجدول هي 4.3 × 10⁻¹⁰ للأنيلين، فهو أضعف هذه القواعد.', '["له أكبر قيمة Kb في الجدول (5.0 × 10⁻⁴) فهو الأقوى؛ اختياره يعكس العلاقة.","","Kb للأمونيا 2.5 × 10⁻⁵ أكبر بكثير من 4.3 × 10⁻¹⁰، فهي أقوى من الأنيلين.","Kb للميثيل أمين 4.3 × 10⁻⁴؛ ومعامله يساوي معامل الأنيلين لكن أسّه أكبر بكثير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.634Z"}'::jsonb),
('mcq', 3, 2, 'قيم Kb تنازليًا: إيثيل أمين 5.0 × 10⁻⁴ > ميثيل أمين 4.3 × 10⁻⁴ > الأمونيا 2.5 × 10⁻⁵ > الأنيلين 4.3 × 10⁻¹⁰، والقاعدة الأقوى لها Kb أكبر، فهذا هو ترتيب القوة التنازلي.', '["هذا ترتيب تصاعدي (من الأضعف إلى الأقوى) لا تنازلي.","رُتّبت القواعد بالمعاملات (5.0، 4.3، 4.3، 2.5) مع إهمال قوى العشرة.","","Kb للإيثيل أمين (5.0 × 10⁻⁴) أكبر من Kb للميثيل أمين (4.3 × 10⁻⁴)، فهو الأقوى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.635Z"}'::jsonb),
('mcq', 4, 1, 'القيمة 4.3 × 10⁻¹⁰ صغيرة جدًا، فالأنيلين يتأين بدرجة ضئيلة جدًا وينتج تركيزًا قليلًا جدًا من OH⁻، وتبقى معظم جزيئاته غير متأينة؛ فهو أضعف قواعد الجدول 2-6.', '["القواعد القوية تتحلل كليًا ولا يُعبَّر عنها بقيمة Kb صغيرة كهذه.","","Kb ثابت اتزان بلا معنى التركيز؛ فهو نسبة تراكيز النواتج إلى تركيز القاعدة.","الأس السالب الأكبر عدديًا يعني قيمة أصغر؛ فالأنيلين أضعف من الأمونيا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.635Z"}'::jsonb),
('mcq', 5, 0, 'النسبة = (5.0 × 10⁻⁴) ÷ (2.5 × 10⁻⁵) = 2.0 × 10¹ = 20؛ فالإيثيل أمين قاعدة أقوى من الأمونيا وقيمة Kb له أكبر بنحو 20 مرة.', '["","قُسم المعاملان (5.0 ÷ 2.5) وأُهملت الأسس، مع أن 10⁻⁴ ÷ 10⁻⁵ = 10.","قُسمت قيمة الأمونيا على قيمة الإيثيل أمين، أي عُكست النسبة.","أُخطئ في الأسس فعُدّ الفرق بينهما قوتين للعشرة بدل قوة واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.635Z"}'::jsonb),
('mcq', 6, 3, 'Kb للميثيل أمين أكبر بكثير من Kb للأنيلين، فالميثيل أمين أقوى ويتأين بدرجة أكبر فينتج تركيزًا أكبر من OH⁻، بينما الأنيلين الأضعف تبقى نسبة أكبر من جزيئاته غير متأينة.', '["العبارة معكوسة؛ فالأنيلين أضعف (Kb أصغر) فيتأين أقل.","تساوي المعاملين 4.3 لا يعني تساوي القيمتين؛ فالأسّان مختلفان (10⁻⁴ و10⁻¹⁰).","القاعدة الأقوى تتأين بنسبة أكبر، فتكون نسبة جزيئاتها غير المتأينة أقل لا مساوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.636Z"}'::jsonb),
('mcq', 7, 2, 'القيمة 1.0 × 10⁻⁶ أكبر من 4.3 × 10⁻¹⁰ (الأنيلين) وأصغر من 2.5 × 10⁻⁵ (الأمونيا)؛ ولأن القاعدة الأقوى لها Kb أكبر، فإن B أقوى من الأنيلين وأضعف من الأمونيا.', '["القيمة 1.0 × 10⁻⁶ أصغر من 2.5 × 10⁻⁵، فهي أضعف من الأمونيا.","قورنت المعاملات وأُهملت الأسس؛ فـ 1.0 × 10⁻⁶ أكبر بكثير من 4.3 × 10⁻¹⁰.","","الأس السالب الأكبر عدديًا يعني قيمة أصغر؛ فهي أضعف من الإيثيل أمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.636Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الترتيب التصاعدي للقوة (بحسب Kb تصاعديًا): الأنيلين (4.3 × 10⁻¹⁰) < الأمونيا (2.5 × 10⁻⁵) < ميثيل أمين (4.3 × 10⁻⁴) < إيثيل أمين (5.0 × 10⁻⁴). عند تساوي التراكيز يحتوي محلول الإيثيل أمين على أعلى [OH⁻] لأن Kb له أكبر فيتأين بدرجة أكبر، ويحتوي محلول الأنيلين على أقل [OH⁻] لأن Kb له أصغر فيتأين بدرجة أقل؛ إذ كلما صغرت Kb كانت القاعدة أضعف.', '["الترتيب الصحيح: الأنيلين < الأمونيا < ميثيل أمين < إيثيل أمين","المعيار: Kb أكبر يعني قاعدة أقوى","أعلى [OH⁻]: الإيثيل أمين","أقل [OH⁻]: الأنيلين","التعليل بدرجة التأين"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":2},{"element":"تحديد الأعلى والأقل في [OH⁻]","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وتوقع صحيح مع التعليل"},{"level":"3 درجات","description":"ترتيب صحيح وتوقع صحيح دون تعليل، أو خطأ في موضع قاعدة واحدة"},{"level":"2 درجتان","description":"ترتيب صحيح فقط، أو ترتيب معكوس مع توقع وتعليل صحيحين"},{"level":"1 درجة","description":"تحديد الأقوى أو الأضعف فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["الترتيب بحسب المعاملات وإهمال الأسس","عدّ الميثيل أمين أقوى من الإيثيل أمين","عكس العلاقة بين Kb والقوة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.636Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) A أقوى لأن Kb لها أكبر؛ النسبة = (3.0 × 10⁻⁶) ÷ (3.0 × 10⁻⁹) = 1.0 × 10³، أي 1000 مرة. (ب) محلول A أفضل توصيلًا؛ لأنها تتأين بدرجة أكبر فتنتج تركيزًا أكبر من الأيونات (BH⁺ وOH⁻) والتوصيل يعتمد على عدد الأيونات. (ج) في محلول B؛ لأنها أضعف (Kb أصغر) فتبقى نسبة أكبر من جزيئاتها غير متأينة.', '["A أقوى لأن Kb أكبر","النسبة 1000 مرة","A أفضل توصيلًا لأنها تنتج أيونات أكثر","نسبة الجزيئات غير المتأينة أعلى في B"]'::jsonb, '["مقارنة Kb: 3.0 × 10⁻⁶ > 3.0 × 10⁻⁹ فـ A أقوى","النسبة = (3.0 × 10⁻⁶) ÷ (3.0 × 10⁻⁹) = 1.0 × 10³","ربط Kb الأكبر بتأين أكبر وأيونات أكثر وتوصيل أفضل","ربط Kb الأصغر بنسبة أكبر من الجزيئات غير المتأينة"]'::jsonb, '[{"element":"تحديد الأقوى مع التعليل","marks":1},{"element":"حساب النسبة","marks":1},{"element":"التوصيل مع التعليل","marks":1},{"element":"الجزيئات غير المتأينة مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابات صحيحة معللة للأجزاء الثلاثة مع حساب صحيح"},{"level":"3 درجات","description":"خطأ واحد كخطأ في الحساب أو نقص تعليل"},{"level":"2 درجتان","description":"إجابتان صحيحتان فقط"},{"level":"1 درجة","description":"تحديد القاعدة الأقوى فقط"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["حساب النسبة 3 بدل 1000 بإهمال الأسس","عدّ المحلولين متساويين لتساوي المعاملين","عكس العلاقة بين Kb ونسبة الجزيئات غير المتأينة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.637Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة. الأس السالب الأكبر عدديًا يعني قيمة أصغر: 10⁻⁵ أصغر من 10⁻⁴، فـ 2.5 × 10⁻⁵ أصغر من 4.3 × 10⁻⁴. ولأن القاعدة الأضعف لها Kb أصغر، فالأمونيا أضعف من الميثيل أمين لا أقوى. النسبة = (4.3 × 10⁻⁴) ÷ (2.5 × 10⁻⁵) = 17.2 ≈ 17، أي أن Kb للميثيل أمين أكبر بنحو 17 مرة.', '["الحكم: العبارة خاطئة","تفسير الخطأ في قراءة الأس السالب","الأمونيا أضعف لأن Kb لها أصغر","النسبة ≈ 17 مرة"]'::jsonb, '["مقارنة القيمتين: 4.3 × 10⁻⁴ = 43 × 10⁻⁵ > 2.5 × 10⁻⁵","الاستنتاج: الميثيل أمين أقوى","النسبة = (4.3 × 10⁻⁴) ÷ (2.5 × 10⁻⁵) = 17.2 ≈ 17"]'::jsonb, '[{"element":"الحكم الصحيح","marks":1},{"element":"تفسير الخطأ وتصحيحه","marks":1},{"element":"حساب النسبة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حكم صحيح مع تفسير الخطأ وحساب صحيح للنسبة"},{"level":"2 درجتان","description":"حكم صحيح مع تفسير دون حساب، أو مع حساب دون تفسير"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة كليًا أو لا إجابة"}]'::jsonb, '["تأييد العبارة","حساب النسبة 1.7 بإهمال الأسس","قسمة قيمة الأمونيا على قيمة الميثيل أمين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.637Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
