from (values
('mcq', 1, 'على مدرج الرقم الهيدروجيني pH عند درجة حرارة 298 K، أيّ مدى من القيم يمثّل منطقة المحاليل القاعدية؟', null, '["من 0 إلى أقل من 7","بين 6 و 8 تقريبًا","أكبر من 7 حتى 14","القيمة 7 فقط"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 74 — الرقم الهيدروجيني pH'),
('mcq', 2, 'يبيّن الجدول قيم pH تقريبية لبعض المواد المألوفة عند 298 K. عند تمثيل هذه المواد على مدرج pH، أيّ العبارات الآتية صحيحة؟', '{"headers":["المادة","قيمة pH التقريبية"],"rows":[["عصير الليمون","2.0"],["الحليب","6.5"],["الدم","7.4"],["منظف الأفران","13.5"]]}'::jsonb, '["الدم يقع في منطقة القاعدية قريبًا من نقطة التعادل","الحليب يقع في منطقة القاعدية لأنه قريب من 7","منظف الأفران أقرب المواد إلى نقطة التعادل","عصير الليمون يقع في منطقة القاعدية القوية"]'::jsonb, 'تطبيق', 'تفسير بيانات', 'متوسط', 'الكتاب ص 74 — الشكل 2-14 قيم pH لمواد مألوفة'),
('mcq', 3, 'محلول A قيمة pH له 3، ومحلول B قيمة pH له 4 عند 298 K. ما العلاقة بين تركيز أيونات الهيدروجين في المحلولين؟', null, '["[H⁺] في A يساوي ثلاثة أرباع [H⁺] في B","[H⁺] في B عشرة أضعاف [H⁺] في A","[H⁺] في A أكبر من B بمقدار 1 mol/L","[H⁺] في A عشرة أضعاف [H⁺] في B"]'::jsonb, 'فهم', 'فهم علاقة', 'سهل', 'الكتاب ص 74 — الطبيعة اللوغاريتمية لتدريج pH'),
('mcq', 4, 'محلول مائي قيمة pOH له 4.0 عند 298 K. أين يقع هذا المحلول على مدرج الرقم الهيدروجيني pH؟', null, '["عند pH = 4 في منطقة الحمضية","عند pH = 10 في منطقة القاعدية","عند pH = 10 في منطقة الحمضية","عند pH = 7 عند نقطة التعادل"]'::jsonb, 'تطبيق', 'تطبيق', 'متوسط', 'الكتاب ص 75 — الشكل 2-15 العلاقة بين pH و pOH'),
('mcq', 5, 'أربعة محاليل مائية عند 298 K قيم pH لها: W = 11، X = 2، Y = 7، Z = 5. ما ترتيبها على مدرج pH من الأقل حمضية إلى الأكثر حمضية؟', null, '["X ثم Z ثم Y ثم W","Y ثم Z ثم X ثم W","W ثم Z ثم Y ثم X","W ثم Y ثم Z ثم X"]'::jsonb, 'تطبيق', 'ترتيب', 'متوسط', 'الكتاب ص 74 — الرقم الهيدروجيني pH'),
('mcq', 6, 'خُفّف محلول حمضي بالماء فانتقلت قيمة pH له على المدرج من 2 إلى 5 عند 298 K. كيف تغيّر تركيز أيونات الهيدروجين [H⁺] فيه؟', null, '["قلّ إلى جزء من ألف من قيمته الأصلية","قلّ إلى خُمسَي قيمته الأصلية","زاد إلى ألف ضعف قيمته الأصلية","قلّ إلى جزء من ثلاثين من قيمته الأصلية"]'::jsonb, 'تطبيق', 'تطبيق', 'صعب', 'الكتاب ص 74 — الطبيعة اللوغاريتمية لتدريج pH'),
('mcq', 7, 'عند الانتقال على مدرج pH من القيمة 7 باتجاه القيمة 14 عند 298 K، ماذا يحدث لتراكيز الأيونات ولطبيعة المحلول؟', null, '["يزداد [H⁺] ويقل [OH⁻] وتزداد القاعدية","يقل [H⁺] و[OH⁻] معًا وتزداد القاعدية","يقل [H⁺] ويزداد [OH⁻] وتزداد القاعدية","يقل [H⁺] ويزداد [OH⁻] وتزداد الحمضية"]'::jsonb, 'فهم', 'فهم علاقة', 'متوسط', 'الكتاب ص 75 — الشكل 2-15 تزداد الحمضية / تزداد القاعدية'),
('essay', 1, 'ارسم مدرج الرقم الهيدروجيني pH من 0 إلى 14 عند 298 K، وحدّد عليه منطقة الحمضية ونقطة التعادل ومنطقة القاعدية، ثم مثّل عليه المواد الآتية: عصير ليمون (pH = 2)، قهوة (pH = 5)، ماء نقي (pH = 7)، ماء البحر (pH = 8)، منظف أفران (pH = 13.5)، وبيّن على الرسم اتجاه ازدياد الحمضية واتجاه ازدياد القاعدية.', null, null, 'تطبيق', 'رسم وتمثيل', 'سهل', 'الكتاب ص 74 — الشكل 2-14 تدريج pH'),
('essay', 2, 'يربط مدرج pH بين أربع كميات هي: [H⁺] و pH و pOH و [OH⁻] عند 298 K. مثّل على مدرج واحد النقاط التي قيم pH لها 1 و 7 و 12، واكتب لكل نقطة قيم [H⁺] و pOH و [OH⁻]، ثم استنتج علاقتين تبقيان ثابتتين عند كل نقطة على المدرج.', null, null, 'تحليل', 'تمثيل واستنتاج', 'صعب', 'الكتاب ص 75 — الشكل 2-15 العلاقة بين [H⁺] و pH و pOH و [OH⁻]'),
('essay', 3, 'قال طالب: «المحلول الذي قيمة pH له 6 قاعدي لأنه قريب من 7، والمحلول الذي قيمة pH له 12 أكثر حمضية من المحلول الذي قيمة pH له 10 لأن رقمه أكبر». قوّم عبارة الطالب مستعينًا بمدرج pH عند 298 K، وصحّح كل خطأ فيها مع التعليل.', null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 74 — الرقم الهيدروجيني pH')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
