from (values
('mcq', 1, 2, 'عند 298 K تكون قيم pH للمحاليل القاعدية أكبر من 7، ويمتد المدرج حتى 14 (قاعدة قوية)؛ لذا فمنطقة القاعدية هي القيم الأكبر من 7 حتى 14.', '["القيم الأقل من 7 تمثل منطقة الحمضية لا القاعدية.","المدى بين 6 و 8 يضم محاليل حمضية ضعيفة ونقطة التعادل وقاعدية ضعيفة، فهو ليس منطقة القاعدية.","","القيمة 7 تمثل نقطة التعادل حيث [H⁺] = [OH⁻]، لا منطقة القاعدية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.638Z"}'::jsonb),
('mcq', 2, 0, 'قيمة pH للدم 7.4 وهي أكبر من 7 بقليل، فيقع الدم في منطقة القاعدية قريبًا جدًّا من نقطة التعادل (7).', '["","قيمة pH للحليب 6.5 أقل من 7، فهو في منطقة الحمضية (حمضي ضعيف) وإن كان قريبًا من 7.","منظف الأفران (13.5) أبعد المواد عن نقطة التعادل، فهو قاعدي قوي جدًّا؛ والدم هو الأقرب إلى 7.","قيمة pH لعصير الليمون 2.0 أقل كثيرًا من 7، فهو في منطقة الحمضية لا القاعدية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.639Z"}'::jsonb),
('mcq', 3, 3, 'مدرج pH لوغاريتمي؛ فتغيّر pH بوحدة واحدة يقابله تغيّر في [H⁺] مقداره 10 مرات. المحلول A أقل في pH بوحدة واحدة، لذا [H⁺] فيه عشرة أضعاف [H⁺] في B (10⁻³ M مقابل 10⁻⁴ M).', '["هذا يعامل المدرج كأنه خطي بقسمة 3 على 4، مع أن المدرج لوغاريتمي.","عكس العلاقة: القيمة الأصغر لـ pH تعني [H⁺] أكبر، فـ A هو الأعلى تركيزًا لا B.","الفرق في pH ليس فرقًا في التركيز بوحدة mol/L؛ فالتركيزان 10⁻³ M و 10⁻⁴ M والفرق بينهما أقل كثيرًا من 1 mol/L.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T09:21:20.639Z"}'::jsonb),
('mcq', 4, 1, 'pH = 14.00 − pOH = 14.00 − 4.0 = 10.0، وهي قيمة أكبر من 7؛ فيقع المحلول عند pH = 10 في منطقة القاعدية.', '["خلط بين pOH و pH، فعدّ قيمة pOH هي نفسها قيمة pH.","","القيمة العددية صحيحة، لكن pH = 10 أكبر من 7 فتقع في منطقة القاعدية لا الحمضية.","نقطة التعادل يكون عندها pH = pOH = 7، أما هنا فـ pOH = 4 فالمحلول ليس متعادلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.639Z"}'::jsonb),
('mcq', 5, 3, 'كلما قلّت قيمة pH زادت الحمضية. الأقل حمضية هو صاحب أكبر pH، فالترتيب: W (11) ثم Y (7) ثم Z (5) ثم X (2).', '["هذا ترتيب من الأكثر حمضية إلى الأقل، أي عكس المطلوب.","وضع المحلول المتعادل Y أولًا ووضع القاعدي W آخرًا، مع أن W أقل المحاليل حمضية.","قدّم Z (pH = 5) على Y (pH = 7) مع أن Z أكثر حمضية من Y.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.640Z"}'::jsonb),
('mcq', 6, 0, 'زيادة pH بثلاث وحدات تعني نقصان [H⁺] بمقدار 10 × 10 × 10 = 10³ = 1000 مرة (من 10⁻² M إلى 10⁻⁵ M)، أي إلى جزء من ألف من قيمته الأصلية.', '["","عامل المدرج معاملة خطية فقسم 2 على 5، مع أن كل وحدة pH تقابلها 10 مرات في [H⁺].","عكس الاتجاه: زيادة pH تعني نقصان [H⁺] لا زيادته.","ضرب عدد الوحدات (3) في 10 بدلًا من رفع 10 للأس 3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T09:21:20.640Z"}'::jsonb),
('mcq', 7, 2, 'كلما زادت قيمة pH قلّ [H⁺] وزاد [OH⁻] (لأن حاصل ضربهما ثابت 1.0 × 10⁻¹⁴)، فتزداد القاعدية باتجاه القيمة 14.', '["زيادة pH تعني نقصان [H⁺] لا زيادته، ومعها يزداد [OH⁻].","لا يمكن أن يقل التركيزان معًا؛ لأن حاصل ضربهما ثابت يساوي Kw.","","تغيّر التراكيز صحيح، لكن زيادة [OH⁻] على حساب [H⁺] تعني ازدياد القاعدية لا الحمضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.641Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يُرسم خط (أو عمود) مدرّج بقيم متساوية الأبعاد من 0 إلى 14. تُعلَّم القيمة 7 بأنها نقطة التعادل، وتُظلَّل القيم الأقل من 7 (من 0 إلى أقل من 7) بأنها منطقة الحمضية، والقيم الأكبر من 7 (حتى 14) بأنها منطقة القاعدية. توضع المواد: عصير الليمون عند 2 والقهوة عند 5 (في منطقة الحمضية)، والماء النقي عند 7 (التعادل)، وماء البحر عند 8 ومنظف الأفران عند 13.5 (في منطقة القاعدية). يُرسم سهم من 7 نحو 0 مكتوب عليه «تزداد الحمضية»، وسهم من 7 نحو 14 مكتوب عليه «تزداد القاعدية».', '["مدرج من 0 إلى 14 بأقسام متساوية","نقطة التعادل عند 7","منطقة الحمضية أقل من 7 ومنطقة القاعدية أكبر من 7","وضع المواد الخمس في مواقعها الصحيحة","سهما اتجاه ازدياد الحمضية والقاعدية"]'::jsonb, '[]'::jsonb, '[{"element":"رسم مدرج من 0 إلى 14 بأقسام منتظمة","marks":1},{"element":"تحديد نقطة التعادل 7 ومنطقتي الحمضية والقاعدية","marks":2},{"element":"تمثيل المواد الخمس في مواقعها الصحيحة","marks":2},{"element":"سهما ازدياد الحمضية وازدياد القاعدية في الاتجاه الصحيح","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"مدرج صحيح بمناطقه الثلاث، والمواد الخمس في مواقعها، والسهمان صحيحان"},{"level":"4–5 درجات","description":"مدرج ومناطق صحيحة مع خطأ في مادة أو مادتين أو نقص أحد السهمين"},{"level":"2–3 درجات","description":"مدرج صحيح مع خلط في تحديد المناطق أو أخطاء كثيرة في تمثيل المواد"},{"level":"1 درجة","description":"رسم مدرج فقط دون تحديد صحيح للمناطق"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس المنطقتين فيجعل القيم الكبيرة حمضية","رسم أقسام غير متساوية أو بدء المدرج من 1 أو انتهاؤه عند 10","وضع ماء البحر في منطقة الحمضية أو عند التعادل","رسم سهم ازدياد الحمضية باتجاه 14"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.642Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عند pH = 1: [H⁺] = 1 × 10⁻¹ M، pOH = 13، [OH⁻] = 1 × 10⁻¹³ M (منطقة الحمضية). عند pH = 7: [H⁺] = 1 × 10⁻⁷ M، pOH = 7، [OH⁻] = 1 × 10⁻⁷ M (نقطة التعادل). عند pH = 12: [H⁺] = 1 × 10⁻¹² M، pOH = 2، [OH⁻] = 1 × 10⁻² M (منطقة القاعدية). تُكتب قيم pH و [H⁺] فوق المدرج وقيم pOH و [OH⁻] تحته. العلاقتان الثابتتان: مجموع pH و pOH عند كل نقطة يساوي 14.00، وحاصل ضرب [H⁺] و [OH⁻] عند كل نقطة يساوي 1.0 × 10⁻¹⁴ (= Kw).', '["قيم النقطة pH = 1 صحيحة","قيم النقطة pH = 7 صحيحة","قيم النقطة pH = 12 صحيحة","pH + pOH = 14.00","[H⁺][OH⁻] = 1.0 × 10⁻¹⁴"]'::jsonb, '["[H⁺] = 10^−pH لكل نقطة: 10⁻¹ و 10⁻⁷ و 10⁻¹² M","pOH = 14 − pH: 13 و 7 و 2","[OH⁻] = 10^−pOH: 10⁻¹³ و 10⁻⁷ و 10⁻² M","التحقق: 1 + 13 = 14 و (10⁻¹)(10⁻¹³) = 10⁻¹⁴، وكذلك لبقية النقاط"]'::jsonb, '[{"element":"تمثيل النقاط الثلاث على المدرج مع قيمها الأربع (درجة لكل نقطة)","marks":3},{"element":"استنتاج أن pH + pOH = 14.00 عند كل نقطة","marks":1},{"element":"استنتاج أن [H⁺][OH⁻] = 1.0 × 10⁻¹⁴ عند كل نقطة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"قيم النقاط الثلاث كلها صحيحة والعلاقتان مستنتجتان"},{"level":"3–4 درجات","description":"قيم صحيحة لنقطتين أو ثلاث مع استنتاج علاقة واحدة"},{"level":"1–2 درجة","description":"قيم صحيحة لنقطة أو نقطتين دون استنتاج"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة [OH⁻] مساويًا لـ [H⁺] في النقاط غير المتعادلة","كتابة pOH مساويًا لـ pH","كتابة الأس موجبًا (10¹² بدلًا من 10⁻¹²)","استنتاج أن حاصل ضرب pH و pOH ثابت بدلًا من مجموعهما"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.642Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة خاطئة في جزأيها. الجزء الأول: المحلول الذي pH له 6 يقع في منطقة الحمضية لأن قيمته أقل من 7؛ والقرب من 7 يعني أنه حمضي ضعيف لا قاعدي، فالقاعدية تبدأ بالقيم الأكبر من 7. الجزء الثاني: القيمتان 12 و 10 كلتاهما في منطقة القاعدية، والمحلول الذي pH له 12 أكثر قاعدية (لا أكثر حمضية) من الذي pH له 10؛ لأن زيادة pH تعني نقصان [H⁺]، والفرق وحدتان يعني أن [H⁺] في المحلول الأول أقل بمقدار 10² = 100 مرة.', '["الحكم بخطأ العبارة","pH = 6 حمضي (ضعيف) لأنه أقل من 7","pH = 12 و pH = 10 كلاهما قاعدي","pH = 12 أكثر قاعدية لأن [H⁺] أقل","الفرق بوحدتين يعني 100 مرة في [H⁺]"]'::jsonb, '[]'::jsonb, '[{"element":"تصحيح الجزء الأول مع التعليل (أقل من 7 حمضي)","marks":2},{"element":"تصحيح الجزء الثاني: كلاهما قاعدي و 12 أكثر قاعدية","marks":2},{"element":"ربط الفرق بوحدتين بتغير [H⁺] مئة مرة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصحيح الخطأين مع تعليل صحيح وذكر مقدار التغير في [H⁺]"},{"level":"3–4 درجات","description":"تصحيح الخطأين مع تعليل ناقص، أو تصحيح خطأ واحد بتعليل كامل"},{"level":"1–2 درجة","description":"الحكم بالخطأ مع تصحيح جزئي دون تعليل"},{"level":"صفر","description":"تأييد عبارة الطالب أو لا إجابة"}]'::jsonb, '["عدّ المحاليل القريبة من 7 متعادلة أو قاعدية","الاعتقاد أن القيمة الأكبر لـ pH تعني حمضية أكبر","عدّ الفرق بوحدتين فرقًا بمقدار مرتين في [H⁺]"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.642Z"}'::jsonb)
