('mcq', 1, 0, 'pH = −log[H⁺] = −log(1.0 × 10⁻⁴) = 4.00.', '["","هذه قيمة pOH (14.00 − 4.00)، لا قيمة pH.","أُهملت إشارة السالب في القانون pH = −log[H⁺]، فقيمة pH هنا موجبة.","هذا هو التركيز نفسه مكتوبًا عشريًّا، ولم يُحسب له اللوغاريتم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T09:21:20.643Z"}'::jsonb),
('mcq', 2, 2, 'pH = −log(2.5 × 10⁻³) = 2.60، ثم pOH = 14.00 − pH = 14.00 − 2.60 = 11.40.', '["هذه قيمة pH لا pOH؛ لم يُكمل الحل بالطرح من 14.00.","خطأ في اللوغاريتم: حُسبت pH = 3 + 0.40 = 3.40 بدلًا من 3 − 0.40 = 2.60، فنتج pOH = 10.60.","","أُهمل المعامل 2.5 واستُعمل الأس فقط (pH = 3)، فنتج pOH = 11.00."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T09:21:20.643Z"}'::jsonb),
('mcq', 3, 1, 'pH = −log(6.3 × 10⁻⁶) = 5.20، و pOH = 14.00 − 5.20 = 8.80. ولأن pH أقل من 7 فالمحلول حمضي.', '["تبادلت القيمتان: 8.80 هي pOH و 5.20 هي pH، فالمحلول ليس قاعديًا.","","القيمتان صحيحتان، لكن pH = 5.20 أقل من 7 فالمحلول حمضي لا قاعدي.","أُخذ معامل التركيز (6.3) قيمةً لـ pH بدل حساب اللوغاريتم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-17T09:21:20.644Z"}'::jsonb),
('mcq', 4, 3, 'pH = −log(8.0 × 10⁻¹⁰) = 10 − 0.90 = 9.10، و pOH = 14.00 − 9.10 = 4.90.', '["خطأ في جمع جزأي اللوغاريتم: جُمع 9 + 0.90 بدلًا من 10 − 0.90.","أُهمل المعامل 8.0 واكتُفي بالأس (10⁻¹⁰).","تبادل القيمتين: 4.90 هي pOH وليست pH.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T09:21:20.644Z"}'::jsonb),
('mcq', 5, 1, 'زيادة [H⁺] على 1.0 × 10⁻⁷ M تجعل −log[H⁺] أقل من 7، فـ pH أقل من 7؛ ولأن pH + pOH = 14.00 تكون pOH أكبر من 7.', '["عكس العلاقة: التركيز الأكبر لـ H⁺ يعطي pH أصغر لا أكبر.","","مجموع pH و pOH يساوي 14.00، فلا يمكن أن تكون القيمتان معًا أقل من 7.","pOH تساوي 7 في المحلول المتعادل فقط، وهنا pH أقل من 7 فلا بد أن pOH أكبر من 7."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-17T09:21:20.644Z"}'::jsonb),
('mcq', 6, 0, 'pH = −log(2.0 × 10⁻⁶) = 5.70، و [OH⁻] = Kw / [H⁺] = (1.0 × 10⁻¹⁴) / (2.0 × 10⁻⁶) = 5.0 × 10⁻⁹ M.', '["","افترض أن [OH⁻] = [H⁺]، وهذا لا يصح إلا في المحلول المتعادل.","خطأ في اللوغاريتم: حُسب 6 + 0.30 بدلًا من 6 − 0.30.","8.30 هي قيمة pOH وليست pH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.645Z"}'::jsonb),
('mcq', 7, 3, 'للمحلول A: pH = 3.00 و pOH = 11.00؛ وللمحلول B: pH = 9.00 و pOH = 5.00. إذن pOH للمحلول A (11.00) أكبر من pOH للمحلول B (5.00).', '["pH للمحلول A يساوي 3.00 وللمحلول B يساوي 9.00، فقيمة A هي الأصغر.","[OH⁻] في A = 1.0 × 10⁻¹¹ M وفي B = 1.0 × 10⁻⁵ M، فالأكبر في B.","الفرق 6 وحدات في pH يعني اختلاف [H⁺] بمقدار 10⁶ مرة، لا 6 مرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T09:21:20.645Z"}'::jsonb),
('essay', 1, null::int, null, null, '[OH⁻] = Kw / [H⁺] = (1.0 × 10⁻¹⁴) / (4.0 × 10⁻¹¹) = 2.5 × 10⁻⁴ M. pH = −log(4.0 × 10⁻¹¹) = 10.40. pOH = 14.00 − 10.40 = 3.60 (ويمكن التحقق: −log(2.5 × 10⁻⁴) = 3.60). المنظف قاعدي لأن pH أكبر من 7 و [OH⁻] أكبر من [H⁺].', '["[OH⁻] = 2.5 × 10⁻⁴ M","pH = 10.40","pOH = 3.60","المنظف قاعدي لأن pH > 7 أو [OH⁻] > [H⁺]"]'::jsonb, '["كتابة Kw = [H⁺][OH⁻] وإيجاد [OH⁻] = Kw/[H⁺]","التعويض: [OH⁻] = (1.0 × 10⁻¹⁴)/(4.0 × 10⁻¹¹) = 2.5 × 10⁻⁴ M","pH = −log[H⁺] = −log(4.0 × 10⁻¹¹) = 10.40","pOH = 14.00 − pH = 3.60","الحكم: pH > 7 فالمحلول قاعدي"]'::jsonb, '[{"element":"حساب [OH⁻] صحيحًا","marks":1},{"element":"حساب pH صحيحًا","marks":1.5},{"element":"حساب pOH صحيحًا","marks":1},{"element":"تحديد الطبيعة القاعدية مع التعليل","marks":1.5}]'::jsonb, '[{"level":"5 درجات","description":"الحسابات الثلاث صحيحة بأرقام معنوية مناسبة والحكم صحيح معلل"},{"level":"3–4 درجات","description":"حسابان صحيحان والحكم صحيح، أو كل الحسابات صحيحة بلا تعليل"},{"level":"1–2 درجة","description":"حساب واحد صحيح أو حكم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["خطأ في اللوغاريتم بجمع 10 + 0.60 = 10.60 بدلًا من 11 − 0.60 = 10.40","قسمة [H⁺] على Kw بدل قسمة Kw على [H⁺]","الحكم بالحمضية لأن [H⁺] موجود في المحلول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.645Z"}'::jsonb),
('essay', 2, null::int, null, null, 'pH = −log(1.0 × 10⁻²) = 2.00. pOH = 14.00 − 2.00 = 12.00. [OH⁻] = Kw/[H⁺] = (1.0 × 10⁻¹⁴)/(1.0 × 10⁻²) = 1.0 × 10⁻¹² M (أو 10^−12.00).', '["pH = 2.00","pOH = 12.00","[OH⁻] = 1.0 × 10⁻¹² M"]'::jsonb, '["pH = −log[H⁺] = −log(1.0 × 10⁻²) = 2.00","pOH = 14.00 − 2.00 = 12.00","[OH⁻] = Kw/[H⁺] = 1.0 × 10⁻¹² M"]'::jsonb, '[{"element":"pH = 2.00 مع كتابة القانون","marks":1},{"element":"pOH = 12.00","marks":1},{"element":"[OH⁻] = 1.0 × 10⁻¹² M","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"القيم الثلاث صحيحة مع خطوات واضحة"},{"level":"2 درجتان","description":"قيمتان صحيحتان"},{"level":"1 درجة","description":"قيمة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة pH = −2.00 بإهمال إشارة السالب","كتابة [OH⁻] = 1.0 × 10⁻² M بافتراض تساوي التركيزين","كتابة الوحدة M بجانب pH أو pOH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T09:21:20.646Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المحلول A: pH = −log(7.9 × 10⁻⁴) = 3.10، pOH = 14.00 − 3.10 = 10.90، وهو حمضي لأن pH < 7. المحلول B: pH = −log(5.0 × 10⁻⁸) = 7.30، pOH = 14.00 − 7.30 = 6.70، وهو قاعدي ضعيف لأن pH > 7 (أكبر من 7 بقليل). المحلول A هو الأكثر حمضية، و [H⁺] فيه أكبر بـ (7.9 × 10⁻⁴)/(5.0 × 10⁻⁸) ≈ 1.6 × 10⁴ مرة.', '["A: pH = 3.10 و pOH = 10.90، حمضي","B: pH = 7.30 و pOH = 6.70، قاعدي (ضعيف)","A أكثر حمضية","النسبة ≈ 1.6 × 10⁴ مرة"]'::jsonb, '["pH(A) = −log(7.9 × 10⁻⁴) = 3.10، pOH(A) = 10.90","pH(B) = −log(5.0 × 10⁻⁸) = 7.30، pOH(B) = 6.70","A حمضي (pH < 7)، B قاعدي (pH > 7)","النسبة = (7.9 × 10⁻⁴)/(5.0 × 10⁻⁸) = 1.6 × 10⁴"]'::jsonb, '[{"element":"pH و pOH للمحلول A","marks":1.5},{"element":"pH و pOH للمحلول B","marks":1.5},{"element":"تحديد طبيعة المحلولين","marks":1},{"element":"حساب نسبة [H⁺] بين المحلولين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"كل الحسابات والأحكام صحيحة مع النسبة"},{"level":"3–4 درجات","description":"حسابات أحد المحلولين أو النسبة ناقصة أو بها خطأ واحد"},{"level":"1–2 درجة","description":"حساب pH لمحلول واحد صحيحًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المحلول B حمضيًا لأن [H⁺] فيه موجود أو لأن قيمته قريبة من 7","حساب النسبة من الفرق بين قيمتي pH (4.2 مرة) بدلًا من نسبة التركيزين","تقريب pH إلى عدد صحيح فيضيع المعامل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T09:21:20.646Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L3-O02') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L3-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'محلول مائي تركيز أيون الهيدروجين فيه [H⁺] = 1.0 × 10⁻³ M عند 298 K. ما تركيز أيون الهيدروكسيد [OH⁻] فيه؟', null, '["1.0 × 10⁻³ M","1.0 × 10¹¹ M","1.0 × 10⁻¹⁷ M","1.0 × 10⁻¹¹ M"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 73 — المثال 2-1'),
('mcq', 2, 'أيّ العلاقات الآتية تُستعمل لحساب تركيز أيون الهيدروكسيد [OH⁻] في محلول مائي إذا عُرف تركيز أيون الهيدروجين [H⁺] عند 298 K؟', null, '["[OH⁻] = [H⁺] / Kw","[OH⁻] = Kw / [H⁺]","[OH⁻] = Kw × [H⁺]","[OH⁻] = Kw − [H⁺]"]'::jsonb, 'فهم', 'فهم علاقة', 'سهل', 'الكتاب ص 72–73 — ثابت تأين الماء Kw'),
('mcq', 3, 'باستعمال ثابت تأين الماء Kw = 1.0 × 10⁻¹⁴، أوجد [OH⁻] لعينة [H⁺] فيها يساوي 5.0 × 10⁻⁴ M.', null, '["2.0 × 10⁻¹¹ M","5.0 × 10⁻¹¹ M","2.0 × 10⁻¹⁰ M","5.0 × 10⁻¹⁸ M"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 73 — المثال 2-1 والمسائل 21'),
('mcq', 4, 'محلول مائي فيه [H⁺] = 2.0 × 10⁻⁹ M عند 298 K. ما تركيز [OH⁻] فيه، وما طبيعة المحلول؟', null, '["5.0 × 10⁻⁶ M، والمحلول حمضي","2.0 × 10⁵ M، والمحلول قاعدي","5.0 × 10⁻⁶ M، والمحلول قاعدي","2.0 × 10⁻²³ M، والمحلول حمضي"]'::jsonb, 'تطبيق', 'حساب وتصنيف', 'متوسط', 'الكتاب ص 73 — المثال 2-1 والمسائل 21'),
('mcq', 5, 'محلول مائي عند 298 K تركيز أيون الهيدروجين فيه [H⁺] أكبر من 1.0 × 10⁻⁷ M. ماذا تتوقع لتركيز [OH⁻] فيه قبل إجراء الحساب؟', null, '["أكبر من 1.0 × 10⁻⁷ M","يساوي 1.0 × 10⁻⁷ M","أقل من 1.0 × 10⁻⁷ M","يساوي [H⁺] في المحلول"]'::jsonb, 'فهم', 'توقع', 'متوسط', 'الكتاب ص 73 — المثال 2-1 (تحليل المسألة)'),
('mcq', 6, 'أُضيف حمض إلى ماء نقي عند 298 K حتى أصبح [H⁺] = 4.0 × 10⁻⁶ M. ما تركيز [OH⁻] في المحلول الناتج، وبكم مرة تغيّر عن قيمته في الماء النقي؟', null, '["2.5 × 10⁻⁹ M، أي نقص 40 مرة","2.5 × 10⁻⁹ M، أي نقص 4 مرات","4.0 × 10⁻⁶ M، أي زاد 40 مرة","2.5 × 10⁻⁸ M، أي نقص 4 مرات"]'::jsonb, 'تطبيق', 'حساب ومقارنة', 'صعب', 'الكتاب ص 72–73 — Kw ومبدأ لوتشاتلييه، المثال 2-1'),
('mcq', 7, 'يبيّن الجدول تركيز أيون الهيدروجين في أربعة محاليل مائية عند 298 K. في أيّ المحاليل يكون تركيز أيون الهيدروكسيد [OH⁻] أكبر من 1.0 × 10⁻³ M؟', '{"headers":["المحلول","[H⁺] (M)"],"rows":[["P","1.0 × 10⁻²"],["Q","3.2 × 10⁻¹²"],["R","1.0 × 10⁻⁷"],["S","2.0 × 10⁻⁹"]]}'::jsonb, '["المحلول P","المحلول R","المحلول S","المحلول Q"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 73 — المسائل 21'),
('essay', 1, 'احسب تركيز أيون الهيدروكسيد [OH⁻] في كل من المحلولين الآتيين عند 298 K، ثم حدّد هل المحلول حمضي أم قاعدي أم متعادل: (a) [H⁺] = 2.5 × 10⁻¹¹ M، (b) [H⁺] = 6.0 × 10⁻³ M.', null, null, 'تطبيق', 'حساب بخطوات', 'متوسط', 'الكتاب ص 73 — المثال 2-1 والمسائل 21'),
('essay', 2, 'في الماء النقي عند 298 K يكون [H⁺] = [OH⁻] = 1.0 × 10⁻⁷ M. أُضيف إليه حمض حتى أصبح [H⁺] = 1.0 × 10⁻⁴ M. احسب [OH⁻] الجديد، وفسّر نقصانه مستعينًا بمبدأ لوتشاتلييه.', null, null, 'تطبيق', 'حساب وتفسير', 'سهل', 'الكتاب ص 72–73 — Kw ومبدأ لوتشاتلييه'),
('essay', 3, 'طُلب من طالبين حساب [OH⁻] لمحلول فيه [H⁺] = 2.0 × 10⁻³ M عند 298 K. كتب الطالب الأول: [OH⁻] = 2.0 × 10⁻¹¹ M، وكتب الطالب الثاني: [OH⁻] = 2.0 × 10⁻³ M لأن الماء يتأين إلى أعداد متساوية من الأيونين. قوّم إجابتي الطالبين، وحدّد خطأ كلٍّ منهما، ثم اكتب الحل الصحيح.', null, null, 'تقويم', 'تقويم حل', 'صعب', 'الكتاب ص 72–73 — ثابت تأين الماء والمثال 2-1')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L3-O03') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, '[OH⁻] = Kw / [H⁺] = (1.0 × 10⁻¹⁴) / (1.0 × 10⁻³) = 1.0 × 10⁻¹¹ M.', '["افترض تساوي [OH⁻] و [H⁺]، وهذا لا يصح إلا في الماء النقي أو المحلول المتعادل.","قسم [H⁺] على Kw (مقلوب العلاقة) فنتج أس موجب لا معنى له.","ضرب Kw في [H⁺] بدلًا من القسمة عليه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-17T09:21:20.647Z"}'::jsonb),
('mcq', 2, 1, 'من Kw = [H⁺][OH⁻] نقسم الطرفين على [H⁺] فنحصل على [OH⁻] = Kw / [H⁺].', '["مقلوب العلاقة الصحيحة؛ يعطي قيمًا كبيرة جدًّا لا تمثل تركيزًا.","","Kw هو حاصل ضرب التركيزين، فإيجاد أحدهما يكون بالقسمة لا بالضرب.","Kw حاصل ضرب لا مجموع، فلا يُحسب [OH⁻] بالطرح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-17T09:21:20.647Z"}'::jsonb),
('mcq', 3, 0, '[OH⁻] = (1.0 × 10⁻¹⁴) / (5.0 × 10⁻⁴) = 0.20 × 10⁻¹⁰ = 2.0 × 10⁻¹¹ M.', '["","قسم الأسس فقط وأبقى المعامل 5.0 كما هو بدلًا من قسمة 1.0 على 5.0.","قسم المعاملين صحيحًا (0.20) لكنه لم يعدّل الأس عند كتابة الناتج بالصيغة العلمية (0.20 × 10⁻¹⁰ = 2.0 × 10⁻¹¹).","ضرب Kw في [H⁺] بدلًا من القسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.647Z"}'::jsonb),
('mcq', 4, 2, '[OH⁻] = (1.0 × 10⁻¹⁴) / (2.0 × 10⁻⁹) = 5.0 × 10⁻⁶ M. ولأن [OH⁻] أكبر من [H⁺] فالمحلول قاعدي.', '["قيمة [OH⁻] صحيحة، لكن [OH⁻] > [H⁺] يعني أن المحلول قاعدي لا حمضي.","قسم [H⁺] على Kw بدلًا من قسمة Kw على [H⁺]، فنتج 2.0 × 10⁵ M وهو ناتج غير ممكن.","","ضرب Kw في [H⁺] بدلًا من القسمة، ثم حكم بالحمضية لصغر الناتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-17T09:21:20.647Z"}'::jsonb),
('mcq', 5, 2, 'حاصل ضرب [H⁺][OH⁻] ثابت ويساوي 1.0 × 10⁻¹⁴، فإذا زاد [H⁺] على 1.0 × 10⁻⁷ M وجب أن يقل [OH⁻] عن 1.0 × 10⁻⁷ M.', '["لو زاد التركيزان معًا لزاد حاصل ضربهما على Kw، وهذا غير ممكن.","التركيز 1.0 × 10⁻⁷ M لـ OH⁻ يخص الماء النقي (المتعادل) فقط.","","تساوي التركيزين يحدث في المحلول المتعادل فقط، وهنا [H⁺] أكبر من 10⁻⁷ M."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-17T09:21:20.647Z"}'::jsonb),
('mcq', 6, 0, '[OH⁻] = (1.0 × 10⁻¹⁴)/(4.0 × 10⁻⁶) = 2.5 × 10⁻⁹ M. وفي الماء النقي [OH⁻] = 1.0 × 10⁻⁷ M، والنسبة (1.0 × 10⁻⁷)/(2.5 × 10⁻⁹) = 40، أي نقص 40 مرة.', '["","التركيز صحيح، لكن النسبة حُسبت خطأً بمقارنة المعاملين فقط دون الأسس؛ النسبة الصحيحة 40.","افترض أن [OH⁻] يساوي [H⁺]، وأن إضافة الحمض تزيد [OH⁻]، وكلاهما خطأ.","خطأ في الأس عند القسمة (−14 − (−6) = −8 دون تعديل المعامل 0.25)، ثم نسبة خاطئة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T09:21:20.648Z"}'::jsonb),
('mcq', 7, 3, '[OH⁻] = Kw/[H⁺]: في P = 1.0 × 10⁻¹² M، وفي Q = 3.1 × 10⁻³ M، وفي R = 1.0 × 10⁻⁷ M، وفي S = 5.0 × 10⁻⁶ M. المحلول الوحيد الذي يزيد فيه [OH⁻] على 1.0 × 10⁻³ M هو Q.', '["في P يكون [OH⁻] = 1.0 × 10⁻¹² M؛ اختيار P يعني الخلط بين [H⁺] الكبير و [OH⁻].","R محلول متعادل فيه [OH⁻] = 1.0 × 10⁻⁷ M، وهو أقل كثيرًا من 10⁻³ M.","S قاعدي لكن [OH⁻] فيه = 5.0 × 10⁻⁶ M فقط، وهو أقل من 10⁻³ M.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T09:21:20.648Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) [OH⁻] = Kw/[H⁺] = (1.0 × 10⁻¹⁴)/(2.5 × 10⁻¹¹) = 4.0 × 10⁻⁴ M، و [OH⁻] > [H⁺] فالمحلول قاعدي. (b) [OH⁻] = (1.0 × 10⁻¹⁴)/(6.0 × 10⁻³) = 1.7 × 10⁻¹² M، و [H⁺] > [OH⁻] فالمحلول حمضي.', '["كتابة [OH⁻] = Kw/[H⁺]","(a) [OH⁻] = 4.0 × 10⁻⁴ M، قاعدي","(b) [OH⁻] = 1.7 × 10⁻¹² M، حمضي"]'::jsonb, '["Kw = [H⁺][OH⁻] ⇒ [OH⁻] = Kw/[H⁺]","(a) (1.0 × 10⁻¹⁴)/(2.5 × 10⁻¹¹) = 4.0 × 10⁻⁴ M","(a) [OH⁻] > [H⁺] ⇒ قاعدي","(b) (1.0 × 10⁻¹⁴)/(6.0 × 10⁻³) = 1.7 × 10⁻¹² M","(b) [H⁺] > [OH⁻] ⇒ حمضي"]'::jsonb, '[{"element":"كتابة العلاقة الصحيحة","marks":1},{"element":"حساب [OH⁻] للمحلول (a) وتصنيفه","marks":2},{"element":"حساب [OH⁻] للمحلول (b) وتصنيفه","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"العلاقة والحسابان والتصنيفان صحيحة"},{"level":"3–4 درجات","description":"محلول واحد كامل الصحة والآخر فيه خطأ واحد"},{"level":"1–2 درجة","description":"العلاقة صحيحة مع أخطاء في الحساب أو التصنيف"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة [H⁺] على Kw","خطأ في الأس عند قسمة المعاملين (كتابة 0.40 × 10⁻³ دون تعديل أو 4.0 × 10⁻³)","تقريب 1.67 إلى 1.6 أو إهمال الأرقام المعنوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T09:21:20.648Z"}'::jsonb),
('essay', 2, null::int, null, null, '[OH⁻] = Kw/[H⁺] = (1.0 × 10⁻¹⁴)/(1.0 × 10⁻⁴) = 1.0 × 10⁻¹⁰ M، أي نقص من 1.0 × 10⁻⁷ M إلى 1.0 × 10⁻¹⁰ M. التفسير: الماء في حالة اتزان H₂O ⇌ H⁺ + OH⁻، وإضافة أيونات H⁺ إضافية تُحدث اضطرابًا في الاتزان، فيتجه النظام إلى تقليل أثر الزيادة بتفاعل أيونات H⁺ المضافة مع أيونات OH⁻ لتكوين جزيئات ماء، فيقل [OH⁻] ويبقى حاصل الضرب [H⁺][OH⁻] = 1.0 × 10⁻¹⁴.', '["[OH⁻] = 1.0 × 10⁻¹⁰ M","الإشارة إلى اتزان تأين الماء","تفاعل H⁺ المضاف مع OH⁻ لتكوين ماء","بقاء Kw ثابتًا"]'::jsonb, '["[OH⁻] = Kw/[H⁺]","[OH⁻] = (1.0 × 10⁻¹⁴)/(1.0 × 10⁻⁴) = 1.0 × 10⁻¹⁰ M"]'::jsonb, '[{"element":"حساب [OH⁻] = 1.0 × 10⁻¹⁰ M","marks":1},{"element":"تفسير بمبدأ لوتشاتلييه (اتجاه الاتزان نحو تكوين الماء)","marks":1},{"element":"ذكر ثبات Kw","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حساب صحيح وتفسير كامل يذكر الاتزان وثبات Kw"},{"level":"2 درجتان","description":"حساب صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"حساب صحيح فقط أو تفسير صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن [OH⁻] يبقى 1.0 × 10⁻⁷ M لأن الحمض لا يحتوي على OH⁻","القول إن Kw يزداد بإضافة الحمض","تفسير النقصان بالتخفيف بدل التفاعل مع H⁺"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T09:21:20.648Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الحل الصحيح: [OH⁻] = Kw/[H⁺] = (1.0 × 10⁻¹⁴)/(2.0 × 10⁻³) = 0.50 × 10⁻¹¹ = 5.0 × 10⁻¹² M. الطالب الأول قسم الأسس صحيحًا لكنه نقل المعامل 2.0 كما هو بدلًا من قسمة 1.0 على 2.0 = 0.50 ثم تعديل الأس، فإجابته خاطئة. الطالب الثاني خلط بين الماء النقي والمحلول؛ فتساوي [H⁺] و [OH⁻] يصح في الماء النقي (أو المحلول المتعادل) فقط، أما في المحلول الحمضي فيقل [OH⁻] لأن حاصل الضرب ثابت يساوي 1.0 × 10⁻¹⁴، ولو صحّت إجابته لكان حاصل الضرب 4.0 × 10⁻⁶ وهو لا يساوي Kw.', '["الحل الصحيح [OH⁻] = 5.0 × 10⁻¹² M","خطأ الطالب الأول: عدم قسمة المعاملات","خطأ الطالب الثاني: تعميم تساوي التركيزين من الماء النقي","التحقق بأن حاصل الضرب يجب أن يساوي Kw"]'::jsonb, '["[OH⁻] = Kw/[H⁺]","(1.0 × 10⁻¹⁴)/(2.0 × 10⁻³) = 0.50 × 10⁻¹¹ = 5.0 × 10⁻¹² M","التحقق: (2.0 × 10⁻³)(5.0 × 10⁻¹²) = 1.0 × 10⁻¹⁴"]'::jsonb, '[{"element":"الحل الصحيح بخطواته","marks":2},{"element":"تحديد خطأ الطالب الأول","marks":1},{"element":"تحديد خطأ الطالب الثاني مع التعليل بثبات Kw","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"حل صحيح وتحديد خطأي الطالبين بتعليل سليم"},{"level":"3–4 درجات","description":"حل صحيح مع تحديد خطأ طالب واحد، أو تحديد الخطأين مع حل فيه خطأ حسابي"},{"level":"1–2 درجة","description":"حل صحيح فقط دون تقويم، أو تقويم دون حل"},{"level":"صفر","description":"تأييد أحد الطالبين أو لا إجابة"}]'::jsonb, '["تأييد الطالب الأول لأن الأس صحيح","تأييد الطالب الثاني بالخلط بين الماء النقي والمحلول الحمضي","كتابة الناتج 0.50 × 10⁻¹¹ دون تحويله إلى صيغة علمية صحيحة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.649Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L3-O03') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L3-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'محلول مائي قيمة pH له 6.00 عند 298 K. ما قيمة pOH لهذا المحلول؟', null, '["6.00","8.00","20.00","−8.00"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 74 — العلاقة بين pH و pOH'),
('mcq', 2, 'قيمة pH لعينة من محلول حمضي تساوي 3.70 عند 298 K. ما تركيز أيون الهيدروجين [H⁺] فيها؟', null, '["5.0 × 10⁻¹¹ M","5.0 × 10⁻⁴ M","2.0 × 10⁻³ M","2.0 × 10⁻⁴ M"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 77 — المثال 2-4'),
('mcq', 3, 'قيمة pH لمحلول قاعدي 10.50 عند 298 K. ما تركيز أيون الهيدروكسيد [OH⁻] فيه؟', null, '["3.2 × 10⁻¹¹ M","3.2 × 10⁻⁴ M","3.2 × 10⁻³ M","1.0 × 10⁻³ M"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 77 — المثال 2-4'),
('mcq', 4, 'أيّ العلاقات الآتية تُستعمل لإيجاد تركيز أيون الهيدروجين [H⁺] لمحلول إذا عُلمت قيمة pH له؟', null, '["[H⁺] = 10^−pH","[H⁺] = −log pH","[H⁺] = 14.00 − pH","[H⁺] = 10^pH"]'::jsonb, 'فهم', 'فهم علاقة', 'سهل', 'الكتاب ص 77 — حساب تراكيز الأيونات من قيم pH'),
('mcq', 5, 'محلول مائي قيمة pH له 4.60 عند 298 K. أيّ مما يأتي يمثّل قيمة pOH وتركيز [OH⁻] فيه؟', null, '["pOH = 9.40، [OH⁻] = 2.5 × 10⁻⁵ M","pOH = 4.60، [OH⁻] = 2.5 × 10⁻⁵ M","pOH = 9.40، [OH⁻] = 4.0 × 10⁻¹⁰ M","pOH = 9.40، [OH⁻] = 4.0 × 10⁻⁹ M"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 77 — المثال 2-4 والمسائل 29'),
('mcq', 6, 'قيمة pOH لمحلول منظف عند 298 K تساوي 2.90. ما قيمة pH له وما تركيز أيون الهيدروجين [H⁺] فيه؟', null, '["pH = 2.90، [H⁺] = 1.3 × 10⁻³ M","pH = 11.10، [H⁺] = 7.9 × 10⁻¹² M","pH = 11.10، [H⁺] = 1.3 × 10⁻³ M","pH = 11.10، [H⁺] = 7.9 × 10⁻¹¹ M"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 77 — حساب التراكيز من pH و pOH، المسألة 30'),
('mcq', 7, 'يبيّن الجدول قيم pH لأربعة محاليل مائية عند 298 K. في أيّ محلول يكون تركيز أيون الهيدروكسيد [OH⁻] أكبر من تركيز أيون الهيدروجين [H⁺] بمقدار 100 مرة بالضبط؟', '{"headers":["المحلول","pH"],"rows":[["A","6.00"],["B","8.00"],["C","9.00"],["D","7.00"]]}'::jsonb, '["المحلول A","المحلول C","المحلول D","المحلول B"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 75 و 77 — الشكل 2-15 والمثال 2-4'),
('essay', 1, 'قيمة pH لمحلول مائي 8.25 عند 298 K. احسب قيم [H⁺] و pOH و [OH⁻] لهذا المحلول موضحًا خطوات الحل، ثم تحقّق من صحة إجابتك.', null, null, 'تطبيق', 'حساب بخطوات', 'متوسط', 'الكتاب ص 77 — المثال 2-4'),
('essay', 2, 'محلول مائي قيمة pH له 5.00 عند 298 K. احسب [H⁺] و pOH و [OH⁻]، ثم حدّد طبيعة المحلول.', null, null, 'تطبيق', 'حساب بخطوات', 'سهل', 'الكتاب ص 77 — حساب تراكيز الأيونات من قيم pH'),
('essay', 3, 'منظف أفران قيمة pH له 12.30، ومحلول منظف آخر قيمة pOH له 4.40 عند 298 K. احسب [H⁺] و [OH⁻] لكل منهما، ثم حدّد أيهما أشد قاعدية، وكم مرة يزيد [OH⁻] فيه على الآخر.', null, null, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 77 — المثال 2-4 والمسائل 29–30')
