('mcq', 1, 1, 'pH + pOH = 14.00، إذن pOH = 14.00 − 6.00 = 8.00.', '["افترض أن pOH تساوي pH، وهذا لا يصح إلا للمحلول المتعادل (7.00).","","جمع 14.00 + 6.00 بدلًا من الطرح.","طرح بترتيب معكوس (6.00 − 14.00)، وقيمة pOH هنا موجبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-17T09:21:20.649Z"}'::jsonb),
('mcq', 2, 3, '[H⁺] = 10^−pH = 10^−3.70 = 2.0 × 10⁻⁴ M.', '["هذه قيمة [OH⁻] (10^−10.30)، لا [H⁺].","خطأ في تجزئة الأس: كتب 10^0.70 × 10⁻⁴ بدلًا من 10^0.30 × 10⁻⁴.","خطأ في تجزئة الأس: كتب 10^0.30 × 10⁻³ بدلًا من 10^0.30 × 10⁻⁴.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.649Z"}'::jsonb),
('mcq', 3, 1, 'pOH = 14.00 − 10.50 = 3.50، ثم [OH⁻] = 10^−3.50 = 3.2 × 10⁻⁴ M.', '["هذه قيمة [H⁺] = 10^−10.50، وليست [OH⁻].","","خطأ في الأس: 10^−3.50 = 10^0.50 × 10⁻⁴ وليس × 10⁻³.","قرّب pOH إلى 3 فأهمل الجزء العشري 0.50."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.649Z"}'::jsonb),
('mcq', 4, 0, 'بما أن pH = −log[H⁺]، فبضرب الطرفين في −1 وأخذ اللوغاريتم العكسي نحصل على [H⁺] = 10^−pH.', '["","هذا أخذ للوغاريتم مرة أخرى بدلًا من اللوغاريتم العكسي.","هذه العلاقة تعطي pOH لا [H⁺].","أُهملت إشارة السالب، فيعطي قيمًا أكبر من 1 لا تمثل تركيز H⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.650Z"}'::jsonb),
('mcq', 5, 2, 'pOH = 14.00 − 4.60 = 9.40، و [OH⁻] = 10^−9.40 = 4.0 × 10⁻¹⁰ M.', '["pOH صحيحة، لكن 2.5 × 10⁻⁵ M هي [H⁺] = 10^−4.60 وليست [OH⁻].","افترض أن pOH = pH وأن [OH⁻] = [H⁺] كما في المحلول المتعادل.","","pOH صحيحة، لكن 10^−9.40 = 10^0.60 × 10⁻¹⁰ لا × 10⁻⁹ (خطأ في الأس)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T09:21:20.650Z"}'::jsonb),
('mcq', 6, 1, 'pH = 14.00 − 2.90 = 11.10، و [H⁺] = 10^−11.10 = 7.9 × 10⁻¹² M.', '["عامل قيمة pOH كأنها pH، فحسب تركيزًا يخص OH⁻ لا H⁺.","","pH صحيحة، لكن 1.3 × 10⁻³ M هي [OH⁻] = 10^−2.90 لا [H⁺].","pH صحيحة، لكن 10^−11.10 = 10^0.90 × 10⁻¹² لا × 10⁻¹¹ (خطأ في الأس)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.651Z"}'::jsonb),
('mcq', 7, 3, 'في المحلول B: [H⁺] = 10^−8.00 = 1.0 × 10⁻⁸ M، و pOH = 6.00 فـ [OH⁻] = 1.0 × 10⁻⁶ M؛ والنسبة [OH⁻]/[H⁺] = 10² = 100.', '["في A يكون [H⁺] = 10⁻⁶ M و [OH⁻] = 10⁻⁸ M، أي أن [H⁺] هو الأكبر بمئة مرة (العلاقة معكوسة).","في C يكون [OH⁻] = 10⁻⁵ M و [H⁺] = 10⁻⁹ M، فالنسبة 10⁴ لا 100.","D متعادل فيه [OH⁻] = [H⁺] = 10⁻⁷ M، والنسبة 1.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.651Z"}'::jsonb),
('essay', 1, null::int, null, null, '[H⁺] = 10^−8.25 = 5.6 × 10⁻⁹ M. pOH = 14.00 − 8.25 = 5.75. [OH⁻] = 10^−5.75 = 1.8 × 10⁻⁶ M. التحقق: [H⁺][OH⁻] = (5.6 × 10⁻⁹)(1.8 × 10⁻⁶) ≈ 1.0 × 10⁻¹⁴ = Kw، كما أن [OH⁻] > [H⁺] وهذا متوقع لأن pH > 7.', '["[H⁺] = 5.6 × 10⁻⁹ M","pOH = 5.75","[OH⁻] = 1.8 × 10⁻⁶ M","التحقق باستعمال Kw أو بمقارنة التركيزين"]'::jsonb, '["[H⁺] = 10^−pH = 10^−8.25 = 5.6 × 10⁻⁹ M","pOH = 14.00 − pH = 14.00 − 8.25 = 5.75","[OH⁻] = 10^−pOH = 10^−5.75 = 1.8 × 10⁻⁶ M","التحقق: (5.6 × 10⁻⁹)(1.8 × 10⁻⁶) ≈ 1.0 × 10⁻¹⁴"]'::jsonb, '[{"element":"حساب [H⁺]","marks":1},{"element":"حساب pOH","marks":1},{"element":"حساب [OH⁻]","marks":1},{"element":"التحقق من الإجابة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القيم الثلاث صحيحة مع تحقق سليم"},{"level":"3 درجات","description":"القيم الثلاث صحيحة دون تحقق، أو قيمتان مع تحقق"},{"level":"1–2 درجة","description":"قيمة أو قيمتان صحيحتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة [H⁺] = 10^8.25 بإهمال الإشارة السالبة","كتابة [OH⁻] = 10^−8.25 (الخلط بين pH و pOH)","خطأ في الأس عند تحويل 10^−8.25 إلى صيغة علمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.651Z"}'::jsonb),
('essay', 2, null::int, null, null, '[H⁺] = 10^−5.00 = 1.0 × 10⁻⁵ M. pOH = 14.00 − 5.00 = 9.00. [OH⁻] = 10^−9.00 = 1.0 × 10⁻⁹ M. المحلول حمضي لأن pH أقل من 7 ([H⁺] > [OH⁻]).', '["[H⁺] = 1.0 × 10⁻⁵ M","pOH = 9.00","[OH⁻] = 1.0 × 10⁻⁹ M","المحلول حمضي"]'::jsonb, '["[H⁺] = 10^−5.00 = 1.0 × 10⁻⁵ M","pOH = 14.00 − 5.00 = 9.00","[OH⁻] = 10^−9.00 = 1.0 × 10⁻⁹ M"]'::jsonb, '[{"element":"[H⁺] صحيح","marks":1},{"element":"pOH صحيح","marks":1},{"element":"[OH⁻] صحيح","marks":1},{"element":"تحديد الطبيعة الحمضية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"القيم الثلاث والتصنيف صحيحة"},{"level":"2–3 درجات","description":"قيمتان صحيحتان مع التصنيف أو دونه"},{"level":"1 درجة","description":"قيمة واحدة صحيحة أو تصنيف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة [H⁺] = 5.0 M أو 1.0 × 10⁵ M","عدّ المحلول قاعديًا لأن pOH أكبر من 7","كتابة [OH⁻] = 1.0 × 10⁻⁵ M"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-10-17T09:21:20.651Z"}'::jsonb),
('essay', 3, null::int, null, null, 'منظف الأفران: [H⁺] = 10^−12.30 = 5.0 × 10⁻¹³ M؛ pOH = 14.00 − 12.30 = 1.70؛ [OH⁻] = 10^−1.70 = 2.0 × 10⁻² M. المنظف الآخر: pH = 14.00 − 4.40 = 9.60؛ [H⁺] = 10^−9.60 = 2.5 × 10⁻¹⁰ M؛ [OH⁻] = 10^−4.40 = 4.0 × 10⁻⁵ M. منظف الأفران أشد قاعدية لأن [OH⁻] فيه أكبر (و pH له أكبر)، والنسبة (2.0 × 10⁻²)/(4.0 × 10⁻⁵) = 5.0 × 10² = 500 مرة.', '["منظف الأفران: [H⁺] = 5.0 × 10⁻¹³ M و [OH⁻] = 2.0 × 10⁻² M","المنظف الآخر: [H⁺] = 2.5 × 10⁻¹⁰ M و [OH⁻] = 4.0 × 10⁻⁵ M","منظف الأفران أشد قاعدية","النسبة 500 مرة"]'::jsonb, '["منظف الأفران: [H⁺] = 10^−12.30 = 5.0 × 10⁻¹³ M","pOH = 14.00 − 12.30 = 1.70 ⇒ [OH⁻] = 10^−1.70 = 2.0 × 10⁻² M","المنظف الآخر: pH = 14.00 − 4.40 = 9.60 ⇒ [H⁺] = 2.5 × 10⁻¹⁰ M","[OH⁻] = 10^−4.40 = 4.0 × 10⁻⁵ M","النسبة = (2.0 × 10⁻²)/(4.0 × 10⁻⁵) = 500"]'::jsonb, '[{"element":"تراكيز منظف الأفران","marks":2},{"element":"تراكيز المنظف الآخر","marks":2},{"element":"تحديد الأشد قاعدية مع التعليل","marks":1},{"element":"حساب النسبة 500","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"التراكيز الأربعة والحكم والنسبة صحيحة"},{"level":"4–5 درجات","description":"خطأ واحد في تركيز أو في النسبة"},{"level":"2–3 درجات","description":"تراكيز محلول واحد صحيحة مع حكم صحيح"},{"level":"1 درجة","description":"حكم صحيح فقط أو تركيز واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقارنة 12.30 بـ 4.40 مباشرة دون تحويل pOH إلى pH","حساب النسبة من الفرق بين القيم اللوغاريتمية بدلًا من نسبة التركيزين","عدّ المنظف ذي pOH الأصغر أقل قاعدية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.652Z"}'::jsonb)
