from (values
('mcq', 1, 'ما المقصود بثابت تأين الماء Kw؟', null, '["تركيز الماء النقي عند 298 K بوحدة mol/L","ثابت الاتزان للتأين الذاتي للماء، ويساوي [H⁺][OH⁻]","نسبة تركيز H⁺ إلى تركيز OH⁻ في المحاليل المائية","ثابت تأين الأحماض الضعيفة عند ذوبانها في الماء"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 72 — ثابت تأين الماء Kw'),
('mcq', 2, 'ما قيمة ثابت تأين الماء Kw عند درجة حرارة 298 K؟', null, '["1.0 × 10⁻¹⁴","1.0 × 10⁻⁷","14.00","2.0 × 10⁻⁷"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 72 — قيمة Kw عند 298 K'),
('mcq', 3, 'عند كتابة تعبير ثابت الاتزان لتأين الماء H₂O(l) ⇌ H⁺(aq) + OH⁻(aq)، لماذا لا يظهر H₂O في المقام؟', null, '["لأن الماء لا يتأين مطلقًا","لأن الماء من النواتج لا من المتفاعلات","لأن تركيز الماء النقي ثابت","لأن تركيز الماء يساوي 1.0 × 10⁻⁷ M"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 72 — ثابت تأين الماء Kw'),
('mcq', 4, 'ماذا يُقصد بالتأين الذاتي للماء؟', null, '["تفكك الماء إلى غازي الهيدروجين والأكسجين","انتقال بروتون بين جزيئي ماء لإنتاج H₃O⁺ و OH⁻","ذوبان الأملاح في الماء وتكوّن أيوناتها","تحوّل الماء السائل إلى بخار عند تسخينه"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'متوسط', 'الكتاب ص 58 و 72 — التأين الذاتي للماء، الشكل 2-13'),
('mcq', 5, 'في معادلة التأين الذاتي للماء H₂O(l) + H₂O(l) ⇌ H₃O⁺(aq) + OH⁻(aq)، ما دور كل من جزيئي الماء؟', null, '["كلاهما يسلك سلوك الحمض فيمنح كلٌّ منهما بروتونًا","كلاهما يسلك سلوك القاعدة فيستقبل كلٌّ منهما بروتونًا","أحدهما يمنح أيون OH⁻ والآخر يستقبل إلكترونًا","أحدهما يسلك سلوك الحمض والآخر يسلك سلوك القاعدة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 72 — الشكل 2-13'),
('mcq', 6, 'أثبتت التجارب أن [H⁺] = [OH⁻] = 1.0 × 10⁻⁷ M في الماء النقي عند 298 K. أيّ مما يأتي يبيّن الحساب الصحيح لقيمة Kw؟', null, '["(1.0 × 10⁻⁷) + (1.0 × 10⁻⁷) = 2.0 × 10⁻⁷","(1.0 × 10⁻⁷)(1.0 × 10⁻⁷) = 1.0 × 10⁻¹⁴","(1.0 × 10⁻⁷) ÷ (1.0 × 10⁻⁷) = 1.0","(1.0 × 10⁻⁷)(1.0 × 10⁻⁷) ÷ 55.5 = 1.8 × 10⁻¹⁶"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 72 — حساب Kw'),
('mcq', 7, 'أيّ العبارات الآتية عن ثابت تأين الماء Kw صحيحة؟', null, '["تزداد قيمته عند إضافة حمض إلى الماء عند 298 K","يساوي مجموع [H⁺] و [OH⁻] في أي محلول مائي","حاصل [H⁺][OH⁻] في المحاليل المائية المخففة يساويه","يُكتب تعبيره Kw = [H⁺][OH⁻] / [H₂O]"]'::jsonb, 'فهم', 'تمييز عبارة صحيحة', 'صعب', 'الكتاب ص 72–73 — ثابت تأين الماء Kw'),
('essay', 1, 'عرّف ثابت تأين الماء Kw، واكتب تعبيره الرياضي، واذكر قيمته عند 298 K.', null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 72 — ثابت تأين الماء Kw'),
('essay', 2, 'اكتب معادلة التأين الذاتي للماء بصورتيها (بأيون الهيدرونيوم وبالصورة المبسطة)، ووضّح دور كل جزيء ماء فيها، ثم فسّر لماذا يتساوى [H⁺] و [OH⁻] في الماء النقي، واستعمل ذلك لحساب Kw عند 298 K.', null, null, 'فهم', 'كتابة معادلات وتفسير', 'صعب', 'الكتاب ص 58 و 72 — التأين الذاتي للماء، الشكل 2-13'),
('essay', 3, 'انطلاقًا من قاعدة كتابة تعبير ثابت الاتزان (النواتج في البسط والمتفاعلات في المقام)، وضّح كيف نصل إلى التعبير Kw = [H⁺][OH⁻] من معادلة التأين الذاتي المبسطة للماء، ثم بيّن ماذا تدل القيمة الصغيرة جدًّا لـ Kw (1.0 × 10⁻¹⁴) على مدى تأين الماء، ولماذا يُعدّ Kw حالة خاصة من ثوابت الاتزان.', null, null, 'تحليل', 'تحليل واشتقاق', 'صعب', 'الكتاب ص 72 — ثابت تأين الماء Kw')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
