from (values
('mcq', 1, 1, 'Kw قيمة تعبّر عن ثابت الاتزان للتأين الذاتي للماء، وتساوي حاصل ضرب تركيز أيون الهيدروجين في تركيز أيون الهيدروكسيد: Kw = [H⁺][OH⁻].', '["Kw ليس تركيز الماء؛ بل إن تركيز الماء الثابت لا يظهر في تعبيره أصلًا.","","Kw حاصل ضرب التركيزين لا نسبتهما، ونسبتهما تساوي 1 في الماء النقي.","ثابت تأين الحمض الضعيف هو Ka، أما Kw فخاص بتأين الماء ذاتيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.652Z"}'::jsonb),
('mcq', 2, 0, 'في الماء النقي عند 298 K: [H⁺] = [OH⁻] = 1.0 × 10⁻⁷ M، فـ Kw = (1.0 × 10⁻⁷)(1.0 × 10⁻⁷) = 1.0 × 10⁻¹⁴.', '["","هذه قيمة تركيز كل من H⁺ و OH⁻ في الماء النقي، لا قيمة Kw.","14.00 هو مجموع pH و pOH، وليس قيمة Kw.","هذا مجموع التركيزين، و Kw حاصل ضربهما لا مجموعهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.652Z"}'::jsonb),
('mcq', 3, 2, 'يُكتب تعبير ثابت الاتزان بوضع تراكيز النواتج في البسط والمتفاعلات في المقام، لكن تركيز الماء النقي ثابت، لذا لا يظهر H₂O في المقام، فيصبح Kw = [H⁺][OH⁻].', '["الماء يتأين ذاتيًا بدرجة ضئيلة، ولولا ذلك لما وُجد H⁺ و OH⁻ في الماء النقي.","الماء في هذه المعادلة هو المادة المتفاعلة، و H⁺ و OH⁻ هما النواتج.","","1.0 × 10⁻⁷ M هو تركيز كل من H⁺ و OH⁻ في الماء النقي، لا تركيز الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.652Z"}'::jsonb),
('mcq', 4, 1, 'التأين الذاتي للماء عملية ينتج فيها الماء النقي أعدادًا متساوية من أيونات الهيدرونيوم (H₃O⁺) والهيدروكسيد (OH⁻)؛ إذ ينتقل بروتون من جزيء ماء إلى جزيء آخر: H₂O + H₂O ⇌ H₃O⁺ + OH⁻.', '["تفكك الماء إلى غازي H₂ و O₂ تحليل كهربائي، وليس تأينًا ذاتيًا.","","تكوّن الأيونات هنا مصدره المذاب (الملح) لا الماء نفسه.","التبخر تغيّر فيزيائي لا تنتج عنه أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.653Z"}'::jsonb),
('mcq', 5, 3, 'في التأين الذاتي يسلك أحد الجزيئين سلوك الحمض فيمنح بروتونًا فيصبح OH⁻، ويسلك الآخر سلوك القاعدة فيستقبل البروتون فيصبح H₃O⁺.', '["لو منح الجزيئان بروتونين لما تكوّن H₃O⁺؛ فلا بد من جزيء يستقبل البروتون.","لو استقبل الجزيئان بروتونات لما تكوّن OH⁻؛ فلا بد من جزيء يمنح البروتون.","المنتقل في التأين الذاتي بروتون (H⁺) لا إلكترون، والمانح لا يمنح OH⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.653Z"}'::jsonb),
('mcq', 6, 1, 'Kw = [H⁺][OH⁻] = (1.0 × 10⁻⁷)(1.0 × 10⁻⁷) = 1.0 × 10⁻¹⁴.', '["جمع التركيزين، و Kw حاصل ضربهما.","","قسم التركيزين، و Kw حاصل ضربهما لا نسبتهما.","أدخل تركيز الماء في المقام، مع أنه لا يظهر في تعبير Kw لأنه ثابت."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.653Z"}'::jsonb),
('mcq', 7, 2, 'حاصل ضرب تركيز أيون الهيدروجين وتركيز أيون الهيدروكسيد في الماء وفي المحاليل المائية المخففة يساوي Kw (1.0 × 10⁻¹⁴ عند 298 K).', '["Kw ثابت عند درجة الحرارة نفسها؛ فإضافة الحمض تزيد [H⁺] وتنقص [OH⁻] ويبقى حاصل الضرب ثابتًا.","Kw حاصل ضرب التركيزين لا مجموعهما.","","تركيز الماء ثابت فلا يظهر في مقام تعبير Kw."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.653Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ثابت تأين الماء Kw: قيمة تعبّر عن ثابت الاتزان للتأين الذاتي للماء، وهو حاصل ضرب تركيز أيون الهيدروجين في تركيز أيون الهيدروكسيد في الماء والمحاليل المائية المخففة. تعبيره: Kw = [H⁺][OH⁻]. قيمته عند 298 K تساوي 1.0 × 10⁻¹⁴.', '["ثابت الاتزان للتأين الذاتي للماء","Kw = [H⁺][OH⁻]","1.0 × 10⁻¹⁴ عند 298 K"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"التعبير الرياضي","marks":1},{"element":"القيمة عند 298 K","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وتعبير صحيح وقيمة صحيحة"},{"level":"3 درجات","description":"تعريف ناقص مع تعبير وقيمة صحيحين"},{"level":"1–2 درجة","description":"التعبير أو القيمة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Kw = [H⁺] + [OH⁻]","ذكر القيمة 1.0 × 10⁻⁷ بدل 1.0 × 10⁻¹⁴","إدخال [H₂O] في المقام"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.653Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الصورة الأولى: H₂O(l) + H₂O(l) ⇌ H₃O⁺(aq) + OH⁻(aq). الصورة المبسطة: H₂O(l) ⇌ H⁺(aq) + OH⁻(aq). في الصورة الأولى يسلك أحد جزيئي الماء سلوك الحمض فيمنح بروتونًا ويتحول إلى OH⁻، ويسلك الآخر سلوك القاعدة فيستقبله ويتحول إلى H₃O⁺. يتساوى التركيزان في الماء النقي لأن كل عملية تأين تنتج أيون H⁺ (H₃O⁺) واحدًا وأيون OH⁻ واحدًا، فتتكون أعداد متساوية منهما. ولأن [H⁺] = [OH⁻] = 1.0 × 10⁻⁷ M عند 298 K، فإن Kw = (1.0 × 10⁻⁷)(1.0 × 10⁻⁷) = 1.0 × 10⁻¹⁴.', '["معادلة التأين بأيون الهيدرونيوم","المعادلة المبسطة","أحد الجزيئين حمض والآخر قاعدة","تساوي التركيزين لأن كل تأين ينتج أيونًا من كل نوع","Kw = 1.0 × 10⁻¹⁴"]'::jsonb, '["Kw = [H⁺][OH⁻]","Kw = (1.0 × 10⁻⁷)(1.0 × 10⁻⁷) = 1.0 × 10⁻¹⁴"]'::jsonb, '[{"element":"المعادلتان صحيحتان بالحالات الفيزيائية","marks":2},{"element":"دور كل جزيء ماء","marks":1},{"element":"تفسير تساوي التركيزين","marks":1},{"element":"حساب Kw","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"المعادلتان والدوران والتفسير والحساب كلها صحيحة"},{"level":"3–4 درجات","description":"نقص عنصر واحد أو خطأ في إحدى المعادلتين"},{"level":"1–2 درجة","description":"معادلة واحدة صحيحة أو الحساب فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة سهم باتجاه واحد بدل سهم الاتزان ⇌","كتابة نواتج التأين H₂ و O₂","عكس الدورين فيُعدّ المكوِّن لـ H₃O⁺ حمضًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.653Z"}'::jsonb),
('essay', 3, null::int, null, null, 'معادلة التأين المبسطة: H₂O(l) ⇌ H⁺(aq) + OH⁻(aq). وفق قاعدة ثابت الاتزان يكون التعبير: تراكيز النواتج [H⁺][OH⁻] في البسط، وتركيز المتفاعل [H₂O] في المقام، وكل تركيز مرفوع لأس يساوي معامله في المعادلة الموزونة وهو 1. لكن تركيز الماء النقي ثابت، فلا يظهر H₂O في المقام، فيصبح Kw = [H⁺][OH⁻]. صغر قيمة Kw جدًّا يدل على أن الماء يتأين بدرجة ضئيلة جدًّا، أي أن معظم الماء يبقى جزيئات غير متأينة ولا يوجد إلا تركيز صغير جدًّا (1.0 × 10⁻⁷ M) من كل من H⁺ و OH⁻. ويُعدّ Kw حالة خاصة لثابت الاتزان لأنه ينطبق على تأين الماء فقط.', '["كتابة المعادلة المبسطة","تطبيق قاعدة ثابت الاتزان والأسس تساوي 1","حذف [H₂O] لثبات تركيزه","صغر Kw يعني تأينًا ضئيلًا جدًّا","Kw حالة خاصة تنطبق على الماء"]'::jsonb, '[]'::jsonb, '[{"element":"اشتقاق التعبير مع حذف [H₂O] وتعليله","marks":2},{"element":"تفسير دلالة صغر قيمة Kw","marks":2},{"element":"سبب عدّه حالة خاصة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"اشتقاق صحيح معلل وتفسير سليم لصغر القيمة وذكر الحالة الخاصة"},{"level":"3–4 درجات","description":"اشتقاق صحيح مع تفسير ناقص"},{"level":"1–2 درجة","description":"كتابة التعبير فقط دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إبقاء [H₂O] في المقام","تفسير صغر Kw بأن الماء لا يتأين مطلقًا","الخلط بين صغر Kw وصغر تركيز الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.654Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
