from (values
('mcq', 1, 'إذا زاد تركيز أيونات الهيدروجين H⁺ في محلول مائي عند 298 K، فماذا يحدث لتركيز أيونات الهيدروكسيد OH⁻؟', null, '["يقل بحيث يبقى [H⁺][OH⁻] ثابتًا","يزداد بالنسبة نفسها التي زاد بها [H⁺]","يبقى ثابتًا دون أي تغيّر","يقل بحيث يبقى [H⁺] + [OH⁻] ثابتًا"]'::jsonb, 'فهم', 'فهم علاقة', 'سهل', 'الكتاب ص 73 — Kw ومبدأ لوتشاتلييه'),
('mcq', 2, 'وفق مبدأ لوتشاتلييه، عند إضافة أيونات H⁺ إلى الماء المتزن H₂O(l) ⇌ H⁺(aq) + OH⁻(aq)، كيف يحدث النقص في تركيز OH⁻؟', null, '["تتحول أيونات OH⁻ إلى غاز الأكسجين","يتأين مزيد من الماء لينتج أيونات H⁺","تتفاعل أيونات H⁺ المضافة مع OH⁻ لتكوين الماء","تتفاعل أيونات OH⁻ مع الماء لتكوين H₃O⁺"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 73 — Kw ومبدأ لوتشاتلييه'),
('mcq', 3, 'لماذا لا تتغير قيمة ثابت تأين الماء Kw عند زيادة تركيز أيونات الهيدروجين في محلول مائي عند 298 K؟', null, '["لأن إضافة H⁺ لا تؤثر في اتزان تأين الماء","لأن [OH⁻] يزداد بمقدار زيادة [H⁺] نفسه","لأن Kw يعتمد على تركيز الماء وحده","لأنه ثابت اتزان، فيقل [OH⁻] تعويضًا عن زيادة [H⁺]"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 73 — ماذا قرأت؟ (لماذا لا يتغير Kw)'),
('mcq', 4, 'أُضيف هيدروكسيد الصوديوم إلى ماء نقي فأصبح [OH⁻] = 1.0 × 10⁻³ M عند 298 K. ما تركيز [H⁺] في المحلول؟', null, '["1.0 × 10⁻⁷ M","1.0 × 10⁻¹¹ M","1.0 × 10⁻³ M","1.0 × 10⁻¹⁷ M"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 73 — Kw ومبدأ لوتشاتلييه، المثال 2-1'),
('mcq', 5, 'أيّ أزواج التراكيز الآتية يمكن أن يوجد معًا في محلول مائي عند 298 K؟', null, '["[H⁺] = 1.0 × 10⁻⁴ M و [OH⁻] = 1.0 × 10⁻¹⁰ M","[H⁺] = 1.0 × 10⁻⁴ M و [OH⁻] = 1.0 × 10⁻⁴ M","[H⁺] = 1.0 × 10⁻⁹ M و [OH⁻] = 1.0 × 10⁻⁹ M","[H⁺] = 1.0 × 10⁻³ M و [OH⁻] = 1.0 × 10⁻¹² M"]'::jsonb, 'فهم', 'تمييز', 'صعب', 'الكتاب ص 73 و 75 — Kw والشكل 2-15'),
('mcq', 6, 'في محلول حمض الإيثانويك CH₃COOH تركيزه 0.10 M يوجد الاتزان CH₃COOH(aq) ⇌ H⁺(aq) + CH₃COO⁻(aq). أُضيفت إليه قطرة من محلول NaOH. وفق مبدأ لوتشاتلييه، ماذا يحدث؟', null, '["يزداد [H⁺] لأن إضافة NaOH تزيح الاتزان نحو اليسار","لا يتغير [H⁺] لأن الحمض ضعيف لا يتأثر بالقاعدة","يقل [H⁺] ويُزاح اتزان تأين الحمض نحو اليسار","يقل [H⁺] ويُزاح اتزان تأين الحمض نحو اليمين"]'::jsonb, 'تطبيق', 'تطبيق مبدأ', 'صعب', 'الكتاب ص 80 — السؤال 37'),
('mcq', 7, 'زاد تركيز أيون الهيدروجين في محلول مائي عشر مرات، من 1.0 × 10⁻⁵ M إلى 1.0 × 10⁻⁴ M عند 298 K. ماذا يحدث لتركيز أيون الهيدروكسيد فيه؟', null, '["يزداد عشر مرات فيصبح 1.0 × 10⁻⁸ M","يقل إلى عُشر قيمته فيصبح 1.0 × 10⁻¹⁰ M","يبقى 1.0 × 10⁻⁹ M دون تغيّر","يقل إلى النصف فيصبح 5.0 × 10⁻¹⁰ M"]'::jsonb, 'تحليل', 'استنتاج علاقة', 'متوسط', 'الكتاب ص 73 — Kw ومبدأ لوتشاتلييه'),
('essay', 1, 'اذكر نص مبدأ لوتشاتلييه، ثم صِف العلاقة بين تركيز أيونات الهيدروجين وتركيز أيونات الهيدروكسيد في المحاليل المائية عند 298 K، وحدّد قيمة كل منهما عندما يتساويان.', null, null, 'فهم', 'وصف علاقة', 'سهل', 'الكتاب ص 72–73 — مراجعة المفردات و Kw ومبدأ لوتشاتلييه'),
('essay', 2, 'شبّه الكتاب سلوك تراكيز أيونات H⁺ و OH⁻ في المحاليل المائية بلعبة التوازن (السيسو). وضّح وجه الشبه، ثم فسّر مستعينًا بمبدأ لوتشاتلييه وثبات Kw ما يحدث لتركيز H⁺ عند إضافة أيونات OH⁻ (قاعدة) إلى الماء النقي.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 72–73 — الربط مع الحياة و Kw ومبدأ لوتشاتلييه'),
('essay', 3, 'محلول حمض الإيثانويك CH₃COOH تركيزه 0.10 M، أُضيفت إليه قطرة من محلول NaOH. اكتب معادلة اتزان تأين الحمض، ثم حلّل مستعينًا بمبدأ لوتشاتلييه ما يحدث لكل من [H⁺] و [OH⁻] وموضع الاتزان، ووضّح لماذا يبقى حاصل [H⁺][OH⁻] ثابتًا.', null, null, 'تحليل', 'تحليل اتزان', 'صعب', 'الكتاب ص 73 و 80 — Kw ومبدأ لوتشاتلييه، السؤال 37')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
