select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'حاصل ضرب [H⁺] و [OH⁻] يساوي دائمًا 1.0 × 10⁻¹⁴ عند 298 K، فإذا زاد [H⁺] نقص [OH⁻] بحيث يبقى حاصل الضرب ثابتًا.', '["","لو زاد التركيزان معًا لزاد حاصل ضربهما على Kw، وهذا غير ممكن.","بقاء [OH⁻] ثابتًا مع زيادة [H⁺] يجعل حاصل الضرب أكبر من Kw.","الثابت هو حاصل الضرب (Kw) لا مجموع التركيزين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T09:21:20.654Z"}'::jsonb),
('mcq', 2, 2, 'إضافة H⁺ تُحدث اضطرابًا في الاتزان، فيعمل النظام على تقليل أثر الزيادة؛ إذ تتفاعل أيونات H⁺ المضافة مع أيونات OH⁻ لتكوين مزيد من جزيئات الماء، فيقل تركيز OH⁻.', '["لا يحدث تفاعل أكسدة ينتج الأكسجين؛ إزاحة الاتزان تكوّن ماءً لا غازًا.","تأين مزيد من الماء يعني إزاحة نحو اليمين، وهو عكس ما يحدث عند زيادة أحد النواتج.","","أيونات OH⁻ قاعدية تستقبل البروتون، ولا تُكوّن H₃O⁺ بتفاعلها مع الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.654Z"}'::jsonb),
('mcq', 3, 3, 'Kw ثابت اتزان قيمته 1.0 × 10⁻¹⁴ عند 298 K، فعند زيادة [H⁺] يتجه الاتزان نحو تكوين الماء فيقل [OH⁻] بالقدر الذي يبقي حاصل الضرب [H⁺][OH⁻] ثابتًا.', '["إضافة H⁺ تُحدث اضطرابًا في الاتزان فيتجه نحو تكوين الماء؛ فهي تؤثر في التراكيز، ولكن لا تغيّر Kw.","زيادة التركيزين معًا تزيد حاصل الضرب، فلا يبقى Kw ثابتًا.","تركيز الماء لا يظهر في تعبير Kw أصلًا، و Kw = [H⁺][OH⁻].",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T09:21:20.655Z"}'::jsonb),
('mcq', 4, 1, '[H⁺] = Kw/[OH⁻] = (1.0 × 10⁻¹⁴)/(1.0 × 10⁻³) = 1.0 × 10⁻¹¹ M؛ فقد نقص [H⁺] لأن [OH⁻] زاد.', '["افترض أن [H⁺] يبقى كما في الماء النقي، مع أن زيادة OH⁻ تنقص H⁺.","","افترض تساوي التركيزين، وهذا يخص المحلول المتعادل فقط.","ضرب Kw في [OH⁻] بدلًا من القسمة عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.655Z"}'::jsonb),
('mcq', 5, 0, 'يجب أن يساوي حاصل الضرب [H⁺][OH⁻] القيمة 1.0 × 10⁻¹⁴: (1.0 × 10⁻⁴)(1.0 × 10⁻¹⁰) = 1.0 × 10⁻¹⁴، وهو الزوج الوحيد المحقق لذلك.', '["","حاصل الضرب 1.0 × 10⁻⁸، أكبر من Kw؛ فلا يمكن أن يكون التركيزان كبيرين معًا.","حاصل الضرب 1.0 × 10⁻¹⁸، أصغر من Kw؛ فلا يمكن أن يكون التركيزان صغيرين معًا.","حاصل الضرب 1.0 × 10⁻¹⁵ لا 1.0 × 10⁻¹⁴؛ مجموع الأسين يجب أن يكون −14."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.655Z"}'::jsonb),
('mcq', 6, 3, 'أيونات OH⁻ المضافة تتفاعل مع H⁺ لتكوين الماء فيقل [H⁺]، فيعمل النظام على تعويض النقص بإزاحة الاتزان نحو اليمين (تأين مزيد من الحمض)، لكن [H⁺] يبقى أقل مما كان عليه قبل الإضافة.', '["OH⁻ يستهلك H⁺ فيقل تركيزه، والنقص في أحد النواتج يزيح الاتزان نحو اليمين لا اليسار.","الحمض الضعيف في حالة اتزان، فيتأثر بإزالة H⁺ منه وفق مبدأ لوتشاتلييه.","نقصان [H⁺] صحيح، لكن إزالة أحد النواتج تزيح الاتزان نحو النواتج (اليمين) لا نحو اليسار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T09:21:20.655Z"}'::jsonb),
('mcq', 7, 1, 'قبل التغيّر: [OH⁻] = 10⁻¹⁴/10⁻⁵ = 1.0 × 10⁻⁹ M، وبعده: [OH⁻] = 10⁻¹⁴/10⁻⁴ = 1.0 × 10⁻¹⁰ M؛ فلبقاء Kw ثابتًا يقل [OH⁻] إلى عُشر قيمته بالضبط عندما يتضاعف [H⁺] عشر مرات.', '["العلاقة بين التركيزين عكسية، فزيادة [H⁺] لا تزيد [OH⁻].","","بقاء [OH⁻] ثابتًا يجعل حاصل الضرب عشرة أضعاف Kw.","النقص يكون بالنسبة نفسها التي زاد بها [H⁺] (عشر مرات) لا إلى النصف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T09:21:20.655Z"}'::jsonb),
('essay', 1, null::int, null, null, 'مبدأ لوتشاتلييه: إذا وقع ضغط (مؤثر) على نظام في حالة اتزان فإن النظام يتجه في الاتجاه الذي يقلل من ذلك الضغط. العلاقة بين [H⁺] و [OH⁻] علاقة عكسية؛ فحاصل ضربهما ثابت يساوي Kw = 1.0 × 10⁻¹⁴ عند 298 K، فإذا زاد أحدهما نقص الآخر. ويتساوى التركيزان في الماء النقي والمحاليل المتعادلة حيث [H⁺] = [OH⁻] = 1.0 × 10⁻⁷ M.', '["نص مبدأ لوتشاتلييه","العلاقة عكسية","حاصل الضرب ثابت = 1.0 × 10⁻¹⁴","يتساويان عند 1.0 × 10⁻⁷ M"]'::jsonb, '[]'::jsonb, '[{"element":"نص مبدأ لوتشاتلييه","marks":1},{"element":"وصف العلاقة العكسية مع ذكر ثبات حاصل الضرب","marks":2},{"element":"قيمة التركيزين عند التساوي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"النص والعلاقة والتعليل بثبات Kw وقيمة التساوي كلها صحيحة"},{"level":"2–3 درجات","description":"وصف العلاقة صحيح مع نقص النص أو قيمة التساوي"},{"level":"1 درجة","description":"ذكر أن العلاقة عكسية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف العلاقة بأنها طردية","القول إن مجموع التركيزين ثابت","ذكر 1.0 × 10⁻¹⁴ M قيمةً لكل تركيز عند التساوي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.656Z"}'::jsonb),
('essay', 2, null::int, null, null, 'وجه الشبه: في لعبة التوازن عندما يرتفع أحد طرفي العارضة يهبط الطرف الآخر، وقد تتوازن العارضة في الوسط؛ وكذلك عندما يزداد [H⁺] يقل [OH⁻] والعكس، ويتساويان في المحلول المتعادل (نقطة الوسط). عند إضافة OH⁻ إلى الماء النقي يضطرب الاتزان H₂O ⇌ H⁺ + OH⁻، فيتجه النظام إلى تقليل أثر الزيادة، فتتفاعل أيونات OH⁻ المضافة مع أيونات H⁺ لتكوين جزيئات ماء، فيقل [H⁺] عن 1.0 × 10⁻⁷ M، ويبقى حاصل الضرب [H⁺][OH⁻] ثابتًا مساويًا 1.0 × 10⁻¹⁴ عند 298 K.', '["ارتفاع طرف يقابله هبوط الآخر = زيادة تركيز يقابلها نقص الآخر","التوازن في الوسط = المحلول المتعادل","OH⁻ المضاف يتفاعل مع H⁺ لتكوين الماء","يقل [H⁺] ويبقى Kw ثابتًا"]'::jsonb, '[]'::jsonb, '[{"element":"وجه الشبه (الطرفان والوسط)","marks":2},{"element":"التفسير بمبدأ لوتشاتلييه (تكوّن الماء)","marks":2},{"element":"نقصان [H⁺] مع ثبات Kw","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وجه شبه كامل وتفسير صحيح يذكر تكوّن الماء وثبات Kw"},{"level":"3–4 درجات","description":"وجه شبه صحيح مع تفسير ناقص، أو تفسير كامل مع وجه شبه ناقص"},{"level":"1–2 درجة","description":"ذكر أن [H⁺] يقل دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن [H⁺] لا يتغير لأن القاعدة لا تحتوي على H⁺","القول إن Kw يزداد بإضافة القاعدة","الاكتفاء بالتشبيه دون ربطه بالاتزان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.656Z"}'::jsonb),
('essay', 3, null::int, null, null, 'معادلة الاتزان: CH₃COOH(aq) ⇌ H⁺(aq) + CH₃COO⁻(aq). أيونات OH⁻ المضافة من NaOH تتفاعل مع أيونات H⁺ لتكوين الماء (H⁺ + OH⁻ → H₂O)، فيقل [H⁺]. هذا النقص في أحد النواتج يضطرب له الاتزان، فيتجه النظام وفق مبدأ لوتشاتلييه إلى تعويضه بإزاحة الاتزان نحو اليمين (يتأين مزيد من الحمض)، غير أن التعويض جزئي فيبقى [H⁺] أقل مما كان عليه. ولأن [H⁺] قلّ فإن [OH⁻] يزداد، إذ يبقى حاصل الضرب [H⁺][OH⁻] مساويًا Kw = 1.0 × 10⁻¹⁴ عند 298 K، لأن Kw ثابت اتزان لا يتغير بتغير التراكيز عند درجة الحرارة نفسها.', '["معادلة اتزان تأين الحمض","تفاعل OH⁻ مع H⁺ لتكوين الماء ونقص [H⁺]","إزاحة الاتزان نحو اليمين وتعويض جزئي","زيادة [OH⁻]","ثبات Kw عند درجة الحرارة نفسها"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة الاتزان","marks":1},{"element":"نقص [H⁺] بتفاعله مع OH⁻","marks":1},{"element":"إزاحة الاتزان نحو اليمين مع التعليل","marks":2},{"element":"زيادة [OH⁻] وثبات Kw","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تحليل كامل: المعادلة، نقص H⁺، اتجاه الإزاحة، زيادة OH⁻، ثبات Kw"},{"level":"4–5 درجات","description":"تحليل صحيح ينقصه عنصر واحد"},{"level":"2–3 درجات","description":"المعادلة ونقص [H⁺] فقط، أو اتجاه إزاحة خاطئ مع بقية صحيحة"},{"level":"1 درجة","description":"المعادلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إزاحة الاتزان نحو اليسار","القول إن [H⁺] يعود إلى قيمته الأصلية تمامًا","القول إن Kw يتغير بإضافة القاعدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T09:21:20.656Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L3-O06') and x.type = v.type and x.number = v.number
