insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L3-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'كيف يُعرَّف الرقم الهيدروجيني pH لمحلول ما؟', null, '["لوغاريتم تركيز أيون الهيدروجين موجب الإشارة","سالب لوغاريتم تركيز أيون الهيدروجين","سالب لوغاريتم تركيز أيون الهيدروكسيد","مقلوب تركيز أيون الهيدروجين"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 74 — الرقم الهيدروجيني pH'),
('mcq', 2, 'أيّ العبارات الآتية تعرّف الرقم الهيدروكسيدي pOH لمحلول ما؟', null, '["سالب لوغاريتم تركيز أيون الهيدروجين","تركيز أيون الهيدروكسيد مضروبًا في 14","سالب لوغاريتم تركيز أيون الهيدروكسيد","الفرق بين Kw وتركيز أيون الهيدروجين"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 74 — الرقم الهيدروكسيدي pOH'),
('mcq', 3, 'ما قيمة مجموع pH و pOH لأي محلول مائي مخفف عند درجة حرارة 298 K؟', null, '["يساوي 7.00","يساوي 1.0 × 10⁻¹⁴","يساوي 10.00","يساوي 14.00"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 74 — العلاقة بين pH و pOH'),
('mcq', 4, 'لماذا يفضّل الكيميائيون التعبير عن تراكيز أيونات الهيدروجين بالرقم الهيدروجيني pH بدلًا من التركيز المولاري؟', null, '["لأن تراكيز H⁺ غالبًا أرقام صغيرة يصعب استعمالها، ويبسّطها تدريج لوغاريتمي","لأن pH تعطي عدد مولات H⁺ مباشرة في اللتر","لأن تراكيز H⁺ دائمًا أكبر من 1 M ويصعب كتابتها","لأن pH لا تتأثر بتغيّر تركيز H⁺ في المحلول"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 74 — ما الرقم الهيدروجيني pH؟'),
('mcq', 5, 'ماذا تعني الطبيعة اللوغاريتمية لتدريج pH عندما تتغير قيمة pH لمحلول بمقدار وحدة واحدة؟', null, '["يتغير [H⁺] بمقدار 1 mol/L","يتغير [H⁺] بمقدار 10 مرات","يتغير [H⁺] بمقدار مرتين","يتغير [H⁺] بمقدار 14 مرة"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'متوسط', 'الكتاب ص 74 — الطبيعة اللوغاريتمية لتدريج pH'),
('mcq', 6, 'ما قيمة pH لمحلول مائي تركيز أيون الهيدروجين فيه 1.0 × 10⁻⁷ M عند 298 K، وما قيمة pOH له؟', null, '["pH = 7.00 و pOH = 7.00","pH = 7.00 و pOH = 14.00","pH = 14.00 و pOH = 7.00","pH = 1.0 و pOH = 13.0"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 75 — المثال 2-2'),
('mcq', 7, 'قارن بين قيمتي pH و pOH لمحلول حمضي عند 298 K، أيّ العبارات الآتية صحيحة؟', null, '["pH أقل من 7 و pOH أقل من 7","pH أكبر من 7 و pOH أقل من 7","pH أقل من 7 و pOH أكبر من 7","pH أكبر من 7 و pOH أكبر من 7"]'::jsonb, 'فهم', 'فهم علاقة', 'صعب', 'الكتاب ص 74 و 80 — قيم pH و pOH للمحاليل'),
('essay', 1, 'عرّف كلًّا من الرقم الهيدروجيني pH والرقم الهيدروكسيدي pOH، واكتب المعادلة الرياضية لكل منهما، ثم اكتب العلاقة التي تربط بينهما عند 298 K.', null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 74 — الرقم الهيدروجيني pH والرقم الهيدروكسيدي pOH'),
('essay', 2, 'فسّر لماذا استخدم الكيميائيون الرقم الهيدروجيني pH للتعبير عن تركيز أيونات الهيدروجين، ثم وضّح معنى كون تدريج pH لوغاريتميًّا بمقارنة محلولين قيمة pH لهما 3 و 4 عند 298 K.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 74 — ما الرقم الهيدروجيني pH؟'),
('essay', 3, 'محلول مائي تركيز أيون الهيدروجين فيه [H⁺] = 1.0 × 10⁻⁷ M، ومحلول آخر قيمة pOH له 2.00 عند 298 K. اشرح كيف تستعمل تعريفي pH و pOH والعلاقة بينهما لتحديد pH ولتصنيف كلٍّ من المحلولين (حمضي، متعادل، قاعدي)، ثم قارن بين المحلولين في تركيز H⁺.', null, null, 'تطبيق', 'تطبيق وتصنيف', 'صعب', 'الكتاب ص 74–75 — pH و pOH والمثال 2-2')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
