insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الرقم الهيدروجيني لمحلول ما هو سالب لوغاريتم تركيز أيون الهيدروجين: pH = −log[H⁺].', '["أُهملت إشارة السالب؛ فيعطي قيمًا سالبة للمحاليل التي تراكيز H⁺ فيها أقل من 1 M.","","هذا تعريف الرقم الهيدروكسيدي pOH لا pH.","المقلوب (1/[H⁺]) ليس هو اللوغاريتم؛ فتعريف pH مبني على اللوغاريتم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.657Z"}'::jsonb),
('mcq', 2, 2, 'الرقم الهيدروكسيدي pOH لمحلول ما هو سالب لوغاريتم تركيز أيون الهيدروكسيد: pOH = −log[OH⁻].', '["هذا تعريف pH لا pOH.","لا علاقة لـ pOH بضرب التركيز في 14؛ فالعدد 14 هو مجموع pH و pOH.","","pOH لا تُعرَّف بطرح تركيز من Kw، بل بسالب لوغاريتم [OH⁻]."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.657Z"}'::jsonb),
('mcq', 3, 3, 'مجموع pH و pOH يساوي 14.00 عند 298 K؛ لأن Kw = [H⁺][OH⁻] = 1.0 × 10⁻¹⁴ وسالب لوغاريتم حاصل الضرب يساوي pH + pOH = 14.00.', '["7.00 هي قيمة كل من pH و pOH في المحلول المتعادل فقط، وليست مجموعهما.","هذه قيمة Kw وهي حاصل ضرب التركيزين لا مجموع الرقمين.","لا تدعم أي علاقة في الكتاب هذا العدد؛ المجموع ثابت يساوي 14.00.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T09:21:20.657Z"}'::jsonb),
('mcq', 4, 0, 'تراكيز أيونات الهيدروجين غالبًا أرقام صغيرة يصعب استعمالها، لذا ابتكر الكيميائيون الرقم الهيدروجيني المبني على اللوغاريتمات طريقةً أسهل للتعبير عنها.', '["","pH لا تعطي عدد المولات؛ إنها دالة لوغاريتمية لتركيز H⁺ ولا تحمل وحدة.","تراكيز H⁺ في المحاليل المخففة صغيرة جدًّا (أقل من 1 M غالبًا) وليست أكبر من 1.","pH تتغير بتغيّر [H⁺]؛ فتغيّر وحدة واحدة فيها يعني تغيّرًا 10 مرات في [H⁺]."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.657Z"}'::jsonb),
('mcq', 5, 1, 'تغير وحدة واحدة في تدريج pH يمثل تغيرًا مقداره 10 مرات في تركيز الأيون؛ فمحلول pH له 3 تركيز H⁺ فيه عشرة أضعاف محلول pH له 4.', '["التغير نسبي (10 مرات) لا فرق ثابت بالمول لكل لتر.","","التدريج بالأساس 10 لا 2؛ فالتغير عشرة أضعاف.","العدد 14 هو مجموع pH و pOH وليس معامل التغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.657Z"}'::jsonb),
('mcq', 6, 0, 'pH = −log(1.0 × 10⁻⁷) = 7.00، و pOH = 14.00 − 7.00 = 7.00؛ فالمحلول متعادل لأن [H⁺] = [OH⁻].', '["","pOH = 14.00 − 7.00 = 7.00 وليست 14.00؛ فلا يكون المجموع 14.00 بهذه القيم.","pH = 7.00 لا 14.00؛ فقيمة pH تساوي −log(10⁻⁷).","أخذ المعامل 1.0 قيمة لـ pH وأهمل الأس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T09:21:20.657Z"}'::jsonb),
('mcq', 7, 2, 'قيم pH للمحاليل الحمضية أقل من 7، وبما أن pH + pOH = 14.00 فإن قيمة pOH أكبر من 7؛ فقيمة pH للمحلول الحمضي أصغر دائمًا من pOH للمحلول نفسه.', '["لا يمكن أن تكون القيمتان معًا أقل من 7 لأن مجموعهما 14.00.","هذا وصف لمحلول قاعدي لا حمضي.","","لا يمكن أن تكون القيمتان معًا أكبر من 7 لأن مجموعهما 14.00."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.658Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الرقم الهيدروجيني pH لمحلول ما هو سالب لوغاريتم تركيز أيون الهيدروجين: pH = −log[H⁺]. الرقم الهيدروكسيدي pOH لمحلول ما هو سالب لوغاريتم تركيز أيون الهيدروكسيد: pOH = −log[OH⁻]. العلاقة بينهما عند 298 K: pH + pOH = 14.00.', '["تعريف pH (سالب لوغاريتم [H⁺])","pH = −log[H⁺]","تعريف pOH (سالب لوغاريتم [OH⁻])","pOH = −log[OH⁻]","pH + pOH = 14.00"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف pH مع معادلته","marks":1.5},{"element":"تعريف pOH مع معادلته","marks":1.5},{"element":"العلاقة pH + pOH = 14.00","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان ومعادلتان والعلاقة كلها صحيحة"},{"level":"3 درجات","description":"التعريفان صحيحان مع نقص العلاقة، أو العكس مع نقص بسيط"},{"level":"1–2 درجة","description":"تعريف واحد صحيح أو العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة pH = log[H⁺] بإهمال الإشارة السالبة","الخلط بين pH و pOH في التعريفين","كتابة pH × pOH = 14"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.658Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تراكيز أيونات الهيدروجين غالبًا أرقام صغيرة يصعب استعمالها، لذا استعمل الكيميائيون تدريج pH المبني على اللوغاريتمات؛ إذ pH = −log[H⁺] وهو يحوّل الأسس الصغيرة إلى أرقام صغيرة سهلة (مثل 10⁻³ ← 3). ومعنى أن التدريج لوغاريتمي أن تغيّر وحدة واحدة في pH يمثّل تغيرًا مقداره 10 مرات في [H⁺]. فالمحلول الذي pH له 3 ([H⁺] = 1 × 10⁻³ M) تركيز H⁺ فيه عشرة أضعاف تركيزه في المحلول الذي pH له 4 ([H⁺] = 1 × 10⁻⁴ M).', '["تراكيز H⁺ صغيرة يصعب استعمالها","pH تدريج لوغاريتمي يسهّل التعبير","وحدة pH واحدة = 10 مرات في [H⁺]","[H⁺] في pH = 3 عشرة أضعافه في pH = 4"]'::jsonb, '[]'::jsonb, '[{"element":"سبب استعمال pH","marks":1},{"element":"معنى التدريج اللوغاريتمي (10 مرات لكل وحدة)","marks":2},{"element":"المقارنة بين pH = 3 و pH = 4 بالتركيز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"سبب صحيح ومعنى لوغاريتمي صحيح ومقارنة صحيحة"},{"level":"2–3 درجات","description":"عنصران صحيحان"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الفرق بين المحلولين 1 mol/L","عكس المقارنة (جعل pH = 4 أعلى تركيزًا)","القول إن التغيير مرتان لا 10 مرات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.658Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المحلول الأول: pH = −log(1.0 × 10⁻⁷) = 7.00، و pOH = 14.00 − 7.00 = 7.00، فهو متعادل. المحلول الثاني: pH = 14.00 − pOH = 14.00 − 2.00 = 12.00، وهي أكبر من 7 فهو قاعدي، و [H⁺] = 10^−12.00 = 1.0 × 10⁻¹² M. المقارنة: [H⁺] في المحلول الأول (1.0 × 10⁻⁷ M) أكبر من [H⁺] في الثاني (1.0 × 10⁻¹² M) بمقدار 10⁵ = 100000 مرة؛ لأن الفرق بين قيمتي pH هو 5 وحدات، وكل وحدة تمثل 10 مرات.', '["الأول pH = 7.00 متعادل","الثاني pH = 12.00 قاعدي","استعمال pH + pOH = 14.00","[H⁺] في الثاني = 1.0 × 10⁻¹² M","النسبة 10⁵ مرة"]'::jsonb, '["الأول: pH = −log(1.0 × 10⁻⁷) = 7.00 ⇒ متعادل","الثاني: pH = 14.00 − 2.00 = 12.00 ⇒ قاعدي","[H⁺] = 10^−12.00 = 1.0 × 10⁻¹² M","النسبة = (1.0 × 10⁻⁷)/(1.0 × 10⁻¹²) = 10⁵"]'::jsonb, '[{"element":"pH وتصنيف المحلول الأول","marks":1},{"element":"pH وتصنيف المحلول الثاني باستعمال pH + pOH = 14.00","marks":2},{"element":"تركيز H⁺ في الثاني","marks":1},{"element":"المقارنة بين التركيزين (10⁵ مرة)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"كل الحسابات والتصنيفات والمقارنة صحيحة"},{"level":"3–4 درجات","description":"خطأ واحد أو نقص في المقارنة"},{"level":"1–2 درجة","description":"تصنيف أحد المحلولين صحيحًا بحساب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ pOH = 2.00 قيمة pH فيُصنَّف المحلول حمضيًا","حساب النسبة بين القيمتين 12/7","الخلط بين النسبة 10⁵ والفرق 5"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T09:21:20.658Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
