('mcq', 1, 'ما قيمة pH لمحلول حمض الهيدروكلوريك HCl تركيزه 0.010 M عند 298 K؟', null, '["12.00","0.010","2.00","1.00"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 78 — المولارية والرقم الهيدروجيني للأحماض القوية'),
('mcq', 2, 'محلول هيدروكسيد الصوديوم NaOH تركيزه 0.050 M عند 298 K. ما قيمتا pOH و pH له؟', null, '["pOH = 12.70، pH = 1.30","pOH = 1.30، pH = 1.30","pOH = 0.050، pH = 13.95","pOH = 1.30، pH = 12.70"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 78 — المولارية والرقم الهيدروجيني للقواعد القوية'),
('mcq', 3, 'ما قيمة pH لمحلول هيدروكسيد الكالسيوم Ca(OH)₂ تركيزه 7.5 × 10⁻⁴ M عند 298 K؟', null, '["10.88","11.18","3.12","2.82"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 78 — Ca(OH)₂ والمولارية'),
('mcq', 4, 'لماذا يمكن حساب [H⁺] لمحلول حمض الهيدروكلوريك مباشرة من مولاريته، في حين لا يمكن ذلك لمحلول حمض ضعيف مثل HF بالتركيز نفسه؟', null, '["لأن HF يحتوي على عدد أكبر من البروتونات القابلة للتأين","لأن HCl يتأين كليًّا فتساوي [H⁺] مولارية الحمض، أما HF فيتأين جزئيًّا","لأن HCl يتأين جزئيًّا بنسبة ثابتة تساوي 50%","لأن HF لا يتأين مطلقًا في الماء"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 78 — ماذا قرأت؟ المولارية والرقم الهيدروجيني'),
('mcq', 5, 'ما قيمة pH لمحلول هيدروكسيد المغنيسيوم Mg(OH)₂ تركيزه 2.4 × 10⁻⁵ M عند 298 K علمًا بأنه قاعدة قوية؟', null, '["9.68","4.62","9.38","4.32"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 78 و 80 — تمرين 40 (Mg(OH)₂)'),
('mcq', 6, 'أُذيب 1.0 × 10⁻³ mol من HCl في ماء ليكون 5.0 L من المحلول عند 298 K. ما قيمة pH للمحلول الناتج؟', null, '["3.00","2.30","3.70","10.30"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 76 — المسألة 28'),
('mcq', 7, 'محلولان تركيز كلٍّ منهما 0.0050 M عند 298 K: الأول NaOH والثاني Ba(OH)₂ (قاعدة قوية). أيّ العبارات الآتية صحيحة؟', null, '["pH للمحلولين متساويتان لأن المولارية واحدة","pH لمحلول NaOH أكبر لأنه أقوى قاعدية","pH لمحلول Ba(OH)₂ أكبر لأن [OH⁻] فيه ضعف [OH⁻] في NaOH","pOH لمحلول Ba(OH)₂ أكبر من pOH لمحلول NaOH"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 78 — المولارية والرقم الهيدروجيني للقواعد القوية'),
('essay', 1, 'احسب pH و pOH لكلٍّ من: (a) محلول HI تركيزه 0.0020 M، (b) محلول KOH تركيزه 0.040 M، عند 298 K، موضحًا لماذا يمكن اعتبار تركيز الأيونات مساويًا للمولارية.', null, null, 'تطبيق', 'حساب بخطوات', 'سهل', 'الكتاب ص 78 و 80 — تمارين 40 و 41'),
('essay', 2, 'احسب pH و pOH لمحلول هيدروكسيد الكالسيوم Ca(OH)₂ تركيزه 6.0 × 10⁻³ M عند 298 K، ثم احسب [H⁺] فيه. وضّح لماذا لا يساوي [OH⁻] مولارية المحلول.', null, null, 'تطبيق', 'حساب بخطوات', 'متوسط', 'الكتاب ص 78 — Ca(OH)₂ والمولارية'),
('essay', 3, 'حسب طالب pH لمحلول Ba(OH)₂ تركيزه 0.020 M عند 298 K بهذه الخطوات: «pH = −log(0.020) = 1.70، إذن المحلول حمضي». قوّم حل الطالب، وحدّد خطأيه، ثم اكتب الحل الصحيح مبيّنًا طبيعة المحلول.', null, null, 'تقويم', 'تقويم حل', 'صعب', 'الكتاب ص 78 — المولارية والرقم الهيدروجيني للقواعد القوية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
