from (values
('mcq', 1, 2, 'HCl حمض قوي أحادي البروتون يتأين كليًّا، فـ [H⁺] = 0.010 M = 1.0 × 10⁻² M، و pH = −log(1.0 × 10⁻²) = 2.00.', '["12.00 هي قيمة pOH لهذا المحلول (14.00 − 2.00)، وقد أُخذت بدلًا من pH.","هذا هو التركيز نفسه، ولم يُحسب سالب اللوغاريتم له.","","قيمة 1.00 تناسب تركيزًا 0.10 M لا 0.010 M؛ أي خطأ في الأس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.659Z"}'::jsonb),
('mcq', 2, 3, 'NaOH قاعدة قوية تنتج أيون OH⁻ واحدًا لكل وحدة صيغة، فـ [OH⁻] = 0.050 M، و pOH = −log(0.050) = 1.30، و pH = 14.00 − 1.30 = 12.70.', '["تبادلت القيمتان؛ ففي القاعدة pOH هي الصغرى و pH هي الكبرى.","نسي أن pH = 14.00 − pOH فكرر القيمة نفسها.","أخذ التركيز نفسه قيمةً لـ pOH ثم طرحه من 14.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T09:21:20.659Z"}'::jsonb),
('mcq', 3, 1, 'Ca(OH)₂ قاعدة قوية تنتج أيوني OH⁻ لكل وحدة صيغة، فـ [OH⁻] = 2 × 7.5 × 10⁻⁴ = 1.5 × 10⁻³ M، و pOH = 2.82، و pH = 14.00 − 2.82 = 11.18.', '["استعمل [OH⁻] = 7.5 × 10⁻⁴ M دون مضاعفته: pOH = 3.12 و pH = 10.88.","","هذه pOH لتركيز 7.5 × 10⁻⁴ M دون مضاعفة، وليست pH.","هذه قيمة pOH الصحيحة، لا قيمة pH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-17T09:21:20.659Z"}'::jsonb),
('mcq', 4, 1, 'الأحماض القوية تتأين كليًّا، فكل جزيء HCl ينتج أيون H⁺ واحدًا فيساوي [H⁺] مولارية الحمض؛ أما الأحماض الضعيفة فتتأين جزئيًّا فقط، فنستعمل Ka لتحديد [H⁺].', '["HF حمض أحادي البروتون أيضًا؛ والفرق في درجة التأين لا في عدد البروتونات.","","HCl يتأين بنسبة 100% لا 50%.","HF يتأين جزئيًّا بدرجة ضئيلة؛ فهو ليس عديم التأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.659Z"}'::jsonb),
('mcq', 5, 0, '[OH⁻] = 2 × 2.4 × 10⁻⁵ = 4.8 × 10⁻⁵ M، و pOH = −log(4.8 × 10⁻⁵) = 4.32، و pH = 14.00 − 4.32 = 9.68.', '["","هذه pOH لتركيز 2.4 × 10⁻⁵ M دون مضاعفة، وليست pH.","استعمل [OH⁻] = 2.4 × 10⁻⁵ M دون مضاعفة: pOH = 4.62 و pH = 9.38.","هذه قيمة pOH الصحيحة لا pH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-10-17T09:21:20.660Z"}'::jsonb),
('mcq', 6, 2, 'المولارية = 1.0 × 10⁻³ mol ÷ 5.0 L = 2.0 × 10⁻⁴ M، وهي تساوي [H⁺] لأن HCl حمض قوي؛ فـ pH = −log(2.0 × 10⁻⁴) = 3.70.', '["أهمل القسمة على الحجم فاستعمل 1.0 × 10⁻³ mol مباشرة كأنها تركيز.","ضرب في 5.0 بدلًا من القسمة: 5.0 × 10⁻³ M ⇒ pH = 2.30.","","هذه pOH للمحلول (14.00 − 3.70)، لا pH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T09:21:20.660Z"}'::jsonb),
('mcq', 7, 2, 'في NaOH: [OH⁻] = 0.0050 M ⇒ pOH = 2.30 و pH = 11.70. وفي Ba(OH)₂: [OH⁻] = 2 × 0.0050 = 0.010 M ⇒ pOH = 2.00 و pH = 12.00. فـ pH لمحلول Ba(OH)₂ أكبر.', '["المولارية المتساوية لا تعني تساوي [OH⁻]؛ فكل وحدة Ba(OH)₂ تنتج أيوني OH⁻.","كلتاهما قاعدة قوية تتأين كليًّا؛ والفرق في عدد أيونات OH⁻ لكل وحدة صيغة.","","pOH لمحلول Ba(OH)₂ تساوي 2.00 وهي أصغر من pOH لمحلول NaOH (2.30)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.660Z"}'::jsonb),
('essay', 1, null::int, null, null, 'HI حمض قوي أحادي البروتون وKOH قاعدة قوية أحادية الهيدروكسيد؛ كلاهما يتأين كليًّا (100%)، فتساوي [H⁺] مولارية HI، و [OH⁻] مولارية KOH. (a) [H⁺] = 0.0020 M، pH = −log(2.0 × 10⁻³) = 2.70، pOH = 14.00 − 2.70 = 11.30. (b) [OH⁻] = 0.040 M، pOH = −log(4.0 × 10⁻²) = 1.40، pH = 14.00 − 1.40 = 12.60.', '["التعليل: تأين كلي لحمض وقاعدة قويين","(a) pH = 2.70 و pOH = 11.30","(b) pOH = 1.40 و pH = 12.60"]'::jsonb, '["(a) [H⁺] = 0.0020 M ⇒ pH = −log(0.0020) = 2.70","(a) pOH = 14.00 − 2.70 = 11.30","(b) [OH⁻] = 0.040 M ⇒ pOH = −log(0.040) = 1.40","(b) pH = 14.00 − 1.40 = 12.60"]'::jsonb, '[{"element":"التعليل بالتأين الكلي","marks":1},{"element":"pH و pOH للمحلول (a)","marks":2},{"element":"pOH و pH للمحلول (b)","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"التعليل والقيم الأربع صحيحة"},{"level":"3–4 درجات","description":"قيمتان أو ثلاث صحيحة مع التعليل أو دونه"},{"level":"1–2 درجة","description":"قيمة واحدة صحيحة أو التعليل فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب pH للقاعدة بأخذ −log[OH⁻] مباشرة","الخلط بين pH و pOH","إهمال خطوة pH + pOH = 14.00"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.660Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Ca(OH)₂ قاعدة قوية تتأين كليًّا: Ca(OH)₂ → Ca²⁺ + 2OH⁻، فتنتج كل وحدة صيغة أيوني هيدروكسيد، ولذا [OH⁻] ضعف المولارية: [OH⁻] = 2 × 6.0 × 10⁻³ = 1.2 × 10⁻² M. pOH = −log(1.2 × 10⁻²) = 1.92، و pH = 14.00 − 1.92 = 12.08. [H⁺] = 10^−12.08 = 8.3 × 10⁻¹³ M.', '["Ca(OH)₂ ينتج أيوني OH⁻","[OH⁻] = 1.2 × 10⁻² M","pOH = 1.92","pH = 12.08","[H⁺] = 8.3 × 10⁻¹³ M"]'::jsonb, '["Ca(OH)₂ → Ca²⁺ + 2OH⁻","[OH⁻] = 2 × 6.0 × 10⁻³ = 1.2 × 10⁻² M","pOH = −log(1.2 × 10⁻²) = 1.92","pH = 14.00 − 1.92 = 12.08","[H⁺] = 10^−12.08 = 8.3 × 10⁻¹³ M"]'::jsonb, '[{"element":"المعادلة وتعليل مضاعفة [OH⁻]","marks":1.5},{"element":"[OH⁻] و pOH","marks":1.5},{"element":"pH","marks":1},{"element":"[H⁺]","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التعليل والقيم كلها صحيحة"},{"level":"3–4 درجات","description":"خطأ واحد في آخر الحل أو نقص في التعليل"},{"level":"1–2 درجة","description":"حل دون مضاعفة [OH⁻] (يعطي pH = 11.78) أو قيمة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم مضاعفة [OH⁻] فيحصل على pH = 11.78","أخذ −log للتركيز ثم عدّه pH","كتابة معادلة التأين دون المعامل 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-10-17T09:21:20.661Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطأ الأول: الطالب حسب −log لتركيز القاعدة نفسها وعدّه pH، بينما −log[OH⁻] هي pOH لا pH، ولم يستعمل pH + pOH = 14.00. الخطأ الثاني: أهمل أن Ba(OH)₂ قاعدة قوية تنتج أيوني OH⁻ لكل وحدة صيغة، فـ [OH⁻] ضعف المولارية. الحل الصحيح: Ba(OH)₂ → Ba²⁺ + 2OH⁻؛ [OH⁻] = 2 × 0.020 = 0.040 M؛ pOH = −log(0.040) = 1.40؛ pH = 14.00 − 1.40 = 12.60. المحلول قاعدي لأن pH أكبر من 7، وهذا يتفق مع كون المادة قاعدة قوية.', '["الخطأ 1: خلط pOH بـ pH","الخطأ 2: إهمال أيوني OH⁻","[OH⁻] = 0.040 M","pOH = 1.40 و pH = 12.60","المحلول قاعدي"]'::jsonb, '["Ba(OH)₂ → Ba²⁺ + 2OH⁻","[OH⁻] = 2 × 0.020 = 0.040 M","pOH = −log(0.040) = 1.40","pH = 14.00 − 1.40 = 12.60"]'::jsonb, '[{"element":"تحديد خطأ الخلط بين pOH و pH","marks":1},{"element":"تحديد إهمال أيوني OH⁻","marks":1},{"element":"الحل الصحيح للقيم","marks":2},{"element":"الحكم بالقاعدية مع التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الخطآن محدّدان والحل صحيح والحكم صحيح"},{"level":"3–4 درجات","description":"خطأ واحد محدد مع حل صحيح، أو الخطآن دون حل كامل"},{"level":"1–2 درجة","description":"حل صحيح فقط دون تقويم أو تقويم جزئي"},{"level":"صفر","description":"تأييد حل الطالب أو لا إجابة"}]'::jsonb, '["تأييد النتيجة 1.70 لأن حساب اللوغاريتم صحيح","تصحيح الخطأ الأول فقط فيحصل على pH = 12.30","عدّ المحلول حمضيًا لأن pH أصغر من pOH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.661Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
