insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L3-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'قيمة pH لمحلول الحمض الضعيف HA الذي تركيزه الابتدائي 0.200 M تساوي 2.00 عند 298 K. ما قيمة Ka للحمض؟', null, '["5.0 × 10⁻⁴","1.0 × 10⁻⁴","5.3 × 10⁻²","5.3 × 10⁻⁴"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 78–79 — حساب Ka من الرقم الهيدروجيني، المثال 2-5'),
('mcq', 2, 'عند حساب Ka لحمض ضعيف أحادي البروتون HA من قيمة pH ومن تركيزه الابتدائي، كيف يُحسب تركيز HA غير المتأين عند الاتزان؟', null, '["يساوي [H⁺] الناتج من قيمة pH","يساوي التركيز الابتدائي مضافًا إليه [H⁺]","يساوي التركيز الابتدائي مطروحًا منه [H⁺]","يساوي التركيز الابتدائي نفسه دون تغيير"]'::jsonb, 'فهم', 'فهم إجراء', 'سهل', 'الكتاب ص 78 — حساب Ka من الرقم الهيدروجيني'),
('mcq', 3, 'محلول الحمض الضعيف HX تركيزه الابتدائي 0.0100 M وقيمة pH له 2.80 عند 298 K. ما قيمة Ka لهذا الحمض؟', null, '["3.0 × 10⁻⁴","2.5 × 10⁻⁴","2.5 × 10⁻⁶","1.6 × 10⁻¹"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 78–79 — المثال 2-5'),
('mcq', 4, 'محلول حمض ضعيف HA تركيزه الابتدائي 0.0500 M وقيمة pH له 2.00. ما تركيز HA وتركيز A⁻ عند الاتزان؟', null, '["[HA] = 0.0500 M و [A⁻] = 0.0100 M","[HA] = 0.0400 M و [A⁻] = 0.0400 M","[HA] = 0.0400 M و [A⁻] = 0.0100 M","[HA] = 0.0600 M و [A⁻] = 0.0100 M"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 78 — حساب Ka من الرقم الهيدروجيني (مثال HF)'),
('mcq', 5, 'محلول حمض ضعيف HA تركيزه الابتدائي 0.0200 M وقيمة pOH له 11.00 عند 298 K. ما قيمة Ka للحمض؟', null, '["5.3 × 10⁻⁵","5.0 × 10⁻²¹","5.0 × 10⁻²","5.0 × 10⁻⁵"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 79 — التمرين 32 (حساب Ka من pOH)'),
('mcq', 6, 'يبيّن الجدول التركيز الابتدائي وقيمة pH لأربعة محاليل أحماض ضعيفة أحادية البروتون عند 298 K. أيّ هذه الأحماض له أكبر قيمة Ka؟', '{"headers":["الحمض","التركيز الابتدائي (M)","pH"],"rows":[["A","0.100","3.00"],["B","0.0200","3.00"],["C","0.0500","2.00"],["D","0.200","2.00"]]}'::jsonb, '["الحمض A","الحمض B","الحمض D","الحمض C"]'::jsonb, 'تحليل', 'مقارنة بيانات', 'صعب', 'الكتاب ص 78–79 — حساب Ka من الرقم الهيدروجيني'),
('mcq', 7, 'محلول حمض HA تركيزه 0.100 M وقيمة pH له 3.00. قال طالب: «الحمض قوي لأن pH صغيرة». أيّ العبارات الآتية تقوّم قوله تقويمًا صحيحًا؟', null, '["صحيح؛ لأن pH أقل من 7 تعني حمضًا قويًّا","خطأ؛ لأن [H⁺] = 1.0 × 10⁻³ M أقل كثيرًا من 0.100 M، فالتأين جزئي","خطأ؛ لأن الحمض الضعيف لا يعطي pH أقل من 7 أبدًا","صحيح؛ لأن الحمض القوي يعطي pH = 3.00 دائمًا"]'::jsonb, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 78 — المولارية و pH للأحماض القوية والضعيفة'),
('essay', 1, 'محلول حمض ضعيف HX تركيزه الابتدائي 0.150 M وقيمة pH له 2.70 عند 298 K. احسب ثابت تأين الحمض Ka موضحًا الخطوات.', null, null, 'تطبيق', 'حساب بخطوات', 'متوسط', 'الكتاب ص 78–79 — المثال 2-5'),
('essay', 2, 'محلول حمض ضعيف أحادي البروتون HA تركيزه الابتدائي 0.0300 M، وقيمة pOH له 11.40 عند 298 K. احسب Ka للحمض، موضحًا كيف تحصل على [H⁺] من pOH.', null, null, 'تطبيق', 'حساب بخطوات', 'متوسط', 'الكتاب ص 79 — التمرين 32'),
('essay', 3, 'حسب طالب Ka لمحلول حمض ضعيف HA تركيزه 0.0500 M وقيمة pH له 2.00 بالطريقة: Ka = [H⁺]² / 0.0500 = (0.010)² / 0.0500 = 2.0 × 10⁻³. قوّم طريقة الطالب وناتجه، ثم اكتب الحل الصحيح، وبيّن لماذا يتغير الناتج، وأين يكون هذا التقريب مقبولًا.', null, null, 'تقويم', 'تقويم حل', 'صعب', 'الكتاب ص 78–79 — حساب Ka من الرقم الهيدروجيني')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
