from (values
('mcq', 1, 3, '[H⁺] = 10⁻² = 1.0 × 10⁻² M = [A⁻]، و [HA] = 0.200 − 0.010 = 0.190 M، فـ Ka = (1.0 × 10⁻²)² / 0.190 = 5.3 × 10⁻⁴.', '["لم يطرح [H⁺] من التركيز الابتدائي فقسم على 0.200 بدلًا من 0.190.","استعمل البسط فقط (H⁺ × A⁻) ولم يقسم على [HA].","قسم [H⁺] على [HA] بدلًا من ضرب [H⁺][A⁻] ثم القسمة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-17T09:21:20.661Z"}'::jsonb),
('mcq', 2, 2, 'جزء من الحمض يتأين فيعطي [H⁺] من المول لكل لتر، لذا [HA] عند الاتزان = التركيز الابتدائي − [H⁺].', '["[H⁺] هو تركيز الجزء المتأين لا الباقي غير المتأين.","إضافة [H⁺] خطأ؛ فالتأين يستهلك جزءًا من الحمض لا يزيده.","","هذا تقريب لا يُعتمد في حل الكتاب؛ إذ يطرح [H⁺] من التركيز الابتدائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.662Z"}'::jsonb),
('mcq', 3, 0, '[H⁺] = 10^−2.80 = 1.58 × 10⁻³ M = [X⁻]؛ [HX] = 0.0100 − 0.00158 = 0.0084 M؛ Ka = (1.58 × 10⁻³)² / 0.0084 = 3.0 × 10⁻⁴.', '["","لم يطرح [H⁺] من 0.0100 فقسم على التركيز الابتدائي (فنتج 2.5 × 10⁻⁴).","استعمل مربع [H⁺] دون القسمة على [HX].","قسم [H⁺] على التركيز الابتدائي (1.58 × 10⁻³ / 0.0100) وهذا ليس Ka."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T09:21:20.662Z"}'::jsonb),
('mcq', 4, 2, '[H⁺] = 10⁻² = 0.0100 M، وبما أن معادلة التأين تعطي A⁻ بنسبة 1:1 مع H⁺ فإن [A⁻] = 0.0100 M؛ و [HA] = 0.0500 − 0.0100 = 0.0400 M.', '["أبقى [HA] مساويًا للتركيز الابتدائي ولم يطرح [H⁺].","ساوى [A⁻] بـ [HA] خطأً؛ والمتساوي هو [A⁻] مع [H⁺].","","أضاف [H⁺] إلى التركيز الابتدائي بدلًا من طرحه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-17T09:21:20.662Z"}'::jsonb),
('mcq', 5, 0, 'pH = 14.00 − 11.00 = 3.00، فـ [H⁺] = 1.0 × 10⁻³ M = [A⁻]؛ [HA] = 0.0200 − 0.0010 = 0.0190 M؛ Ka = (1.0 × 10⁻³)² / 0.0190 = 5.3 × 10⁻⁵.', '["","عدّ قيمة pOH هي pH فحسب [H⁺] = 10⁻¹¹ وهو خطأ.","قسم [H⁺] على التركيز الابتدائي (1.0 × 10⁻³ / 0.0200) وهذا ليس Ka.","لم يطرح [H⁺] من التركيز الابتدائي فقسم على 0.0200."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-17T09:21:20.662Z"}'::jsonb),
('mcq', 6, 3, 'Ka = [H⁺]² / (C − [H⁺]): A = 1.0 × 10⁻⁵، و B = 5.3 × 10⁻⁵، و C = 2.5 × 10⁻³، و D = 5.05 × 10⁻⁴. أكبرها C.', '["Ka للحمض A = 1.0 × 10⁻⁵ وهي أصغر القيم.","Ka للحمض B = 5.3 × 10⁻⁵ وهي أصغر كثيرًا من Ka للحمض C.","D له pH مساوية لـ C لكن تركيزه أعلى (0.200 M)، فيتأين نسبة أقل؛ Ka له = 5.05 × 10⁻⁴.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T09:21:20.663Z"}'::jsonb),
('mcq', 7, 1, 'لو كان الحمض قويًّا لكانت [H⁺] = 0.100 M و pH = 1.00. لكن [H⁺] = 10⁻³ M فقط، أي تأين 1% من الحمض، فالتأين جزئي والحمض ضعيف (Ka ≈ 1.0 × 10⁻⁵).', '["pH أقل من 7 تدل على الحمضية لا على القوة؛ فالحمض الضعيف يعطي pH أقل من 7 أيضًا.","","الأحماض الضعيفة تعطي pH أقل من 7 ما دامت تتأين جزئيًّا.","لا توجد قيمة pH ثابتة للأحماض القوية؛ تعتمد على التركيز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T09:21:20.663Z"}'::jsonb),
('essay', 1, null::int, null, null, 'معادلة التأين: HX(aq) ⇌ H⁺(aq) + X⁻(aq)، و Ka = [H⁺][X⁻]/[HX]. [H⁺] = 10^−2.70 = 2.0 × 10⁻³ M. من المعادلة [X⁻] = [H⁺] = 2.0 × 10⁻³ M. [HX] عند الاتزان = 0.150 − 0.0020 = 0.148 M. Ka = (2.0 × 10⁻³)(2.0 × 10⁻³)/0.148 = 2.7 × 10⁻⁵.', '["كتابة معادلة التأين وتعبير Ka","[H⁺] = 2.0 × 10⁻³ M","[X⁻] = [H⁺]","[HX] = 0.148 M","Ka = 2.7 × 10⁻⁵"]'::jsonb, '["[H⁺] = 10^−pH = 10^−2.70 = 2.0 × 10⁻³ M","[X⁻] = [H⁺] = 2.0 × 10⁻³ M","[HX] = 0.150 − 0.0020 = 0.148 M","Ka = (2.0 × 10⁻³)² / 0.148 = 2.7 × 10⁻⁵"]'::jsonb, '[{"element":"معادلة التأين وتعبير Ka","marks":1},{"element":"[H⁺] و [X⁻]","marks":1},{"element":"[HX] عند الاتزان","marks":1},{"element":"Ka صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الخطوات والنتيجة صحيحة"},{"level":"3 درجات","description":"خطأ حسابي واحد في النتيجة مع خطوات سليمة"},{"level":"1–2 درجة","description":"حساب [H⁺] فقط أو تعبير Ka فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم طرح [H⁺] من التركيز الابتدائي","أخذ [X⁻] = التركيز الابتدائي","إهمال إشارة السالب في 10^−pH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T09:21:20.663Z"}'::jsonb),
('essay', 2, null::int, null, null, 'pH = 14.00 − pOH = 14.00 − 11.40 = 2.60. [H⁺] = 10^−2.60 = 2.5 × 10⁻³ M، و [A⁻] = [H⁺] = 2.5 × 10⁻³ M. [HA] = 0.0300 − 0.0025 = 0.0275 M. Ka = (2.5 × 10⁻³)²/0.0275 = 2.3 × 10⁻⁴.', '["pH = 2.60 من pH + pOH = 14.00","[H⁺] = [A⁻] = 2.5 × 10⁻³ M","[HA] = 0.0275 M","Ka = 2.3 × 10⁻⁴"]'::jsonb, '["pH = 14.00 − 11.40 = 2.60","[H⁺] = 10^−2.60 = 2.5 × 10⁻³ M = [A⁻]","[HA] = 0.0300 − 0.0025 = 0.0275 M","Ka = (2.5 × 10⁻³)² / 0.0275 = 2.3 × 10⁻⁴"]'::jsonb, '[{"element":"تحويل pOH إلى pH","marks":1},{"element":"[H⁺] و [A⁻]","marks":1},{"element":"[HA] عند الاتزان","marks":1},{"element":"Ka صحيحة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"كل الخطوات والنتيجة صحيحة"},{"level":"3 درجات","description":"خطأ حسابي في آخر الحل فقط"},{"level":"1–2 درجة","description":"تحويل pOH إلى pH فقط أو خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال pOH مباشرة في 10^−pOH على أنه [H⁺]","عدم طرح [H⁺] من التركيز الابتدائي","الخلط بين [OH⁻] و [H⁺]"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-17T09:21:20.663Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الطالب لم يطرح [H⁺] الناتج من تأين الحمض من التركيز الابتدائي، فاستعمل 0.0500 M بدلًا من [HA] عند الاتزان. الحل الصحيح: [H⁺] = 10⁻² = 0.010 M = [A⁻]؛ [HA] = 0.0500 − 0.010 = 0.0400 M؛ Ka = (0.010)²/0.0400 = 2.5 × 10⁻³. الناتج يتغير من 2.0 × 10⁻³ إلى 2.5 × 10⁻³ (خطأ 20%)، لأن 20% من الحمض تأين فلا يمكن إهماله. ويكون التقريب مقبولًا فقط عندما يكون الجزء المتأين صغيرًا جدًّا (كأقل من 1–5% من التركيز الابتدائي) كما في محلول تركيزه 0.100 M و pH = 3.00.', '["الخطأ: عدم طرح [H⁺] من التركيز الابتدائي","[HA] = 0.0400 M","Ka = 2.5 × 10⁻³","سبب الاختلاف: 20% من الحمض متأين","التقريب مقبول عندما يكون التأين ضئيلًا"]'::jsonb, '["[H⁺] = [A⁻] = 0.010 M","[HA] = 0.0500 − 0.010 = 0.0400 M","Ka = (0.010)² / 0.0400 = 2.5 × 10⁻³"]'::jsonb, '[{"element":"تحديد خطأ الطالب","marks":1},{"element":"الحل الصحيح","marks":2},{"element":"تفسير سبب الفرق بنسبة التأين","marks":1},{"element":"متى يقبل التقريب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد الخطأ، حل صحيح، تفسير وشرط التقريب"},{"level":"3–4 درجات","description":"حل صحيح مع تحديد الخطأ دون التفسير الكامل"},{"level":"1–2 درجة","description":"حل صحيح فقط أو تحديد الخطأ فقط"},{"level":"صفر","description":"تأييد طريقة الطالب أو لا إجابة"}]'::jsonb, '["تأييد الطالب لأن الفرق صغير","طرح [H⁺] من [H⁺]","القول إن الخطأ في حساب [H⁺] من pH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.664Z"}'::jsonb)
