from (values
('mcq', 1, 'كيف تُستعمل أوراق كاشف pH (مثل ورق تباع الشمس) للحصول على قيمة pH لمحلول؟', null, '["توضع أقطاب الورقة في المحلول وتقرأ القيمة من شاشة","يُقاس التيار الكهربائي المار بين طرفي الورقة","يُعدّ عدد القطرات اللازمة لتغيير لون الورقة بالكامل","تُغمس الورقة في المحلول ثم يقارن لونها الجديد بألوان كاشف pH المعياري على ورقة مدرّجة"]'::jsonb, 'فهم', 'تذكر/فهم إجراء', 'سهل', 'الكتاب ص 80 — قياس الرقم الهيدروجيني pH، الشكل 2-18'),
('mcq', 2, 'كيف يعطي مقياس pH الرقمي قيمة الرقم الهيدروجيني للمحلول؟', null, '["بتغيّر لون ورقة معالجة بالكاشف عند غمسها في المحلول","بمقارنة لون المحلول بألوان معيارية على ورقة مدرجة","بوضع أقطابه في المحلول فيعطي المقياس قراءة مباشرة","بإضافة قطرة فينولفثالين ثم ملاحظة اللون"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 80 — الشكل 2-18 (b)'),
('mcq', 3, 'أيّ طريقتي قياس pH أدق، وما السبب؟', null, '["مقياس pH الرقمي لأنه يعطي قراءة مباشرة بدلًا من تقدير اللون","ورق الكاشف لأن اللون يتغير بسرعة عند غمسه","الطريقتان متساويتان في الدقة لأن كلتيهما تعتمدان على [H⁺]","ورق الكاشف لأن مقارنة اللون تعطي رقمين عشريين"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 80 — الشكل 2-18'),
('mcq', 4, 'لماذا تُعدّ قيمة pH التي يعطيها ورق الكاشف قيمة تقريبية؟', null, '["لأن الورق لا يتغير لونه بتغير [H⁺]","لأن الورق يقيس تركيز OH⁻ فقط","لأن الورق يعطي قيمة سالبة دائمًا","لأن القيمة تُحدَّد بمقارنة اللون بألوان معيارية على ورقة مدرجة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 80 — قياس الرقم الهيدروجيني pH'),
('mcq', 5, 'أيّ الصفوف في الجدول الآتي يقارن مقارنة صحيحة بين ورق الكاشف ومقياس pH الرقمي؟', '{"headers":["الصف","ورق الكاشف","مقياس pH الرقمي"],"rows":[["1","قراءة مباشرة وأكثر دقة","مقارنة لون وقيمة تقريبية"],["2","مقارنة لون وقيمة تقريبية","قراءة مباشرة وأكثر دقة"],["3","قراءة مباشرة بأقطاب","مقارنة لون بألوان معيارية"],["4","مقارنة لون وأكثر دقة","قراءة مباشرة وأقل دقة"]]}'::jsonb, '["الصف 1","الصف 2","الصف 3","الصف 4"]'::jsonb, 'تحليل', 'تفسير جدول', 'متوسط', 'الكتاب ص 80 — الشكل 2-18'),
('mcq', 6, 'في الشكل 2-18 قيس pH لمطر حمضي بمقياس pH الرقمي فكانت القراءة 5.50. أيّ العبارات الآتية تحلّل هذا الموقف تحليلًا صحيحًا؟', null, '["كان ورق تباع الشمس سيعطي القيمة 5.50 نفسها بدقة مماثلة","لا يمكن استعمال ورق الكاشف مطلقًا مع المطر الحمضي","قراءة المقياس الرقمي مقارنة لونية تقريبية","ورق تباع الشمس كان سيعطي قيمة تقريبية قريبة من 5.5، بينما المقياس أعطى قراءة مباشرة أدق"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 80 — الشكل 2-18'),
('mcq', 7, 'أراد طالب تحديد pH لعينة بأعلى دقة ممكنة، وأراد آخر معرفة قيمة تقريبية لـ pH سريعًا دون جهاز. ما الأداة الأنسب لكلٍّ منهما؟', null, '["الأول: ورق الكاشف، والثاني: مقياس pH الرقمي","الأول: مقياس pH الرقمي، والثاني: ورق الكاشف","كلاهما: مقياس pH الرقمي","كلاهما: ورق الكاشف"]'::jsonb, 'تقويم', 'اختيار أداة', 'متوسط', 'الكتاب ص 80 — قياس الرقم الهيدروجيني pH'),
('essay', 1, 'قارن بين قياس pH باستعمال ورق الكاشف وقياسه بمقياس pH الرقمي من حيث: (1) طريقة القياس، (2) نوع القيمة التي نحصل عليها، (3) الدقة.', null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 80 — قياس الرقم الهيدروجيني pH'),
('essay', 2, 'اشرح كيف يستدل ورق تباع الشمس وأوراق كاشف pH على حموضة محلول أو قاعديته، ولماذا تُعدّ القيمة التي نحصل عليها بها تقريبية، ثم بيّن كيف يختلف عنها مقياس pH الرقمي.', null, null, 'فهم', 'شرح', 'سهل', 'الكتاب ص 80 — قياس الرقم الهيدروجيني pH'),
('essay', 3, 'عينتان: الأولى مطر حمضي يحتاج باحث إلى قيمة pH له بأدق ما يمكن، والثانية محلول مجهول يريد طالب أن يعرف سريعًا هل هو حمضي أم قاعدي وبقيمة تقريبية. اختر الأداة الأنسب لكل حالة (ورق الكاشف أم مقياس pH الرقمي)، وعلّل اختيارك، ثم حلّل ما يخسره الطالب إن استعمل الورق مع العينة الأولى.', null, null, 'تقويم', 'اختيار وتعليل', 'صعب', 'الكتاب ص 80 — الشكل 2-18')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L3-O10') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'أوراق الكاشف معالجة بمواد (كواشف) يتغير لونها بتغير تركيز H⁺، فيقارن اللون الجديد بالألوان المعيارية على ورقة مدرجة، فتعطي قيمة pH تقريبية.', '["الأقطاب والشاشة من مكونات مقياس pH الرقمي لا ورق الكاشف.","لا يُقاس تيار في ورق الكاشف؛ المعتمد هو تغيّر اللون.","الكتاب لا يعتمد عدّ القطرات؛ الطريقة مقارنة اللون بمقياس معياري.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.664Z"}'::jsonb),
('mcq', 2, 2, 'عند وضع أقطاب مقياس pH الرقمي في المحلول يعطي المقياس قراءة مباشرة لقيمة pH.', '["هذه طريقة ورق الكاشف لا المقياس الرقمي.","المقارنة بألوان معيارية هي طريقة ورق الكاشف.","","الفينولفثالين من الكواشف التي يتغير لونها، وهو لا يعطي قراءة رقمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.665Z"}'::jsonb),
('mcq', 3, 0, 'يعطي مقياس pH الرقمي قياسًا أدق من ورق تباع الشمس؛ إذ يعطي قراءة مباشرة، أما ورق الكاشف فيعطي قيمة تقريبية بمقارنة اللون.', '["","سرعة تغيّر اللون لا تعني دقة؛ فالتقدير بالمقارنة اللونية يعطي قيمة تقريبية.","الدقة مختلفة؛ فالمقياس الرقمي أدق من الورق.","ورق الكاشف يعطي قيمة تقريبية لا قراءة بأرقام عشرية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T09:21:20.665Z"}'::jsonb),
('mcq', 4, 3, 'قيمة pH تُستنتج بمقارنة لون الورقة بالألوان المعيارية المدرّجة، وتُحدَّد بالنظر إلى أقرب لون مطابق؛ ولذلك تكون القيمة تقريبية لا قراءة مباشرة.', '["الورق معالج بكواشف يتغير لونها بتغير تركيز H⁺؛ فهو يتأثر به.","الكاشف يتغير لونه بتغير تركيز H⁺ ولا يقيس OH⁻ وحده.","قيم pH للمحاليل في تدريج الكتاب من 0 إلى 14، وليست سالبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.665Z"}'::jsonb),
('mcq', 5, 1, 'ورق الكاشف يعتمد على مقارنة اللون ويعطي قيمة تقريبية، أما مقياس pH الرقمي فيعطي قراءة مباشرة بصورة أدق؛ وهذا هو الصف 2.', '["عكس الطريقتين؛ نسب القراءة المباشرة الأدق إلى الورق.","","عكس الطريقتين؛ الأقطاب والقراءة المباشرة للمقياس الرقمي لا للورق.","نسب الدقة الأكبر إلى الورق، والصحيح أن المقياس الرقمي هو الأدق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.665Z"}'::jsonb),
('mcq', 6, 3, 'المقياس الرقمي يعطي قراءة مباشرة (5.50) وهي أدق من قيمة ورق تباع الشمس التي تُقدَّر بمقارنة اللون فتكون تقريبية، وقد تقرب من 5.5 دون أن تطابقها بدقة.', '["ورق تباع الشمس لا يعطي دقة مماثلة؛ فقيمته تقريبية.","يمكن استعمال ورق الكاشف مع المحاليل الحمضية لكن الناتج تقريبي.","المقياس الرقمي يعطي قراءة مباشرة لا مقارنة لونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T09:21:20.665Z"}'::jsonb),
('mcq', 7, 1, 'الدقة الأعلى تتحقق بمقياس pH الرقمي الذي يعطي قراءة مباشرة، أما الحصول على قيمة تقريبية دون جهاز فيكفيه ورق الكاشف بمقارنة لونه بالألوان المعيارية.', '["عكس الأداتين؛ ورق الكاشف أقل دقة.","","المقياس الرقمي أدق لكن الثاني لا يريد جهازًا، وورق الكاشف يلبي حاجته.","ورق الكاشف يعطي قيمة تقريبية فلا يلبي حاجة الطالب الأول إلى الدقة العالية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.666Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ورق الكاشف: تُغمس ورقة معالجة بكاشف (مثل ورق تباع الشمس) في المحلول فيتغير لونها بتغير تركيز H⁺، ثم يقارن اللون الجديد بالألوان المعيارية على ورقة مدرجة؛ فنحصل على قيمة pH تقريبية، ودقته أقل. مقياس pH الرقمي: توضع أقطابه في المحلول فيعطي قراءة مباشرة لقيمة pH، ودقته أعلى.', '["ورق الكاشف: تغيّر اللون ثم مقارنته بألوان معيارية","ورق الكاشف: قيمة تقريبية وأقل دقة","المقياس الرقمي: أقطاب في المحلول وقراءة مباشرة","المقياس الرقمي: أدق"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة قياس ورق الكاشف","marks":1},{"element":"طريقة قياس المقياس الرقمي","marks":1},{"element":"نوع القيمة (تقريبية / مباشرة)","marks":1},{"element":"الدقة (الرقمي أدق)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المقارنة صحيحة في الطريقة والقيمة والدقة للأداتين"},{"level":"3 درجات","description":"عنصر واحد ناقص"},{"level":"1–2 درجة","description":"وصف أداة واحدة صحيحًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة الدقة الأعلى إلى ورق الكاشف","خلط الأقطاب بورق الكاشف","القول إن ورق الكاشف يعطي قراءة رقمية مباشرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.666Z"}'::jsonb),
('essay', 2, null::int, null, null, 'أوراق كاشف pH (ومنها ورق تباع الشمس) معالجة بمادة أو أكثر تسمى الكواشف، ويتغير لونها اعتمادًا على تركيز أيونات الهيدروجين في المحلول. عند غمس الورقة في المحلول يتغير لونها، ثم يقارن اللون الجديد بألوان كاشف pH المعياري الموجودة على ورقة مدرجة، فتعطي قيمة pH تقريبية؛ لأن التحديد يعتمد على مطابقة اللون بالنظر مع ألوان معيارية. أما مقياس pH الرقمي فتوضع أقطابه في المحلول فيعطي قراءة مباشرة، فيكون القياس أدق ولا يحتاج إلى مقارنة لونية.', '["الورق معالج بكواشف يتغير لونها بتغير [H⁺]","مقارنة اللون بالألوان المعيارية على ورقة مدرجة","القيمة تقريبية لأن التحديد بمطابقة اللون","المقياس الرقمي: أقطاب وقراءة مباشرة وأدق"]'::jsonb, '[]'::jsonb, '[{"element":"الكواشف وتغير اللون بتغير [H⁺]","marks":1},{"element":"المقارنة بالألوان المعيارية","marks":1},{"element":"سبب كون القيمة تقريبية","marks":1},{"element":"اختلاف المقياس الرقمي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الشرح كامل وصحيح"},{"level":"3 درجات","description":"عنصر واحد ناقص"},{"level":"1–2 درجة","description":"عنصر أو عنصران صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الورق يتأثر بـ OH⁻ فقط","عدّ القراءة اللونية دقيقة كالرقمية","نسبة الأقطاب إلى ورق الكاشف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.666Z"}'::jsonb),
('essay', 3, null::int, null, null, 'للعينة الأولى (الدقة المطلوبة عالية): مقياس pH الرقمي؛ لأن أقطابه تُوضع في المحلول فيعطي قراءة مباشرة أدق من استعمال ورق تباع الشمس. للعينة الثانية (قيمة تقريبية سريعة): ورق الكاشف؛ إذ يكفي غمسه ومقارنة لونه بالألوان المعيارية فيعطي قيمة تقريبية تكفي لمعرفة هل المحلول حمضي (pH أقل من 7) أم قاعدي (أكبر من 7). إن استعمل الطالب الورق مع العينة الأولى فسيحصل على قيمة تقريبية بمقارنة اللون بالنظر بدلًا من القراءة المباشرة الأدق، فتقل دقة النتيجة.', '["الأولى: مقياس رقمي مع التعليل بالقراءة المباشرة الأدق","الثانية: ورق الكاشف مع التعليل بالقيمة التقريبية","الحكم بالحمضية أو القاعدية من القيمة (أقل أو أكبر من 7)","خسارة الدقة عند استعمال الورق للأولى"]'::jsonb, '[]'::jsonb, '[{"element":"اختيار المقياس الرقمي للأولى مع التعليل","marks":1.5},{"element":"اختيار ورق الكاشف للثانية مع التعليل","marks":1.5},{"element":"تحليل خسارة الدقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اختياران صحيحان معللان وتحليل الخسارة"},{"level":"3 درجات","description":"اختياران صحيحان مع تعليل ناقص"},{"level":"1–2 درجة","description":"اختيار صحيح واحد معلل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الاختيارين","القول إن الورق أدق لأنه أسرع","عدم تعليل الاختيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.666Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
