from (values
('mcq', 1, 'ما المقصود بتفاعل التعادل؟', null, '["تفاعل فلز نشط مع محلول حمض ينتج ملحًا وغاز الهيدروجين","تفاعل محلول حمض مع محلول قاعدة ينتج ملحًا وماءً","تفاعل حمض مع الماء ينتج أيونات الهيدرونيوم وقاعدته المرافقة","تفاعل أيونات ملح مع الماء ينتج محلولًا حمضيًا أو قاعديًا"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 81 — التفاعلات بين الأحماض والقواعد'),
('mcq', 2, 'يُعرَّف الملح الناتج من تفاعل التعادل بأنه:', null, '["مركب أيوني يتكون من أيون موجب من الحمض وأيون سالب من القاعدة","مركب جزيئي يتكون من اتحاد أيون H⁺ من الحمض وأيون OH⁻ من القاعدة","مركب أيوني يتكون دائمًا من أيونات الصوديوم وأيونات الكلوريد فقط","مركب أيوني يتكون من أيون موجب من القاعدة وأيون سالب من الحمض"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 81 — التفاعلات بين الأحماض والقواعد'),
('mcq', 3, 'ينتمي تفاعل التعادل بين محلول حمض ومحلول قاعدة إلى تفاعلات:', null, '["الإحلال المزدوج","الإحلال البسيط","التحلل","الاحتراق"]'::jsonb, 'تذكر', 'تصنيف', 'متوسط', 'الكتاب ص 81 — التفاعلات بين الأحماض والقواعد'),
('mcq', 4, 'ما المعادلة الأيونية النهائية لتفاعل التعادل بين حمض قوي وقاعدة قوية؟', null, '["Na⁺(aq) + Cl⁻(aq) → NaCl(aq)","H₂O(l) → H⁺(aq) + OH⁻(aq)","H⁺(aq) + OH⁻(aq) → H₂O(l)","H⁺(aq) + Cl⁻(aq) → HCl(aq)"]'::jsonb, 'تذكر', 'تذكر معادلة', 'متوسط', 'الكتاب ص 82 — كتابة معادلات التعادل (الشكل 2-20)'),
('mcq', 5, 'في تفاعل مضاد الحموضة: Mg(OH)₂(aq) + 2HCl(aq) → MgCl₂(aq) + 2H₂O(l)، ما الملح الناتج؟', null, '["MgCl₂","H₂O","HCl","Mg(OH)₂"]'::jsonb, 'فهم', 'تحديد مكونات تفاعل', 'سهل', 'الكتاب ص 81 — التفاعلات بين الأحماض والقواعد'),
('mcq', 6, 'أيّ التفاعلات الآتية يُعدّ تفاعل تعادل؟', null, '["Zn(s) + 2HCl(aq) → ZnCl₂(aq) + H₂(g)","NH₃(aq) + H₂O(l) ⇌ NH₄⁺(aq) + OH⁻(aq)","2H₂(g) + O₂(g) → 2H₂O(l)","KOH(aq) + HNO₃(aq) → KNO₃(aq) + H₂O(l)"]'::jsonb, 'فهم', 'تمييز أمثلة', 'متوسط', 'الكتاب ص 81 — التفاعلات بين الأحماض والقواعد'),
('mcq', 7, 'يُنصح من يعاني من حرقة المعدة بتناول حليب المغنيسيا الذي يحتوي على Mg(OH)₂. ما سبب تخفيفه للحموضة؟', null, '["يخفف حمض المعدة بالماء فقط دون أن يحدث بينهما أي تفاعل","تتفاعل قاعدته مع حمض HCl في المعدة تفاعل تعادل فينتج ملح وماء","يحوّل حمض HCl في المعدة إلى غاز الهيدروجين الذي يخرج منها","يزيد تركيز أيونات H⁺ في المعدة فتنخفض قيمة pH للمحلول"]'::jsonb, 'فهم', 'تفسير تطبيق حياتي', 'صعب', 'الكتاب ص 81 — التفاعلات بين الأحماض والقواعد'),
('essay', 1, 'عرّف كلًّا من: تفاعل التعادل، والملح. ثم اكتب المعادلة الكيميائية الموزونة لتفاعل حمض الهيدروكلوريك HCl مع هيدروكسيد الصوديوم NaOH، وحدّد الملح الناتج.', null, null, 'تذكر', 'تعريف مع مثال', 'متوسط', 'الكتاب ص 81 — التفاعلات بين الأحماض والقواعد'),
('essay', 2, 'يعمل حليب المغنيسيا Mg(OH)₂ مضادًا للحموضة عند تفاعله مع حمض HCl في المعدة.
(أ) اكتب المعادلة الكيميائية الموزونة للتفاعل.
(ب) لماذا يُعدّ هذا التفاعل تفاعل إحلال مزدوج؟
(ج) حدّد في المعادلة: الحمض، والقاعدة، والملح، والماء، وبيّن من أين جاء كل أيون في الملح.', null, null, 'فهم', 'كتابة معادلة وتفسير', 'صعب', 'الكتاب ص 81 — التفاعلات بين الأحماض والقواعد'),
('essay', 3, 'يوضح الشكل 2-20 في الكتاب أن أيون الهيدروجين ينتقل من أيون الهيدرونيوم H₃O⁺ إلى أيون الهيدروكسيد OH⁻ في تفاعل التعادل.
(أ) اكتب معادلة هذا الانتقال، وفسّر لماذا ينتج جزيئا ماء.
(ب) ما المعادلة الأيونية النهائية لتعادل حمض قوي مع قاعدة قوية؟
(ج) لماذا تكون هذه المعادلة واحدة لكل تفاعلات تعادل الأحماض القوية مع القواعد القوية؟', null, null, 'فهم', 'تفسير نموذج', 'صعب', 'الكتاب ص 82 — كتابة معادلات التعادل (الشكل 2-20)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
