select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'تفاعل التعادل كما عرّفه الكتاب: تفاعل محلول حمض مع محلول قاعدة ينتج ملحًا وماءً. فالبديل الصحيح «تفاعل محلول حمض مع محلول قاعدة ينتج ملحًا وماءً».', '["تفاعل الفلز مع الحمض تفاعل إحلال بسيط ينتج غاز الهيدروجين، ولا يدخل فيه محلول قاعدة.","","هذا وصف لتأين الحمض في الماء، لا لتفاعله مع قاعدة.","هذا وصف لتميّه الأملاح، وهو تفاعل الملح مع الماء لا تفاعل الحمض مع القاعدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.667Z"}'::jsonb),
('mcq', 2, 3, 'الملح مركب أيوني يتكون من أيون موجب من قاعدة وأيون سالب من حمض؛ ففي MgCl₂ جاء Mg²⁺ من Mg(OH)₂ وCl⁻ من HCl. إذن الإجابة: «مركب أيوني يتكون من أيون موجب من القاعدة وأيون سالب من الحمض».', '["عكس الصحيح؛ فالأيون الموجب في الملح مصدره القاعدة (مثل Mg²⁺) والسالب مصدره الحمض (مثل Cl⁻).","اتحاد H⁺ مع OH⁻ يكوّن الماء لا الملح.","NaCl مثال واحد فقط على الأملاح؛ فـ MgCl₂ وKNO₃ أملاح أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.667Z"}'::jsonb),
('mcq', 3, 0, 'في تفاعل Mg(OH)₂ مع HCl يحل المغنسيوم محل الهيدروجين في HCl، ويحل الهيدروجين محل المغنسيوم في Mg(OH)₂، فيتبادل المركبان أيوناتهما؛ لذا يُعدّ التعادل تفاعل «الإحلال المزدوج».', '["","في الإحلال البسيط يحل عنصر محل عنصر آخر في مركب، أما في التعادل فيتبادل مركبان أيوناتهما.","التحلل يبدأ بمادة واحدة تتفكك، والتعادل يبدأ بمادتين (حمض وقاعدة).","الاحتراق تفاعل مادة مع الأكسجين منتجًا طاقة، وليس تفاعل حمض مع قاعدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.667Z"}'::jsonb),
('mcq', 4, 2, 'بحذف الأيونات المتفرجة من المعادلة الأيونية الكاملة لتعادل حمض قوي مع قاعدة قوية يبقى: H⁺(aq) + OH⁻(aq) → H₂O(l)، وهي المعادلة الأيونية النهائية نفسها لأي حمض قوي مع أي قاعدة قوية.', '["Na⁺ وCl⁻ أيونات متفرجة تظهر على جانبي المعادلة وتُحذف، فلا تمثل التفاعل.","هذه معادلة معكوسة تمثل تأين الماء، لا تكوّن الماء في التعادل.","","HCl حمض قوي متأين كليًا في المحلول، ولا تتحد أيوناته في تفاعل التعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.667Z"}'::jsonb),
('mcq', 5, 0, 'تفاعل التعادل: قاعدة + حمض → ملح + ماء. والملح هنا MgCl₂؛ إذ اتحد الأيون الموجب Mg²⁺ من القاعدة مع الأيون السالب Cl⁻ من الحمض.', '["","الماء هو الناتج الثاني لتفاعل التعادل، وليس ملحًا.","HCl هو الحمض المتفاعل لا الملح الناتج.","Mg(OH)₂ هو القاعدة المتفاعلة لا الملح الناتج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.668Z"}'::jsonb),
('mcq', 6, 3, 'التعادل تفاعل حمض مع قاعدة ينتج ملحًا وماءً؛ وفي KOH + HNO₃ → KNO₃ + H₂O تفاعلت القاعدة KOH مع الحمض HNO₃ فنتج الملح KNO₃ والماء، فهو تفاعل التعادل المطلوب.', '["تفاعل فلز مع حمض (إحلال بسيط) ينتج غاز الهيدروجين، لا ماءً وملحًا من قاعدة.","هذا تفاعل قاعدة ضعيفة مع الماء (تأين)، ولا ينتج ملحًا.","هذا تكوين الماء من عناصره، ولا يتضمن حمضًا ولا قاعدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.668Z"}'::jsonb),
('mcq', 7, 1, 'Mg(OH)₂ قاعدة، وعند ملامستها حمض HCl في المعدة يحدث تفاعل تعادل: Mg(OH)₂ + 2HCl → MgCl₂ + 2H₂O، فيُستهلك الحمض وينتج ملح وماء؛ ولهذا يخفف الحموضة.', '["Mg(OH)₂ قاعدة تتفاعل فعلًا مع الحمض؛ فالتخفيف وحده لا يفسر عمل مضاد الحموضة.","","غاز الهيدروجين ينتج من تفاعل فلز نشط مع حمض، لا من تفاعل قاعدة مع حمض.","القاعدة تستهلك أيونات H⁺ ولا تزيدها، وزيادتها تعني حموضة أشد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.668Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تفاعل التعادل: تفاعل محلول حمض مع محلول قاعدة ينتج ملحًا وماءً. الملح: مركب أيوني يتكون من أيون موجب من قاعدة وأيون سالب من حمض. المعادلة: HCl(aq) + NaOH(aq) → NaCl(aq) + H₂O(l)، والملح الناتج كلوريد الصوديوم NaCl (Na⁺ من القاعدة وCl⁻ من الحمض).', '["تعريف تفاعل التعادل: حمض + قاعدة → ملح + ماء","تعريف الملح: أيون موجب من القاعدة وأيون سالب من الحمض","المعادلة الموزونة HCl + NaOH → NaCl + H₂O","تحديد الملح NaCl"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف تفاعل التعادل","marks":1},{"element":"تعريف الملح","marks":1},{"element":"المعادلة الموزونة بالحالات","marks":1},{"element":"تحديد الملح الناتج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان ومعادلة موزونة وتحديد الملح"},{"level":"3 درجات","description":"تعريفان صحيحان ومعادلة صحيحة دون تحديد الملح، أو خطأ يسير في أحدها"},{"level":"2 درجتان","description":"تعريف واحد صحيح مع معادلة صحيحة"},{"level":"1 درجة","description":"تعريف واحد صحيح فقط أو معادلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الماء ملحًا","عكس مصدر الأيونات في الملح (الموجب من الحمض)","نسيان الماء في نواتج التعادل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.669Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Mg(OH)₂(s) + 2HCl(aq) → MgCl₂(aq) + 2H₂O(l).
(ب) لأن المركبين يتبادلان أيوناتهما: يتحد Mg²⁺ من القاعدة مع Cl⁻ من الحمض لتكوين MgCl₂، ويتحد H⁺ من الحمض مع OH⁻ من القاعدة لتكوين H₂O.
(ج) القاعدة Mg(OH)₂، والحمض HCl، والملح MgCl₂، والماء H₂O؛ وفي الملح جاء Mg²⁺ من القاعدة وCl⁻ من الحمض.', '["معادلة موزونة بمعاملين 2 لـ HCl و H₂O","تفسير الإحلال المزدوج بتبادل الأيونات","تحديد الحمض والقاعدة والملح والماء","مصدر Mg²⁺ القاعدة ومصدر Cl⁻ الحمض"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة الموزونة","marks":2},{"element":"تفسير الإحلال المزدوج","marks":1},{"element":"تحديد المكونات الأربعة","marks":1},{"element":"مصدر أيوني الملح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلة موزونة وتفسير صحيح وتحديد كامل للمكونات ومصدر الأيونات"},{"level":"4 درجات","description":"خطأ في الوزن فقط مع بقية الإجابة صحيحة"},{"level":"3 درجات","description":"معادلة صحيحة مع تحديد المكونات دون تفسير الإحلال المزدوج"},{"level":"2 درجتان","description":"معادلة صحيحة فقط أو تحديد المكونات فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Mg(OH)₂ + HCl → MgCl₂ + H₂O دون وزن","وصف التفاعل بأنه إحلال بسيط","كتابة صيغة الملح MgCl بدل MgCl₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.669Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) H₃O⁺(aq) + OH⁻(aq) → 2H₂O(l)؛ فعندما يخسر H₃O⁺ أيون هيدروجين يصبح جزيء ماء، وعندما يكسب OH⁻ أيون الهيدروجين يصبح أيضًا جزيء ماء.
(ب) H⁺(aq) + OH⁻(aq) → H₂O(l).
(ج) لأن الحمض القوي والقاعدة القوية والملح الذائب تكون في صورة أيونات، وأيونات الملح (الموجب من القاعدة والسالب من الحمض) تظهر على جانبي المعادلة فتُحذف بوصفها أيونات متفرجة، فلا يبقى إلا اتحاد H⁺ مع OH⁻ لتكوين الماء.', '["معادلة H₃O⁺ + OH⁻ → 2H₂O","تفسير تكوّن جزيئي ماء","H⁺ + OH⁻ → H₂O","حذف الأيونات المتفرجة فيبقى التفاعل نفسه"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة الانتقال","marks":1},{"element":"تفسير تكون جزيئي الماء","marks":1},{"element":"المعادلة الأيونية النهائية","marks":1},{"element":"تفسير ثبات المعادلة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة الأجزاء الثلاثة كاملة صحيحة"},{"level":"3 درجات","description":"المعادلتان صحيحتان مع تفسير ناقص"},{"level":"2 درجتان","description":"المعادلتان فقط دون تفسير"},{"level":"1 درجة","description":"معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة H₃O⁺ + OH⁻ → H₂O بجزيء ماء واحد","إبقاء أيونات Na⁺ وCl⁻ في المعادلة النهائية","الظن أن المعادلة النهائية تختلف باختلاف الملح الناتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.669Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
