('mcq', 1, 'ما المقصود بكواشف الأحماض والقواعد؟', null, '["محاليل معلومة التركيز توضع في السحاحة لمعايرة محلول مجهول","أجهزة تقيس قيمة pH للمحلول بأقطاب تُغمس فيه مباشرة","أصباغ كيميائية تتأثر ألوانها بالمحاليل الحمضية والقاعدية","أملاح تتفاعل أيوناتها مع الماء فتجعل المحلول حمضيًا أو قاعديًا"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 84 — كواشف الأحماض والقواعد (الشكلان 2-23 و2-24)'),
('mcq', 2, 'تُسمّى النقطة التي يتغير عندها لون الكاشف في أثناء المعايرة:', null, '["نقطة النهاية","نقطة التكافؤ","نقطة التشبع","نقطة التأين"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 85 — الكواشف ونقطة نهاية المعايرة'),
('mcq', 3, 'ما المقصود بنقطة التكافؤ في المعايرة؟', null, '["النقطة التي يتساوى عندها حجم الحمض في الكأس مع حجم القاعدة المضافة من السحاحة","النقطة التي تصبح عندها قيمة pH للمحلول مساوية 7 في جميع أنواع المعايرات","النقطة التي يبدأ عندها إضافة المحلول القياسي إلى المحلول المجهول التركيز","النقطة التي يتساوى عندها عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 83 — خطوات المعايرة'),
('mcq', 4, 'ذكر الكتاب أن كاشف البروموثيمول الأزرق مناسب عند:', null, '["معايرة حمض ضعيف بقاعدة قوية","معايرة حمض قوي بقاعدة قوية","قياس سعة محلول منظم مكوّن من HF وNaF","معايرة أي حمض بأي قاعدة مهما كانت قوتهما"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 84 — كواشف الأحماض والقواعد (الشكلان 2-23 و2-24)'),
('mcq', 5, 'عند معايرة حمض الميثانويك HCOOH بمحلول NaOH (الشكل 2-25 في الكتاب)، أُضيفت قطرات من كاشف:', null, '["البروموثيمول الأزرق","الميثيل البرتقالي","الكريستال البنفسجي","الفينولفثالين"]'::jsonb, 'تذكر', 'تذكر مثال', 'متوسط', 'الكتاب ص 85 — الكواشف ونقطة نهاية المعايرة'),
('mcq', 6, 'يصبح لون الشاي الأحمر فاتحًا عند إضافة عصير الليمون إليه. ما تفسير ذلك حسب الكتاب؟', null, '["عصير الليمون قاعدة تتعادل مع البوليفينولات الحمضية فيتكون ملح فاتح اللون","الحمض المضاف يزيد تأين البوليفينولات فيظهر لون أيوناتها الفاتح","البوليفينولات أحماض ضعيفة يقل تأينها بإضافة الحمض فيظهر لون الجزيئات غير المتأينة","عصير الليمون يخفف الشاي بالماء فقط فيقل تركيز المادة الملوّنة"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 84 — كواشف الأحماض والقواعد (الشكلان 2-23 و2-24)'),
('mcq', 7, 'لماذا يجب اختيار كاشف يتغير لونه عند نقطة التكافؤ في المعايرة؟', null, '["لأن تغير لونه يدل على إضافة كمية كافية من المحلول القياسي لتعادل المحلول المجهول","لأن الكاشف يتفاعل مع المحلول المجهول فيقلل حجم المحلول القياسي اللازم","لأن الكاشف يجعل قيمة pH للمحلول تساوي 7 تمامًا عند نقطة التكافؤ","لأن نقطة التكافؤ في جميع المعايرات تقع عند قيمة pH واحدة ثابتة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 85 — الكواشف ونقطة نهاية المعايرة'),
('essay', 1, 'عرّف كلًّا مما يأتي: (أ) كواشف الأحماض والقواعد. (ب) نقطة النهاية. (ج) نقطة التكافؤ.', null, null, 'تذكر', 'تعريف مصطلحات', 'متوسط', 'الكتاب ص 85 — الكواشف ونقطة نهاية المعايرة'),
('essay', 2, 'يصبح لون الشاي الأحمر فاتحًا عند إضافة عصير الليمون إليه.
(أ) ما المادة في الشاي التي تعمل كاشفًا؟ وما طبيعتها الحمضية؟
(ب) فسّر تغير اللون مستعينًا بمبدأ لوتشاتلييه.
(ج) ما الذي يجمع بين معظم الكواشف المستعملة في المعايرة؟', null, null, 'فهم', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 84 — كواشف الأحماض والقواعد (الشكلان 2-23 و2-24)'),
('essay', 3, 'اذكر الكاشف الذي بيّن الكتاب أنه مناسب لكل من المعايرتين الآتيتين، مع ذكر موضع نقطة التكافؤ في كل منهما:
(أ) معايرة HCl بمحلول NaOH.
(ب) معايرة HCOOH بمحلول NaOH.
ثم فسّر لماذا لا يصلح كاشف واحد لجميع المعايرات.', null, null, 'فهم', 'تذكر مع تفسير', 'صعب', 'الكتاب ص 84 — كواشف الأحماض والقواعد (الشكلان 2-23 و2-24)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
