from (values
('mcq', 1, 2, 'عرّف الكتاب كواشف الأحماض والقواعد بأنها الأصباغ الكيميائية التي تتأثر ألوانها بالمحاليل الحمضية والقاعدية، ويستعملها الكيميائيون بدلًا من مقياس pH لتحري نقطة التكافؤ.', '["هذا وصف المحلول القياسي، لا الكاشف.","هذا وصف مقياس pH، وقد ذكر الكتاب أن الكواشف تُستعمل بديلًا منه.","","هذا وصف الأملاح التي يحدث لها تميّه، لا الكواشف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.670Z"}'::jsonb),
('mcq', 2, 0, 'حسب الكتاب: تسمى النقطة التي يتغير لون الكاشف عندها نقطة النهاية للمعايرة.', '["","نقطة التكافؤ هي النقطة التي يتساوى عندها عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة، لا نقطة تغير اللون.","نقطة التشبع مصطلح من الذائبية يصف المحلول الذي لا يذيب مزيدًا من المذاب.","لا يوجد في المعايرة مصطلح «نقطة التأين» لوصف تغير لون الكاشف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T09:21:20.670Z"}'::jsonb),
('mcq', 3, 3, 'نقطة التكافؤ كما في الكتاب: النقطة التي يتساوى عندها عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة.', '["التكافؤ يتعلق بتساوي المولات لا الحجوم؛ فالحجمان يختلفان إذا اختلف التركيزان.","نقطة التكافؤ لا تكون دائمًا عند pH = 7؛ ففي معايرة HCOOH بـ NaOH تقع بين 8 و9.","بداية الإضافة هي أول المعايرة، أما التكافؤ فيُبلغ بعد إضافة كمية كافية من المحلول القياسي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.670Z"}'::jsonb),
('mcq', 4, 1, 'بيّن الكتاب أن البروموثيمول الأزرق كاشف مناسب عند معايرة حمض قوي بقاعدة قوية (نقطة التكافؤ عند pH = 7 تقريبًا)، أما الفينولفثالين فلمعايرة حمض ضعيف بقاعدة قوية.', '["الكاشف الذي ذكره الكتاب لمعايرة حمض ضعيف بقاعدة قوية هو الفينولفثالين، لأن نقطة التكافؤ فيها بين 8 و9.","","الكواشف تستعمل لتحري نقطة التكافؤ في المعايرة، لا لقياس سعة المحلول المنظم.","لا يصلح كاشف واحد لكل المعايرات؛ لأن نقطة التكافؤ لا تكون دائمًا عند pH = 7."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.670Z"}'::jsonb),
('mcq', 5, 3, 'في الشكل 2-25 احتوى الدورق على HCOOH مع قطرات من كاشف الفينولفثالين، وأصبح اللون ورديًا فاتحًا عند نقطة النهاية؛ لأن الفينولفثالين يغير لونه عند نقطة تكافؤ معايرة حمض ضعيف بقاعدة قوية.', '["البروموثيمول الأزرق ذكره الكتاب لمعايرة حمض قوي بقاعدة قوية، ونقطة التكافؤ هنا بين pH 8 و9.","الميثيل البرتقالي يتغير لونه في وسط حمضي بعيد عن نقطة تكافؤ هذه المعايرة (بين 8 و9).","الكريستال البنفسجي يتغير لونه عند قيم pH منخفضة جدًا (قرب 0 إلى 2) بعيدًا عن نقطة التكافؤ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.670Z"}'::jsonb),
('mcq', 6, 2, 'يحتوي الشاي على البوليفينولات وهي أحماض ضعيفة تعمل كاشفًا. وعند إضافة حمض الليمون يقل تأين البوليفينولات بحسب مبدأ لوتشاتلييه، فيصبح لون البوليفينولات غير المتأينة أكثر وضوحًا، أي يفتح اللون.', '["عصير الليمون يحتوي على حمض لا على قاعدة.","إضافة الحمض تزيح اتزان تأين الحمض الضعيف نحو الجزيئات غير المتأينة بحسب مبدأ لوتشاتلييه، فيقل التأين ولا يزيد.","","تغير اللون ناتج عن تغير تأين الكاشف، لا عن التخفيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T09:21:20.670Z"}'::jsonb),
('mcq', 7, 0, 'ذكر الكتاب أن دور الكاشف أن يبيّن بدقة -عن طريق تغير لونه- أنه قد تمت إضافة كمية كافية من المحلول القياسي لتعادل المحلول المجهول؛ لذا يجب أن يتغير لونه عند نقطة التكافؤ.', '["","الكاشف يُضاف بقطرات قليلة ليدل على النقطة، ولا يغير كمية المحلول القياسي اللازمة.","الكاشف لا يحدد قيمة pH، بل يتغير لونه استجابة لها.","نقطة التكافؤ تختلف باختلاف المعايرة؛ فقد تكون أقل من 7 أو أكبر منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.670Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) كواشف الأحماض والقواعد: أصباغ كيميائية تتأثر ألوانها بالمحاليل الحمضية والقاعدية.
(ب) نقطة النهاية: النقطة التي يتغير عندها لون الكاشف في المعايرة.
(ج) نقطة التكافؤ: النقطة التي يتساوى عندها عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة.', '["الكاشف صبغة يتأثر لونها بالحمض والقاعدة","نقطة النهاية: تغير لون الكاشف","نقطة التكافؤ: تساوي مولات H⁺ ومولات OH⁻"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الكاشف","marks":1},{"element":"تعريف نقطة النهاية","marks":1},{"element":"تعريف نقطة التكافؤ","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التعريفات الثلاثة صحيحة"},{"level":"2 درجتان","description":"تعريفان صحيحان"},{"level":"1 درجة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين نقطة النهاية ونقطة التكافؤ","تعريف نقطة التكافؤ بتساوي الحجوم بدل المولات","تعريف الكاشف بأنه جهاز لقياس pH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.671Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) البوليفينولات polyphenols، وهي تحتوي على ذرات هيدروجين متأينة جزئيًا؛ لذا فهي أحماض ضعيفة.
(ب) عند إضافة حمض الليمون يزداد تركيز H⁺، فينزاح اتزان تأين البوليفينولات نحو الجزيئات غير المتأينة بحسب مبدأ لوتشاتلييه، فيقل تأينها ويصبح لون البوليفينولات غير المتأينة أكثر وضوحًا، فيفتح لون الشاي.
(ج) معظم الكواشف جزيئات كبيرة تعمل أحماضًا ضعيفة، ويختلف لونها لاختلاف أنماط الروابط عندما يتأين جزيء الكاشف أو لا يتأين.', '["البوليفينولات أحماض ضعيفة","زيادة H⁺ تزيح الاتزان نحو غير المتأين","ظهور لون الصورة غير المتأينة","الكواشف أحماض ضعيفة يختلف لونها بين الصورتين"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد البوليفينولات وطبيعتها","marks":1},{"element":"التفسير بلوتشاتلييه","marks":2},{"element":"ما يجمع الكواشف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة للأجزاء الثلاثة"},{"level":"3 درجات","description":"تفسير صحيح مع نقص في أحد الجزأين الآخرين"},{"level":"2 درجتان","description":"تحديد المادة وطبيعتها مع تفسير ناقص"},{"level":"1 درجة","description":"تحديد المادة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عصير الليمون قاعدة","القول إن الحمض يزيد تأين الكاشف","عزو التغير إلى التخفيف فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T09:21:20.671Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) البروموثيمول الأزرق؛ فنقطة التكافؤ في معايرة حمض قوي بقاعدة قوية عند pH = 7.
(ب) الفينولفثالين؛ فنقطة التكافؤ في معايرة حمض ضعيف بقاعدة قوية تقع بين pH 8 و9.
لا يصلح كاشف واحد لأن نقطة التكافؤ لا تكون دائمًا عند pH = 7، ولكل كاشف مدى pH خاص يتغير لونه عنده، فيجب أن يتغير لون الكاشف عند نقطة التكافؤ للمعايرة المعينة.', '["البروموثيمول الأزرق للمعايرة (أ)","pH = 7 عند التكافؤ في (أ)","الفينولفثالين للمعايرة (ب)","التكافؤ بين 8 و9 في (ب)","اختلاف نقطة التكافؤ ومدى تغير لون الكاشف"]'::jsonb, '[]'::jsonb, '[{"element":"الكاشف وموضع التكافؤ في (أ)","marks":2},{"element":"الكاشف وموضع التكافؤ في (ب)","marks":2},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الكاشفان وموضعا التكافؤ والتفسير صحيحة"},{"level":"4 درجات","description":"الكاشفان وموضعا التكافؤ دون تفسير"},{"level":"3 درجات","description":"الكاشفان صحيحان مع خطأ في موضع التكافؤ"},{"level":"2 درجتان","description":"كاشف واحد مع موضع تكافئه"},{"level":"1 درجة","description":"ذكر كاشف واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الكاشفين","القول إن نقطة التكافؤ دائمًا عند pH = 7","الاعتقاد بأن الكاشف يغير قيمة pH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.671Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
