from (values
('mcq', 1, 'عويِر 30.00 mL من محلول HCl مجهول التركيز بمحلول NaOH تركيزه 0.1000 M، فلزم 24.60 mL منه للوصول إلى نقطة التكافؤ. ما مولارية HCl؟', null, '["0.1220 M","2.460 M","0.04100 M","0.08200 M"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 86 — مثال 2-6: حساب المولارية من بيانات المعايرة'),
('mcq', 2, 'في الخطوة الأولى من حساب مولارية حمض مجهول، لزم 22.50 mL من محلول NaOH القياسي تركيزه 0.2000 M. كم عدد مولات NaOH المضافة؟', null, '["4.500 mol","4.500 × 10⁻³ mol","0.1125 mol","8.889 mol"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'سهل', 'الكتاب ص 85 — استراتيجية حل المسائل: حساب المولارية'),
('mcq', 3, 'عويِر 25.00 mL من محلول H₂SO₄ بمحلول NaOH تركيزه 0.1500 M، فلزم 32.40 mL منه للوصول إلى نقطة التكافؤ وفق المعادلة: H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O. ما مولارية H₂SO₄؟', null, '["0.1944 M","0.3888 M","0.09720 M","0.05787 M"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 85 — استراتيجية حل المسائل: حساب المولارية'),
('mcq', 4, 'عويِر 20.00 mL من محلول Ca(OH)₂ بمحلول HCl تركيزه 0.1200 M، فلزم 18.50 mL منه للوصول إلى نقطة التكافؤ وفق المعادلة: Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O. ما مولارية Ca(OH)₂؟', null, '["0.05550 M","0.1110 M","0.2220 M","0.06486 M"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 85 — استراتيجية حل المسائل: حساب المولارية'),
('mcq', 5, 'ما الأساس الذي يُبنى عليه حساب مولارية المحلول المجهول عند نقطة التكافؤ في معايرة HCl بـ NaOH؟', null, '["حجم الحمض في الدورق يساوي حجم القاعدة المضافة من السحاحة","مولارية الحمض تساوي مولارية القاعدة المستعملة في المعايرة","عدد مولات H⁺ من الحمض يساوي عدد مولات OH⁻ من القاعدة","كتلة الحمض في الدورق تساوي كتلة القاعدة المضافة من السحاحة"]'::jsonb, 'فهم', 'تفسير مبدأ', 'سهل', 'الكتاب ص 83 — خطوات المعايرة ونقطة التكافؤ'),
('mcq', 6, 'كم mL من محلول NaOH تركيزه 0.2500 M يلزم لمعادلة 20.00 mL من محلول H₂SO₄ تركيزه 0.1500 M؟', null, '["24.00 mL","12.00 mL","6.000 mL","1.500 mL"]'::jsonb, 'تطبيق', 'مسألة حسابية (حساب حجم)', 'صعب', 'الكتاب ص 85 — استراتيجية حل المسائل: حساب المولارية'),
('mcq', 7, 'أيّ المحاليل الآتية يحتاج إلى أكبر حجم من محلول NaOH تركيزه 0.100 M للوصول إلى نقطة التكافؤ؟', null, '["25.0 mL من HCl تركيزه 0.100 M","25.0 mL من H₂SO₄ تركيزه 0.100 M","25.0 mL من HCOOH تركيزه 0.100 M","50.0 mL من HCl تركيزه 0.0400 M"]'::jsonb, 'تحليل', 'مقارنة كمية', 'صعب', 'الكتاب ص 85 — استراتيجية حل المسائل: حساب المولارية'),
('essay', 1, 'لتحديد تركيز حمض الإيثانويك CH₃COOH في عينة خل، عويِر 10.00 mL منها بمحلول NaOH تركيزه 0.1000 M، فلزم 15.20 mL منه للوصول إلى نقطة التكافؤ.
CH₃COOH(aq) + NaOH(aq) → CH₃COONa(aq) + H₂O(l)
احسب مولارية حمض الإيثانويك في العينة، موضحًا خطوات الحل.', null, null, 'تطبيق', 'مسألة حسابية بخطوات', 'متوسط', 'الكتاب ص 86 — مثال 2-6: حساب المولارية من بيانات المعايرة'),
('essay', 2, 'عويِر 20.00 mL من محلول حمض الكبريتيك H₂SO₄ بمحلول NaOH تركيزه 0.1000 M، فلزم 33.30 mL منه للوصول إلى نقطة التكافؤ.
(أ) اكتب المعادلة الموزونة للتفاعل، واحسب مولارية H₂SO₄.
(ب) حصل طالب على الناتج 0.1665 M. ما الخطأ الذي وقع فيه؟', null, null, 'تطبيق', 'مسألة حسابية مع تشخيص خطأ', 'متوسط', 'الكتاب ص 85 — استراتيجية حل المسائل: حساب المولارية'),
('essay', 3, 'يُستعمل محلول الأمونيا NH₃ في مواد التنظيف المنزلي. عويِر 25.00 mL منه بمحلول HCl تركيزه 0.2500 M، فلزم 38.40 mL منه للوصول إلى نقطة التكافؤ.
NH₃(aq) + HCl(aq) → NH₄Cl(aq)
(أ) احسب مولارية محلول الأمونيا.
(ب) احسب حجم محلول HCl نفسه اللازم لمعايرة 10.00 mL من محلول الأمونيا نفسه.', null, null, 'تطبيق', 'مسألة حسابية متعددة الخطوات', 'صعب', 'الكتاب ص 86 — مثال 2-6: حساب المولارية من بيانات المعايرة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
