from (values
('mcq', 1, 3, 'mol NaOH = 0.1000 × 0.02460 = 2.460 × 10⁻³ mol، والنسبة HCl : NaOH = 1 : 1 فـ mol HCl = 2.460 × 10⁻³ mol، ثم MA = 2.460 × 10⁻³ ÷ 0.03000 L = 0.08200 M.', '["ناتج عكس الحجمين: (0.1000 × 30.00) ÷ 24.60؛ أي القسمة على حجم القاعدة بدل حجم الحمض.","ناتج ضرب 0.1000 × 24.60 دون تحويل mL إلى L ودون القسمة على حجم الحمض.","ناتج استعمال نسبة مولية 1:2 خطأً؛ فالنسبة بين HCl وNaOH هي 1:1.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T09:21:20.672Z"}'::jsonb),
('mcq', 2, 1, 'mol NaOH = MB × VB = 0.2000 mol/L × 0.02250 L = 4.500 × 10⁻³ mol.', '["ناتج ضرب 0.2000 × 22.50 دون تحويل الحجم من mL إلى L.","","ناتج قسمة الحجم (0.02250 L) على المولارية بدل ضربهما.","ناتج قسمة المولارية على الحجم (0.2000 ÷ 0.02250) بدل ضربهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.672Z"}'::jsonb),
('mcq', 3, 2, 'mol NaOH = 0.1500 × 0.03240 = 4.860 × 10⁻³ mol؛ ومن المعادلة mol H₂SO₄ = mol NaOH × 1/2 = 2.430 × 10⁻³ mol؛ إذن MA = 2.430 × 10⁻³ ÷ 0.02500 = 0.09720 M.', '["ناتج إهمال النسبة المولية 1:2 واعتبار mol H₂SO₄ = mol NaOH.","ناتج ضرب مولات NaOH في 2 بدل القسمة على 2 (عكس النسبة المولية).","","ناتج عكس الحجمين في القسمة: (0.1500 × 25.00 ÷ 32.40) ÷ 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-17T09:21:20.672Z"}'::jsonb),
('mcq', 4, 0, 'mol HCl = 0.1200 × 0.01850 = 2.220 × 10⁻³ mol؛ ومن المعادلة mol Ca(OH)₂ = 2.220 × 10⁻³ ÷ 2 = 1.110 × 10⁻³ mol؛ إذن M = 1.110 × 10⁻³ ÷ 0.02000 = 0.05550 M.', '["","ناتج إهمال النسبة المولية واعتبار مولات القاعدة مساوية لمولات HCl.","ناتج ضرب مولات HCl في 2 بدل القسمة عليها (عكس النسبة المولية).","ناتج عكس الحجمين: (0.1200 × 20.00 ÷ 18.50) ÷ 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-10-17T09:21:20.672Z"}'::jsonb),
('mcq', 5, 2, 'عند نقطة التكافؤ يتساوى عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة، فنحسب مولات المحلول القياسي (M × V) ثم نستعمل النسبة المولية لإيجاد مولات المجهول وتركيزه.', '["الحجوم لا تتساوى إلا إذا تساوى التركيزان؛ والمتساوي هو عدد المولات.","لو كانت المولاريتان متساويتين دائمًا لما احتجنا إلى المعايرة؛ المتساوي عدد المولات لا التركيز.","","الكتل المولية للحمض والقاعدة مختلفة؛ فالتكافؤ بالمولات لا بالكتل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.672Z"}'::jsonb),
('mcq', 6, 0, 'mol H₂SO₄ = 0.1500 × 0.02000 = 3.000 × 10⁻³ mol؛ mol NaOH = 2 × 3.000 × 10⁻³ = 6.000 × 10⁻³ mol؛ V = 6.000 × 10⁻³ ÷ 0.2500 = 0.02400 L = 24.00 mL.', '["","ناتج إهمال النسبة المولية (2 mol NaOH لكل 1 mol H₂SO₄).","ناتج القسمة على 2 بدل الضرب فيها (عكس النسبة المولية).","ناتج ضرب مولات NaOH في المولارية بدل القسمة عليها: 6.000 × 10⁻³ × 0.2500 L."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T09:21:20.673Z"}'::jsonb),
('mcq', 7, 1, 'مولات H₂SO₄ = 2.50 × 10⁻³ mol، وكل مول منه يحتاج 2 mol NaOH، فيلزم 5.00 × 10⁻³ mol أي 50.0 mL؛ أما HCl وHCOOH (25.0 mL) فيحتاج كل منهما 25.0 mL، والمحلول الأخير 20.0 mL. إذن الأكبر حجمًا: 25.0 mL من H₂SO₄ تركيزه 0.100 M.', '["يحتوي على 2.50 × 10⁻³ mol H⁺ فقط فيحتاج 25.0 mL، بينما H₂SO₄ يحتاج ضعف ذلك.","","الحمض الضعيف يتعادل كليًا مع القاعدة القوية؛ فمولاته 2.50 × 10⁻³ mol ويحتاج 25.0 mL فقط مثل HCl.","الحجم الأكبر لا يعني مولات أكثر: 0.0400 × 0.0500 = 2.00 × 10⁻³ mol فيحتاج 20.0 mL."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.673Z"}'::jsonb),
('essay', 1, null::int, null, null, 'mol NaOH = 0.1000 mol/L × 0.01520 L = 1.520 × 10⁻³ mol. النسبة المولية 1:1 فـ mol CH₃COOH = 1.520 × 10⁻³ mol. MA = 1.520 × 10⁻³ mol ÷ 0.01000 L = 0.1520 M.', '["تحويل الحجوم إلى L","حساب مولات NaOH","تطبيق النسبة المولية 1:1","MA = 0.1520 M"]'::jsonb, '["VB = 15.20 mL × (1 L / 1000 mL) = 0.01520 L؛ VA = 0.01000 L","mol NaOH = MB × VB = 0.1000 × 0.01520 = 1.520 × 10⁻³ mol","من المعادلة 1 mol NaOH يعادل 1 mol CH₃COOH ⇒ mol CH₃COOH = 1.520 × 10⁻³ mol","MA = 1.520 × 10⁻³ ÷ 0.01000 = 0.1520 M"]'::jsonb, '[{"element":"تحويل الحجوم","marks":1},{"element":"مولات NaOH","marks":1},{"element":"النسبة المولية","marks":1},{"element":"الناتج النهائي بالوحدة والأرقام المعنوية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"خطوات كاملة وناتج صحيح بالوحدة"},{"level":"3 درجات","description":"خطوات صحيحة مع خطأ في الأرقام المعنوية أو الوحدة"},{"level":"2 درجتان","description":"حساب مولات NaOH صحيح دون إكمال"},{"level":"1 درجة","description":"تحويل الحجوم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تحويل mL إلى L","القسمة على حجم القاعدة بدل حجم الحمض","الظن أن الحمض الضعيف لا يتعادل كليًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.673Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O. mol NaOH = 0.1000 × 0.03330 = 3.330 × 10⁻³ mol؛ mol H₂SO₄ = 3.330 × 10⁻³ ÷ 2 = 1.665 × 10⁻³ mol؛ MA = 1.665 × 10⁻³ ÷ 0.02000 = 0.08325 M.
(ب) أهمل النسبة المولية 1:2 بين H₂SO₄ وNaOH واعتبر مولات الحمض مساوية لمولات القاعدة، فجاء ناتجه ضعف الناتج الصحيح.', '["المعادلة الموزونة","مولات NaOH = 3.330 × 10⁻³ mol","مولات H₂SO₄ = 1.665 × 10⁻³ mol","MA = 0.08325 M","تحديد الخطأ: إهمال النسبة المولية"]'::jsonb, '["H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O","mol NaOH = 0.1000 × 0.03330 = 3.330 × 10⁻³ mol","mol H₂SO₄ = 3.330 × 10⁻³ × (1/2) = 1.665 × 10⁻³ mol","MA = 1.665 × 10⁻³ ÷ 0.02000 L = 0.08325 M"]'::jsonb, '[{"element":"المعادلة الموزونة","marks":1},{"element":"مولات NaOH","marks":1},{"element":"تطبيق النسبة 1:2","marks":1},{"element":"المولارية النهائية","marks":1},{"element":"تشخيص خطأ الطالب","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة للجزأين"},{"level":"4 درجات","description":"حساب صحيح مع تشخيص ناقص"},{"level":"3 درجات","description":"خطأ في النسبة المولية مع بقية الخطوات صحيحة"},{"level":"2 درجتان","description":"معادلة موزونة ومولات NaOH فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال النسبة المولية 1:2","ضرب مولات NaOH في 2 بدل القسمة","عدم تحويل الحجوم إلى L"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-10-17T09:21:20.673Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) mol HCl = 0.2500 × 0.03840 = 9.600 × 10⁻³ mol = mol NH₃ (نسبة 1:1)؛ M(NH₃) = 9.600 × 10⁻³ ÷ 0.02500 = 0.3840 M.
(ب) mol NH₃ في 10.00 mL = 0.3840 × 0.01000 = 3.840 × 10⁻³ mol = mol HCl؛ V(HCl) = 3.840 × 10⁻³ ÷ 0.2500 = 0.01536 L = 15.36 mL.', '["مولات HCl = 9.600 × 10⁻³ mol","النسبة 1:1","M(NH₃) = 0.3840 M","مولات NH₃ في 10.00 mL","V(HCl) = 15.36 mL"]'::jsonb, '["mol HCl = 0.2500 × 0.03840 = 9.600 × 10⁻³ mol","mol NH₃ = 9.600 × 10⁻³ mol (1:1)","M(NH₃) = 9.600 × 10⁻³ ÷ 0.02500 = 0.3840 M","mol NH₃ (10.00 mL) = 0.3840 × 0.01000 = 3.840 × 10⁻³ mol","V(HCl) = 3.840 × 10⁻³ ÷ 0.2500 = 0.01536 L = 15.36 mL"]'::jsonb, '[{"element":"مولات HCl","marks":1},{"element":"مولارية الأمونيا","marks":2},{"element":"مولات NH₃ في 10.00 mL","marks":1},{"element":"حجم HCl","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الجزءان صحيحان بالخطوات والوحدات"},{"level":"5 درجات","description":"خطأ يسير في الوحدة أو الأرقام المعنوية"},{"level":"4 درجات","description":"الجزء (أ) صحيح كاملًا مع خطأ في (ب)"},{"level":"2 درجتان","description":"حساب مولات HCl فقط مع محاولة غير مكتملة"},{"level":"1 درجة","description":"تحويل الحجوم فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تحويل mL إلى L","قسمة المولات على حجم HCl بدل حجم الأمونيا","ضرب المولات في المولارية بدل القسمة عند حساب الحجم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T09:21:20.674Z"}'::jsonb)
