from (values
('mcq', 1, 'ما المقصود بتميّه الأملاح؟', null, '["عملية تتفاعل فيها الأملاح مع الماء، فتستقبل أيوناتها السالبة H⁺ منه أو تمنحه أيوناتها الموجبة","ذوبان الملح في الماء وتفكك بلورته إلى أيونات دون أي تفاعل بين هذه الأيونات والماء","تفاعل محلول حمض مع محلول قاعدة لإنتاج ملح وماء بكميات متكافئة عند نقطة التكافؤ","ارتباط عدد محدد من جزيئات الماء ببلورة الملح الصلبة لتكوين ملح مائي متبلور"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)'),
('mcq', 2, 'في أثناء تميّه الأملاح، تتفاعل الأيونات السالبة من الملح مع الماء بحيث:', null, '["تمنح أيونات الهيدروجين للماء","تستقبل أيونات الهيدروكسيد من الماء","تستقبل أيونات الهيدروجين من الماء","تمنح الماء إلكترونات فيتكوّن غاز الهيدروجين"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)'),
('mcq', 3, 'في تميّه كلوريد الأمونيوم NH₄Cl يسلك أيون NH₄⁺ سلوكًا يتمثل في أنه:', null, '["يستقبل أيون هيدروجين من الماء فيتكون NH₅⁺ وOH⁻","يمنح أيون هيدروجين للماء فيتكون NH₃ وH₃O⁺","يمنح أيون هيدروكسيد للماء فيتكون NH₃ وOH⁻","يتحد بأيون Cl⁻ فيتكون جزيء HCl وNH₃"]'::jsonb, 'فهم', 'تطبيق المفهوم على مثال', 'متوسط', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)'),
('mcq', 4, 'أيّ المعادلات الآتية تمثّل تفاعل تميّه ملح؟', null, '["KF(s) → K⁺(aq) + F⁻(aq)","HF(aq) + KOH(aq) → KF(aq) + H₂O(l)","H⁺(aq) + OH⁻(aq) → H₂O(l)","F⁻(aq) + H₂O(l) ⇌ HF(aq) + OH⁻(aq)"]'::jsonb, 'فهم', 'تمييز معادلات', 'متوسط', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)'),
('mcq', 5, 'أُضيف كاشف البروموثيمول الأزرق إلى ثلاثة محاليل أملاح متساوية التركيز كما في الجدول. ما سبب اختلاف لون الكاشف فيها؟', '{"headers":["المحلول (0.10 M)","لون البروموثيمول الأزرق"],"rows":[["NH₄Cl","أصفر"],["NaNO₃","أخضر"],["KF","أزرق"]]}'::jsonb, '["تفاعل أيونات بعض هذه الأملاح مع الماء، أي تميّه الأملاح","اختلاف تراكيز المحاليل الثلاثة بعضها عن بعض","تفاعل الكاشف مع أيونات الملح وتكوّن رواسب ملونة","اختلاف درجات حرارة المحاليل الثلاثة عند الإذابة"]'::jsonb, 'فهم', 'تفسير بيانات', 'متوسط', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)'),
('mcq', 6, 'عند إذابة كلوريد الأمونيوم في الماء يتفاعل أيون NH₄⁺ مع الماء منتجًا NH₃ وH₃O⁺. ماذا تُسمّى هذه العملية؟', null, '["تفاعل التعادل","التأين الذاتي للماء","تميّه الأملاح","المعايرة"]'::jsonb, 'تذكر', 'تعرف مصطلح', 'سهل', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)'),
('mcq', 7, 'لماذا لا تتفاعل أيونات K⁺ مع الماء عند إذابة KF؟', null, '["لأن K⁺ يستقبل أيونات الهيدروجين من الماء","لأن K⁺ أيون مصدره القاعدة القوية KOH","لأن K⁺ حمض ضعيف بحسب برونستد–لوري","لأن K⁺ يبقى متحدًا بأيون F⁻ في المحلول"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)'),
('essay', 1, 'عرّف تميّه الأملاح، ثم اذكر الطريقتين اللتين يتفاعل بهما أيون الملح مع الماء، ومثّل لكل منهما بمعادلة من الكتاب.', null, null, 'تذكر', 'تعريف مع أمثلة', 'متوسط', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)'),
('essay', 2, 'عند إذابة فلوريد البوتاسيوم KF في الماء يحدث تفككه ثم تميّه أحد أيوناته.
(أ) اكتب معادلة تفكك KF في الماء.
(ب) اكتب معادلة التميّه، وحدد الأيون الذي يتميّه.
(ج) وضّح الفرق بين المعادلتين، وبيّن أيهما تمثل تميّه الملح، ولماذا يصبح المحلول قاعديًا.', null, null, 'فهم', 'مقارنة ومعادلات', 'صعب', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)'),
('essay', 3, 'فسّر لماذا لا يحدث تميّه في محلول نترات الصوديوم NaNO₃، بينما يحدث في محلول كلوريد الأمونيوم NH₄Cl، مستعينًا بمصدر أيونات كل ملح وبمعادلة التميّه حيث تلزم.', null, null, 'فهم', 'تفسير ومقارنة', 'صعب', 'الكتاب ص 87 — تميّه الأملاح (الشكل 2-26)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
