from (values
('mcq', 1, 0, 'عرّف الكتاب تميّه الأملاح بأنه عملية تتفاعل فيها الأملاح مع الماء؛ حيث تستقبل الأيونات السالبة من الملح المتأين أيونات الهيدروجين من الماء، أو تمنح الأيونات الموجبة من الملح المتفكك أيونات الهيدروجين للماء.', '["","التفكك وحده لا يُعدّ تميّهًا؛ فالتميّه يتطلب تفاعل أيونات الملح مع الماء.","هذا تعريف تفاعل التعادل، والتميّه تفاعل الملح نفسه مع الماء.","هذا وصف الأملاح المائية (البلورات المتميهة)، وهو معنى مختلف عن تميّه الأملاح في هذا الدرس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.674Z"}'::jsonb),
('mcq', 2, 2, 'تستقبل الأيونات السالبة من الملح أيونات الهيدروجين من الماء، كما في F⁻ + H₂O ⇌ HF + OH⁻.', '["منح H⁺ للماء سلوك الأيونات الموجبة (مثل NH₄⁺) في التميّه، لا السالبة.","الأيون السالب لا يستقبل OH⁻ السالب؛ بل يستقبل H⁺ فيتبقى OH⁻ في المحلول.","","التميّه انتقال أيونات هيدروجين لا انتقال إلكترونات، ولا ينتج غازًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.674Z"}'::jsonb),
('mcq', 3, 1, 'حسب الكتاب: NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq)؛ أي أن الأيون الموجب يمنح أيون هيدروجين للماء.', '["NH₄⁺ حمض ضعيف بحسب برونستد–لوري فيمنح H⁺ ولا يستقبله.","","NH₄⁺ لا يحتوي على OH⁻ ليمنحه؛ وهو يمنح H⁺.","Cl⁻ لا يتفاعل مع الماء ولا يكوّن HCl في المحلول؛ لأن HCl حمض قوي متأين كليًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.675Z"}'::jsonb),
('mcq', 4, 3, 'في تميّه الأملاح يتفاعل أيون الملح مع الماء؛ والمعادلة F⁻(aq) + H₂O(l) ⇌ HF(aq) + OH⁻(aq) تبين أيون الفلوريد السالب يستقبل H⁺ من الماء، فهي معادلة التميّه.', '["هذه معادلة تفكك الملح عند ذوبانه، ولا يتفاعل فيها أي أيون مع الماء.","هذا تفاعل تعادل ينتج فيه الملح، لا تفاعل الملح مع الماء.","هذه المعادلة الأيونية النهائية لتعادل حمض قوي مع قاعدة قوية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.675Z"}'::jsonb),
('mcq', 5, 0, 'تتفاعل أيونات NH₄⁺ (في NH₄Cl) وF⁻ (في KF) مع الماء فيصبح المحلول الأول حمضيًا والثاني قاعديًا، بينما لا تتفاعل أيونات NaNO₃؛ وهذا هو تميّه الأملاح الذي يفسر اختلاف لون الكاشف.', '["","التراكيز متساوية (0.10 M) كما في الجدول، فلا تفسر الاختلاف.","لم تتكون رواسب؛ فالكاشف يتغير لونه بحسب حمضية المحلول أو قاعديته.","لم يُذكر اختلاف في درجات الحرارة، والكاشف يستجيب لقيمة pH الناتجة عن التميّه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-17T09:21:20.675Z"}'::jsonb),
('mcq', 6, 2, 'تفاعل أيون من الملح مع الماء (هنا NH₄⁺ يمنح H⁺ للماء) هو تميّه الأملاح.', '["التعادل تفاعل حمض مع قاعدة ينتج ملحًا وماءً، وهنا يتفاعل أيون الملح مع الماء.","التأين الذاتي يحدث بين جزيئات الماء نفسها دون أيونات ملح.","","المعايرة طريقة عملية لتحديد التركيز، لا اسم لتفاعل أيون مع الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.675Z"}'::jsonb),
('mcq', 7, 1, 'ذكر الكتاب أن أيونات K⁺ لا تتفاعل مع الماء بسبب تعادلها مع أيونات OH⁻ وتكوين محلول قاعدي قوي من KOH؛ أي أن K⁺ مصدره قاعدة قوية فلا يحدث له تميّه، بينما يتميّه F⁻.', '["الأيون الموجب K⁺ لا يستقبل H⁺؛ والأيونات السالبة هي التي قد تستقبله.","","لو كان K⁺ حمضًا ضعيفًا لتفاعل مع الماء ومنحه H⁺ كما يفعل NH₄⁺.","KF يتفكك كليًا في الماء إلى K⁺ وF⁻، فلا يبقيان متحدين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.675Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تميّه الأملاح: عملية تتفاعل فيها الأملاح مع الماء. الطريقة الأولى: يستقبل الأيون السالب من الملح أيون هيدروجين من الماء، مثل: F⁻(aq) + H₂O(l) ⇌ HF(aq) + OH⁻(aq). الطريقة الثانية: يمنح الأيون الموجب من الملح أيون هيدروجين للماء، مثل: NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq).', '["التعريف: تفاعل الأملاح مع الماء","الأيون السالب يستقبل H⁺","معادلة F⁻","الأيون الموجب يمنح H⁺","معادلة NH₄⁺"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"سلوك الأيون السالب مع المعادلة","marks":2},{"element":"سلوك الأيون الموجب مع المعادلة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تعريف صحيح والطريقتان بمعادلتين صحيحتين"},{"level":"4 درجات","description":"خطأ يسير في إحدى المعادلتين"},{"level":"3 درجات","description":"تعريف وطريقتان دون معادلات"},{"level":"2 درجتان","description":"تعريف مع طريقة واحدة"},{"level":"1 درجة","description":"التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين التميّه وتكوين الأملاح المائية المتبلورة","عكس سلوك الأيونين","كتابة سهم باتجاه واحد بدل ⇌"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.675Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) KF(s) → K⁺(aq) + F⁻(aq).
(ب) F⁻(aq) + H₂O(l) ⇌ HF(aq) + OH⁻(aq)؛ الأيون المتميّه F⁻.
(ج) الأولى تفكك الملح إلى أيوناته عند ذوبانه دون تفاعل مع الماء، والثانية تفاعل أيون الملح مع الماء فهي التي تمثل التميّه؛ فالأيون F⁻ قاعدة ضعيفة بحسب برونستد–لوري يستقبل H⁺ من الماء فتتكون أيونات OH⁻ ويصبح المحلول قاعديًا، أما K⁺ فلا يتفاعل مع الماء.', '["معادلة التفكك","معادلة تميّه F⁻","التفكك ليس تفاعلًا مع الماء","التميّه ينتج OH⁻ فيصبح المحلول قاعديًا","K⁺ لا يتفاعل"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة التفكك","marks":1},{"element":"معادلة التميّه وتحديد الأيون","marks":2},{"element":"الفرق بين المعادلتين","marks":1},{"element":"تفسير القاعدية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"4 درجات","description":"المعادلتان صحيحتان مع تفسير ناقص"},{"level":"3 درجات","description":"المعادلتان صحيحتان دون تفسير"},{"level":"2 درجتان","description":"معادلة واحدة صحيحة مع تفسير جزئي"},{"level":"1 درجة","description":"معادلة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ معادلة التفكك تميّهًا","كتابة تميّه K⁺ بدل F⁻","إنتاج H₃O⁺ بدل OH⁻ في معادلة F⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.676Z"}'::jsonb),
('essay', 3, null::int, null, null, 'NaNO₃ ناتج من حمض قوي HNO₃ وقاعدة قوية NaOH، وأيوناه Na⁺ وNO₃⁻ لا يتفاعلان مع الماء، فلا يحدث تميّه ويبقى المحلول متعادلًا. أما NH₄Cl فناتج من حمض قوي HCl وقاعدة ضعيفة NH₃؛ فأيون Cl⁻ لا يتفاعل مع الماء، لكن NH₄⁺ حمض ضعيف بحسب برونستد–لوري يمنح H⁺ للماء: NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq)، فيحدث التميّه ويصبح المحلول حمضيًا.', '["NaNO₃ من حمض قوي وقاعدة قوية","Na⁺ وNO₃⁻ لا يتفاعلان مع الماء","NH₄Cl من قاعدة ضعيفة وحمض قوي","معادلة تميّه NH₄⁺","Cl⁻ لا يتفاعل"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير عدم تميّه NaNO₃","marks":2},{"element":"مصدر NH₄Cl وأيوناته","marks":1},{"element":"معادلة تميّه NH₄⁺","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للملحين مع معادلة صحيحة"},{"level":"4 درجات","description":"تفسير كامل مع خطأ يسير في المعادلة"},{"level":"3 درجات","description":"تفسير أحد الملحين كاملًا مع إشارة للآخر"},{"level":"2 درجتان","description":"ذكر مصادر الأملاح فقط"},{"level":"1 درجة","description":"إجابة جزئية صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن Cl⁻ يتميّه فيكوّن HCl","الظن أن كل ملح يتميّه","كتابة NH₄⁺ يستقبل H⁺"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.676Z"}'::jsonb)
