from (values
('mcq', 1, 0, 'CH₃COONa ملح من قاعدة قوية NaOH وحمض ضعيف CH₃COOH؛ فلا يتفاعل Na⁺ مع الماء، بينما يتميّه CH₃COO⁻: CH₃COO⁻ + H₂O ⇌ CH₃COOH + OH⁻، فيكون المحلول قاعديًا.', '["","CH₃COO⁻ قاعدة مرافقة لحمض ضعيف فيستقبل H⁺ ولا يمنحه.","CH₃COO⁻ مصدره حمض ضعيف فيتفاعل مع الماء؛ وعدم التفاعل صفة أيونات الأحماض والقواعد القوية.","الملح من قاعدة قوية (NaOH) وحمض ضعيف، فيكون قاعديًا لا حمضيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.677Z"}'::jsonb),
('mcq', 2, 0, 'NH₄NO₃ ملح من قاعدة ضعيفة NH₃ وحمض قوي HNO₃؛ يتميّه NH₄⁺: NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺ فيكون المحلول حمضيًا.', '["","ملح من قاعدة قوية KOH وحمض قوي HNO₃ فمحلوله متعادل.","ملح من قاعدة قوية وحمض ضعيف HCOOH، فيتميّه HCOO⁻ ويكون المحلول قاعديًا.","ملح من قاعدة قوية NaOH وحمض قوي HBr فمحلوله متعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T09:21:20.677Z"}'::jsonb),
('mcq', 3, 3, 'KCl ملح من قاعدة قوية KOH وحمض قوي HCl؛ فلا يتفاعل K⁺ ولا Cl⁻ مع الماء، ويكون المحلول متعادلًا.', '["ملح من قاعدة ضعيفة وحمض قوي؛ يتميّه NH₄⁺ فيكون المحلول حمضيًا.","ملح من قاعدة قوية وحمض ضعيف HF؛ يتميّه F⁻ فيكون المحلول قاعديًا.","ملح من قاعدة قوية وحمض ضعيف؛ يتميّه CO₃²⁻ فيكون المحلول قاعديًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T09:21:20.677Z"}'::jsonb),
('mcq', 4, 3, 'NH₄⁺ حمض ضعيف بحسب برونستد–لوري يمنح H⁺ للماء: NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq)، فيتكون H₃O⁺ ويصبح المحلول حمضيًا.', '["Br⁻ مصدره حمض قوي HBr فلا يتفاعل مع الماء، ولو تفاعل لجعل المحلول قاعديًا لا حمضيًا.","هذه معادلة تأين الأمونيا قاعدةً في الماء، وتنتج OH⁻ فلا تفسر الحمضية.","هذه معادلة تفكك الملح فقط، ولا تتضمن تفاعلًا مع الماء ينتج H₃O⁺.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T09:21:20.677Z"}'::jsonb),
('mcq', 5, 1, 'CO₃²⁻ أيون سالب مصدره حمض ضعيف، فيستقبل H⁺ من الماء: CO₃²⁻ + H₂O ⇌ HCO₃⁻ + OH⁻، وتكوّن OH⁻ يجعل المحلول قاعديًا.', '["Na⁺ مصدره قاعدة قوية فلا يتفاعل مع الماء، ولو أنتج H⁺ لجعل المحلول حمضيًا.","","هذه المعادلة تستهلك OH⁻ ولا تنتجه، ولا يتفاعل فيها أيون الملح مع الماء.","هذه معادلة تفكك الملح، ولا تبين تكوّن OH⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T09:21:20.678Z"}'::jsonb),
('mcq', 6, 2, 'X أصفر ⇒ حمضي ⇒ NH₄Cl (قاعدة ضعيفة + حمض قوي)؛ Y أخضر ⇒ متعادل ⇒ NaNO₃ (حمض قوي + قاعدة قوية)؛ Z أزرق ⇒ قاعدي ⇒ KF (قاعدة قوية + حمض ضعيف). إذن: X هو NH₄Cl، وY هو NaNO₃، وZ هو KF.', '["عكسٌ للحمضي والقاعدي: محلول KF قاعدي فيعطي الأزرق، وNH₄Cl حمضي فيعطي الأصفر.","NaNO₃ متعادل فيعطي الأخضر لا الأصفر، وNH₄Cl حمضي لا متعادل.","","KF قاعدي فيعطي الأزرق لا الأخضر، وNaNO₃ متعادل لا قاعدي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.678Z"}'::jsonb),
('mcq', 7, 1, 'NH₃ + HBr → NH₄Br؛ والملح الناتج من قاعدة ضعيفة وحمض قوي، فيتميّه NH₄⁺: NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺، فيكون المحلول حمضيًا (pH أقل من 7) عند نقطة التكافؤ.', '["تساوي المولات لا يعني أن pH = 7؛ فالملح الناتج NH₄Br يتميّه.","","Br⁻ مصدره حمض قوي HBr فلا يتفاعل مع الماء.","عند نقطة التكافؤ تكون NH₃ قد تحولت كلها إلى NH₄⁺، فلا تبقى قاعدة زائدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.678Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq)؛ محلول حمضي لأنه ملح من قاعدة ضعيفة NH₃ وحمض قوي HNO₃، وNO₃⁻ لا يتفاعل.
(ب) CH₃COO⁻(aq) + H₂O(l) ⇌ CH₃COOH(aq) + OH⁻(aq)؛ محلول قاعدي لأنه ملح من قاعدة قوية KOH وحمض ضعيف CH₃COOH، وK⁺ لا يتفاعل.
(ج) لا يحدث تميّه؛ لأن K⁺ وNO₃⁻ من قاعدة قوية وحمض قوي ولا يتفاعلان مع الماء، فالمحلول متعادل.', '["معادلة تميّه NH₄⁺ وتصنيفه حمضيًا","معادلة تميّه CH₃COO⁻ وتصنيفه قاعديًا","KNO₃ لا يتميّه ومتعادل","التبرير بقوة الحمض والقاعدة الأصليين"]'::jsonb, '[]'::jsonb, '[{"element":"الملح (أ): المعادلة والتصنيف","marks":2},{"element":"الملح (ب): المعادلة والتصنيف","marks":2},{"element":"الملح (ج): التصنيف والتبرير","marks":1},{"element":"التبرير بقوة الحمض والقاعدة","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"المعادلات والتصنيفات والتبريرات كاملة صحيحة"},{"level":"5 درجات","description":"خطأ يسير في إحدى المعادلتين"},{"level":"4 درجات","description":"التصنيفات الثلاثة صحيحة مع معادلة واحدة"},{"level":"3 درجات","description":"التصنيفات الثلاثة صحيحة دون معادلات"},{"level":"2 درجتان","description":"تصنيفان صحيحان"},{"level":"1 درجة","description":"تصنيف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة تميّه للأيون المتفرج NO₃⁻ أو K⁺","تصنيف CH₃COOK حمضيًا لأنه من حمض","إنتاج OH⁻ في تميّه NH₄⁺"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T09:21:20.678Z"}'::jsonb),
('essay', 2, null::int, null, null, 'NH₄Cl: من قاعدة ضعيفة NH₃ وحمض قوي HCl؛ يتميّه NH₄⁺: NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺ فيكون المحلول حمضيًا (أصفر).
NaNO₃: من قاعدة قوية NaOH وحمض قوي HNO₃؛ لا يتفاعل Na⁺ ولا NO₃⁻ مع الماء فيكون متعادلًا (أخضر).
