('mcq', 1, 'ما المحلول المنظم؟', null, '["محلول تبقى قيمة pH له مساوية 7 دائمًا لأنه متعادل","محلول معلوم التركيز يوضع في السحاحة لمعايرة محلول مجهول","محلول يقاوم التغيرات في قيم pH عند إضافة كميات محددة من الأحماض أو القواعد","محلول لا تتغير قيمة pH له مهما أضيف إليه من حمض أو قاعدة"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 88 — المحاليل المنظمة: ما المحلول المنظم؟'),
('mcq', 2, 'ما المقصود بسعة المحلول المنظم؟', null, '["قيمة pH التي يكون عندها المحلول المنظم أكثر فاعلية في المقاومة","حجم المحلول المنظم اللازم للوصول إلى نقطة التكافؤ في المعايرة","تركيز أيونات الهيدروجين في المحلول المنظم عند وصوله إلى الاتزان","كمية الحمض أو القاعدة التي يستوعبها المحلول المنظم دون تغير مهم في pH"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 89 — سعة المحلول المنظم'),
