('mcq', 5, 'ماذا يحدث عند إضافة كمية كبيرة جدًا من حمض قوي إلى محلول منظم؟', null, '["يبقى pH ثابتًا تمامًا لأن المحلول المنظم يقاوم أي إضافة","تُتجاوز قدرته على مقاومة تغير pH فيتغير pH تغيرًا كبيرًا","يتحول المحلول المنظم إلى محلول متعادل قيمة pH له 7","تزداد سعة المحلول المنظم تلقائيًا لاستيعاب الحمض المضاف"]'::jsonb, 'فهم', 'تنبؤ', 'متوسط', 'الكتاب ص 89 — سعة المحلول المنظم'),
('mcq', 6, 'أيّ الإجراءات الآتية يزيد سعة المحلول المنظم؟', null, '["تخفيف المحلول المنظم بإضافة الماء المقطر إليه","إضافة قطرات من كاشف مناسب إلى المحلول المنظم","زيادة تراكيز الجزيئات والأيونات المنظمة في المحلول","إضافة كمية كبيرة من حمض قوي إلى المحلول المنظم"]'::jsonb, 'فهم', 'تطبيق قاعدة', 'صعب', 'الكتاب ص 89 — سعة المحلول المنظم'),
('mcq', 7, 'أيّ العبارات الآتية صحيحة عن المحاليل المنظمة؟', null, '["قيمة pH لجميع المحاليل المنظمة تساوي 7 لأنها محاليل متعادلة","منها محاليل حمضية وأخرى قاعدية، ولكلٍّ قيمة pH يكون عندها أكثر فاعلية","يمنع المحلول المنظم أي تغير في pH مهما كانت الكمية المضافة","أي محلول ملح ذائب في الماء يُعدّ محلولًا منظمًا للـ pH"]'::jsonb, 'فهم', 'حكم على عبارات', 'متوسط', 'الكتاب ص 89 — سعة المحلول المنظم'),
