from (values
('mcq', 1, 2, 'عرّف الكتاب المحاليل المنظمة بأنها محاليل تقاوم التغيرات في قيم pH عند إضافة كميات محددة من الأحماض أو القواعد.', '["المحاليل المنظمة ليست كلها متعادلة؛ فمنها ما يحافظ على pH حمضي أو قاعدي (مثل 4.76 أو 9.4).","هذا تعريف المحلول القياسي في المعايرة.","","مقاومة المحلول المنظم محدودة بسعته، وتُتجاوز عند إضافة كمية كبيرة من الحمض أو القاعدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T09:21:20.679Z"}'::jsonb),
('mcq', 2, 3, 'سعة المحلول المنظم كما في الكتاب: كمية الحمض أو القاعدة التي يستطيع المحلول المنظم أن يستوعبها دون تغير مهم في pH.', '["هذه قيمة pH المثلى للنظام (مثل 7.21 لـ H₂PO₄⁻/HPO₄²⁻) وليست سعته.","المحلول المنظم لا يُستعمل في السحاحة للوصول إلى نقطة التكافؤ، والسعة ليست حجمًا.","تركيز H⁺ يحدد قيمة pH ولا يعبر عن قدرة المحلول على استيعاب الحمض أو القاعدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T09:21:20.680Z"}'::jsonb),
('mcq', 3, 0, '[H⁺] = 0.01 mol ÷ 1 L = 0.01 M، فـ pH = −log 0.01 = 2.0؛ وهو ما ذكره الكتاب: تنخفض pH من 7.0 إلى 2.0.', '["","هذا تغير لا يزيد على 0.1 وحدة، وهو سلوك المحلول المنظم لا الماء النقي.","الماء النقي ليس محلولًا منظمًا، فلا يقاوم تغير pH.","12.0 هي قيمة pH عند إضافة 0.01 mol من NaOH لا من HCl."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.680Z"}'::jsonb),
('mcq', 4, 0, 'ذكر الكتاب أنه عند إضافة الكمية نفسها من HCl أو NaOH إلى 1 L من محلول منظم فقد يتغير pH بما لا يزيد على 0.1 وحدة.', '["","التغير بمقدار وحدة كاملة يعني تغير [H⁺] عشرة أضعاف، وهذا أكبر مما ذكره الكتاب للمحلول المنظم.","التغير بمقدار 5 وحدات هو ما يحدث للماء النقي (من 7.0 إلى 2.0 أو 12.0).","10 وحدات تغير هائل لا يحدث حتى في الماء النقي بهذه الكمية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.680Z"}'::jsonb),
('mcq', 5, 1, 'ذكر الكتاب أن قدرة المحلول المنظم على مقاومة تغير pH يتم تجاوزها في حالة إضافة كمية كبيرة من الحمض أو القاعدة؛ لأن له سعة محدودة.', '["مقاومة المحلول المنظم محدودة بسعته ولا تمتد إلى الكميات الكبيرة.","","إضافة حمض قوي بكمية كبيرة تجعل المحلول أكثر حمضية لا متعادلًا.","السعة تعتمد على تراكيز المكونات المنظمة، وتنقص باستهلاكها ولا تزداد تلقائيًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.680Z"}'::jsonb),
('mcq', 6, 2, 'حسب الكتاب: كلما زادت تراكيز الجزيئات والأيونات المنظمة في المحلول زادت سعة المحلول المنظم.', '["التخفيف يقلل تراكيز المكونات المنظمة فتقل السعة.","الكاشف يبين الحمضية أو القاعدية ولا يغير قدرة المحلول على المقاومة.","","الحمض القوي يستهلك جزءًا من المكونات المنظمة فتنقص السعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.680Z"}'::jsonb),
('mcq', 7, 1, 'يبين الجدول 2-7 محاليل منظمة يكون كل منها أكثر فاعلية عند pH معين (مثل 3.20 لـ HF/F⁻ و9.4 لـ NH₄⁺/NH₃)، فمنها الحمضي ومنها القاعدي.', '["الجدول 2-7 يبين محاليل منظمة عند pH 3.20 و4.76 و9.4 وغيرها، فليست كلها 7.","","للمحلول المنظم سعة محدودة تُتجاوز عند إضافة كمية كبيرة.","محلول NaCl مثلًا ليس منظمًا؛ فالمحلول المنظم يحتوي على مكونات تقاوم تغير pH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.680Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المحلول المنظم: محلول يقاوم التغيرات في قيم pH عند إضافة كميات محددة من الأحماض أو القواعد.
(ب) سعة المحلول المنظم: كمية الحمض أو القاعدة التي يستطيع المحلول المنظم أن يستوعبها دون تغير مهم في pH.
تزداد السعة بزيادة تراكيز الجزيئات والأيونات المنظمة في المحلول.', '["تعريف المحلول المنظم","تعريف السعة","زيادة تراكيز المكونات المنظمة تزيد السعة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المحلول المنظم","marks":1},{"element":"تعريف السعة","marks":1},{"element":"العامل المؤثر في السعة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التعريفان والعامل صحيحة"},{"level":"2 درجتان","description":"تعريفان صحيحان دون العامل أو تعريف وعامل"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحلول المنظم لا يتغير pH له أبدًا","تعريف السعة بأنها قيمة pH المثلى","القول إن التخفيف يزيد السعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.681Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) مع HCl: [H⁺] = 0.01 M ⇒ pH = −log(0.01) = 2.0، والتغير 5.0 وحدات (انخفاض). مع NaOH: [OH⁻] = 0.01 M ⇒ pOH = 2.0 ⇒ pH = 14.0 − 2.0 = 12.0، والتغير 5.0 وحدات (ارتفاع).
(ب) في المحلول المنظم لا يتغير pH بأكثر من 0.1 وحدة عند إضافة الكميتين نفسيهما؛ إذن المحلول المنظم محلول يقاوم التغيرات في قيم pH عند إضافة كميات محددة من الأحماض أو القواعد، بخلاف الماء النقي.', '["pH = 2.0 مع HCl","pH = 12.0 مع NaOH","التغير 5 وحدات في كل حالة","في المنظم ≤ 0.1 وحدة","الاستنتاج: مقاومة تغير pH"]'::jsonb, '["[H⁺] = 0.01 mol ÷ 1 L = 0.01 M ⇒ pH = −log 0.01 = 2.0","[OH⁻] = 0.01 M ⇒ pOH = 2.0 ⇒ pH = 14.0 − 2.0 = 12.0","ΔpH = 7.0 − 2.0 = 5.0 و ΔpH = 12.0 − 7.0 = 5.0","في المحلول المنظم ΔpH ≤ 0.1"]'::jsonb, '[{"element":"pH مع HCl","marks":1},{"element":"pH مع NaOH","marks":1},{"element":"مقدار التغير","marks":1},{"element":"المقارنة بالمحلول المنظم","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة ومقارنة واستنتاج"},{"level":"4 درجات","description":"حسابات صحيحة ومقارنة دون استنتاج واضح"},{"level":"3 درجات","description":"حساب الحالتين صحيح فقط"},{"level":"2 درجتان","description":"حساب حالة واحدة مع المقارنة"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب pH مع NaOH بأنه 2.0 بنسيان pOH","الظن أن pH الماء النقي لا يتغير","القول إن المحلول المنظم لا يتغير مطلقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.681Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجزء الأول خطأ: المحلول المنظم يقاوم تغير pH عند إضافة كميات محددة فقط؛ وله سعة هي كمية الحمض أو القاعدة التي يستوعبها دون تغير مهم في pH، وعند إضافة كمية كبيرة تُتجاوز قدرته ويتغير pH كثيرًا. الجزء الثاني خطأ أيضًا: تزداد السعة بزيادة تراكيز الجزيئات والأيونات المنظمة، والتخفيف بالماء يقلل هذه التراكيز فيقلل السعة. التصحيح: المحلول المنظم يقاوم تغير pH ضمن سعته، ولزيادة قدرته نزيد تراكيز مكوناته.', '["الحكم على الجزء الأول بالخطأ","ذكر السعة وتعريفها","تجاوز السعة يغير pH","الحكم على الجزء الثاني بالخطأ","زيادة التراكيز تزيد السعة والتخفيف يقللها"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم الجزء الأول مع التعليل","marks":2},{"element":"تعريف السعة","marks":1},{"element":"تقويم الجزء الثاني مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تقويم صحيح للجزأين مع تعليل كامل"},{"level":"4 درجات","description":"تقويم صحيح للجزأين مع نقص في التعليل"},{"level":"3 درجات","description":"تقويم جزء واحد كاملًا"},{"level":"2 درجتان","description":"الحكم على الجزأين دون تعليل"},{"level":"1 درجة","description":"حكم صحيح على جزء واحد دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول أن pH لا يتغير مطلقًا","القول إن التخفيف يزيد السعة","الخلط بين السعة وقيمة pH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T09:21:20.681Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
