insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'حسب الكتاب: المحلول المنظم خليط من حمض ضعيف مع قاعدته المرافقة، أو قاعدة ضعيفة مع حمضها المرافق.', '["الحمض القوي يتأين كليًا ولا يكوّن اتزانًا يقاوم تغير pH.","الحمض القوي والقاعدة القوية يتعادلان فينتج ملح متعادل وماء، ولا يقاومان تغير pH.","محلول الملح المتعادل (مثل NaCl) لا يحتوي على مكونات تستهلك H⁺ أو OH⁻ المضافة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.682Z"}'::jsonb),
('mcq', 2, 1, 'HF حمض ضعيف، وNaF يعطي أيون F⁻ وهو قاعدته المرافقة؛ فالخليط HF/NaF محلول منظم كما في مثال الكتاب.', '["HCl حمض قوي، وCl⁻ لا يستقبل H⁺، فلا يقاوم الخليط تغير pH.","","HNO₃ حمض قوي متأين كليًا، وNO₃⁻ لا يتفاعل مع H⁺ المضاف.","NaOH قاعدة قوية ولا يوجد في الخليط حمض ضعيف وقاعدته المرافقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.682Z"}'::jsonb),
('mcq', 3, 0, 'NH₃ قاعدة ضعيفة، وNH₄⁺ (من NH₄Cl) حمضها المرافق؛ فهما الزوج NH₄⁺/NH₃ الوارد في الجدول 2-7.', '["","NaOH قاعدة قوية وليست الحمض المرافق لـ NH₃.","HCl حمض قوي، ولا يوجد في الخليط القاعدة الضعيفة NH₃.","KOH قاعدة قوية، وKCl ملح متعادل؛ فلا يوجد زوج مترافق ضعيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T09:21:20.682Z"}'::jsonb),
('mcq', 4, 2, 'بحسب مبدأ لوتشاتلييه تكوّن أيونات H⁺ المضافة ضغطًا على الاتزان، فتتفاعل مع F⁻ لتكوين مزيد من HF وينزاح الاتزان إلى اليسار، فيستهلك معظم H⁺ المضاف ويتغير pH قليلًا.', '["إضافة H⁺ تمثل ضغطًا على الاتزان فيتجه إلى اليسار بحسب مبدأ لوتشاتلييه لا إلى اليمين.","Na⁺ أيون متفرج موجب لا يتفاعل مع H⁺ الموجب.","","وجود F⁻ يستهلك معظم H⁺ المضاف، ولذلك يتغير pH قليلًا فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T09:21:20.683Z"}'::jsonb),
('mcq', 5, 0, 'تتفاعل أيونات OH⁻ المضافة مع H⁺ لتكوين H₂O، فيقل تركيز H⁺، فيتجه الاتزان HF ⇌ H⁺ + F⁻ إلى اليمين لتعويضه، أي يتأين مزيد من HF وينتج مزيد من F⁻، ويبقى pH ثابتًا تقريبًا.', '["","OH⁻ وF⁻ أيونان سالبان لا يتفاعلان معًا لتكوين HF.","استهلاك H⁺ يقلل تركيزه فينزاح الاتزان إلى اليمين للتعويض، لا إلى اليسار.","NaOH مركب ذائب في الماء لا يترسب، وNa⁺ أيون متفرج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T09:21:20.683Z"}'::jsonb),
('mcq', 6, 3, 'معادلة النظام NH₃ + H₂O ⇌ NH₄⁺ + OH⁻ تبين أن NH₃ قاعدة ضعيفة تستقبل H⁺ وNH₄⁺ حمضها المرافق، أما بقية الأزواج فحمض ضعيف مع قاعدته المرافقة.', '["HF حمض ضعيف وF⁻ قاعدته المرافقة؛ فالمكوّن الأساسي حمض لا قاعدة.","CH₃COOH حمض ضعيف وCH₃COO⁻ قاعدته المرافقة.","H₂CO₃ حمض ضعيف وHCO₃⁻ قاعدته المرافقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.683Z"}'::jsonb),
('mcq', 7, 1, 'ذكر الكتاب أن المحلول المنظم يكون أكثر فاعلية عندما يساوي تركيز الحمض تركيز القاعدة المرافقة له أو يكاد يكون مساويًا؛ فعندها يستطيع استهلاك الحمض أو القاعدة المضافين بقدر متقارب.', '["عندما يقل تركيز القاعدة المرافقة كثيرًا يضعف المحلول عن استهلاك الحمض المضاف.","","فاعلية المحلول المنظم لا ترتبط بأن يكون pH = 7؛ فلكل نظام قيمة pH خاصة به.","التخفيف يقلل تراكيز المكونات المنظمة فيقلل قدرته على المقاومة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.683Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الحمض الضعيف CH₃COOH وقاعدته المرافقة CH₃COO⁻ (من CH₃COONa)؛ فهما زوج مترافق.
(ب) CH₃COOH(aq) ⇌ H⁺(aq) + CH₃COO⁻(aq).
(ج) لأن HCl حمض قوي يتأين كليًا ولا يكوّن اتزانًا، وأيون Cl⁻ لا يستقبل H⁺؛ فلا يوجد في الخليط حمض ضعيف وقاعدته المرافقة لاستهلاك H⁺ أو OH⁻ المضافة.', '["CH₃COOH حمض ضعيف","CH₃COO⁻ قاعدته المرافقة","معادلة الاتزان","HCl قوي وCl⁻ لا يستقبل H⁺"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المكونين والعلاقة","marks":2},{"element":"معادلة الاتزان","marks":1},{"element":"تفسير HCl/NaCl","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة"},{"level":"3 درجات","description":"المكونان والمعادلة صحيحة مع تفسير ناقص"},{"level":"2 درجتان","description":"تحديد المكونين فقط"},{"level":"1 درجة","description":"تحديد مكون واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ Na⁺ مكونًا منظمًا","الظن أن أي حمض مع ملحه يكون منظمًا","كتابة سهم باتجاه واحد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.684Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تُشكّل أيونات H⁺ المضافة ضغطًا على الاتزان، فتتفاعل مع F⁻ لتكوين مزيد من HF، وينزاح الاتزان إلى اليسار؛ فيُستهلك معظم H⁺ المضاف.
(ب) تتفاعل أيونات OH⁻ المضافة مع H⁺ لتكوين H₂O فيقل تركيز H⁺، فينزاح الاتزان إلى اليمين لتعويضه؛ أي يتأين مزيد من HF وينتج مزيد من F⁻.
يتغير pH قليلًا لأن الاتزان يستهلك معظم H⁺ المضاف أو يعوّض H⁺ المستهلك، فلا يتغير تركيز H⁺ كثيرًا.', '["إضافة الحمض: H⁺ + F⁻ → HF","الانزياح إلى اليسار","إضافة القاعدة: OH⁻ + H⁺ → H₂O","الانزياح إلى اليمين وتأين HF","تركيز H⁺ لا يتغير كثيرًا"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير إضافة الحمض","marks":2},{"element":"تفسير إضافة القاعدة","marks":2},{"element":"سبب صغر تغير pH","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تفسير كامل للحالتين مع السبب"},{"level":"4 درجات","description":"تفسير الحالتين صحيح دون السبب"},{"level":"3 درجات","description":"حالة صحيحة كاملة وأخرى ناقصة"},{"level":"2 درجتان","description":"حالة واحدة صحيحة"},{"level":"1 درجة","description":"ذكر اتجاه الانزياح دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس اتجاه الانزياح","القول إن OH⁻ يتفاعل مع F⁻","القول إن pH لا يتغير مطلقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T09:21:20.684Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) القاعدة الضعيفة NH₃، وحمضها المرافق NH₄⁺ (من NH₄Cl).
(ب) يتفاعل H⁺ المضاف مع OH⁻ مكوّنًا H₂O، فيقل تركيز OH⁻، فينزاح الاتزان إلى اليمين لتعويضه؛ فتُستهلك NH₃ ويتكون NH₄⁺، ومحصلة ذلك أن NH₃ استهلكت H⁺ المضاف، فيتغير pH قليلًا.
(ج) أيونات OH⁻ المضافة تزيد تركيز OH⁻ فينزاح الاتزان إلى اليسار بحسب مبدأ لوتشاتلييه؛ فيتفاعل NH₄⁺ مع OH⁻ مكوّنًا NH₃ وH₂O، فيُستهلك معظم OH⁻ المضاف ويتغير pH قليلًا.', '["NH₃ قاعدة ضعيفة وNH₄⁺ حمضها المرافق","إضافة HCl: H⁺ + OH⁻ → H₂O والانزياح لليمين","NH₃ تستهلك الحمض المضاف","إضافة NaOH: الانزياح لليسار","NH₄⁺ يستهلك OH⁻"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الزوج المترافق","marks":1},{"element":"تفسير إضافة HCl","marks":2},{"element":"تفسير إضافة NaOH","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة"},{"level":"4 درجات","description":"تفسير الحالتين مع خطأ يسير في الاتجاه أو المكون"},{"level":"3 درجات","description":"تحديد الزوج مع تفسير حالة واحدة"},{"level":"2 درجتان","description":"تفسير حالة واحدة فقط"},{"level":"1 درجة","description":"تحديد الزوج فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ Cl⁻ مكونًا منظمًا","عكس اتجاه الانزياح","الظن أن المحلول المنظم القاعدي لا يستطيع مقاومة القاعدة المضافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.684Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
