from (values
('mcq', 1, 'يجب أن تبقى قيمة pH للدم في جسم الإنسان ضمن المدى:', null, '["من 1.6 إلى 1.8","من 8.1 إلى 8.4","من 7.1 إلى 7.7","من 5.1 إلى 5.7"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 88 — المحاليل المنظمة في الكائنات الحية (الشكل 2-27)'),
('mcq', 2, 'يجب أن تبقى قيمة pH للعصارة المعدية بين 1.6 و1.8. ما أهمية ذلك حسب الكتاب؟', null, '["يحافظ على تراكيب البروتينات في الدم","يضمن صحة البيئة لقناديل البحر","يمنع تكوّن غاز CO₂ في المعدة","يساعد على هضم أنواع معينة من الطعام"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'سهل', 'الكتاب ص 88 — المحاليل المنظمة في الكائنات الحية (الشكل 2-27)'),
('mcq', 3, 'ما المحلول المنظم الذي ذكره الكتاب بوصفه أحد أنظمة المحافظة على pH الدم؟', null, '["H₂CO₃/HCO₃⁻ (حمض الكربونيك/الكربونات الهيدروجينية)","HF/F⁻ (حمض الهيدروفلوريك/الفلوريد)","NH₄⁺/NH₃ (الأمونيوم/الأمونيا)","C₂H₅NH₃⁺/C₂H₅NH₂ (الإيثيل أمونيوم/الإيثيل أمين)"]'::jsonb, 'تذكر', 'تذكر مثال', 'سهل', 'الكتاب ص 90 — مختبر حل المشكلات: كيف يحافظ الدم على قيمة pH ثابتة؟'),
('mcq', 4, 'لكي تكون البيئة صحية لقناديل البحر (الشكل 2-27)، يجب أن تبقى قيمة pH لمياه أحواض الأحياء المائية بين:', null, '["7.1 و7.7","1.6 و1.8","8.1 و8.4","6.1 و6.4"]'::jsonb, 'تذكر', 'تذكر حقيقة', 'متوسط', 'الكتاب ص 88 — المحاليل المنظمة في الكائنات الحية (الشكل 2-27)'),
('mcq', 5, 'لماذا يجب أن تبقى قيمة pH للدم ضمن مدى ضيق؟', null, '["لأن الأكسجين لا يذوب في الدم إلا عندما تكون قيمة pH له 7 تمامًا","لأن قيمة pH للدم يجب أن تساوي قيمة pH للعصارة المعدية في الجسم","لأن الدم يتحول إلى مادة صلبة إذا تغيرت قيمة pH له بأي مقدار","لأن البروتينات في الجسم تفقد تراكيبها ومقدرتها على أداء عملها خارج هذا المدى"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 90 — مختبر حل المشكلات: كيف يحافظ الدم على قيمة pH ثابتة؟'),
('mcq', 6, 'أيّ الأوساط الآتية يجب أن تكون قيمة pH فيه حمضية بدرجة كبيرة (بين 1.6 و1.8)؟', null, '["دم الإنسان","العصارة المعدية","ماء حوض قناديل البحر","الماء النقي عند 298 K"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 88 — المحاليل المنظمة في الكائنات الحية (الشكل 2-27)'),
('mcq', 7, 'عند دخول كمية قليلة من حمض إلى مجرى الدم تبقى قيمة pH ضمن المدى 7.1–7.7 بوجود نظام H₂CO₃/HCO₃⁻. ما التفسير الصحيح؟', null, '["تتفاعل أيونات H⁺ المضافة مع H₂CO₃ فتزداد أيونات HCO₃⁻ في الدم","ينزاح الاتزان إلى اليمين فتزداد أيونات H⁺ زيادة كبيرة","تتحول جميع أيونات HCO₃⁻ إلى أيونات OH⁻ في الحال","تتفاعل أيونات H⁺ المضافة مع HCO₃⁻ فينزاح الاتزان إلى اليسار ويُستهلك معظمها"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 90 — مختبر حل المشكلات: كيف يحافظ الدم على قيمة pH'),
('essay', 1, 'اذكر ثلاثة أمثلة أوردها الكتاب على أهمية بقاء قيمة pH ضمن مدى محدد في الكائنات الحية، مع ذكر المدى المطلوب في كل مثال.', null, null, 'تذكر', 'تعداد أمثلة', 'متوسط', 'الكتاب ص 88 — المحاليل المنظمة في الكائنات الحية (الشكل 2-27)'),
('essay', 2, 'يحافظ الدم على قيمة pH ثابتة تقريبًا بنظام H₂CO₃/HCO₃⁻:
CO₂(g) + H₂O(l) ⇌ H₂CO₃(aq) ⇌ H⁺(aq) + HCO₃⁻(aq)
(أ) ما المدى الذي يجب أن يبقى فيه pH الدم؟ ولماذا هو مهم؟
(ب) فسّر ما يحدث للاتزان عند دخول حمض إلى مجرى الدم.
(ج) كيف تساعد الرئتان في هذه الحالة؟', null, null, 'فهم', 'تفسير نظام حيوي', 'صعب', 'الكتاب ص 90 — مختبر حل المشكلات: كيف يحافظ الدم على قيمة pH ثابتة؟'),
('essay', 3, 'يذكر الكتاب المدى المطلوب لقيمة pH في ثلاثة أوساط: الدم (7.1–7.7)، والعصارة المعدية (1.6–1.8)، ومياه أحواض قناديل البحر (8.1–8.4). رتّب هذه الأوساط تصاعديًا بحسب قيمة pH وحدّد طبيعة كل منها (حمضي، أو قريب من التعادل، أو قاعدي ضعيف)، ثم فسّر لماذا تحتاج هذه الأوساط إلى المحافظة على pH ضمن مدى ضيق.', null, null, 'فهم', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 88 — المحاليل المنظمة في الكائنات الحية (الشكل 2-27)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
