('mcq', 3, 0, 'ذكر الكتاب أن من المحاليل المنظمة في الدم محلول حمض الكربونيك والكربونات الهيدروجينية H₂CO₃/HCO₃⁻: CO₂ + H₂O ⇌ H₂CO₃ ⇌ H⁺ + HCO₃⁻.', '["","HF/F⁻ نظام منظم يكون أكثر فاعلية عند pH = 3.20، ولم يذكره الكتاب للدم.","NH₄⁺/NH₃ نظام منظم أكثر فاعلية عند pH = 9.4، ولم يذكره الكتاب للدم.","هذا النظام أكثر فاعلية عند pH = 10.70، ولم يذكره الكتاب للدم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.686Z"}'::jsonb),
('mcq', 4, 2, 'حسب الشكل 2-27 في الكتاب: يجب أن تبقى قيمة pH للماء في أحواض الأحياء المائية بين 8.1 و8.4.', '["هذا مدى pH الدم في جسم الإنسان.","هذا مدى pH العصارة المعدية.","","مدى حمضي قليلًا لم يذكره الكتاب؛ والمطلوب لقناديل البحر مدى قاعدي قليلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.686Z"}'::jsonb),
('mcq', 5, 3, 'ذكر الكتاب أن الدم يحافظ على pH ضمن مدى ضيق بين 7.1 و7.7، وخارج هذا المستوى تفقد البروتينات في الجسم تراكيبها ومقدرتها على أداء عملها.', '["الكتاب لا يذكر هذا، ومدى pH الطبيعي للدم 7.1 إلى 7.7 وليس 7 تمامًا.","مدى pH العصارة المعدية (1.6 إلى 1.8) يختلف كثيرًا عن مدى pH الدم.","هذه مبالغة غير صحيحة؛ والأثر الذي ذكره الكتاب هو فقد البروتينات تراكيبها ووظائفها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T09:21:20.686Z"}'::jsonb),
('mcq', 6, 1, 'يذكر الكتاب أن قيمة pH للعصارة المعدية يجب أن تبقى بين 1.6 و1.8 فهي شديدة الحمضية، أما الدم فبين 7.1 و7.7 وحوض قناديل البحر بين 8.1 و8.4، والماء النقي pH له 7.', '["pH الدم بين 7.1 و7.7، أي قريب من التعادل لا شديد الحمضية.","","pH حوض قناديل البحر بين 8.1 و8.4، أي قاعدي ضعيف.","pH الماء النقي عند 298 K يساوي 7، أي متعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.686Z"}'::jsonb),
('mcq', 7, 3, 'تتفاعل أيونات H⁺ المضافة مع أيونات HCO₃⁻ مكوّنة H₂CO₃، فينزاح الاتزان إلى اليسار بحسب مبدأ لوتشاتلييه ويُستهلك معظم H⁺ المضاف، فلا يتغير pH الدم كثيرًا.', '["H⁺ المضافة تتفاعل مع القاعدة HCO₃⁻ لا مع الحمض H₂CO₃، وعدد HCO₃⁻ يقل لا يزداد.","زيادة H⁺ تدفع الاتزان إلى اليسار لا اليمين، ولو زاد H⁺ كثيرًا لتغير pH.","HCO₃⁻ لا يتحول كليًا إلى OH⁻؛ بل يستهلك جزءًا منه فقط في التفاعل مع H⁺.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.687Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) الدم في جسم الإنسان: يجب أن يبقى pH بين 7.1 و7.7. 2) العصارة المعدية: يجب أن يبقى pH بين 1.6 و1.8 لتساعد على هضم أنواع معينة من الطعام. 3) قناديل البحر: يجب أن يبقى pH مياه أحواض الأحياء المائية بين 8.1 و8.4. ويحافظ الجسم على pH ضمن حدود معينة من خلال إنتاج محاليل منظمة.', '["الدم 7.1–7.7","العصارة المعدية 1.6–1.8","أحواض قناديل البحر 8.1–8.4"]'::jsonb, '[]'::jsonb, '[{"element":"مثال الدم ومداه","marks":1},{"element":"مثال العصارة المعدية ومداه","marks":1},{"element":"مثال قناديل البحر ومداه","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أمثلة صحيحة بمداها"},{"level":"2 درجتان","description":"مثالان صحيحان بمداهما أو ثلاثة أمثلة دون مدى"},{"level":"1 درجة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين مدى الدم ومدى أحواض قناديل البحر","ذكر pH = 7 للدم","ذكر أمثلة دون قيم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.687Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) بين 7.1 و7.7؛ لأن البروتينات في الجسم تفقد خارج هذا المدى تراكيبها ومقدرتها على أداء عملها.
(ب) تزيد أيونات H⁺ المضافة تركيز H⁺، فينزاح الاتزان إلى اليسار بحسب مبدأ لوتشاتلييه؛ فتتفاعل H⁺ مع HCO₃⁻ مكوّنة H₂CO₃ الذي يتحول إلى CO₂ وH₂O، فيُستهلك معظم H⁺ المضاف ويبقى pH ثابتًا تقريبًا.
(ج) تطرد الرئتان CO₂ الزائد من الجسم عن طريق التنفس، فيستمر انزياح الاتزان إلى اليسار ويُتخلص من الحمض الزائد.', '["المدى 7.1–7.7","فقد البروتينات تراكيبها خارجه","الانزياح إلى اليسار واستهلاك H⁺ بـ HCO₃⁻","تكوّن CO₂","الرئتان تطردان CO₂"]'::jsonb, '[]'::jsonb, '[{"element":"المدى وأهميته","marks":1},{"element":"تفسير الانزياح عند دخول الحمض","marks":2},{"element":"دور الرئتين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة للأجزاء الثلاثة"},{"level":"3 درجات","description":"المدى والتفسير صحيحان دون دور الرئتين"},{"level":"2 درجتان","description":"المدى مع تفسير ناقص"},{"level":"1 درجة","description":"المدى فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس اتجاه الانزياح عند إضافة الحمض","القول إن pH الدم يساوي 7","إغفال دور CO₂ في الاتزان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.687Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الترتيب التصاعدي: العصارة المعدية (1.6–1.8) ثم دم الإنسان (7.1–7.7) ثم مياه أحواض قناديل البحر (8.1–8.4). العصارة المعدية وسط حمضي بدرجة كبيرة، والدم قريب من التعادل إلى قاعدي ضعيف، ومياه الحوض قاعدية ضعيفة. وتحتاج إلى مدى ضيق لأن تغير pH خارجه يضر الكائن: في الدم تفقد البروتينات تراكيبها ومقدرتها على أداء عملها، وفي المعدة يُضعف الهضم، ولا تعيش قناديل البحر في غير مدى pH المناسب لها؛ ويحافظ على ذلك وجود محاليل منظمة تقاوم تغير pH.', '["الترتيب التصاعدي الصحيح","طبيعة كل وسط","سبب الحاجة إلى مدى ضيق في كل وسط","دور المحاليل المنظمة"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح","marks":1},{"element":"طبيعة الأوساط الثلاثة","marks":1},{"element":"سبب الحاجة إلى مدى ضيق","marks":1},{"element":"دور المحاليل المنظمة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ترتيب صحيح وطبيعة كل وسط وتفسير صحيح مع ذكر دور المحاليل المنظمة"},{"level":"3 درجات","description":"ثلاثة من العناصر الأربعة"},{"level":"2 درجتان","description":"الترتيب والطبيعة فقط"},{"level":"1 درجة","description":"ترتيب صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الترتيب بين الدم وحوض قناديل البحر","وصف الدم بأنه حمضي","القول إن المحلول المنظم يثبت pH مهما أضيف إليه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.687Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
