insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L4-O09'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المعادلة الأيونية النهائية لتفاعل تعادل حمض النيتريك HNO₃ مع هيدروكسيد البوتاسيوم KOH في محلول مائي؟', null, '["H⁺ + OH⁻ → H₂O","K⁺ + NO₃⁻ → KNO₃","HNO₃ + KOH → KNO₃ + H₂O","HNO₃ + OH⁻ → NO₃⁻ + H₂O"]'::jsonb, 'تطبيق', 'كتابة معادلة أيونية نهائية', 'سهل', 'الكتاب ص 82 — المعادلة الأيونية الكاملة والنهائية'),
('mcq', 2, 'في تفاعل التعادل: HBr(aq) + LiOH(aq) → LiBr(aq) + H₂O(l)، ما الأيونات المتفرجة؟', null, '["H⁺ و OH⁻","Li⁺ و Br⁻","Li⁺ و OH⁻","H⁺ و Br⁻"]'::jsonb, 'تطبيق', 'تحديد الأيونات المتفرجة', 'سهل', 'الكتاب ص 82 — المعادلة الأيونية الكاملة والنهائية'),
('mcq', 3, 'لماذا تكون المعادلة الأيونية النهائية لتعادل أي حمض قوي مع أي قاعدة قوية هي المعادلة نفسها دائمًا؟', null, '["لأن جميع الأحماض القوية والقواعد القوية تنتج الملح نفسه عند تعادلها","لأن الأيونات الموجبة من القاعدة تتحد دائمًا مع الأيونات السالبة من الحمض","لأن الحمض والقاعدة والملح الذائب تكون أيونات، فتُحذف المتفرجة ويبقى تفاعل H⁺ مع OH⁻","لأن الماء الناتج يتفكك كليًا إلى أيونات H⁺ وOH⁻ في المحلول"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 82، 90 — المعادلة الأيونية النهائية (السؤال 48)'),
('mcq', 4, 'ما المعادلة الأيونية الكاملة لتعادل حمض الكبريتيك مع هيدروكسيد الصوديوم وفق المعادلة: H₂SO₄ + 2NaOH → Na₂SO₄ + 2H₂O؟ (حُذفت رموز الحالة للاختصار)', null, '["H₂⁺ + SO₄²⁻ + Na₂⁺ + 2OH⁻ → Na₂⁺ + SO₄²⁻ + 2H₂O","2H⁺ + SO₄²⁻ + 2Na⁺ + 2OH⁻ → Na₂SO₄ + 2H₂O","H⁺ + SO₄²⁻ + Na⁺ + OH⁻ → Na⁺ + SO₄²⁻ + H₂O","2H⁺ + SO₄²⁻ + 2Na⁺ + 2OH⁻ → 2Na⁺ + SO₄²⁻ + 2H₂O"]'::jsonb, 'تطبيق', 'كتابة معادلة أيونية كاملة', 'متوسط', 'الكتاب ص 82، 85 — المعادلة الأيونية الكاملة'),
('mcq', 5, 'حمض الميثانويك HCOOH حمض ضعيف يوجد معظمه في المحلول على هيئة جزيئات غير متأينة. ما المعادلة الأيونية النهائية لتعادله مع NaOH؟', null, '["H⁺(aq) + OH⁻(aq) → H₂O(l)","HCOOH(aq) + OH⁻(aq) → HCOO⁻(aq) + H₂O(l)","HCOOH(aq) + NaOH(aq) → HCOONa(aq) + H₂O(l)","HCOO⁻(aq) + Na⁺(aq) → HCOONa(aq)"]'::jsonb, 'تحليل', 'كتابة معادلة أيونية نهائية لحمض ضعيف', 'صعب', 'الكتاب ص 82، 86 — المعادلة الأيونية النهائية ومثال 2-6'),
('mcq', 6, 'ما المعادلة الكيميائية الموزونة لتعادل حمض الهيدروكلوريك HCl مع هيدروكسيد الكالسيوم Ca(OH)₂؟', null, '["Ca(OH)₂ + HCl → CaCl₂ + H₂O","Ca(OH)₂ + 2HCl → CaCl + 2H₂O","Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O","Ca(OH)₂ + 2HCl → CaCl₂ + H₂O"]'::jsonb, 'تطبيق', 'وزن معادلة تعادل', 'سهل', 'الكتاب ص 81–82 — كتابة معادلات التعادل'),
('mcq', 7, 'كتب طالب المعادلة الأيونية النهائية لتعادل KOH مع HCl على النحو: K⁺(aq) + Cl⁻(aq) → KCl(aq). ما الخطأ في إجابته؟', null, '["K⁺ وCl⁻ متفرجان يُحذفان، والتفاعل الفعلي هو تكوّن الماء من H⁺ وOH⁻","لا خطأ؛ لأن الملح هو الناتج الرئيس في أي تفاعل تعادل","كان يجب أن يُكتب KCl في الحالة الصلبة (s) لأنه ملح","لم يُضف OH⁻ إلى طرفي المعادلة بوصفه أيونًا متفرجًا"]'::jsonb, 'تحليل', 'تحليل خطأ', 'صعب', 'الكتاب ص 82 — المعادلة الأيونية الكاملة والنهائية'),
('essay', 1, 'لتفاعل تعادل حمض الهيدروبروميك HBr مع هيدروكسيد البوتاسيوم KOH في محلول مائي، اكتب: (a) المعادلة الكيميائية الموزونة. (b) المعادلة الأيونية الكاملة. (c) الأيونات المتفرجة. (d) المعادلة الأيونية النهائية.', null, null, 'تطبيق', 'كتابة معادلات', 'متوسط', 'الكتاب ص 82 — ماذا قرأت؟ (تعادل حمض قوي مع قاعدة قوية)'),
('essay', 2, 'يتفاعل هيدروكسيد الكالسيوم Ca(OH)₂ مع حمض النيتريك HNO₃ تفاعل تعادل في محلول مائي. (a) اكتب المعادلة الكيميائية الموزونة. (b) اكتب المعادلة الأيونية الكاملة مع المعاملات. (c) حدد الأيونات المتفرجة. (d) اكتب المعادلة الأيونية النهائية في أبسط صورة، ووضح كيف تحصل عليها.', null, null, 'تطبيق', 'كتابة معادلات مع المعاملات', 'متوسط', 'الكتاب ص 81–82 — كتابة معادلات التعادل'),
('essay', 3, 'قارن بين المعادلة الأيونية النهائية لتعادل HCl مع NaOH، والمعادلة الأيونية النهائية لتعادل حمض الميثانويك HCOOH (حمض ضعيف) مع NaOH. اكتب المعادلتين، وفسّر سبب اختلافهما، وحدد الأيونات المتفرجة في كل تفاعل.', null, null, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 82، 86 — المعادلة الأيونية النهائية ومثال 2-6')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
