insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'HNO₃ حمض قوي وKOH قاعدة قوية وKNO₃ ملح ذائب، فكلها في صورة أيونات. المعادلة الأيونية الكاملة: H⁺ + NO₃⁻ + K⁺ + OH⁻ → K⁺ + NO₃⁻ + H₂O. بحذف الأيونات المتفرجة K⁺ وNO₃⁻ تبقى المعادلة الأيونية النهائية H⁺ + OH⁻ → H₂O.', '["","K⁺ وNO₃⁻ أيونات متفرجة لا تتحد، وKNO₃ ملح ذائب يبقى في صورة أيونات؛ فهذه ليست المعادلة النهائية.","هذه المعادلة الكيميائية للتفاعل، لا المعادلة الأيونية النهائية؛ فلم تُكتب فيها المواد المتأينة في صورة أيونات.","كتب HNO₃ في صورة جزيئات، مع أنه حمض قوي يتأين كليًا في الماء، فيجب كتابته أيونات ثم حذف NO₃⁻ المتفرج."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-17T09:21:20.688Z"}'::jsonb),
('mcq', 2, 1, 'في المعادلة الأيونية الكاملة H⁺ + Br⁻ + Li⁺ + OH⁻ → Li⁺ + Br⁻ + H₂O يظهر Li⁺ وBr⁻ على طرفي المعادلة دون تغيير، فهما الأيونان المتفرجان، ويُحذفان لتبقى H⁺ + OH⁻ → H₂O.', '["H⁺ وOH⁻ هما الأيونان اللذان يتفاعلان فعلًا لتكوين الماء، فليسا متفرجين.","","OH⁻ يتفاعل مع H⁺ ليكوّن الماء؛ والمتفرج من القاعدة هو Li⁺ وحده.","H⁺ يتفاعل مع OH⁻؛ والمتفرج من الحمض هو Br⁻ وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T09:21:20.688Z"}'::jsonb),
('mcq', 3, 2, 'الحمض القوي والقاعدة القوية يتأينان كليًا، والملح الناتج ذائب، فتظهر أيونات الملح على طرفي المعادلة الأيونية الكاملة بوصفها أيونات متفرجة. بحذفها يبقى دائمًا التفاعل H⁺(aq) + OH⁻(aq) → H₂O(l) مهما كان الحمض القوي أو القاعدة القوية.', '["الملح يختلف باختلاف الحمض والقاعدة (NaCl، KNO₃، LiBr…)، والذي لا يتغير هو تكوّن الماء من H⁺ وOH⁻.","هذه الأيونات تبقى ذائبة متفرجة ولا تدخل في التفاعل، ولذلك تُحذف من المعادلة.","","الماء الناتج يُكتب جزيئات H₂O(l)؛ فهو لا يتأين إلا بقدر ضئيل جدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.688Z"}'::jsonb),
('mcq', 4, 3, 'يتأين H₂SO₄ إلى 2H⁺ وSO₄²⁻، ويتفكك 2NaOH إلى 2Na⁺ و2OH⁻، ويتفكك الملح الذائب Na₂SO₄ إلى 2Na⁺ وSO₄²⁻، ويبقى الماء جزيئات. فالمعادلة الأيونية الكاملة: 2H⁺ + SO₄²⁻ + 2Na⁺ + 2OH⁻ → 2Na⁺ + SO₄²⁻ + 2H₂O، وهي موزونة ذريًّا وفي الشحنة.', '["نقل الأرقام السفلية إلى صيغ الأيونات (H₂⁺، Na₂⁺)؛ والصحيح أن الرقم السفلي يصبح معاملًا: 2H⁺ و2Na⁺.","كتب الملح Na₂SO₄ في صورة مركب، مع أنه ملح ذائب يجب أن يُكتب أيونات 2Na⁺ وSO₄²⁻.","أهمل المعاملات، فأصبحت المعادلة غير موزونة في عدد الذرات والشحنات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.689Z"}'::jsonb),
('mcq', 5, 1, 'يُكتب HCOOH جزيئات لأنه حمض ضعيف، وتُكتب NaOH والملح HCOONa أيونات: HCOOH + Na⁺ + OH⁻ → Na⁺ + HCOO⁻ + H₂O. بحذف Na⁺ المتفرج تكون المعادلة النهائية HCOOH(aq) + OH⁻(aq) → HCOO⁻(aq) + H₂O(l).', '["هذه المعادلة لتعادل حمض قوي مع قاعدة قوية؛ وتهمل أن HCOOH لا يتأين إلا جزئيًا فيُكتب جزيئات.","","هذه المعادلة الكيميائية للتفاعل؛ فلم تُكتب فيها NaOH والملح الذائب في صورة أيونات ولم تُحذف المتفرجة.","أيونا الملح يبقيان ذائبين ولا يتحدان، وNa⁺ أيون متفرج يُحذف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T09:21:20.689Z"}'::jsonb),
('mcq', 6, 2, 'تفاعل التعادل إحلال مزدوج ينتج ملحًا وماء: Ca²⁺ من القاعدة مع Cl⁻ من الحمض يكوّنان CaCl₂. وكل 1 mol من Ca(OH)₂ يحتوي 2 mol OH⁻ فيحتاج إلى 2 mol HCl وينتج 2 mol H₂O: Ca(OH)₂ + 2HCl → CaCl₂ + 2H₂O، كما في مثال Mg(OH)₂ في الكتاب.', '["غير موزونة: في الطرف الأيسر ذرة Cl واحدة وفي الأيمن ذرتان، ولا تتساوى ذرات H وO.","صيغة الملح خاطئة؛ فأيون Ca²⁺ يحتاج إلى أيوني Cl⁻ فتكون الصيغة CaCl₂.","","وزن Cl لكنه كتب جزيء ماء واحدًا، فلا تتساوى ذرات H (4 مقابل 2) ولا O (2 مقابل 1)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.689Z"}'::jsonb),
('mcq', 7, 0, 'أيونا K⁺ وCl⁻ يظهران على طرفي المعادلة الأيونية الكاملة دون تغيير، فهما متفرجان يجب حذفهما، لا كتابتهما متفاعلين. والتغير الحقيقي هو اتحاد H⁺ مع OH⁻: H⁺(aq) + OH⁻(aq) → H₂O(l).', '["","الملح KCl ذائب ويبقى أيونات K⁺ وCl⁻ لا تتغير، فلا يمثل التغير الكيميائي الحادث.","KCl ملح ذائب في الماء فيبقى في صورة أيونات، ولا يترسب.","OH⁻ ليس متفرجًا؛ فهو يتفاعل مع H⁺ ويُستهلك لتكوين الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.689Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) HBr(aq) + KOH(aq) → KBr(aq) + H₂O(l). (b) H⁺(aq) + Br⁻(aq) + K⁺(aq) + OH⁻(aq) → K⁺(aq) + Br⁻(aq) + H₂O(l). (c) K⁺ وBr⁻ لأنهما يظهران على طرفي المعادلة دون تغيير. (d) H⁺(aq) + OH⁻(aq) → H₂O(l).', '["معادلة كيميائية موزونة بنواتجها الملح KBr والماء","كتابة الحمض القوي والقاعدة القوية والملح الذائب أيونات والماء جزيئات","تحديد K⁺ وBr⁻ أيونات متفرجة","المعادلة النهائية H⁺ + OH⁻ → H₂O"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة الكيميائية الموزونة","marks":1},{"element":"المعادلة الأيونية الكاملة","marks":1},{"element":"الأيونات المتفرجة","marks":1},{"element":"المعادلة الأيونية النهائية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلات الثلاث صحيحة وموزونة مع تحديد المتفرجين"},{"level":"3 درجات","description":"ثلاثة عناصر صحيحة"},{"level":"2 درجتان","description":"عنصران صحيحان، كأن تصح المعادلة الكيميائية والنهائية فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["كتابة KBr مركبًا غير متفكك في المعادلة الأيونية الكاملة","عدّ OH⁻ أو H⁺ من الأيونات المتفرجة","كتابة الماء أيونات H⁺ وOH⁻ في النواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-17T09:21:20.690Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) Ca(OH)₂(aq) + 2HNO₃(aq) → Ca(NO₃)₂(aq) + 2H₂O(l). (b) Ca²⁺ + 2OH⁻ + 2H⁺ + 2NO₃⁻ → Ca²⁺ + 2NO₃⁻ + 2H₂O. (c) Ca²⁺ وNO₃⁻. (d) بحذف المتفرجين تبقى 2H⁺ + 2OH⁻ → 2H₂O، وبقسمة المعاملات على 2: H⁺(aq) + OH⁻(aq) → H₂O(l).', '["معادلة موزونة بمعامل 2 لكل من HNO₃ والماء","معادلة أيونية كاملة بمعاملات صحيحة (2OH⁻، 2H⁺، 2NO₃⁻)","تحديد Ca²⁺ وNO₃⁻ متفرجين","حذف المتفرجين ثم تبسيط المعاملات للوصول إلى H⁺ + OH⁻ → H₂O"]'::jsonb, '["Ca(OH)₂ يعطي 2OH⁻، فيلزم 2HNO₃ وينتج 2H₂O","تفكيك المواد المتأينة: Ca²⁺ + 2OH⁻ + 2H⁺ + 2NO₃⁻ → Ca²⁺ + 2NO₃⁻ + 2H₂O","حذف Ca²⁺ و2NO₃⁻ من الطرفين: 2H⁺ + 2OH⁻ → 2H₂O","القسمة على 2: H⁺ + OH⁻ → H₂O"]'::jsonb, '[{"element":"المعادلة الكيميائية الموزونة","marks":1},{"element":"المعادلة الأيونية الكاملة بالمعاملات","marks":2},{"element":"الأيونات المتفرجة","marks":1},{"element":"المعادلة النهائية المبسطة مع التوضيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع المعادلات صحيحة وموزونة مع التبسيط والتوضيح"},{"level":"4 درجات","description":"خطأ واحد بسيط في المعاملات أو نقص في التوضيح"},{"level":"3 درجات","description":"المعادلة الكيميائية والنهائية صحيحتان والأيونية الكاملة ناقصة"},{"level":"1–2 درجة","description":"معادلة واحدة أو عنصران صحيحان"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["كتابة الصيغة Ca(NO₃) بدلًا من Ca(NO₃)₂","كتابة OH₂⁻ بدلًا من 2OH⁻","ترك المعادلة النهائية 2H⁺ + 2OH⁻ → 2H₂O دون تبسيط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T09:21:20.690Z"}'::jsonb),
('essay', 3, null::int, null, null, 'HCl + NaOH: المعادلة النهائية H⁺(aq) + OH⁻(aq) → H₂O(l)، والمتفرجان Na⁺ وCl⁻. HCOOH + NaOH: المعادلة النهائية HCOOH(aq) + OH⁻(aq) → HCOO⁻(aq) + H₂O(l)، والمتفرج Na⁺ فقط. سبب الاختلاف: HCl حمض قوي يتأين كليًا فيُكتب H⁺ وCl⁻، أما HCOOH فحمض ضعيف يبقى معظمه جزيئات غير متأينة فيُكتب في صورة جزيء، ولا يكون HCOO⁻ متفرجًا لأنه يتكون في التفاعل.', '["المعادلة النهائية لتعادل HCl مع NaOH","المعادلة النهائية لتعادل HCOOH مع NaOH","تحديد المتفرجين: Na⁺ وCl⁻ في الأول، وNa⁺ في الثاني","التفسير بقوة الحمض ودرجة تأينه"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة HCl مع NaOH والمتفرجان","marks":1},{"element":"معادلة HCOOH مع NaOH والمتفرج","marks":2},{"element":"تفسير الاختلاف بالتأين الكلي مقابل الجزئي","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"المعادلتان صحيحتان والمتفرجون محددون والتفسير مرتبط بقوة الحمض"},{"level":"3–4 درجات","description":"المعادلتان صحيحتان مع تفسير ناقص أو خطأ في المتفرجين"},{"level":"1–2 درجة","description":"معادلة واحدة صحيحة فقط"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["كتابة H⁺ + OH⁻ → H₂O للحمض الضعيف أيضًا","عدّ HCOO⁻ أيونًا متفرجًا","التفسير بأن NaOH قاعدة ضعيفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T09:21:20.690Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
