from (values
('mcq', 1, 3, 'في خطوات المعايرة تُملأ السحاحة بمحلول المعايرة المعلوم تركيزه، ويسمى هذا المحلول المحلول القياسي.', '["المحلول المنظم يقاوم تغير pH، وليس هو المحلول المعلوم التركيز المستعمل في المعايرة.","المحلول المشبع يحتوي على أكبر كمية مذابة عند درجة حرارة معينة، ولا علاقة لذلك بمعرفة تركيزه في المعايرة.","المحلول المجهول هو الذي يوضع في الكأس ويُراد تحديد تركيزه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.691Z"}'::jsonb),
('mcq', 2, 0, 'المعايرة طريقة لتحديد تركيز محلول ما بتفاعل حجم معلوم منه مع محلول تركيزه معلوم؛ فلإيجاد تركيز حمض يُعاير بمحلول قاعدي معلوم التركيز، والعكس.', '["","تحضير المحلول المنظم ليس غرض المعايرة؛ فالمعايرة تُستعمل لتحديد التركيز.","المعايرة تعتمد على تفاعل التعادل وحجم المحلول القياسي، لا على التوصيل الكهربائي.","لا يُفصل الملح في المعايرة؛ المطلوب معرفة حجم المحلول القياسي اللازم للتعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T09:21:20.691Z"}'::jsonb),
('mcq', 3, 1, 'يوضع حجم معين من المحلول المجهول في الكأس ويُقاس pH الابتدائي (3)، ثم تُملأ السحاحة بالمحلول القياسي (2)، ثم يضاف كاشف مناسب ويُضاف المحلول القياسي ببطء مع تسجيل pH بعد كل إضافة (1)، ويُستمر حتى نقطة التكافؤ (4).', '["لا يمكن إضافة المحلول القياسي قبل ملء السحاحة به.","","بدأ بالإضافة قبل وضع الحمض في الكأس وقبل ملء السحاحة.","جعل الوصول إلى نقطة التكافؤ قبل إضافة المحلول القياسي، مع أن التكافؤ نتيجة للإضافة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.691Z"}'::jsonb),
('mcq', 4, 2, 'قرب نقطة التكافؤ تُستهلك أيونات H⁺ كلها تقريبًا، فتؤدي إضافة حجم صغير جدًا من القاعدة إلى ارتفاع حاد في pH؛ لذا تُضاف القاعدة ببطء حتى لا يُتجاوز حجم التكافؤ ويُقرأ حجم المحلول القياسي بدقة.', '["تركيز المحلول في السحاحة لا يتأثر بسرعة خروجه منها.","الكاشف يتغير لونه تبعًا لقيمة pH، لا لسرعة إضافة المحلول.","","تفاعل التعادل سريع؛ والبطء مطلوب لدقة قياس الحجم لا لبطء التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.691Z"}'::jsonb),
('mcq', 5, 3, 'تُغمس أقطاب مقياس pH في المحلول فتُقرأ قيمته الابتدائية، ثم تُقرأ قيمة pH وتسجل بعد كل إضافة؛ أي إن المقياس يُستعمل لمراقبة التغير في قيم pH في أثناء المعايرة.', '["حجم المحلول المضاف يُقرأ من تدريج السحاحة، لا من مقياس pH.","مقياس pH أداة قياس فقط، ولا يؤثر في سرعة التفاعل.","المقياس لا يثبت pH؛ بل إن pH يتغير مع كل إضافة، وهذا ما يسجله المقياس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T09:21:20.691Z"}'::jsonb),
('mcq', 6, 0, 'الحجم المضاف = القراءة النهائية − القراءة الابتدائية = 18.78 − 0.50 = 18.28 mL، وهو الحجم الذي تبينه القراءة الدقيقة للسحاحة في الشكل 2-25.', '["","جمع القراءتين (18.78 + 0.50) بدل طرح القراءة الابتدائية من النهائية.","عدّ القراءة النهائية هي الحجم المضاف، ونسي طرح القراءة الابتدائية 0.50 mL.","هذا حجم محلول الحمض في الدورق، لا حجم المحلول القياسي المضاف من السحاحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.692Z"}'::jsonb),
('mcq', 7, 1, 'يُضاف المحلول القياسي ببطء، فيتحول الفينولفثالين إلى اللون الوردي موضعيًا، لكن اللون يختفي عند تحريك المحلول لأن القاعدة تتعادل مع الحمض المتبقي؛ ويُستمر في الإضافة حتى يصل إلى نقطة النهاية حين يثبت اللون الوردي الفاتح.', '["نقطة النهاية يدل عليها لون ثابت لا يختفي بالتحريك؛ واختفاء اللون يعني بقاء حمض لم يتعادل.","","الفينولفثالين مناسب لمعايرة حمض ضعيف بقاعدة قوية؛ واختفاء اللون سلوك طبيعي قبل نقطة النهاية.","اللون الموضعي يظهر لزيادة القاعدة موضعيًا، ولا يدل على خطأ في تركيز المحلول القياسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.692Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) يوضع حجم معين معلوم من محلول HCl في كأس (أو دورق)، وتُغمس أقطاب مقياس pH فيه وتُسجل قيمة pH الابتدائية. 2) تُملأ السحاحة بالمحلول القياسي NaOH (0.100 M) وتُسجل القراءة الابتدائية. 3) تُضاف قطرتان من كاشف مناسب (كالبروموثيمول الأزرق لمعايرة حمض قوي بقاعدة قوية)، ثم تُضاف أحجام معلومة من NaOH ببطء مع الخلط، ويُقرأ pH ويُسجل بعد كل إضافة. 4) يُستمر حتى الوصول إلى نقطة التكافؤ التي يتساوى عندها عدد مولات H⁺ مع مولات OH⁻ (يتغير لون الكاشف ويرتفع pH ارتفاعًا حادًا). 5) تُسجل قراءة السحاحة النهائية بدقة لمعرفة حجم NaOH المستعمل، ومنه ومن تركيزه وحجم الحمض يُحسب التركيز المجهول.', '["وضع حجم معلوم من المجهول وقياس pH الابتدائي","ملء السحاحة بالمحلول القياسي","إضافة الكاشف ثم المحلول القياسي ببطء مع تسجيل pH","الاستمرار حتى نقطة التكافؤ","تسجيل حجم المحلول القياسي المستعمل بدقة"]'::jsonb, '[]'::jsonb, '[{"element":"وضع المجهول وقياس pH الابتدائي","marks":1},{"element":"ملء السحاحة بالمحلول القياسي","marks":1},{"element":"إضافة الكاشف والإضافة البطيئة مع التسجيل","marks":1},{"element":"الوصول إلى نقطة التكافؤ","marks":1},{"element":"تسجيل حجم المحلول القياسي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الخطوات كاملة ومرتبة مع ذكر القياس النهائي"},{"level":"3–4 درجات","description":"خطوة واحدة أو اثنتان ناقصتان أو الترتيب مضطرب قليلًا"},{"level":"1–2 درجة","description":"ذكر خطوة أو اثنتين فقط"},{"level":"صفر","description":"إجابة لا تصف المعايرة"}]'::jsonb, '["ملء السحاحة بالمحلول المجهول مع وضع القياسي في الكأس دون توضيح","نسيان تسجيل الحجم المستعمل","إضافة كمية كبيرة من الكاشف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.692Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) لتوفير خلفية مناسبة تساعد على رؤية التغير في لون الكاشف بوضوح عند نقطة النهاية. (b) لأن حجم المحلول المضاف يُقرأ من السحاحة، وبمعرفة تركيزه يمكن حساب عدد مولاته اللازمة للتعادل ومنها تركيز المجهول. (c) لأن اللون الذي يختفي عند التحريك يعني أن القاعدة المضافة تعادلت مع حمض ما زال موجودًا، ونقطة النهاية هي التي يثبت عندها اللون الوردي الفاتح.', '["الورقة البيضاء لوضوح رؤية تغير اللون","المحلول القياسي في السحاحة لأن حجمه المضاف وتركيزه معلومان","ثبات اللون هو علامة نقطة النهاية؛ اختفاؤه يعني بقاء حمض"]'::jsonb, '[]'::jsonb, '[{"element":"تعليل (a)","marks":1},{"element":"تعليل (b)","marks":1},{"element":"تعليل (c)","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التعليلات الثلاثة صحيحة"},{"level":"درجتان","description":"تعليلان صحيحان"},{"level":"1 درجة","description":"تعليل واحد صحيح"},{"level":"صفر","description":"لا تعليل صحيح"}]'::jsonb, '["القول إن الورقة البيضاء تمنع انسكاب المحلول","القول إن المحلول القياسي يوضع في السحاحة لأنه أكثر تركيزًا","التوقف عند أول لون يظهر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.692Z"}'::jsonb),
('essay', 3, null::int, null, null, 'توضع في السحاحة محلول HCl القياسي (0.1000 M) وتُسجل قراءتها الابتدائية. يُقاس حجم معلوم من NaOH المجهول (مثلًا 25.00 mL) ويوضع في دورق مخروطي (أو كأس فيها أقطاب مقياس pH) فوق ورقة بيضاء، وتُضاف قطرتان من كاشف يتغير لونه عند نقطة التكافؤ (البروموثيمول الأزرق لأن التفاعل بين قاعدة قوية وحمض قوي ونقطة تكافئه عند pH = 7). يُضاف الحمض من السحاحة ببطء مع التحريك، وتُسجل قيم pH بعد كل إضافة إن استُعمل المقياس، وتُبطأ الإضافة قطرة قطرة قرب نقطة النهاية. يُتوقف عند تغير لون الكاشف تغيرًا ثابتًا (نقطة النهاية) أو عند الارتفاع/الانخفاض الحاد في pH. تُسجل القراءة النهائية للسحاحة، فيُحسب حجم HCl المستعمل، ويُستعمل مع تركيزه وحجم القاعدة لحساب تركيز NaOH.', '["HCl القياسي في السحاحة وحجم معلوم من NaOH في الدورق","الأدوات: سحاحة، دورق/كأس، ماصة أو مخبار، مقياس pH أو كاشف","اختيار كاشف مناسب مع التعليل","الإضافة البطيئة والتوقف عند ثبات تغير اللون أو القفزة في pH","تسجيل الحجم الابتدائي والنهائي للسحاحة وحجم القاعدة"]'::jsonb, '[]'::jsonb, '[{"element":"توزيع المحلولين بين السحاحة والدورق","marks":1},{"element":"الأدوات والكاشف المناسب","marks":1},{"element":"طريقة الإضافة ومعيار التوقف","marks":1},{"element":"القياسات المسجلة وكيف تُستعمل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصميم كامل ومنطقي يشمل المحاليل والأدوات والكاشف ومعيار التوقف والقياسات"},{"level":"3 درجات","description":"تصميم صحيح ينقصه عنصر واحد"},{"level":"درجتان","description":"عنصران صحيحان فقط"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"تصميم لا يحقق الغرض"}]'::jsonb, '["وضع المحلول المجهول في السحاحة دون معرفة حجمه في الدورق","عدم قياس حجم القاعدة بدقة","اختيار كاشف لا يتغير لونه قرب نقطة التكافؤ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.692Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L4-O10') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L4-O11'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بنقطة نهاية المعايرة؟', null, '["النقطة التي يتساوى عندها عدد مولات H⁺ مع عدد مولات OH⁻","النقطة التي تكون عندها قيمة pH تساوي 7 دائمًا","النقطة التي يتغير عندها لون الكاشف","النقطة التي ينفد عندها المحلول القياسي من السحاحة"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 85 — الكواشف ونقطة نهاية المعايرة'),
('mcq', 2, 'أيّ العبارات الآتية تصف نقطة التكافؤ في معايرة حمض بقاعدة؟', null, '["يتغير عندها لون الكاشف المضاف إلى الدورق","يتساوى عندها حجم الحمض مع حجم القاعدة المضافة","يبدأ عندها pH المحلول في الانخفاض التدريجي","يتساوى عندها عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة"]'::jsonb, 'فهم', 'تمييز مفهوم', 'متوسط', 'الكتاب ص 83 — نقطة التكافؤ'),
('mcq', 3, 'ما الاسم الآخر الذي تُعرف به نقطة التكافؤ في معايرة حمض قوي بقاعدة قوية؟', null, '["نقطة التعادل","نقطة النهاية","نقطة الاتزان","نقطة التشبع"]'::jsonb, 'تذكر', 'مصطلح', 'سهل', 'الكتاب ص 85 — الكواشف ونقطة نهاية المعايرة'),
('mcq', 4, 'متى تكون نقطة النهاية مؤشرًا دقيقًا على نقطة التكافؤ في معايرة ما؟', null, '["عندما تُضاف كمية كبيرة من الكاشف إلى الدورق","عندما يتغير لون الكاشف في مدى pH يشمل قيمة pH عند نقطة التكافؤ","عندما تكون قيمة pH عند نقطة التكافؤ أكبر من 7","عندما يُضاف المحلول القياسي بسرعة كبيرة"]'::jsonb, 'فهم', 'شرط', 'متوسط', 'الكتاب ص 85 — الكواشف ونقطة نهاية المعايرة'),
('mcq', 5, 'استُعمل الميثيل البرتقالي (مدى تغير لونه من pH 3.2 إلى 4.4) في معايرة حمض ضعيف بقاعدة قوية تقع نقطة تكافؤها عند pH ≈ 8.2. ماذا تتوقع؟', null, '["يتغير اللون بعد تجاوز نقطة التكافؤ، فيكون الحجم المقروء أكبر","تتطابق نقطة النهاية مع نقطة التكافؤ تمامًا","يتغير اللون قبل نقطة التكافؤ، فيكون الحجم المقروء أقل من حجم التكافؤ","لا يتغير لون الكاشف أبدًا في أثناء المعايرة"]'::jsonb, 'تحليل', 'تنبؤ وتفسير', 'صعب', 'الكتاب ص 85 — الكواشف ونقطة نهاية المعايرة'),
('mcq', 6, 'أُجريت المعايرة نفسها مرتين باستعمال كاشفين مختلفين. أيّ مما يأتي يمكن أن يختلف بين التجربتين؟', null, '["موقع نقطة التكافؤ في المعايرة","عدد مولات القاعدة اللازمة لتعادل الحمض","صيغة الملح الناتج من تفاعل التعادل","موقع نقطة النهاية (الحجم الذي يتغير عنده اللون)"]'::jsonb, 'فهم', 'تمييز مفهومين', 'متوسط', 'الكتاب ص 85 — الكواشف ونقطة نهاية المعايرة'),
('mcq', 7, 'في معايرة حمض قوي بقاعدة قوية باستعمال البروموثيمول الأزرق، لماذا تتطابق نقطة النهاية تقريبًا مع نقطة التكافؤ؟', null, '["لأن لونه يتغير في مدى (6.0–7.6) يشمل pH = 7 عند نقطة التكافؤ","لأن البروموثيمول الأزرق قاعدة قوية تتفاعل مع الحمض","لأن نقطة النهاية ونقطة التكافؤ اسمان لمفهوم واحد","لأن لون البروموثيمول الأزرق لا يتأثر بقيمة pH"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 83–84 — الشكلان 2-22 و2-24'),
('essay', 1, 'اشرح الفرق بين نقطة التكافؤ ونقطة نهاية المعايرة، ولماذا يجب أن تقعا عند الموضع نفسه تقريبًا في المعايرة الجيدة؟', null, null, 'فهم', 'مقارنة مفهومين', 'متوسط', 'الكتاب ص 83، 85، 90 — السؤال 49'),
('essay', 2, 'عاير طالبان 25.00 mL من محلول HCOOH بمحلول NaOH تركيزه 0.1000 M. استعمل الأول الفينولفثالين (مدى تغير لونه 8.2–10.0) فتغير اللون عند 18.28 mL، واستعمل الثاني الميثيل البرتقالي (3.2–4.4) فتغير اللون عند نحو 15 mL. علمًا أن نقطة التكافؤ في هذه المعايرة تقع بين pH 8 و9: (a) أيّ القراءتين تمثل حجم التكافؤ؟ (b) فسّر سبب اختلاف القراءتين مستعملًا مفهومي نقطة النهاية ونقطة التكافؤ. (c) ما أثر استعمال قراءة الطالب الثاني في تركيز الحمض المحسوب؟', null, null, 'تحليل', 'تحليل بيانات تجريبية', 'صعب', 'الكتاب ص 83–85 — الشكلان 2-22b و2-25'),
('essay', 3, 'قال طالب: «نقطة التكافؤ تكون دائمًا عند pH = 7، ولذلك تتطابق نقطة النهاية مع نقطة التكافؤ مهما كان الكاشف المستعمل». قوّم هذه العبارة بجزأيها، مع ذكر مثال من الكتاب.', null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 83–85 — نقطة التكافؤ ونقطة النهاية')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
