insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تسمى النقطة التي يتغير عندها لون الكاشف نقطة نهاية المعايرة، أما تساوي مولات الحمض والقاعدة فهو نقطة التكافؤ.', '["هذا تعريف نقطة التكافؤ، لا نقطة النهاية.","نقطة النهاية مرتبطة بلون الكاشف، وقد تكون عند pH أقل من 7 أو أكبر منه.","","نفاد المحلول من السحاحة لا علاقة له بنهاية التفاعل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.693Z"}'::jsonb),
('mcq', 2, 3, 'نقطة التكافؤ هي النقطة التي يتساوى عندها عدد مولات أيونات H⁺ من الحمض مع عدد مولات أيونات OH⁻ من القاعدة، وتتحدد بكميات المواد المتفاعلة لا بلون الكاشف.', '["تغير لون الكاشف يحدد نقطة النهاية، وقد لا يتطابق تمامًا مع نقطة التكافؤ.","التكافؤ تساوٍ في عدد المولات لا في الحجوم؛ فالحجمان يختلفان إذا اختلف التركيزان.","عند إضافة قاعدة إلى حمض يرتفع pH ارتفاعًا حادًا عند نقطة التكافؤ، لا ينخفض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T09:21:20.693Z"}'::jsonb),
('mcq', 3, 0, 'تسمى نقطة التكافؤ نقطة التعادل في حالة تفاعل الأحماض والقواعد القوية، لأن المحلول عندها يكون متعادلًا (pH = 7).', '["","نقطة النهاية مرتبطة بتغير لون الكاشف، وهي مفهوم مختلف وإن اقتربت من نقطة التكافؤ.","الاتزان حالة تتساوى فيها سرعتا التفاعلين الأمامي والعكسي، وليس اسمًا لنقطة التكافؤ.","التشبع مفهوم يخص الذائبية، لا المعايرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T09:21:20.693Z"}'::jsonb),
('mcq', 4, 1, 'لكل كاشف مدى pH يتغير لونه عنده، ولذلك يجب اختيار كاشف يغير لونه عند نقطة التكافؤ؛ فإذا شمل مدى تغير اللون قيمة pH عند التكافؤ تطابقت نقطة النهاية مع نقطة التكافؤ تقريبًا.', '["زيادة كمية الكاشف لا تغير قيمة pH التي يتغير عندها لونه، فلا تجعل نقطة النهاية أدق.","","قيمة pH عند التكافؤ وحدها لا تكفي؛ المهم أن يوافقها مدى تغير لون الكاشف.","الإضافة السريعة تؤدي إلى تجاوز نقطة التكافؤ، فتقل الدقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.693Z"}'::jsonb),
('mcq', 5, 2, 'في أثناء إضافة القاعدة يرتفع pH تدريجيًا من قيمة حمضية، فيبلغ المدى 3.2–4.4 قبل وقت طويل من نقطة التكافؤ (8.2). فيتغير لون الكاشف مبكرًا، وتسبق نقطة النهاية نقطة التكافؤ، ويُقرأ حجم أقل من الحجم اللازم فعلًا للتعادل.', '["مدى الميثيل البرتقالي (3.2–4.4) أقل من 8.2، وpH يرتفع في أثناء المعايرة فيبلغ هذا المدى أولًا، أي قبل التكافؤ.","التطابق يتطلب أن يشمل مدى تغير اللون القيمة 8.2، والمدى هنا لا يشملها.","","pH المحلول يمر بالمدى 3.2–4.4 في أثناء ارتفاعه نحو 8.2، فيتغير اللون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.694Z"}'::jsonb),
('mcq', 6, 3, 'نقطة التكافؤ صفة للتفاعل نفسه (تساوي مولات H⁺ وOH⁻)، فتبقى ثابتة. أما نقطة النهاية فهي النقطة التي يتغير عندها لون الكاشف، ولكل كاشف مدى pH خاص به، فقد يختلف موقعها باختلاف الكاشف.', '["نقطة التكافؤ تحددها كميتا الحمض والقاعدة، فلا تتغير بتغيير الكاشف.","مولات القاعدة اللازمة يحددها عدد مولات الحمض والمعادلة الموزونة، لا الكاشف.","الملح يعتمد على الحمض والقاعدة المتفاعلين، ولا يؤثر فيه الكاشف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T09:21:20.694Z"}'::jsonb),
('mcq', 7, 0, 'نقطة التكافؤ في معايرة حمض قوي بقاعدة قوية عند pH = 7، والبروموثيمول الأزرق يتغير لونه بين pH 6.0 و7.6 تقريبًا، فيتغير لونه عند هذه النقطة، ولذلك يُعد كاشفًا مناسبًا لها.', '["","الكواشف أحماض ضعيفة غالبًا، وكميتها ضئيلة لا تؤثر في التعادل.","هما مفهومان مختلفان: الأولى تغير لون الكاشف، والثانية تساوي مولات H⁺ وOH⁻.","الكاشف يتغير لونه بتغير pH، وهذا أساس استعماله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T09:21:20.694Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نقطة التكافؤ: النقطة التي يتساوى عندها عدد مولات H⁺ من الحمض مع عدد مولات OH⁻ من القاعدة، وتحددها كميات المواد المتفاعلة (وتسمى نقطة التعادل في معايرة حمض قوي بقاعدة قوية). نقطة النهاية: النقطة التي يتغير عندها لون الكاشف، وتعتمد على مدى pH الخاص بالكاشف. الكاشف يُستعمل ليدلنا بتغير لونه على أن كمية كافية من المحلول القياسي أُضيفت لتعادل المجهول؛ فإذا لم تتطابق النقطتان كان الحجم المقروء أقل أو أكبر من حجم التكافؤ، فيُحسب تركيز خاطئ. لذا يُختار كاشف يتغير لونه عند pH نقطة التكافؤ.', '["تعريف نقطة التكافؤ","تعريف نقطة النهاية","دور الكاشف في الدلالة على التكافؤ","أثر عدم التطابق في دقة النتيجة واختيار الكاشف"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف نقطة التكافؤ","marks":1},{"element":"تعريف نقطة النهاية","marks":1},{"element":"دور الكاشف","marks":1},{"element":"أثر عدم التطابق واختيار الكاشف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريفان صحيحان مع تفسير ضرورة التطابق وأثره"},{"level":"3 درجات","description":"التعريفان صحيحان وتفسير ناقص"},{"level":"درجتان","description":"التعريفان فقط"},{"level":"1 درجة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["تعريف نقطة التكافؤ بأنها النقطة التي يكون عندها pH = 7 دائمًا","الخلط بين التعريفين","القول إن نوع الكاشف يغير موقع نقطة التكافؤ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.694Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) قراءة الطالب الأول 18.28 mL. (b) نقطة التكافؤ واحدة في التجربتين لأنها تعتمد على مولات الحمض والقاعدة، وتقع عند pH بين 8 و9. مدى الفينولفثالين (8.2–10.0) يشمل هذه القيمة فتطابقت نقطة النهاية مع التكافؤ. أما الميثيل البرتقالي فيتغير لونه عند pH 3.2–4.4، وهي قيمة يبلغها المحلول مبكرًا في أثناء ارتفاع pH، فوقعت نقطة النهاية قبل نقطة التكافؤ بكثير. (c) يكون حجم القاعدة المقروء أقل من الحقيقي، فتُحسب مولات الحمض أقل، ويكون تركيز الحمض المحسوب أقل من التركيز الحقيقي.', '["تحديد 18.28 mL حجمًا للتكافؤ","التكافؤ ثابت ويقع بين pH 8 و9","مدى الفينولفثالين يشمل pH التكافؤ","الميثيل البرتقالي يتغير لونه قبل التكافؤ","التركيز المحسوب أقل من الحقيقي"]'::jsonb, '[]'::jsonb, '[{"element":"(a) تحديد القراءة الصحيحة","marks":1},{"element":"(b) تفسير بمقارنة مدى كل كاشف بنقطة التكافؤ","marks":3},{"element":"(c) أثر الخطأ في التركيز","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح وتفسير كامل يميز بين النقطتين وأثر صحيح في التركيز"},{"level":"3–4 درجات","description":"تحديد صحيح مع تفسير ناقص أو أثر غير مذكور"},{"level":"1–2 درجة","description":"تحديد القراءة الصحيحة فقط أو تفسير جزئي"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["القول إن نقطة التكافؤ تغيرت بتغيير الكاشف","اختيار القراءة الأصغر لأنها وصلت أولًا","القول إن التركيز المحسوب يكون أكبر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.695Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجزء الأول غير صحيح: نقطة التكافؤ تكون عند pH = 7 في معايرة حمض قوي بقاعدة قوية فقط (مثل HCl مع NaOH)، أما في معايرة حمض ضعيف بقاعدة قوية (مثل HCOOH مع NaOH) فتقع بين pH 8 و9، وبعض المعايرات نقطة تكافئها أقل من 7؛ بسبب تفاعل الأملاح الناتجة مع الماء. الجزء الثاني غير صحيح: نقطة النهاية هي نقطة تغير لون الكاشف، ولكل كاشف مدى pH خاص، فلا تتطابق مع نقطة التكافؤ إلا إذا شمل مدى الكاشف قيمة pH عند التكافؤ؛ لذا يُختار البروموثيمول الأزرق لمعايرة حمض قوي بقاعدة قوية والفينولفثالين لمعايرة حمض ضعيف بقاعدة قوية.', '["الحكم بخطأ الجزء الأول مع التعليل","مثال من الكتاب (HCOOH مع NaOH بين 8 و9)","الحكم بخطأ الجزء الثاني مع التعليل","مثال على اختيار الكاشف المناسب"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم الجزء الأول مع التعليل","marks":1},{"element":"مثال لنقطة تكافؤ ≠ 7","marks":1},{"element":"تقويم الجزء الثاني مع التعليل","marks":1},{"element":"مثال على كاشف مناسب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح للجزأين مع تعليل ومثالين"},{"level":"3 درجات","description":"تقويم صحيح للجزأين وينقصه مثال"},{"level":"درجتان","description":"تقويم صحيح لجزء واحد مع تعليله"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"موافقة الطالب على العبارة"}]'::jsonb, '["الموافقة على أن التكافؤ دائمًا عند 7","تقويم الجزء الأول فقط","ذكر أمثلة دون ربطها بمدى الكاشف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.695Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
