from (values
('mcq', 1, 'يبين الجدول قيم pH في أثناء معايرة 50.0 mL من محلول HCl تركيزه 0.100 M بمحلول NaOH تركيزه 0.100 M. عند أي حجم من NaOH تقع نقطة التكافؤ؟', '{"headers":["حجم NaOH المضاف (mL)","pH"],"rows":[["0","1.00"],["25.0","1.48"],["45.0","2.28"],["49.0","3.00"],["50.0","7.00"],["51.0","11.00"],["55.0","11.68"],["60.0","11.96"]]}'::jsonb, '["25.0 mL","50.0 mL","55.0 mL","60.0 mL"]'::jsonb, 'تحليل', 'تحديد نقطة التكافؤ من بيانات', 'متوسط', 'الكتاب ص 83 — منحنيات المعايرة (الشكل 2-22)'),
