('mcq', 3, 'بماذا يتميّز منحنى معايرة حمض قوي بقاعدة قوية عند نقطة التكافؤ؟', null, '["انخفاض حاد في pH عند إضافة حجم صغير جدًا من القاعدة","ثبات pH عند 7 مع إضافة حجوم كبيرة من القاعدة","ارتفاع تدريجي بطيء في pH كبقية أجزاء المنحنى","ارتفاع حاد في pH عند إضافة حجم صغير جدًا من القاعدة"]'::jsonb, 'فهم', 'وصف منحنى', 'سهل', 'الكتاب ص 83 — منحنيات المعايرة (الشكل 2-22)'),
('mcq', 4, 'مقارنة بمنحنى معايرة 50.0 mL من HCl تركيزه 0.100 M بـ NaOH تركيزه 0.100 M، أيّ العبارات تصف منحنى معايرة 50.0 mL من حمض ضعيف تركيزه 0.100 M بالقاعدة نفسها؟', null, '["يبدأ بقيمة pH أعلى، وتقع نقطة تكافئه عند الحجم نفسه وعند pH أكبر من 7","يبدأ بقيمة pH أقل، وتقع نقطة تكافئه عند الحجم نفسه وعند pH = 7","يبدأ بقيمة pH أعلى، ويحتاج إلى حجم أكبر من القاعدة للوصول إلى التكافؤ","يبدأ بقيمة pH أعلى، وتقع نقطة تكافئه عند الحجم نفسه وعند pH أقل من 7"]'::jsonb, 'تحليل', 'مقارنة منحنيين', 'صعب', 'الكتاب ص 83، 87 — منحنيات المعايرة وتميّه الأملاح'),
('mcq', 5, 'يبين الجدول قيم pH في أثناء معايرة 50.0 mL من محلول الأمونيا NH₃ تركيزه 0.100 M بمحلول HCl تركيزه 0.100 M. ماذا تستنتج عن pH عند نقطة التكافؤ؟', '{"headers":["حجم HCl المضاف (mL)","pH"],"rows":[["0","11.12"],["25.0","9.26"],["45.0","8.30"],["49.0","7.57"],["50.0","5.28"],["51.0","3.00"],["55.0","2.32"]]}'::jsonb, '["أكبر من 7؛ لأن الأمونيا مادة قاعدية في الأصل","أقل من 7؛ لأن أيون الأمونيوم الناتج يتميّه منتجًا H₃O⁺","يساوي 7؛ لأن مولات الحمض تساوي مولات القاعدة","أقل من 7؛ لأن أيون الكلوريد الناتج يتميّه منتجًا H₃O⁺"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 83، 87 — منحنيات المعايرة وتميّه الأملاح'),
('mcq', 6, 'يبين الجدول قيم pH في أثناء معايرة 50.0 mL من محلول HCl تركيزه 0.100 M بمحلول NaOH تركيزه 0.100 M. ما مقدار التغير في pH عند زيادة حجم NaOH من 49.0 mL إلى 51.0 mL، مقارنة بالتغير من 0 إلى 45.0 mL؟', '{"headers":["حجم NaOH المضاف (mL)","pH"],"rows":[["0","1.00"],["25.0","1.48"],["45.0","2.28"],["49.0","3.00"],["50.0","7.00"],["51.0","11.00"],["55.0","11.68"],["60.0","11.96"]]}'::jsonb, '["1.28 وحدة مقابل 8.00 وحدات","4.00 وحدات مقابل 1.28 وحدة فقط","8.00 وحدات مقابل 2.28 وحدة","8.00 وحدات مقابل 1.28 وحدة فقط"]'::jsonb, 'تحليل', 'حساب من جدول', 'متوسط', 'الكتاب ص 83 — منحنيات المعايرة (الشكل 2-22)'),
('mcq', 7, 'لماذا لا تقع نقطة التكافؤ عند pH = 7 في جميع معايرات الأحماض والقواعد؟', null, '["لأن مولات الحمض لا تساوي مولات القاعدة عند نقطة التكافؤ","لأن الكاشف المضاف يغير قيمة pH للمحلول عند التكافؤ","لأن الأملاح المتكونة قد تتفاعل مع الماء فتنتج H₃O⁺ أو OH⁻","لأن الماء الناتج من تفاعل التعادل يكون حمضيًا"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 83، 87 — منحنيات المعايرة وتميّه الأملاح'),
('essay', 1, 'قارن بين منحنى معايرة 50.0 mL من HCl تركيزه 0.100 M ومنحنى معايرة 50.00 mL من حمض الميثانويك HCOOH تركيزه 0.1000 M، كلاهما بمحلول NaOH له التركيز نفسه، واذكر اختلافين بينهما مع تفسير كل منهما.', null, null, 'تحليل', 'مقارنة منحنيين', 'سهل', 'الكتاب ص 83 — اختبار الرسم البياني (الشكل 2-22)'),
('essay', 2, 'يبين الجدول قيم pH في أثناء معايرة 50.0 mL من محلول HCl تركيزه 0.100 M بمحلول NaOH تركيزه 0.100 M. (a) حدد حجم NaOH وقيمة pH عند نقطة التكافؤ. (b) وضّح الطريقة التي استعملتها لتحديدها من البيانات. (c) لماذا يكون pH عند هذه النقطة مساويًا 7؟', '{"headers":["حجم NaOH المضاف (mL)","pH"],"rows":[["0","1.00"],["25.0","1.48"],["45.0","2.28"],["49.0","3.00"],["50.0","7.00"],["51.0","11.00"],["55.0","11.68"],["60.0","11.96"]]}'::jsonb, null, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 83 — منحنيات المعايرة (الشكل 2-22)'),
('essay', 3, 'يبين الجدول قيم pH في أثناء معايرة 50.0 mL من محلول NH₃ تركيزه 0.100 M بمحلول HCl تركيزه 0.100 M. (a) حدد موقع نقطة التكافؤ وقيمة pH عندها. (b) فسّر لماذا ينخفض pH في هذه المعايرة بدل أن يرتفع. (c) فسّر قيمة pH عند نقطة التكافؤ بمعادلة. (d) قارن موقع نقطة التكافؤ هنا بموقعها في معايرة حمض قوي بقاعدة قوية.', '{"headers":["حجم HCl المضاف (mL)","pH"],"rows":[["0","11.12"],["25.0","9.26"],["45.0","8.30"],["49.0","7.57"],["50.0","5.28"],["51.0","3.00"],["55.0","2.32"]]}'::jsonb, null, 'تحليل', 'تحليل بيانات وتفسير', 'صعب', 'الكتاب ص 83، 87 — منحنيات المعايرة وتميّه الأملاح')
