from (values
('mcq', 1, 1, 'تقع نقطة التكافؤ في منتصف الارتفاع الحاد في pH: فبين 49.0 mL و51.0 mL قفز pH من 3.00 إلى 11.00، وعند 50.0 mL كان pH = 7.00. ويتفق ذلك مع الحساب: مولات NaOH عند 50.0 mL = مولات HCl = 5.00×10⁻³ mol.', '["عند 25.0 mL لم يتعادل إلا نصف الحمض، وpH ما زال 1.48 ولم تحدث القفزة الحادة.","","عند 55.0 mL يكون في المحلول فائض من NaOH بعد تجاوز نقطة التكافؤ.","اختار الحجم الذي له أعلى pH، مع أن نقطة التكافؤ هي موضع القفزة الحادة لا آخر نقطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-10-17T09:21:20.695Z"}'::jsonb),
('mcq', 2, 2, 'تقع القفزة الحادة بين 49.0 mL و51.0 mL، ونقطة التكافؤ عند 50.0 mL حيث pH = 8.22، أي أكبر من 7. والسبب أن الملح الناتج (NaA) يتكون من قاعدة قوية وحمض ضعيف، فيتميّه أيونه السالب: A⁻ + H₂O ⇌ HA + OH⁻ فيصبح المحلول قاعديًا، كما في معايرة حمض الميثانويك التي تقع نقطة تكافئها بين pH 8 و9.', '["تساوي المولات لا يعني pH = 7؛ فملح الحمض الضعيف قاعدي بسبب التميّه.","عند 51.0 mL يوجد فائض من NaOH؛ أي إن هذه النقطة بعد التكافؤ.","","عند 49.0 mL لم يكتمل التعادل بعد، فهذه نقطة قبل التكافؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (62%)"}],"at":"2026-10-17T09:21:20.696Z"}'::jsonb),
('mcq', 3, 3, 'في أثناء إضافة NaOH يزداد pH تدريجيًا، لكن عندما تُستهلك أيونات H⁺ جميعها تقريبًا يزداد pH على نحو كبير بإضافة حجم صغير جدًا من القاعدة، وهذه الزيادة الحادة تحدث عند نقطة التكافؤ.', '["إضافة القاعدة ترفع pH ولا تخفضه.","pH لا يثبت عند 7؛ بل يمر بها بسرعة في أثناء القفزة.","الارتفاع التدريجي يكون قبل نقطة التكافؤ وبعدها، أما عندها فالارتفاع حاد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.696Z"}'::jsonb),
('mcq', 4, 0, 'الحمض الضعيف يتأين جزئيًا، فتركيز H⁺ فيه أقل ويبدأ منحناه بـ pH أعلى. وعدد مولاته يساوي عدد مولات HCl فيتعادل بالحجم نفسه (50.0 mL). وبسبب تميّه أيون الملح السالب يكون pH عند التكافؤ أكبر من 7 (بين 8 و9 لحمض الميثانويك)، بينما يكون 7 لمعايرة HCl.', '["","الحمض الضعيف يتأين جزئيًا فيكون pH الابتدائي أعلى، ونقطة تكافئه قاعدية لا متعادلة.","مولات الحمضين متساوية، فيلزم الحجم نفسه من القاعدة؛ ضعف الحمض لا يغير عدد مولاته.","نقطة التكافؤ أقل من 7 تكون عند معايرة قاعدة ضعيفة بحمض قوي، لا هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T09:21:20.696Z"}'::jsonb),
('mcq', 5, 1, 'القفزة الحادة (هنا انخفاض لأن الحمض هو المضاف) بين 49.0 mL و51.0 mL، ونقطة التكافؤ عند 50.0 mL حيث pH = 5.28، أي أقل من 7. والسبب أن الملح NH₄Cl ناتج من قاعدة ضعيفة وحمض قوي، فيتميّه NH₄⁺: NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺، فيصبح المحلول حمضيًا.', '["عند التكافؤ تكون الأمونيا قد تعادلت وتحولت إلى NH₄⁺؛ والجدول يبين pH = 5.28.","","تساوي المولات لا يعني التعادل التام؛ فالجدول يبين أن pH عند 50.0 mL هو 5.28.","Cl⁻ أيون من حمض قوي فلا يتفاعل مع الماء؛ والذي يتميّه هو NH₄⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-10-17T09:21:20.696Z"}'::jsonb),
('mcq', 6, 3, 'من 49.0 إلى 51.0 mL: 11.00 − 3.00 = 8.00 وحدات بإضافة 2.0 mL فقط، بينما من 0 إلى 45.0 mL: 2.28 − 1.00 = 1.28 وحدة رغم إضافة 45.0 mL. وهذا يبين أن التغير الحاد في pH يتركز حول نقطة التكافؤ.', '["عكس المقارنة؛ فالتغير الكبير (8.00) حدث في المدى الصغير قرب التكافؤ.","حسب التغير من 49.0 إلى 50.0 mL فقط (7.00 − 3.00) بدل المدى المطلوب حتى 51.0 mL.","أخذ قيمة pH عند 45.0 mL (2.28) بدل الفرق بينها وبين القيمة الابتدائية 1.00.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-10-17T09:21:20.697Z"}'::jsonb),
('mcq', 7, 2, 'قد تظن أن نقطة التكافؤ يجب أن تكون عند pH = 7، لكن بعض المعايرات نقطة تكافئها أقل من 7 وبعضها أكبر؛ وتحدث هذه الاختلافات بسبب تفاعلات الأملاح المتكونة مع الماء (تميّه الأملاح).', '["تعريف نقطة التكافؤ هو تساوي مولات H⁺ وOH⁻، فهذا السبب يناقض التعريف.","كمية الكاشف ضئيلة جدًا، ولا تحدد قيمة pH عند التكافؤ.","","الماء الناتج متعادل؛ والذي يحدد pH عند التكافؤ هو الملح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.697Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الاختلاف الأول: قيمة pH الابتدائية؛ منحنى HCl يبدأ عند pH = 1.00، ومنحنى HCOOH يبدأ عند pH أعلى، لأن HCl حمض قوي متأين كليًا، أما HCOOH فحمض ضعيف متأين جزئيًا فتركيز H⁺ فيه أقل. الاختلاف الثاني: pH عند نقطة التكافؤ؛ يساوي 7 لمعايرة HCl، ويقع بين 8 و9 لمعايرة HCOOH، لأن أيون الميثانوات HCOO⁻ في الملح الناتج يتميّه: HCOO⁻ + H₂O ⇌ HCOOH + OH⁻. (ويُقبل: الارتفاع الحاد في pH عند التكافؤ أقصر في منحنى الحمض الضعيف، أو اختلاف الكاشف المناسب: البروموثيمول الأزرق مقابل الفينولفثالين.) وفي الحالتين يكون حجم التكافؤ نفسه تقريبًا لأن مولات الحمضين متساوية.', '["اختلاف pH الابتدائي وتفسيره بقوة الحمض","اختلاف pH عند التكافؤ وتفسيره بتميّه الملح"]'::jsonb, '[]'::jsonb, '[{"element":"الاختلاف الأول","marks":1},{"element":"تفسيره","marks":1},{"element":"الاختلاف الثاني","marks":1},{"element":"تفسيره","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اختلافان صحيحان مع تفسيرهما"},{"level":"3 درجات","description":"اختلافان صحيحان مع تفسير أحدهما"},{"level":"درجتان","description":"اختلافان دون تفسير أو اختلاف واحد مع تفسيره"},{"level":"1 درجة","description":"اختلاف واحد دون تفسير"},{"level":"صفر","description":"لا اختلاف صحيح"}]'::jsonb, '["القول إن الحمض الضعيف يحتاج حجمًا أكبر من القاعدة","القول إن نقطة التكافؤ للحمض الضعيف أقل من 7","ذكر الاختلاف دون تفسير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T09:21:20.697Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) نقطة التكافؤ عند 50.0 mL من NaOH وpH = 7.00. (b) تتحدد بموقع الارتفاع الحاد في pH: فمن 0 إلى 49.0 mL ارتفع pH من 1.00 إلى 3.00 فقط، أما بين 49.0 و51.0 mL فقفز من 3.00 إلى 11.00؛ ونقطة التكافؤ في منتصف هذه القفزة. ويؤكدها الحساب: مولات HCl = 0.100 × 0.0500 = 5.00×10⁻³ mol، وتلزم 5.00×10⁻³ mol من NaOH أي 50.0 mL. (c) لأن HCl حمض قوي وNaOH قاعدة قوية، والملح الناتج NaCl لا يتفاعل أيوناه مع الماء، فيكون المحلول عند التكافؤ متعادلًا.', '["الحجم 50.0 mL وpH 7.00","تحديدها من موضع القفزة الحادة","تأكيد بتساوي المولات","تعليل pH = 7 بعدم تميّه NaCl"]'::jsonb, '["مولات HCl = 0.100 mol/L × 0.0500 L = 5.00×10⁻³ mol","حجم NaOH اللازم = 5.00×10⁻³ mol ÷ 0.100 mol/L = 0.0500 L = 50.0 mL","القفزة بين 49.0 mL (pH 3.00) و51.0 mL (pH 11.00) تحيط بـ 50.0 mL"]'::jsonb, '[{"element":"(a) الحجم وقيمة pH","marks":1},{"element":"(b) الطريقة: موضع القفزة الحادة أو تساوي المولات","marks":2},{"element":"(c) التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد صحيح وطريقة واضحة وتعليل صحيح"},{"level":"3 درجات","description":"تحديد وطريقة صحيحان وتعليل ناقص"},{"level":"درجتان","description":"تحديد صحيح فقط مع إشارة للقفزة"},{"level":"1 درجة","description":"تحديد الحجم فقط"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["اختيار الحجم الذي له أعلى pH","تحديد النقطة عند 49.0 mL","تعليل pH = 7 بتساوي الحجوم فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-17T09:21:20.697Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) عند 50.0 mL من HCl، حيث pH = 5.28 (منتصف الانخفاض الحاد من 7.57 عند 49.0 mL إلى 3.00 عند 51.0 mL). (b) لأن المضاف من السحاحة حمض يستهلك القاعدة في الدورق، فيقل القاعدي تدريجيًا ثم يصبح المحلول حمضيًا. (c) الملح الناتج NH₄Cl من قاعدة ضعيفة وحمض قوي، فيتميّه أيون الأمونيوم: NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq)، فيكون المحلول حمضيًا (pH < 7). (d) في معايرة حمض قوي بقاعدة قوية تقع نقطة التكافؤ عند pH = 7 لأن الملح لا يتميّه، أما هنا فتقع عند pH أقل من 7.', '["نقطة التكافؤ عند 50.0 mL وpH = 5.28","تفسير انخفاض pH بإضافة الحمض","معادلة تميّه NH₄⁺","المقارنة مع pH = 7 للحمض القوي والقاعدة القوية"]'::jsonb, '[]'::jsonb, '[{"element":"(a) تحديد الموقع والقيمة","marks":1},{"element":"(b) التفسير","marks":1},{"element":"(c) المعادلة والتفسير","marks":2},{"element":"(d) المقارنة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة مع معادلة التميّه"},{"level":"4 درجات","description":"خطأ بسيط في جزء واحد"},{"level":"3 درجات","description":"التحديد والمقارنة صحيحان دون معادلة صحيحة"},{"level":"1–2 درجة","description":"تحديد الموقع فقط أو جزء آخر واحد"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["القول إن pH عند التكافؤ أكبر من 7 لأن NH₃ قاعدة","كتابة تميّه Cl⁻","تحديد التكافؤ عند 51.0 mL"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T09:21:20.698Z"}'::jsonb)
