select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'يجب أن يتغير لون الكاشف عند نقطة التكافؤ. مدى البروموثيمول الأزرق (6.0–7.6) يشمل pH = 7، ولذلك فهو كاشف مناسب لمعايرة حمض قوي بقاعدة قوية.', '["","مداه (3.2–4.4) أقل بكثير من 7، فيتغير لونه قبل نقطة التكافؤ.","مداه (8.2–10.0) لا يشمل 7؛ وهو الكاشف الذي يختاره الكتاب لمعايرة حمض ضعيف بقاعدة قوية.","مداه (10.0–12.0) أعلى بكثير من 7، فيتغير لونه بعد تجاوز نقطة التكافؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-17T09:21:20.698Z"}'::jsonb),
('mcq', 2, 3, 'القيمة 8.7 تقع داخل مدى الفينولفثالين (8.2–10.0)، فيتغير لونه عند نقطة التكافؤ؛ وهو الكاشف المناسب لمعايرة حمض ضعيف بقاعدة قوية كما في الشكل 2-22b.', '["مداه (4.2–6.2) أقل من 8.7، فيتغير لونه قبل الوصول إلى التكافؤ.","مداه (6.0–7.6) يناسب نقطة تكافؤ عند 7، لا عند 8.7.","مداه (3.2–4.4) بعيد جدًا عن 8.7، فتسبق نقطة النهاية نقطة التكافؤ بكثير.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-17T09:21:20.699Z"}'::jsonb),
('mcq', 3, 1, 'نقطة التكافؤ هنا حمضية (5.3) لأن NH₄⁺ الناتج يتميّه منتجًا H₃O⁺، والقيمة 5.3 تقع داخل مدى الميثيل الأحمر (4.2–6.2)، فهو الكاشف المناسب.', '["مداه (8.2–10.0) أعلى من 5.3، فيتغير لونه قبل التكافؤ بينما ما زال المحلول قاعديًا.","","مداه (6.0–7.6) لا يشمل 5.3؛ فهو مناسب لنقطة تكافؤ عند 7.","مداه (9.4–10.6) بعيد جدًا عن 5.3."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-10-17T09:21:20.699Z"}'::jsonb),
('mcq', 4, 2, 'إن عملية اختيار الكاشف الصحيح مهمة جدًا؛ إذ يجب أن يغير الكاشف لونه عند نقطة التكافؤ التي لا تكون دائمًا عند pH = 7، أي أن يشمل مدى تغير لونه قيمة pH عند التكافؤ.', '["نقطة التكافؤ لا تكون دائمًا عند pH = 7، فلا يصلح كاشف واحد لكل المعايرات.","وضوح اللون مفيد، لكنه لا يضمن أن يتغير اللون عند نقطة التكافؤ.","","معظم الكواشف أحماض ضعيفة، وكميتها ضئيلة لا تشارك في التعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T09:21:20.699Z"}'::jsonb),
('mcq', 5, 0, 'المدى 4.2–6.2 حمضي، فيناسب معايرة تقع نقطة تكافئها عند pH أقل من 7، أي معايرة قاعدة ضعيفة بحمض قوي؛ فعند تعادل NH₃ مع HCl يتكون NH₄⁺ الذي يتميّه: NH₄⁺ + H₂O ⇌ NH₃ + H₃O⁺.', '["","نقطة تكافؤ هذه المعايرة عند pH = 7، وهي خارج المدى 4.2–6.2.","نقطة التكافؤ قاعدية (بين 8 و9) لأن أيون الميثانوات يتميّه منتجًا OH⁻.","حمض ضعيف مع قاعدة قوية، فنقطة التكافؤ قاعدية (أكبر من 7) لتميّه F⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.699Z"}'::jsonb),
('mcq', 6, 1, 'في معايرة HCOOH بـ NaOH تقع نقطة التكافؤ بين pH 8 و9، ومدى البروموثيمول الأزرق 6.0–7.6 لا يشملها؛ فيتغير لونه قبل الوصول إلى التكافؤ، ولذلك يُستعمل الفينولفثالين في هذه المعايرة.', '["مداه 6.0–7.6 قريب من التعادل، لا في المحاليل القاعدية القوية.","","نقطة التكافؤ في معايرة حمض ضعيف بقاعدة قوية أكبر من 7 (بين 8 و9).","الكواشف أحماض ضعيفة وتضاف بكميات ضئيلة، فلا تؤثر في حجم التكافؤ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.699Z"}'::jsonb),
('mcq', 7, 3, '(1) حمض قوي وقاعدة قوية: التكافؤ عند pH = 7 ← البروموثيمول الأزرق (6.0–7.6). (2) حمض ضعيف وقاعدة قوية: التكافؤ أكبر من 7 لتميّه CH₃COO⁻ ← الفينولفثالين (8.2–10.0). (3) قاعدة ضعيفة وحمض قوي: التكافؤ أقل من 7 لتميّه NH₄⁺ ← الميثيل الأحمر (4.2–6.2).', '["بدّل بين الأولى والثانية: نقطة تكافؤ الحمض القوي مع القاعدة القوية عند 7 والحمض الضعيف مع القاعدة القوية أكبر من 7.","بدّل بين الثانية والثالثة: الحمض الضعيف مع قاعدة قوية نقطة تكافئه قاعدية، والقاعدة الضعيفة مع حمض قوي نقطة تكافئها حمضية.","افترض أن معايرة الحمض القوي حمضية وأن معايرة القاعدة الضعيفة متعادلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.700Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكاشف المناسب: البروموثيمول الأزرق؛ لأن HCl حمض قوي وNaOH قاعدة قوية فتقع نقطة التكافؤ عند pH = 7 (الملح NaCl لا يتميّه)، ومدى تغير لون البروموثيمول الأزرق (6.0–7.6) يشمل 7، فتتطابق نقطة النهاية مع نقطة التكافؤ. كاشف غير مناسب: الميثيل البرتقالي (3.2–4.4) لأنه يتغير لونه قبل التكافؤ، أو الثيمولفثالين (9.4–10.6) لأنه يتغير بعده.', '["اختيار البروموثيمول الأزرق","pH التكافؤ = 7 لحمض قوي وقاعدة قوية","المدى يشمل 7","ذكر كاشف غير مناسب مع السبب"]'::jsonb, '[]'::jsonb, '[{"element":"اختيار الكاشف","marks":1},{"element":"التعليل بمقارنة المدى بـ pH التكافؤ","marks":1},{"element":"كاشف غير مناسب مع السبب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"اختيار صحيح وتعليل ومثال غير مناسب مع سببه"},{"level":"درجتان","description":"اختيار صحيح مع تعليل فقط"},{"level":"1 درجة","description":"اختيار صحيح دون تعليل"},{"level":"صفر","description":"اختيار خاطئ"}]'::jsonb, '["اختيار الفينولفثالين دون مقارنة مداه بـ 7","التعليل بلون الكاشف لا بمداه","القول إن أي كاشف يصلح لأن التعادل عند 7"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.701Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) NH₄OH(aq) + HBr(aq) → NH₄Br(aq) + H₂O(l). (b) أقل من 7؛ لأن الملح NH₄Br ناتج من قاعدة ضعيفة وحمض قوي، فيتميّه أيون الأمونيوم: NH₄⁺(aq) + H₂O(l) ⇌ NH₃(aq) + H₃O⁺(aq)، بينما Br⁻ لا يتفاعل مع الماء. (c) الميثيل الأحمر (4.2–6.2)؛ لأن مداه حمضي يشمل قيمة pH عند التكافؤ (أقل من 7).', '["معادلة التعادل الموزونة","pH التكافؤ أقل من 7","معادلة تميّه NH₄⁺","اختيار الميثيل الأحمر مع الربط بالمدى"]'::jsonb, '[]'::jsonb, '[{"element":"(a) المعادلة","marks":1},{"element":"(b) الحكم","marks":1},{"element":"(b) معادلة التميّه","marks":1},{"element":"(c) الكاشف","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ في جزء واحد"},{"level":"درجتان","description":"المعادلة والحكم فقط"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["الحكم بأن pH أكبر من 7 لأن NH₄OH قاعدة","كتابة تميّه Br⁻","اختيار الفينولفثالين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.701Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) اختيار غير مناسب؛ لأن مدى الفينولفثالين (8.2–10.0) لا يشمل pH نقطة التكافؤ (5.3). (b) المحلول قاعدي في البداية فيكون الكاشف ورديًا، ومع إضافة الحمض ينخفض pH فيختفي اللون عند pH ≈ 8.2، أي بعد نحو 45 mL فقط، قبل نقطة التكافؤ (50.0 mL). فيكون الحجم المقروء أقل من حجم التكافؤ، وتُحسب مولات NH₃ أقل، فيكون التركيز المحسوب أقل من 0.100 M. (c) الميثيل الأحمر (4.2–6.2) لأن مداه يشمل 5.3، فتتطابق نقطة النهاية مع نقطة التكافؤ.', '["الحكم بعدم الملاءمة مع التعليل","تغير اللون نحو 45 mL قبل التكافؤ","الحجم أقل والتركيز المحسوب أقل","اقتراح الميثيل الأحمر مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(a) التقويم مع التعليل","marks":1},{"element":"(b) موقع تغير اللون","marks":1},{"element":"(b) أثره في الحجم والتركيز","marks":1},{"element":"(c) الكاشف البديل مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم صحيح وتحليل كامل للأثر وبديل مناسب معلل"},{"level":"3 درجات","description":"ينقص عنصر واحد"},{"level":"درجتان","description":"تقويم صحيح وبديل مناسب دون تحليل الأثر"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"الموافقة على اختيار الطالب"}]'::jsonb, '["القول إن الفينولفثالين يتغير لونه بعد التكافؤ","القول إن التركيز المحسوب يكون أكبر","اقتراح البروموثيمول الأزرق بحجة أن التكافؤ عند 7"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.701Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L4-O13') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L4-O14'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'بحسب الكتاب، ما قيمة pH لـ 1 L من الماء النقي بعد إذابة 0.01 mol من غاز HCl فيه؟', null, '["2.0","7.0","6.9","12.0"]'::jsonb, 'فهم', 'تطبيق بيانات الكتاب', 'سهل', 'الكتاب ص 88 — المحاليل المنظمة'),
('mcq', 2, 'أُضيف 0.01 mol من NaOH إلى 1 L من الماء النقي، والكمية نفسها إلى 1 L من محلول منظم pH له 7.0. ما قيمتا pH المتوقعتان على الترتيب؟', null, '["12.0 للماء، و12.0 للمحلول المنظم","12.0 للماء، ونحو 7.1 للمحلول المنظم","نحو 7.1 للماء، و12.0 للمحلول المنظم","2.0 للماء، ونحو 6.9 للمحلول المنظم"]'::jsonb, 'تحليل', 'مقارنة سلوكين', 'متوسط', 'الكتاب ص 88 — المحاليل المنظمة'),
('mcq', 3, 'انخفض pH الماء النقي من 7.0 إلى 2.0 عند إضافة 0.01 mol من HCl إلى 1 L منه. كم مرة ازداد تركيز أيونات H⁺؟', null, '["5 مرات","3.5 مرة","10⁷ مرة","10⁵ مرة"]'::jsonb, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 88 — المحاليل المنظمة'),
('mcq', 4, 'يبين الجدول قيم pH لثلاثة محاليل حجم كل منها 1 L قبل إضافة 0.01 mol من HCl وبعدها. أيّ المحاليل محلول منظم؟', '{"headers":["المحلول (1 L)","pH قبل الإضافة","pH بعد إضافة 0.01 mol HCl"],"rows":[["ماء نقي","7.00","2.00"],["المحلول X","4.76","4.67"],["المحلول Y","3.00","1.96"]]}'::jsonb, '["المحلول Y؛ لأنه حمضي في الأصل فلا يتأثر بإضافة الحمض","المحلول X فقط؛ لأن pH تغير بأقل من 0.1 وحدة","الماء النقي؛ لأن pH له متعادل يساوي 7","المحلولان X وY معًا؛ لأن كليهما حمضي"]'::jsonb, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 88 — المحاليل المنظمة'),
('mcq', 5, 'لماذا يتغير pH الماء النقي تغيرًا كبيرًا عند إضافة كمية قليلة من حمض قوي، بينما لا يتغير pH المحلول المنظم إلا قليلًا؟', null, '["لأن الماء النقي يتفاعل مع الحمض فينتج مزيدًا من أيونات H⁺","لأن المحلول المنظم يحتوي على قاعدة قوية تعادل الحمض كليًا","لأن الماء لا يحوي مكوّنًا يستهلك H⁺ المضاف، أما المنظم فتستهلكه قاعدته المرافقة","لأن الحمض القوي لا يتأين عندما يُضاف إلى المحلول المنظم"]'::jsonb, 'فهم', 'تفسير مقارن', 'سهل', 'الكتاب ص 88–89 — كيف تعمل المحاليل المنظمة؟'),
('mcq', 6, 'قارن ما يحدث لأيونات OH⁻ عند إضافة كمية قليلة من NaOH إلى محلول منظم HF/NaF، بما يحدث لها عند إضافتها إلى ماء نقي.', null, '["في المنظم تتفاعل مع H⁺ فيتأين مزيد من HF، وفي الماء تبقى حرة فيرتفع pH كثيرًا","في المنظم تتفاعل مع F⁻ لتكوين HF، وفي الماء تتفاعل مع H₂O لتكوين H⁺","في المنظم وفي الماء تبقى حرة، لكن المنظم يغيّر لونه فقط","في المنظم يُزاح الاتزان HF ⇌ H⁺ + F⁻ إلى اليسار، وفي الماء تتعادل كليًا"]'::jsonb, 'تحليل', 'مقارنة على المستوى الجزيئي', 'صعب', 'الكتاب ص 88–89 — كيف تعمل المحاليل المنظمة؟'),
('mcq', 7, 'محلول مائي غير منظم حجمه 1 L يحتوي على 0.005 mol من حمض قوي أحادي البروتون، فما قيمة pH له تقريبًا؟', null, '["2.0","11.7","6.9","2.3"]'::jsonb, 'تطبيق', 'حساب pH', 'متوسط', 'الكتاب ص 88 — المحاليل المنظمة'),
('essay', 1, 'قارن بين نتائج تجربتين: الأولى إضافة كمية صغيرة من قاعدة إلى محلول غير منظم له pH = 7، والثانية إضافة الكمية نفسها من القاعدة إلى محلول منظم له pH = 7.', null, null, 'تحليل', 'مقارنة', 'سهل', 'الكتاب ص 88، 90 — السؤال 50'),
('essay', 2, 'عند إضافة 0.01 mol من HCl إلى 1 L من الماء النقي انخفض pH من 7.0 إلى 2.0، وعند إضافة الكمية نفسها إلى 1 L من محلول منظم انخفض pH من 7.0 إلى 6.9. (a) احسب عدد مرات زيادة [H⁺] في كل حالة. (b) ماذا تستنتج من المقارنة؟', null, null, 'تحليل', 'حساب ومقارنة', 'متوسط', 'الكتاب ص 88 — المحاليل المنظمة'),
('essay', 3, 'لديك قارورتان غير معنونتين، pH كل منهما 4.76: إحداهما محلول منظم من CH₃COOH وCH₃COONa، والأخرى محلول HCl مخفف جدًا. (a) صمّم تجربة بسيطة باستعمال مقياس pH للتمييز بينهما. (b) توقع النتائج. (c) فسّر النتيجة المتوقعة للمحلول المنظم بمعادلة الاتزان.', null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 88–89 — كيف تعمل المحاليل المنظمة؟')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L4-O14') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'HCl حمض قوي يتأين كليًا، فيصبح [H⁺] = 0.01 mol ÷ 1 L = 1×10⁻² M، وpH = −log(1×10⁻²) = 2.0؛ أي إن pH الماء النقي انخفض من 7.0 إلى 2.0.', '["","الماء النقي ليس محلولًا منظمًا، فلا يقاوم تغير pH.","هذا تغير بمقدار 0.1 وحدة، وهو سلوك المحلول المنظم لا الماء النقي.","هذه قيمة pH عند إضافة 0.01 mol من NaOH، لا من HCl."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.703Z"}'::jsonb),
('mcq', 2, 1, 'في الماء النقي يصبح [OH⁻] = 1×10⁻² M فيرتفع pH من 7.0 إلى 12.0. أما في المحلول المنظم فلا يتغير pH بأكثر من 0.1 وحدة، فيصبح نحو 7.1 على الأكثر.', '["المحلول المنظم يقاوم التغير، فلا يتغير pH له بأكثر من 0.1 وحدة.","","عكس السلوكين: الماء هو الذي يتغير pH له كثيرًا، والمنظم يقاوم التغير.","إضافة قاعدة ترفع pH ولا تخفضه؛ القيمة 2.0 تخص إضافة HCl."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.703Z"}'::jsonb),
('mcq', 3, 3, '[H⁺] الابتدائي = 10⁻⁷ M، والنهائي = 10⁻² M؛ فالنسبة = 10⁻² ÷ 10⁻⁷ = 10⁵. أي إن تركيز H⁺ ازداد مئة ألف مرة، بينما في المحلول المنظم (تغير 0.1 وحدة) يزداد بنحو 1.26 مرة فقط.', '["عامل فرق pH (7 − 2 = 5) كأنه نسبة خطية، مع أن pH مقياس لوغاريتمي.","قسم قيمتي pH (7 ÷ 2)؛ والصحيح قسمة التركيزين: 10⁻² ÷ 10⁻⁷.","استعمل أس التركيز الابتدائي فقط ولم يأخذ في الحساب التركيز النهائي 10⁻² M.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.704Z"}'::jsonb),
('mcq', 4, 1, 'المحلول المنظم يقاوم التغير في pH عند إضافة كميات محددة من حمض أو قاعدة. المحلول X تغير من 4.76 إلى 4.67 (0.09 وحدة)، بينما تغير Y بنحو 1.04 وحدة والماء بـ 5 وحدات؛ فالمحلول X وحده منظم.', '["pH المحلول Y انخفض أكثر من وحدة كاملة (3.00 → 1.96)، فهو لا يقاوم التغير.","","الماء النقي تغير pH له 5 وحدات، فهو غير منظم.","كون المحلول حمضيًا لا يجعله منظمًا؛ المعيار هو مقاومة تغير pH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T09:21:20.704Z"}'::jsonb),
('mcq', 5, 2, 'في الماء النقي يبقى H⁺ المضاف حرًا فيرتفع تركيزه كثيرًا. أما في المحلول المنظم (مثل HF/F⁻) فتتفاعل أيونات H⁺ المضافة مع F⁻ لتكوين HF، فيزاح الاتزان HF ⇌ H⁺ + F⁻ إلى اليسار ويُستهلك معظم H⁺ المضاف، فيتغير pH قليلًا فقط.', '["الماء لا ينتج H⁺ إضافيًا؛ المشكلة أن H⁺ المضاف يبقى حرًا لعدم وجود ما يستهلكه.","المحلول المنظم يحتوي على حمض ضعيف وقاعدته المرافقة، لا قاعدة قوية.","","الحمض القوي يتأين كليًا في أي محلول مائي؛ لكن H⁺ الناتج يُستهلك في المنظم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T09:21:20.704Z"}'::jsonb),
('mcq', 6, 0, 'في المحلول المنظم تتفاعل OH⁻ مع H⁺ لتكوين H₂O، فيقل [H⁺] ويزاح الاتزان HF ⇌ H⁺ + F⁻ إلى اليمين فيتأين مزيد من HF ويعوّض H⁺، فيتغير pH قليلًا. أما في الماء النقي فلا يوجد ما يستهلك OH⁻، فيرتفع pH ارتفاعًا كبيرًا (من 7.0 إلى 12.0 لـ 0.01 mol في 1 L).', '["","OH⁻ لا يتفاعل مع F⁻ (كلاهما قاعدة)، ولا ينتج H⁺ من تفاعله مع الماء.","المنظم يستهلك OH⁻ كيميائيًا ولا علاقة لذلك بتغير اللون.","استهلاك H⁺ بواسطة OH⁻ يزيح الاتزان إلى اليمين لا اليسار، والماء النقي لا يعادل OH⁻ المضاف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.704Z"}'::jsonb),
('mcq', 7, 3, '[H⁺] = 0.005 mol ÷ 1 L = 5×10⁻³ M، وpH = −log(5×10⁻³) = 2.30 ≈ 2.3. فإضافة كمية صغيرة من حمض قوي إلى محلول غير منظم تخفض pH بنحو 4.7 وحدات.', '["استعمل كمية الكتاب (0.01 mol) بدل 0.005 mol المعطاة.","حسب pOH بدل pH، أو طرح الناتج من 14 دون مبرر؛ فالمحلول حمضي.","افترض أن الماء يقاوم التغير كالمحلول المنظم، فلم يتغير pH إلا 0.1 وحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.704Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في التجربة الأولى يرتفع pH المحلول غير المنظم ارتفاعًا كبيرًا (مثلًا من 7.0 إلى 12.0 عند إضافة 0.01 mol NaOH إلى 1 L ماء)، لأنه لا يحتوي على ما يستهلك OH⁻ المضافة. وفي التجربة الثانية يبقى pH المحلول المنظم قريبًا من 7 (لا يتغير بأكثر من 0.1 وحدة تقريبًا)، لأن الحمض الضعيف في المنظم يتفاعل مع OH⁻ المضافة فيقاوم التغير.', '["غير المنظم: ارتفاع كبير في pH","المنظم: تغير طفيف في pH","التعليل بوجود مكون يستهلك OH⁻ في المنظم وغيابه في غير المنظم"]'::jsonb, '[]'::jsonb, '[{"element":"نتيجة التجربة الأولى","marks":1},{"element":"نتيجة التجربة الثانية","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"النتيجتان صحيحتان مع التعليل"},{"level":"درجتان","description":"النتيجتان صحيحتان دون تعليل"},{"level":"1 درجة","description":"نتيجة واحدة صحيحة"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["القول إن pH المحلولين يتغير بالمقدار نفسه لأن لهما pH نفسه","القول إن pH المنظم لا يتغير مطلقًا","القول إن pH غير المنظم ينخفض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T09:21:20.705Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الماء النقي: [H⁺] من 1×10⁻⁷ إلى 1×10⁻² M؛ النسبة = 10⁻²/10⁻⁷ = 1×10⁵ مرة. المحلول المنظم: [H⁺] من 1×10⁻⁷ إلى 10⁻⁶·⁹ = 1.26×10⁻⁷ M؛ النسبة ≈ 1.26 مرة. (b) الكمية نفسها من الحمض زادت [H⁺] في الماء مئة ألف مرة، بينما زادته في المحلول المنظم بنحو الربع فقط؛ أي إن المحلول المنظم يستهلك معظم H⁺ المضاف ويقاوم تغير pH، أما الماء النقي فلا يقاوم.', '["حساب نسبة الزيادة في الماء (10⁵)","حساب نسبة الزيادة في المنظم (≈ 1.26)","استنتاج مقاومة المنظم لتغير pH"]'::jsonb, '["الماء: [H⁺]₁ = 10⁻⁷ M، [H⁺]₂ = 10⁻² M، النسبة = 10⁵","المنظم: [H⁺]₂ = 10⁻⁶·⁹ = 1.26×10⁻⁷ M، النسبة = 1.26×10⁻⁷ ÷ 1×10⁻⁷ = 1.26","المقارنة: 10⁵ مقابل 1.26"]'::jsonb, '[{"element":"نسبة الزيادة في الماء","marks":1},{"element":"نسبة الزيادة في المنظم","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان واستنتاج واضح"},{"level":"3 درجات","description":"الحسابان صحيحان مع استنتاج ناقص"},{"level":"درجتان","description":"حساب واحد صحيح مع استنتاج"},{"level":"1 درجة","description":"استنتاج صحيح دون حساب"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["حساب النسبة بطرح قيمتي pH (5 مرات)","نسيان أن pH مقياس لوغاريتمي","حساب [H⁺] = 6.9×10⁻⁷"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.705Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) يُؤخذ حجمان متساويان من المحلولين، ويُقاس pH لكل منهما، ثم تُضاف إلى كل منهما الكمية الصغيرة نفسها من حمض قوي (مثلًا قطرات من HCl بتركيز معلوم)، ويُقاس pH بعد الإضافة (ويمكن تكرار ذلك بقاعدة قوية على عينتين جديدتين). (b) المحلول الذي يتغير pH له تغيرًا طفيفًا (نحو 0.1 وحدة) هو المنظم، والذي ينخفض pH له كثيرًا هو محلول HCl المخفف. (c) في المنظم يوجد الاتزان CH₃COOH ⇌ H⁺ + CH₃COO⁻؛ عند إضافة H⁺ يتفاعل مع CH₃COO⁻ ويزاح الاتزان إلى اليسار حسب مبدأ لوتشاتلييه فيُستهلك معظم H⁺ المضاف. أما HCl المخفف فلا يحتوي على قاعدة مرافقة تستهلك H⁺ (Cl⁻ لا يتفاعل)، فيزداد [H⁺] كثيرًا.', '["تجربة مضبوطة: حجمان متساويان وكمية مضافة متساوية وقياس pH قبل وبعد","توقع: تغير طفيف للمنظم وكبير لغير المنظم","تفسير بالاتزان CH₃COOH ⇌ H⁺ + CH₃COO⁻ ومبدأ لوتشاتلييه","تفسير غياب المقاومة في HCl"]'::jsonb, '[]'::jsonb, '[{"element":"تصميم التجربة المضبوطة","marks":2},{"element":"توقع النتائج","marks":1},{"element":"التفسير بمعادلة الاتزان","marks":1},{"element":"تفسير سلوك HCl المخفف","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصميم مضبوط وتوقع صحيح وتفسير كامل للمحلولين"},{"level":"3–4 درجات","description":"تصميم وتوقع صحيحان مع تفسير ناقص"},{"level":"1–2 درجة","description":"فكرة التجربة صحيحة دون ضبط أو تفسير"},{"level":"صفر","description":"تصميم لا يميز بين المحلولين"}]'::jsonb, '["الاكتفاء بقياس pH دون إضافة حمض أو قاعدة","إضافة كميتين مختلفتين للمحلولين","زعم أن المنظم لا يتغير pH له مطلقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T09:21:20.705Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
