insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L4-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بسعة المحلول المنظم؟', null, '["كمية الحمض أو القاعدة التي يستوعبها المحلول المنظم دون تغير مهم في pH","قيمة pH التي يحافظ عليها المحلول المنظم","حجم الماء اللازم لتحضير المحلول المنظم","عدد الأيونات الذائبة في 1 L من المحلول المنظم"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 89 — سعة المحلول المنظم'),
('mcq', 2, 'ماذا يحدث لقدرة المحلول المنظم على مقاومة تغير pH عند إضافة كمية كبيرة جدًا من الحمض أو القاعدة؟', null, '["تزداد قدرته لأن الاتزان يزاح أكثر","تُتجاوز قدرته ويتغير pH تغيرًا كبيرًا","تبقى ثابتة مهما كانت الكمية المضافة","يتحول المحلول إلى ماء نقي pH له 7"]'::jsonb, 'تذكر', 'تعرف خاصية', 'سهل', 'الكتاب ص 89 — سعة المحلول المنظم'),
('mcq', 3, 'ما العامل الذي تزداد به سعة المحلول المنظم؟', null, '["زيادة حجم الماء المضاف لتخفيف المحلول","تقليل تركيز الحمض الضعيف وقاعدته المرافقة","زيادة تراكيز الجزيئات والأيونات المنظمة في المحلول","رفع درجة حرارة المحلول المنظم"]'::jsonb, 'تذكر', 'تعرف عامل', 'متوسط', 'الكتاب ص 89 — سعة المحلول المنظم'),
('mcq', 4, 'محلولان منظمان من HF/NaF لهما pH نفسه: الأول تركيز كل من مكونيه 0.50 M، والثاني 0.050 M. أيّهما أكبر سعة، ولماذا؟', null, '["الثاني؛ لأن تركيزه الأقل يجعل الاتزان أسرع","سعتهما متساوية لأن pH لهما متساوٍ","الثاني؛ لأن قلة الأيونات تسمح باستيعاب كمية أكبر من الحمض","الأول؛ لأن تراكيز مكوناته أكبر فيستوعب كمية أكبر من الحمض أو القاعدة"]'::jsonb, 'فهم', 'تطبيق على موقف', 'متوسط', 'الكتاب ص 88–89 — المحاليل المنظمة وسعتها'),
('mcq', 5, 'محلول منظم حجمه 1 L يحتوي على 1.0 mol من CH₃COOH و1.0 mol من CH₃COO⁻. أُضيف إليه 0.010 mol من HCl فلم يتغير pH إلا قليلًا. ما المتوقع لو أُضيف 1.5 mol من HCl إلى المحلول نفسه؟', null, '["لا يتغير pH إلا قليلًا لأن المحلول منظم","يتغير pH تغيرًا كبيرًا لأن CH₃COO⁻ ينفد وتُتجاوز السعة","يرتفع pH لأن الحمض القوي يتحول إلى قاعدة","يبقى pH ثابتًا تمامًا لأن مولات CH₃COOH كبيرة"]'::jsonb, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 88–89 — المحاليل المنظمة وسعتها'),
('mcq', 6, 'أيّ المحاليل الآتية له أكبر سعة منظمة؟', null, '["محلول من 0.01 M HF و0.01 M NaF","محلول من 0.10 M HF و0.10 M NaF","محلول من 1.0 M HF و1.0 M NaF","محلول 1.0 M من HF وحده دون NaF"]'::jsonb, 'فهم', 'مقارنة سعات', 'سهل', 'الكتاب ص 89 — سعة المحلول المنظم'),
('mcq', 7, 'لماذا لا يضمن وجود المحلول المنظم ثبات pH مهما أُضيف إليه من حمض أو قاعدة؟', null, '["لأن المحلول المنظم لا يتفاعل مع الحمض أو القاعدة المضافة","لأن الحمض القوي لا يتأين في المحلول المنظم","لأن قيمة pH تتغير تلقائيًا بمرور الزمن","لأن مكوني المحلول يُستهلكان عند الإضافة، فللمحلول سعة محدودة"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 89 — سعة المحلول المنظم'),
('essay', 1, 'عرّف سعة المحلول المنظم، وبيّن ماذا يحدث عند إضافة كمية كبيرة جدًا من حمض قوي إليه.', null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 89 — سعة المحلول المنظم'),
('essay', 2, 'محلولان منظمان من CH₃COOH/CH₃COONa لهما pH = 4.76: الأول بتركيز 1.0 M لكل من المكونين، والثاني بتركيز 0.10 M لكل منهما. (a) أيهما أكبر سعة؟ (b) احسب عدد مولات CH₃COO⁻ في 1 L من كل منهما. (c) فسّر العلاقة بين تركيز المكونات والسعة.', null, null, 'تطبيق', 'مقارنة وحساب', 'متوسط', 'الكتاب ص 88–89 — المحاليل المنظمة وسعتها'),
('essay', 3, 'أُضيف 0.050 mol من NaOH إلى 1 L من كل من المحلولين المنظمين في السؤال السابق (الأول 1.0 M HA وA⁻، والثاني 0.10 M). حلّل ماذا يحدث في كل منهما، وبيّن أيهما يُتجاوز سعته وكيف تعرف ذلك.', null, null, 'تحليل', 'تحليل موقف بالحساب', 'صعب', 'الكتاب ص 88–89 — المحاليل المنظمة وسعتها')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
