from (values
('mcq', 1, 0, 'سعة المحلول المنظم هي كمية الحمض أو القاعدة التي يستطيع المحلول المنظم أن يستوعبها دون تغير مهم في pH.', '["","هذه قيمة pH للمحلول المنظم، أما السعة فهي كمية الحمض أو القاعدة التي يستوعبها.","السعة لا تتعلق بحجم الماء المستعمل في التحضير.","السعة تقاس بقدرة المحلول على استيعاب الحمض أو القاعدة، لا بعدد الأيونات الكلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.706Z"}'::jsonb),
('mcq', 2, 1, 'قدرة المحلول المنظم على مقاومة تغير pH تُتجاوز عند إضافة كمية كبيرة من الحمض أو القاعدة؛ أي إن سعته محدودة.', '["كلما استُهلك أحد مكوني المنظم قلّت قدرته، ولا تزداد.","","للمحلول المنظم سعة محدودة تُتجاوز عند إضافة كمية كبيرة.","المحلول يبقى محلولًا من أيونات وجزيئات، لكن pH يتغير بحسب الفائض من الحمض أو القاعدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-17T09:21:20.706Z"}'::jsonb),
('mcq', 3, 2, 'كلما زادت تراكيز الجزيئات والأيونات المنظمة في المحلول زادت سعة المحلول المنظم.', '["التخفيف يقلل تراكيز المكونات فتقل السعة.","تقليل التراكيز يقلل كمية الحمض أو القاعدة التي يمكن استيعابها.","","الكتاب يربط السعة بتراكيز المكونات المنظمة لا بدرجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.706Z"}'::jsonb),
('mcq', 4, 3, 'سعة المحلول المنظم تزداد بزيادة تراكيز الجزيئات والأيونات المنظمة؛ فالمحلول 0.50 M أكبر سعة، لأن فيه كمية أكبر من F⁻ لاستهلاك H⁺ المضاف وكمية أكبر من HF لاستهلاك OH⁻.', '["السعة لا ترتبط بسرعة الاتزان، بل بكمية المكونات المنظمة.","تساوي pH لا يعني تساوي السعة؛ فالسعة تعتمد على التراكيز.","قلة المكونات المنظمة تعني استهلاكها أسرع عند إضافة الحمض أو القاعدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.706Z"}'::jsonb),
('mcq', 5, 1, 'H⁺ المضاف يتفاعل مع CH₃COO⁻ (1.0 mol فقط). إضافة 1.5 mol تزيد عما يوجد منه، فيُستهلك كله ويبقى 0.5 mol من H⁺ حرًا، فتُتجاوز السعة ويتغير pH تغيرًا كبيرًا.', '["المنظم يقاوم التغير ضمن سعته فقط، وH⁺ المضاف يزيد عن CH₃COO⁻ المتاح (1.0 mol).","","إضافة حمض لا ترفع pH.","CH₃COOH لا يستهلك H⁺ المضاف؛ المستهلك هو القاعدة المرافقة CH₃COO⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.707Z"}'::jsonb),
('mcq', 6, 2, 'السعة تزداد بزيادة تراكيز مكوني المحلول المنظم، وعندما يكون HF وF⁻ بتركيز 1.0 M يكون المحلول أكبر استيعابًا للحمض والقاعدة.', '["تراكيزه صغيرة جدًا، فتُستنفد مكوناته سريعًا.","تراكيزه أقل من 1.0 M، فسعته أصغر.","","غياب القاعدة المرافقة F⁻ يعني عدم وجود ما يستهلك الحمض المضاف، فليس محلولًا منظمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T09:21:20.707Z"}'::jsonb),
('mcq', 7, 3, 'عند إضافة الحمض تُستهلك القاعدة المرافقة، وعند إضافة القاعدة يُستهلك الحمض الضعيف؛ فإذا نفد أحد المكونين فقد المحلول قدرته على المقاومة. ولذلك تُتجاوز قدرته عند إضافة كمية كبيرة.', '["بل يتفاعل: القاعدة المرافقة تستهلك الحمض والحمض الضعيف يستهلك القاعدة.","الحمض القوي يتأين كليًا، وH⁺ الناتج هو الذي يستهلكه المنظم.","pH المحلول المنظم ثابت ما لم يُضف إليه حمض أو قاعدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.707Z"}'::jsonb),
('essay', 1, null::int, null, null, 'سعة المحلول المنظم هي كمية الحمض أو القاعدة التي يستطيع المحلول المنظم أن يستوعبها دون تغير مهم في pH. وعند إضافة كمية كبيرة جدًا من حمض قوي تُتجاوز قدرة المحلول على مقاومة تغير pH، إذ تُستهلك القاعدة المرافقة كلها ويبقى H⁺ حرًا، فيتغير pH تغيرًا كبيرًا.', '["تعريف السعة","تجاوز القدرة عند الكمية الكبيرة","سبب التجاوز: استهلاك القاعدة المرافقة وبقاء H⁺"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف السعة","marks":1},{"element":"تجاوز القدرة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التعريف والنتيجة والتفسير صحيحة"},{"level":"درجتان","description":"التعريف والنتيجة"},{"level":"1 درجة","description":"التعريف فقط"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["تعريف السعة بأنها قيمة pH للمحلول","القول إن المحلول يقاوم أي كمية مهما كبرت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-10-17T09:21:20.707Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الأول. (b) الأول: 1.0 mol/L × 1 L = 1.0 mol؛ الثاني: 0.10 mol/L × 1 L = 0.10 mol. (c) تتفاعل H⁺ المضافة مع CH₃COO⁻، وتتفاعل OH⁻ المضافة مع CH₃COOH؛ فكلما زادت مولات المكونين زادت كمية الحمض أو القاعدة التي يمكن استيعابها قبل نفاد أحدهما، فتزداد السعة بزيادة التراكيز.', '["الأول أكبر سعة","حساب المولات 1.0 و0.10","ربط السعة بكمية المكونات"]'::jsonb, '["mol = M × V","الأول: 1.0 × 1 = 1.0 mol","الثاني: 0.10 × 1 = 0.10 mol"]'::jsonb, '[{"element":"(a) تحديد الأكبر سعة","marks":1},{"element":"(b) حساب المولات","marks":1},{"element":"(c) التفسير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع الأجزاء صحيحة"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["اعتبار السعة متساوية لتساوي pH","نسيان ضرب التركيز بالحجم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T09:21:20.707Z"}'::jsonb),
('essay', 3, null::int, null, null, 'OH⁻ المضاف يتفاعل مع الحمض الضعيف HA. في المحلول الأول: يوجد 1.0 mol من HA، فيُستهلك 0.050 mol فقط ويبقى 0.95 mol، فيتغير pH قليلًا ولا تُتجاوز السعة. في الثاني: يوجد 0.10 mol من HA، فيُستهلك 0.050 mol ويبقى 0.050 mol، أي نصف الحمض، فيتغير pH أكثر من الأول وتقترب السعة من النفاد، ولو أُضيف أكثر من 0.10 mol لنفد الحمض وتُتجاوز السعة. إذن لا يُتجاوز أي منهما بهذه الكمية، لكن الأول أبعد عن حد السعة.', '["OH⁻ يستهلك الحمض الضعيف","حساب المتبقي: 0.95 mol و0.050 mol","المقارنة: الأول أبعد عن حد السعة","حد التجاوز عند إضافة أكثر من مولات الحمض"]'::jsonb, '["الأول: 1.0 − 0.050 = 0.95 mol من HA","الثاني: 0.10 − 0.050 = 0.050 mol من HA","التجاوز عندما تزيد مولات OH⁻ عن مولات HA"]'::jsonb, '[{"element":"المقاوم المتفاعل مع OH⁻","marks":1},{"element":"حساب المتبقي في كل محلول","marks":2},{"element":"المقارنة وحد التجاوز","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحليل كامل مع الحساب والمقارنة"},{"level":"3–4 درجات","description":"حساب صحيح مع مقارنة ناقصة"},{"level":"1–2 درجة","description":"فكرة صحيحة دون حساب"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["القول إن المحلول الثاني تُتجاوز سعته بهذه الكمية","القول إن OH⁻ يتفاعل مع A⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.707Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
