('mcq', 3, 'يراد تحضير محلول منظم قيمة pH له نحو 9.4. أيّ الخيارات الآتية مناسب؟', '{"headers":["الزوج المترافق (حمض/قاعدة مرافقة)","pH الأكثر فاعلية"],"rows":[["HF/F⁻","3.20"],["CH₃COOH/CH₃COO⁻","4.76"],["H₂CO₃/HCO₃⁻","6.35"],["H₂PO₄⁻/HPO₄²⁻","7.21"],["NH₄⁺/NH₃","9.4"],["C₂H₅NH₃⁺/C₂H₅NH₂","10.70"]]}'::jsonb, '["NH₄Cl مع NH₃ بتركيزين متساويين","CH₃COOH مع CH₃COONa بتركيزين متساويين","HF مع NaF بتركيزين متساويين","NaH₂PO₄ مع Na₂HPO₄ بتركيزين متساويين"]'::jsonb, 'تطبيق', 'اختيار محلول منظم', 'متوسط', 'الكتاب ص 89–90 — الجدول 2-7 والسؤال 52'),
('mcq', 4, 'ثابت تأين الحمض HF هو Ka = 6.3×10⁻⁴. ما قيمة pH لمحلول منظم يحتوي على تركيزين متساويين من HF وF⁻؟', null, '["3.20","4.80","10.80","6.3×10⁻⁴"]'::jsonb, 'تطبيق', 'حساب pH من Ka', 'متوسط', 'الكتاب ص 89 — اختيار المحلول المنظم والجدول 2-7'),
('mcq', 5, 'ثابت تأين H₂PO₄⁻ هو Ka = 6.2×10⁻⁸. لماذا يكون المحلول المنظم H₂PO₄⁻/HPO₄²⁻ أنسب ما يكون عندما يكون pH قرب 7.21؟', null, '["لأن pH كل محلول منظم يساوي 7 دائمًا","لأن Ka يساوي 1×10⁻⁷ تمامًا","لأن HPO₄²⁻ حمض قوي يعادل القاعدة المضافة","لأن pH = −log Ka = 7.21 عند تساوي تركيزي الحمض وقاعدته المرافقة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 89 — اختيار المحلول المنظم والجدول 2-7'),
('mcq', 6, 'أراد طالب محلولًا منظمًا pH له نحو 5.0، فاختار زوجًا مترافقًا من الجدول. أيّ اختيار هو الأفضل؟', '{"headers":["الزوج المترافق (حمض/قاعدة مرافقة)","pH الأكثر فاعلية"],"rows":[["HF/F⁻","3.20"],["CH₃COOH/CH₃COO⁻","4.76"],["H₂CO₃/HCO₃⁻","6.35"],["H₂PO₄⁻/HPO₄²⁻","7.21"],["NH₄⁺/NH₃","9.4"],["C₂H₅NH₃⁺/C₂H₅NH₂","10.70"]]}'::jsonb, '["H₂CO₃/HCO₃⁻ لأن قيمته 6.35 أكبر من 5.0","HF/F⁻ لأن قيمته 3.20 أقل من 5.0","CH₃COOH/CH₃COO⁻ لأن قيمته 4.76 أقرب القيم إلى 5.0","NH₄⁺/NH₃ لأنه الزوج الوحيد المتاح من قاعدة ضعيفة"]'::jsonb, 'تطبيق', 'اختيار بالمقارنة العددية', 'صعب', 'الكتاب ص 89 — اختيار المحلول المنظم والجدول 2-7'),
('mcq', 7, 'أيّ المحاليل الآتية لا يصلح محلولًا منظمًا فعالًا للمحافظة على pH = 7.2؟', '{"headers":["الزوج المترافق (حمض/قاعدة مرافقة)","pH الأكثر فاعلية"],"rows":[["HF/F⁻","3.20"],["CH₃COOH/CH₃COO⁻","4.76"],["H₂CO₃/HCO₃⁻","6.35"],["H₂PO₄⁻/HPO₄²⁻","7.21"],["NH₄⁺/NH₃","9.4"],["C₂H₅NH₃⁺/C₂H₅NH₂","10.70"]]}'::jsonb, '["محلول من NaH₂PO₄ وNa₂HPO₄ بتركيزين متساويين","محلول من HF وNaF بتركيزين متساويين","محلول من NaH₂PO₄ وNa₂HPO₄ بتركيز 1.0 M لكل منهما","محلول من NaH₂PO₄ وNa₂HPO₄ بتركيز 0.50 M لكل منهما"]'::jsonb, 'تحليل', 'استبعاد', 'صعب', 'الكتاب ص 89 — اختيار المحلول المنظم والجدول 2-7'),
('essay', 1, 'يراد تحضير محلول منظم للمحافظة على pH = 10.7. اعتمادًا على الجدول، اختر الزوج المترافق المناسب، واذكر المادتين اللتين تحتاج إليهما، وعلّل اختيارك.', '{"headers":["الزوج المترافق (حمض/قاعدة مرافقة)","pH الأكثر فاعلية"],"rows":[["HF/F⁻","3.20"],["CH₃COOH/CH₃COO⁻","4.76"],["H₂CO₃/HCO₃⁻","6.35"],["H₂PO₄⁻/HPO₄²⁻","7.21"],["NH₄⁺/NH₃","9.4"],["C₂H₅NH₃⁺/C₂H₅NH₂","10.70"]]}'::jsonb, null, 'تطبيق', 'اختيار وتعليل', 'متوسط', 'الكتاب ص 89–90 — الجدول 2-7'),
('essay', 2, 'لديك محلول منظم من H₂PO₄⁻ وHPO₄²⁻ بتركيزين متساويين، وثابت تأين الحمض H₂PO₄⁻ هو Ka = 6.2×10⁻⁸. (a) اكتب معادلة تأين H₂PO₄⁻ وعبارة Ka. (b) احسب [H⁺] وpH للمحلول. (c) هل يصلح لمحافظة على pH = 7.2؟ علّل.', null, null, 'تطبيق', 'حساب وتعليل', 'متوسط', 'الكتاب ص 89 — اختيار المحلول المنظم والجدول 2-7'),
('essay', 3, 'يحتاج مختبر إلى محلولين منظمين: الأول pH له نحو 3.2، والثاني نحو 9.4. اعتمادًا على الجدول، اختر الزوج المناسب لكل منهما، ثم قوّم اقتراح زميل بأن يستعمل زوجًا واحدًا هو H₂PO₄⁻/HPO₄²⁻ للمحلولين معًا.', '{"headers":["الزوج المترافق (حمض/قاعدة مرافقة)","pH الأكثر فاعلية"],"rows":[["HF/F⁻","3.20"],["CH₃COOH/CH₃COO⁻","4.76"],["H₂CO₃/HCO₃⁻","6.35"],["H₂PO₄⁻/HPO₄²⁻","7.21"],["NH₄⁺/NH₃","9.4"],["C₂H₅NH₃⁺/C₂H₅NH₂","10.70"]]}'::jsonb, null, 'تقويم', 'اختيار وتقويم', 'صعب', 'الكتاب ص 89 — الجدول 2-7')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
