select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يكون المحلول المنظم أكثر فاعلية عندما يكون pH المطلوب قريبًا من pH الزوج عند تساوي تركيزي الحمض وقاعدته المرافقة؛ والزوج CH₃COOH/CH₃COO⁻ قيمته 4.76، وهي الأقرب إلى 4.8.', '["قيمة pH الأكثر فاعلية لهذا الزوج 3.20، وهي بعيدة عن 4.8.","","قيمة pH الأكثر فاعلية 6.35، وهي أعلى بكثير من 4.8.","قيمة pH الأكثر فاعلية 9.4، وهي بعيدة جدًا عن 4.8."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T09:21:20.708Z"}'::jsonb),
('mcq', 2, 2, 'أقرب قيمة في الجدول إلى 7.2 هي 7.21 للزوج H₂PO₄⁻/HPO₄²⁻، وهو أنسب زوج لهذا pH.', '["قيمته 3.20، بعيد جدًا عن 7.2.","قيمته 9.4، أعلى بنحو وحدتين عن 7.2.","","قيمته 10.70، بعيد جدًا عن 7.2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T09:21:20.708Z"}'::jsonb),
('mcq', 3, 0, 'عند تساوي تركيزي الحمض وقاعدته المرافقة يكون pH مساويًا pKa للحمض، وللزوج NH₄⁺/NH₃ القيمة 9.4، وهو المناسب كما في السؤال 52 من الكتاب (يلزم NH₄Cl لتوفير NH₄⁺).', '["","pH هذا المحلول نحو 4.76، لا 9.4.","pH هذا المحلول نحو 3.20، لا 9.4.","pH هذا المحلول نحو 7.21، لا 9.4."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.708Z"}'::jsonb),
('mcq', 4, 0, 'عند تساوي [HF] و[F⁻] يكون [H⁺] = Ka = 6.3×10⁻⁴ M، فيكون pH = −log(6.3×10⁻⁴) = 3.20.', '["","حسب −log Ka باستعمال 6.3×10⁻⁵ بدل 6.3×10⁻⁴.","حسب pOH بدل pH، أي 14 − 3.20.","كتب قيمة [H⁺] بدل pH، ولم يطبق −log."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.708Z"}'::jsonb),
('mcq', 5, 3, 'من Ka = [H⁺][HPO₄²⁻]/[H₂PO₄⁻] وتساوي تركيزي الحمض وقاعدته المرافقة يكون [H⁺] = Ka = 6.2×10⁻⁸ M، فيكون pH = −log(6.2×10⁻⁸) = 7.21، وهو أكثر الحالات فاعلية.', '["pH المحلول المنظم يختلف باختلاف الزوج (3.20، 4.76، 9.4…).","Ka لهذا الحمض 6.2×10⁻⁸، وهو قريب من 10⁻⁷ لكنه ليس يساويه.","HPO₄²⁻ هو القاعدة المرافقة، وليس حمضًا قويًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.709Z"}'::jsonb),
('mcq', 6, 2, 'يُختار الزوج الذي pH الأكثر فاعلية له أقرب إلى المطلوب: |4.76 − 5.0| = 0.24 وهو الأصغر بين قيم الجدول، فهو الأنسب.', '["القيمة 6.35 تبعد 1.35 وحدة عن 5.0، بينما تبعد 4.76 نحو 0.24 فقط.","القيمة 3.20 تبعد 1.8 وحدة عن 5.0، فهي أبعد من 4.76.","","القيمة 9.4 بعيدة جدًا، ونوع الزوج لا يحدد ملاءمته؛ المعيار هو قرب pH الزوج من المطلوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.709Z"}'::jsonb),
('mcq', 7, 1, 'المحلول المنظم HF/F⁻ يكون أكثر فاعلية قرب pH = 3.20، وهو بعيد جدًا عن 7.2؛ فلا يصلح للمحافظة على pH = 7.2. أما أزواج الفوسفات فقيمتها 7.21.', '["pH له 7.21، فهو مناسب جدًا لهذه القيمة.","","pH له 7.21، وسعته كبيرة لارتفاع تراكيزه.","pH له 7.21، فهو مناسب لهذه القيمة وسعته جيدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.709Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الزوج المناسب: C₂H₅NH₃⁺/C₂H₅NH₂ لأن قيمة pH الأكثر فاعلية له 10.70 وهي الأقرب إلى 10.7. نحتاج إلى القاعدة الضعيفة C₂H₅NH₂ (إيثيل أمين) وملح حمضها المرافق (مثل C₂H₅NH₃Cl) المحتوي على C₂H₅NH₃⁺ بتركيزين متساويين، لأن المحلول المنظم يكون أكثر فاعلية عند تساوي تركيز الحمض وقاعدته المرافقة، فيكون pH = pKa.', '["اختيار C₂H₅NH₃⁺/C₂H₅NH₂","تحديد المادتين: القاعدة وملح حمضها المرافق","التعليل بقرب 10.70 من 10.7","تساوي التركيزين"]'::jsonb, '[]'::jsonb, '[{"element":"اختيار الزوج","marks":1},{"element":"المادتان","marks":1},{"element":"التعليل بالقرب من القيمة","marks":1},{"element":"ذكر تساوي التركيزين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اختيار صحيح مع المادتين والتعليل وتساوي التركيزين"},{"level":"3 درجات","description":"ينقص عنصر واحد"},{"level":"درجتان","description":"اختيار صحيح مع تعليل فقط"},{"level":"1 درجة","description":"اختيار صحيح دون تعليل"},{"level":"صفر","description":"اختيار خاطئ"}]'::jsonb, '["اختيار NH₄⁺/NH₃ لأنه الأقرب نوعًا","ذكر الحمض فقط دون قاعدته المرافقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.709Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) H₂PO₄⁻ ⇌ H⁺ + HPO₄²⁻؛ Ka = [H⁺][HPO₄²⁻]/[H₂PO₄⁻] = 6.2×10⁻⁸. (b) بتساوي [H₂PO₄⁻] و[HPO₄²⁻] يختصران فيكون [H⁺] = Ka = 6.2×10⁻⁸ M، وpH = −log(6.2×10⁻⁸) = 7.21. (c) نعم؛ لأن pH المحلول 7.21 قريب جدًا من 7.2، ولأن تساوي تركيز الحمض وقاعدته المرافقة يجعله أكثر فاعلية.', '["معادلة التأين وعبارة Ka","[H⁺] = Ka = 6.2×10⁻⁸ M","pH = 7.21","صلاحية المحلول مع التعليل"]'::jsonb, '["Ka = [H⁺][HPO₄²⁻]/[H₂PO₄⁻]","التركيزان متساويان فيختصران: [H⁺] = 6.2×10⁻⁸ M","pH = −log(6.2×10⁻⁸) = 7.21"]'::jsonb, '[{"element":"(a) المعادلة وعبارة Ka","marks":1},{"element":"(b) [H⁺]","marks":1},{"element":"(b) pH","marks":1},{"element":"(c) الحكم والتعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ بسيط في جزء واحد"},{"level":"درجتان","description":"حساب [H⁺] فقط مع الحكم"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["نسيان الإشارة السالبة في اللوغاريتم","كتابة عبارة Ka بقلب البسط والمقام","حساب pH = 6.2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.709Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأول: HF/F⁻ (3.20)، والثاني: NH₄⁺/NH₃ (9.4)، لأن كلًّا منهما يكون أكثر فاعلية عند pH يساوي قيمته عند تساوي تركيزي الحمض وقاعدته المرافقة. اقتراح الزميل غير مناسب؛ لأن pH الأكثر فاعلية لزوج الفوسفات 7.21، وهو بعيد عن 3.2 بنحو 4 وحدات وعن 9.4 بنحو وحدتين، فلا يحافظ على أي من القيمتين فاعلية، وتكون مقاومته لتغير pH ضعيفة عندهما.', '["HF/F⁻ للأول","NH₄⁺/NH₃ للثاني","الاختيار بقرب القيمة من pH المطلوب","تقويم اقتراح الفوسفات بحساب بعده عن القيمتين"]'::jsonb, '[]'::jsonb, '[{"element":"الزوج الأول","marks":1},{"element":"الزوج الثاني","marks":1},{"element":"تعليل الاختيار","marks":1},{"element":"تقويم الاقتراح بالتعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"اختيار صحيح للزوجين وتقويم معلل للاقتراح"},{"level":"3–4 درجات","description":"الزوجان صحيحان مع تقويم ناقص"},{"level":"1–2 درجة","description":"زوج واحد صحيح"},{"level":"صفر","description":"لا عناصر صحيحة"}]'::jsonb, '["الموافقة على اقتراح الزميل لأن الفوسفات يصلح للجميع","اختيار الزوجين معكوسين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T09:21:20.710Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
