('mcq', 1, 'تُعرَّف عملية الأكسدة في الكيمياء الحديثة بأنها:', null, '["اكتساب ذرات المادة للإلكترونات","فقدان ذرات المادة للإلكترونات","اتحاد المادة بالهيدروجين","انتقال البروتونات من مادة إلى أخرى"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 105 — الأكسدة والاختزال'),
('mcq', 2, 'ما المقصود بعملية الاختزال وفق التعريف الحديث؟', null, '["فقدان ذرات المادة للإلكترونات","اتحاد المادة بالأكسجين","تكوين رابطة تساهمية بين ذرتين","اكتساب ذرات المادة للإلكترونات"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 105 — الأكسدة والاختزال'),
('mcq', 3, 'يُسمّى التفاعل الذي تنتقل فيه الإلكترونات من إحدى الذرات إلى ذرة أخرى:', null, '["تفاعل الأكسدة والاختزال","تفاعل التعادل","تفاعل الإحلال المزدوج","تفاعل التفكك"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'متوسط', 'الكتاب ص 105 — الأكسدة والاختزال'),
('mcq', 4, 'أُطلقت كلمة «الأكسدة» فيما مضى على التفاعلات التي تتضمن:', null, '["فقدان المادة للإلكترونات","نزع الأكسجين من المركب","اتحاد المادة بالأكسجين","اتحاد المادة بالهيدروجين"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 105 — الأكسدة والاختزال'),
('mcq', 5, 'عرّف الكيميائيون قديمًا عملية الاختزال بأنها:', null, '["نزع الأكسجين من المركب","اتحاد المادة بالأكسجين","اكتساب المادة للإلكترونات","تحويل الفلز إلى أكسيده"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — المفهوم القديم للأكسدة والاختزال'),
('mcq', 6, 'أيّ التفاعلات الآتية يُعدّ أكسدة واختزالًا وفق التعريف الحديث، ولا يُعدّ أكسدة وفق المفهوم القديم؟', null, '["2Mg + O₂ → 2MgO","C + O₂ → CO₂","4Fe + 3O₂ → 2Fe₂O₃","2Na + Cl₂ → 2NaCl"]'::jsonb, 'فهم', 'مقارنة/تمييز', 'صعب', 'الكتاب ص 104–105 + المحتوى المكمّل (ليس في الكتاب) — توسيع مفهوم الأكسدة'),
('mcq', 7, 'في التفاعل CuO + H₂ → Cu + H₂O، ما الوصف الصحيح وفق المفهوم القديم للأكسدة والاختزال؟', null, '["تأكسد CuO لأنه فقد الأكسجين، واختُزل H₂ لأنه اتحد به","اختُزل CuO وحده، ولم تحدث أكسدة في التفاعل","اختُزل CuO لأنه فقد الأكسجين، وتأكسد H₂ لأنه اتحد به","تأكسد H₂ وحده، ولم يحدث اختزال في التفاعل"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'صعب', 'المحتوى المكمّل (ليس في الكتاب) — المفهوم القديم للأكسدة والاختزال'),
('essay', 1, 'قارن بين المفهوم القديم والتعريف الحديث لكلٍّ من الأكسدة والاختزال، مع ذكر مثال واحد يوضح كل مفهوم.', null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 105 + المحتوى المكمّل (ليس في الكتاب) — المفهوم القديم للاختزال'),
('essay', 2, 'يحترق المغنيسيوم في الهواء وفق المعادلة: 2Mg + O₂ → 2MgO.
(أ) بيّن أن هذا التفاعل يُعدّ أكسدة للمغنيسيوم وفق المفهوم القديم.
(ب) اكتب ما يحدث لكلٍّ من Mg وO بدلالة الإلكترونات، وحدد المادة التي تأكسدت والتي اختُزلت وفق التعريف الحديث.
(ج) فسّر لماذا يُعدّ التعريف الحديث أعم من القديم، مستشهدًا بتفاعل الصوديوم مع الكلور.', null, null, 'تحليل', 'تفسير وتحليل', 'صعب', 'الكتاب ص 104 — انتقال الإلكترون وتفاعل الأكسدة والاختزال'),
('essay', 3, 'صنّف كل تغير مما يأتي إلى أكسدة أو اختزال، مع ذكر السبب:
(أ) Na → Na⁺ + e⁻
(ب) Cl₂ + 2e⁻ → 2Cl⁻
(ج) Fe²⁺ → Fe³⁺ + e⁻
(د) Ag⁺ + e⁻ → Ag', null, null, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 109 — مسائل تدريبية (1)')
