from (values
('mcq', 1, 1, 'يعرّف الكتاب الأكسدة حاليًا بأنها فقدان ذرات المادة للإلكترونات، مثل تأكسد الصوديوم: Na → Na⁺ + e⁻.', '["هذا تعريف الاختزال لا الأكسدة.","","ليس تعريف الأكسدة في الكتاب؛ والاتحاد بالهيدروجين يرتبط تاريخيًا بالاختزال لا بالأكسدة.","انتقال البروتونات يخص تفاعلات الأحماض والقواعد، أما الأكسدة فتتعلق بالإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.710Z"}'::jsonb),
('mcq', 2, 3, 'الاختزال هو اكتساب ذرات المادة للإلكترونات، مثل اختزال الكلور: Cl₂ + 2e⁻ → 2Cl⁻.', '["هذا تعريف الأكسدة، وهو عكس الاختزال.","هذا هو المفهوم القديم للأكسدة لا للاختزال.","تكوين الرابطة التساهمية لا يعرّف الاختزال؛ فالاختزال يعرَّف باكتساب الإلكترونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.710Z"}'::jsonb),
('mcq', 3, 0, 'يسمي الكتاب التفاعل الذي تنتقل فيه الإلكترونات من إحدى الذرات إلى ذرة أخرى تفاعل الأكسدة والاختزال، كما في تفاعل Mg مع O₂.', '["","التعادل تفاعل حمض مع قاعدة، ولا يُعرَّف بانتقال الإلكترونات.","الإحلال المزدوج تبادل للأيونات بين مركبين دون انتقال للإلكترونات في العادة.","التفكك تحلل مركب إلى مواد أبسط، وهو تصنيف بحسب شكل التفاعل لا تعريف لانتقال الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T09:21:20.710Z"}'::jsonb),
('mcq', 4, 2, 'يذكر الكتاب أن كلمة الأكسدة أُطلقت فيما مضى على التفاعلات التي تتضمن اتحاد المادة بالأكسجين، مثل احتراق المغنيسيوم وصدأ الحديد.', '["هذا هو التعريف الحديث للأكسدة لا المفهوم القديم.","نزع الأكسجين هو المفهوم القديم للاختزال، وهو عكس الأكسدة.","","لم يعرّف الكيميائيون الأكسدة قديمًا بالاتحاد بالهيدروجين، بل بالاتحاد بالأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.711Z"}'::jsonb),
('mcq', 5, 0, 'في المفهوم القديم كان الاختزال يعني نزع الأكسجين من المركب، وارتبط باستخلاص الفلزات من أكاسيدها، مثل: CuO + H₂ → Cu + H₂O.', '["","هذا المفهوم القديم للأكسدة لا للاختزال.","هذا التعريف الحديث للاختزال، لا المفهوم القديم.","تحويل الفلز إلى أكسيده اتحاد بالأكسجين؛ أي أكسدة بالمفهوم القديم، وهو عكس المطلوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T09:21:20.711Z"}'::jsonb),
('mcq', 6, 3, 'في تفاعل 2Na + Cl₂ → 2NaCl لا يدخل الأكسجين، فلا يُعدّ أكسدة بالمفهوم القديم، لكن الصوديوم يفقد إلكترونًا (Na → Na⁺ + e⁻) والكلور يكتسبه، فهو تفاعل أكسدة واختزال بالتعريف الحديث؛ ولذلك وُسّع المفهوم ليشمل التفاعلات التي لا يدخلها الأكسجين.', '["يتحد فيه المغنيسيوم بالأكسجين، فهو أكسدة بالمفهومين القديم والحديث.","يتحد فيه الكربون بالأكسجين، فهو أكسدة بالمفهوم القديم أيضًا.","يتحد فيه الحديد بالأكسجين (الصدأ)، فهو أكسدة بالمفهوم القديم أيضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T09:21:20.711Z"}'::jsonb),
('mcq', 7, 2, 'بالمفهوم القديم: الاختزال نزع الأكسجين من المركب، والأكسدة الاتحاد بالأكسجين. فأكسيد النحاس(II) فقد أكسجينه وتحول إلى Cu فاختُزل، والهيدروجين اتحد بالأكسجين مكوّنًا H₂O فتأكسد؛ والعمليتان تحدثان معًا.', '["عكس المفهومين: فقد الأكسجين اختزال، والاتحاد بالأكسجين أكسدة.","الأكسدة والاختزال يحدثان معًا؛ فالهيدروجين اتحد بالأكسجين مكوّنًا الماء أي تأكسد.","","أكسيد النحاس(II) فقد الأكسجين وتحول إلى نحاس، وهذا اختزال بالمفهوم القديم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T09:21:20.711Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المفهوم القديم: الأكسدة اتحاد المادة بالأكسجين، مثل 2Mg + O₂ → 2MgO؛ والاختزال نزع الأكسجين من المركب، مثل CuO + H₂ → Cu + H₂O (اختُزل CuO إلى Cu). التعريف الحديث: الأكسدة فقدان ذرات المادة للإلكترونات، مثل Na → Na⁺ + e⁻؛ والاختزال اكتساب ذرات المادة للإلكترونات، مثل Cl₂ + 2e⁻ → 2Cl⁻. التعريف الحديث أعم؛ إذ يشمل تفاعلات لا يدخلها الأكسجين مثل تكوين NaCl.', '["الأكسدة قديمًا: الاتحاد بالأكسجين مع مثال","الاختزال قديمًا: نزع الأكسجين من المركب مع مثال","الأكسدة حديثًا: فقدان الإلكترونات مع مثال","الاختزال حديثًا: اكتساب الإلكترونات مع مثال"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الأكسدة القديم مع مثال","marks":1},{"element":"تعريف الاختزال القديم مع مثال","marks":1},{"element":"تعريف الأكسدة الحديث مع مثال","marks":1},{"element":"تعريف الاختزال الحديث مع مثال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يقارن المفهومين لكلتا العمليتين مقارنة صحيحة مع مثال مناسب لكل منهما."},{"level":"2–3 درجات","description":"يذكر التعريفات صحيحة لكن ينقصه مثال أو تعريف واحد."},{"level":"1 درجة","description":"يذكر تعريفًا واحدًا صحيحًا فقط."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["الخلط بين الأكسدة والاختزال في التعريف الحديث.","تعريف الاختزال القديم بأنه اكتساب الأكسجين.","الاعتقاد أن الأكسدة لا تحدث إلا بوجود الأكسجين."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T09:21:20.711Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) اتحد المغنيسيوم بالأكسجين مكوّنًا MgO، والاتحاد بالأكسجين هو الأكسدة بالمفهوم القديم. (ب) تفقد كل ذرة Mg إلكترونين: Mg → Mg²⁺ + 2e⁻ فتتأكسد، وتكتسب كل ذرة أكسجين إلكترونين: O + 2e⁻ → O²⁻ (أي O₂ + 4e⁻ → 2O²⁻) فيُختزل الأكسجين. (ج) لأن التعريف الحديث لا يشترط وجود الأكسجين؛ ففي 2Na + Cl₂ → 2NaCl يفقد الصوديوم إلكترونًا ويكتسبه الكلور، فهو أكسدة واختزال رغم عدم وجود الأكسجين، والتعريف الحديث يشمل حالات المفهوم القديم أيضًا.', '["الاتحاد بالأكسجين = أكسدة قديمًا","Mg → Mg²⁺ + 2e⁻ (أكسدة)","O₂ + 4e⁻ → 2O²⁻ (اختزال)","التعريف الحديث لا يشترط الأكسجين","مثال 2Na + Cl₂ → 2NaCl"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تعليل الأكسدة بالمفهوم القديم","marks":1},{"element":"(ب) نصف تفاعل المغنيسيوم وتحديد تأكسده","marks":1},{"element":"(ب) نصف تفاعل الأكسجين وتحديد اختزاله","marks":1},{"element":"(ج) تفسير عمومية التعريف الحديث بمثال NaCl","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"يجيب عن الأجزاء الثلاثة إجابة صحيحة كاملة مع أنصاف التفاعلات والمثال."},{"level":"3–4 درجات","description":"يجيب عن (أ) و(ب) صحيحًا، ويقدم تفسيرًا ناقصًا في (ج)."},{"level":"1–2 درجة","description":"يجيب عن جزء واحد صحيحًا."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ الأكسجين متأكسدًا لأنه دخل في التفاعل.","كتابة الإلكترونات في الطرف الخطأ من نصف التفاعل.","القول إن التعريفين متعارضان."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T09:21:20.712Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) أكسدة؛ لأن الصوديوم فقد إلكترونًا. (ب) اختزال؛ لأن الكلور اكتسب إلكترونين. (ج) أكسدة؛ لأن أيون Fe²⁺ فقد إلكترونًا. (د) اختزال؛ لأن أيون Ag⁺ اكتسب إلكترونًا.', '["(أ) أكسدة: فقد e⁻","(ب) اختزال: اكتساب e⁻","(ج) أكسدة: فقد e⁻","(د) اختزال: اكتساب e⁻"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يصنف التغيرات الأربعة صحيحًا مع السبب."},{"level":"2–3 درجات","description":"يصنف تغيرين أو ثلاثة صحيحًا مع السبب."},{"level":"1 درجة","description":"يصنف تغيرًا واحدًا صحيحًا."},{"level":"صفر","description":"تصنيف خاطئ أو بلا إجابة."}]'::jsonb, '["عدّ (ج) اختزالًا لأن الشحنة الموجبة زادت.","الحكم من موضع الإلكترون دون فهم معناه.","الخلط بين فقد الإلكترونات واكتسابها."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T09:21:20.712Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
