('mcq', 3, 3, 'كل أيون Ag⁺ يكتسب إلكترونًا (Ag⁺ + e⁻ → Ag) فيُختزل ويؤكسد الحديد؛ لذا فالعامل المؤكسد هو Ag⁺.', '["الحديد فقد إلكترونين وتأكسد، فهو العامل المختزل.","Fe²⁺ ناتج تأكسد الحديد، وليس مادة متفاعلة.","Ag ناتج اختزال أيونات الفضة، والعامل المؤكسد يكون من المتفاعلات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.712Z"}'::jsonb),
('mcq', 4, 1, 'يتأكسد Mg من صفر إلى +2 بفقد إلكترونين فهو العامل المختزل، ويُختزل اليود من صفر إلى −1 باكتسابها فهو العامل المؤكسد I₂.', '["عكس الصواب؛ فالمغنيسيوم يفقد إلكترونين فهو العامل المختزل.","","MgI₂ ناتج، والعامل المؤكسد هو المتفاعل الذي اكتسب الإلكترونات.","MgI₂ ناتج التفاعل لا عامل مختزل؛ المختزل هو Mg."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T09:21:20.713Z"}'::jsonb),
('mcq', 5, 1, 'Al → Al³⁺ + 3e⁻ : تأكسد الألومنيوم بفقد 3 إلكترونات فهو العامل المختزل، وFe³⁺ + 3e⁻ → Fe : اختُزل الحديد فهو العامل المؤكسد.', '["المادة التي تفقد الإلكترونات تتأكسد وتختزل غيرها، فهي عامل مختزل لا مؤكسد.","","المادة التي تكتسب الإلكترونات تُختزل وتؤكسد غيرها، فهي عامل مؤكسد.","Fe³⁺ يكتسب الإلكترونات ولا يفقدها (Fe³⁺ + 3e⁻ → Fe)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T09:21:20.713Z"}'::jsonb),
('mcq', 6, 0, 'عدد تأكسد الكبريت في H₂S يساوي −2 ويصبح صفرًا في S، فقد تأكسد بفقد إلكترونين؛ لذا فالمادة H₂S هي العامل المختزل، أما Cl₂ (من صفر إلى −1) فهو العامل المؤكسد. والهيدروجين بقي +1.', '["","عدد تأكسد الكلور قلّ من صفر إلى −1، فقد اختُزل وهو العامل المؤكسد.","الكبريت ناتج تأكسد H₂S، وليس مادة متفاعلة.","HCl ناتج التفاعل، ويحوي الكلور المختزل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T09:21:20.713Z"}'::jsonb),
('mcq', 7, 3, 'عدد تأكسد الكادميوم في CdO يساوي +2 ويصبح صفرًا في Cd، فقد اختُزل؛ لذا فـ CdO هو العامل المؤكسد. أما الكربون فيتغير من +2 في CO إلى +4 في CO₂ فيتأكسد، ويبقى الأكسجين −2.', '["الكربون في CO يتغير من +2 إلى +4 فيتأكسد، فـ CO هو العامل المختزل.","Cd ناتج اختزال الكادميوم، وليس مادة متفاعلة.","CO₂ ناتج تأكسد CO، والعامل المؤكسد من المتفاعلات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T09:21:20.713Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الأكسدة: Na → Na⁺ + e⁻ (أو 2Na → 2Na⁺ + 2e⁻)، الاختزال: 2H⁺ + 2e⁻ → H₂. (ب) العامل المختزل Na لأنه فقد الإلكترونات وتأكسد، والعامل المؤكسد H⁺ لأنه اكتسب الإلكترونات واختُزل.', '["نصف تفاعل الأكسدة للصوديوم","نصف تفاعل الاختزال لأيونات الهيدروجين","العامل المختزل Na","العامل المؤكسد H⁺"]'::jsonb, '["تحديد المادة التي فقدت الإلكترونات (Na) والتي اكتسبتها (H⁺).","كتابة نصفي التفاعل.","تطبيق التعريف: المتأكسد عامل مختزل، والمختزَل عامل مؤكسد."]'::jsonb, '[{"element":"نصف تفاعل الأكسدة","marks":1},{"element":"نصف تفاعل الاختزال","marks":1},{"element":"العامل المختزل","marks":1},{"element":"العامل المؤكسد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"نصفا التفاعل والعاملان صحيحة."},{"level":"2–3 درجات","description":"يحدد العاملين صحيحًا مع خطأ في أحد نصفي التفاعل أو العكس."},{"level":"1 درجة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ Na⁺ أو H₂ (النواتج) عاملين.","تسمية H⁺ عاملًا مختزلًا لأنه اختُزل.","إهمال الإلكترونين في نصف تفاعل الهيدروجين."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.713Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Sn في SnCl₂: n + 2(−1) = 0 ⇒ +2، وفي SnCl₄: n + 4(−1) = 0 ⇒ +4. Fe في FeCl₃: +3، وفي FeCl₂: +2. (ب) زاد عدد تأكسد القصدير من +2 إلى +4 فتأكسد، لذا SnCl₂ هو العامل المختزل؛ وقلّ عدد تأكسد الحديد من +3 إلى +2 فاختُزل، لذا FeCl₃ هو العامل المؤكسد. (ج) لا؛ لأن عدد تأكسد الكلور بقي −1 في جميع المواد.', '["Sn: +2 → +4","Fe: +3 → +2","SnCl₂ عامل مختزل","FeCl₃ عامل مؤكسد","الكلور لم يتغير عدد تأكسده"]'::jsonb, '["SnCl₂: n(Sn) + 2(−1) = 0 ⇒ n(Sn) = +2","SnCl₄: n(Sn) + 4(−1) = 0 ⇒ n(Sn) = +4","FeCl₃: n(Fe) + 3(−1) = 0 ⇒ n(Fe) = +3","FeCl₂: n(Fe) + 2(−1) = 0 ⇒ n(Fe) = +2","الزيادة (+2 → +4) أكسدة ⇒ SnCl₂ عامل مختزل؛ النقصان (+3 → +2) اختزال ⇒ FeCl₃ عامل مؤكسد"]'::jsonb, '[{"element":"أعداد تأكسد Sn","marks":1},{"element":"أعداد تأكسد Fe","marks":1},{"element":"العامل المختزل مع التعليل","marks":1},{"element":"العامل المؤكسد مع التعليل","marks":1},{"element":"دور الكلور","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة وتحديد صحيح للعاملين مع التعليل وبيان أن الكلور لم يتغير."},{"level":"3–4 درجات","description":"حسابات صحيحة مع خطأ في التعليل أو في دور الكلور."},{"level":"1–2 درجة","description":"يحسب بعض أعداد التأكسد فقط."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ FeCl₂ أو SnCl₄ (النواتج) عاملين.","عدّ الكلور عاملًا مؤكسدًا لأنه عنصر كهروسالبيته عالية.","الخلط بين اتجاه التغير في عدد التأكسد ونوع العملية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T09:21:20.713Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تفقد كل ذرة Ce ثلاثة إلكترونات (Ce → Ce³⁺ + 3e⁻) فيزيد عدد تأكسدها من صفر إلى +3، أي تتأكسد؛ لذا Ce هو العامل المختزل. ويكتسب كل أيون Cu²⁺ إلكترونين (Cu²⁺ + 2e⁻ → Cu) فيقل عدد تأكسده من +2 إلى صفر، أي يُختزل؛ لذا Cu²⁺ هو العامل المؤكسد.', '["Ce يفقد 3e⁻ ويزيد عدد تأكسده 0 → +3","Ce عامل مختزل","Cu²⁺ يكتسب 2e⁻ ويقل عدد تأكسده +2 → 0","Cu²⁺ عامل مؤكسد"]'::jsonb, '[]'::jsonb, '[{"element":"العامل المختزل","marks":1},{"element":"تعليله بالإلكترونات وعدد التأكسد","marks":1},{"element":"العامل المؤكسد","marks":1},{"element":"تعليله بالإلكترونات وعدد التأكسد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحدد العاملين ويعلل كلًّا منهما بالإلكترونات وعدد التأكسد."},{"level":"2–3 درجات","description":"يحدد العاملين صحيحًا مع تعليل ناقص."},{"level":"1 درجة","description":"يحدد عاملًا واحدًا صحيحًا."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ Cu²⁺ عاملًا مختزلًا لأنه اختُزل.","عدّ Ce³⁺ أو Cu (النواتج) عوامل.","الخطأ في عدد الإلكترونات المنتقلة لكل ذرة أو أيون."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T09:21:20.714Z"}'::jsonb)
