('mcq', 3, 0, 'X تفقد الإلكترونات فتتأكسد ويزيد عدد تأكسدها وهي العامل المختزل، وY تكتسبها فتُختزل ويقل عدد تأكسدها وهي العامل المؤكسد.', '["","Y تكتسب الإلكترونات فتُختزل، والمادة المختزَلة هي العامل المؤكسد.","X تفقد الإلكترونات فتتأكسد، فهي العامل المختزل.","X عامل مختزل فعلًا، لكن عدد تأكسدها يزيد لأنها فقدت إلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T09:21:20.714Z"}'::jsonb),
('mcq', 4, 2, 'زيادة عدد التأكسد من −1 إلى صفر تعني فقد إلكترون واحد، أي أكسدة، والمادة التي تتأكسد هي العامل المختزل (كما في Br⁻ عند تفاعله مع Cl₂).', '["الانتقال من −1 إلى صفر زيادة في عدد التأكسد، أي فقد إلكترون لا اكتسابه.","المادة التي تفقد الإلكترونات تتأكسد، فهي عامل مختزل.","","زيادة عدد التأكسد تعني فقد إلكترون لا اكتسابه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T09:21:20.715Z"}'::jsonb),
('mcq', 5, 2, 'يصف الجدول 1-3 كلًّا من X (المختزل) وY (المؤكسد) بأنها «المادة المتفاعلة»؛ فالعاملان من المتفاعلات، كما في 2K + Cl₂ حيث K المختزل وCl₂ المؤكسد.', '["العاملان مادتان تتفاعلان فتؤكسد إحداهما الأخرى، فهما من المتفاعلات.","العامل المختزل أيضًا مادة متفاعلة تفقد الإلكترونات.","","العامل المؤكسد مادة متفاعلة تكتسب الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T09:21:20.715Z"}'::jsonb),
('mcq', 6, 3, 'عدد تأكسد الكلور يقل من صفر إلى −1 فيُختزل، فهو العامل المؤكسد؛ وعدد تأكسد البروم يزيد من −1 إلى صفر فيتأكسد، فأيون البروميد هو العامل المختزل؛ ويبقى K⁺ دون تغير.', '["تبادل للدورين: نقصان عدد التأكسد يعني الاختزال، والمادة المختزلة عامل مؤكسد.","اتجاه التغير معكوس: الكلور من صفر إلى −1، والبروم من −1 إلى صفر.","عدد تأكسد البوتاسيوم يبقى +1، فهو أيون متفرج وليس عاملًا مختزلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T09:21:20.715Z"}'::jsonb),
('mcq', 7, 1, 'Na (العامل المختزل) يتغير من صفر إلى +1 فتفقد كل ذرة إلكترونًا، وH⁺ (العامل المؤكسد) يتغير من +1 إلى صفر فيكتسب كل أيون إلكترونًا؛ فيتساوى المفقود (2) والمكتسب (2).', '["عدد تأكسد Na يتغير من صفر إلى +1 فقط، فتفقد كل ذرة إلكترونًا واحدًا.","","عكس اتجاه الانتقال؛ فالصوديوم (المختزل) يفقد والهيدروجين (المؤكسد) يكتسب.","كل أيون H⁺ يتغير من +1 إلى صفر، فيكتسب إلكترونًا واحدًا، والإلكترونان يكتسبهما أيونا H⁺ معًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T09:21:20.715Z"}'::jsonb),
('essay', 1, null::int, null, null, 'العامل المؤكسد: (1) يكتسب الإلكترونات، (2) يقل عدد تأكسده، (3) يُختزل، (4) Cl₂ (من صفر إلى −1). العامل المختزل: (1) يفقد الإلكترونات، (2) يزيد عدد تأكسده، (3) يتأكسد، (4) K (من صفر إلى +1).', '["انتقال الإلكترونات","التغير في عدد التأكسد","العملية (أكسدة/اختزال)","المثال من تفاعل K وCl₂"]'::jsonb, '[]'::jsonb, '[{"element":"انتقال الإلكترونات للعاملين","marks":1},{"element":"التغير في عدد التأكسد للعاملين","marks":1},{"element":"العملية لكل عامل","marks":1},{"element":"المثالان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة كاملة في الأوجه الأربعة."},{"level":"2–3 درجات","description":"مقارنة صحيحة في وجهين أو ثلاثة."},{"level":"1 درجة","description":"وجه واحد صحيح."},{"level":"صفر","description":"مقارنة خاطئة أو خالية."}]'::jsonb, '["القول إن العامل المؤكسد يتأكسد.","ربط اكتساب الإلكترونات بزيادة عدد التأكسد.","عدّ KCl عاملًا."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.715Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Al عامل مختزل، وCu²⁺ عامل مؤكسد. (ب) تفقد كل ذرة Al ثلاثة إلكترونات فيزيد عدد تأكسدها من صفر إلى +3، ويكتسب كل أيون Cu²⁺ إلكترونين فيقل عدد تأكسده من +2 إلى صفر. (ج) المفقود: 2 × 3 = 6 إلكترونات، والمكتسب: 3 × 2 = 6 إلكترونات؛ وهما متساويان.', '["Al مختزل وCu²⁺ مؤكسد","Al: 3e⁻ لكل ذرة، 0 → +3","Cu²⁺: 2e⁻ لكل أيون، +2 → 0","6 إلكترونات مفقودة = 6 مكتسبة"]'::jsonb, '["Al → Al³⁺ + 3e⁻ ؛ ذرتان ⇒ 2 × 3 = 6e⁻ مفقودة","Cu²⁺ + 2e⁻ → Cu ؛ ثلاثة أيونات ⇒ 3 × 2 = 6e⁻ مكتسبة"]'::jsonb, '[{"element":"(أ) تحديد العاملين","marks":1},{"element":"(ب) المقارنة في الإلكترونات وعدد التأكسد","marks":2},{"element":"(ج) حساب الإلكترونات الكلية","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحديد صحيح ومقارنة كاملة وحساب صحيح للإلكترونات المفقودة والمكتسبة."},{"level":"3–4 درجات","description":"تحديد ومقارنة صحيحان مع خطأ في الحساب الكلي."},{"level":"1–2 درجة","description":"تحديد العاملين فقط أو مقارنة جزئية."},{"level":"صفر","description":"إجابة خاطئة أو خالية."}]'::jsonb, '["عدّ الإلكترونات لذرة واحدة دون ضربها في المعامل.","القول إن Al يفقد إلكترونات أكثر من التي يكتسبها Cu²⁺ في التفاعل الكلي.","تبديل دوري العاملين."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T09:21:20.715Z"}'::jsonb),
('essay', 3, null::int, null, null, 'لأن الكلور يكتسب الإلكترونات من الصوديوم (Cl₂ + 2e⁻ → 2Cl⁻) فيُختزل هو، وبأخذه هذه الإلكترونات يسبب فقد الصوديوم لها أي أكسدة الصوديوم؛ فالتسمية تصف أثره في المادة الأخرى (يؤكسدها)، لا ما يحدث له.', '["الكلور يكتسب الإلكترونات فيُختزل","اكتسابه الإلكترونات يسبب أكسدة الصوديوم","التسمية تصف أثره في غيره"]'::jsonb, '[]'::jsonb, '[{"element":"اكتساب الكلور للإلكترونات واختزاله","marks":1},{"element":"تسببه في أكسدة الصوديوم","marks":1},{"element":"ربط التسمية بأثره في المادة الأخرى","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير كامل يربط الاختزال بأكسدة المادة الأخرى."},{"level":"1–2 درجة","description":"يذكر أن الكلور اكتسب إلكترونات دون ربط ذلك بأكسدة الصوديوم."},{"level":"صفر","description":"تفسير خاطئ أو خالٍ."}]'::jsonb, '["القول إن الكلور يتأكسد لأنه عامل مؤكسد.","الخلط بين اسم العامل والعملية التي تحدث له."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T09:21:20.716Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
